import { createSlice } from '@reduxjs/toolkit';
import type { PayloadAction } from '@reduxjs/toolkit';

export interface SettingsState {
  musicVolume: number;
  sfxVolume?: number;
  useScientificNotation: boolean;
}

const initialState: SettingsState = {
  musicVolume: localStorage.getItem('musicVolume')
    ? parseInt(localStorage.getItem('musicVolume') as string, 10)
    : 20,
  sfxVolume: localStorage.getItem('sfxVolume')
    ? parseInt(localStorage.getItem('sfxVolume') as string, 10)
    : 40,
  useScientificNotation: localStorage.getItem('useScientificNotation')
    ? localStorage.getItem('useScientificNotation') === 'true'
    : true,
};

export const settingsSlice = createSlice({
  name: 'settings',
  initialState,
  reducers: {
    updateSetting: (
      state,
      action: PayloadAction<{ setting: string; value: any }>,
    ) => {
      const { setting, value } = action.payload;
      (state[setting as keyof SettingsState] as any) = value;
      localStorage.setItem(setting, value);
    },
  },
});

// Action creators are generated for each case reducer function
export const { updateSetting } = settingsSlice.actions;

export default settingsSlice.reducer;
