import { createAsyncThunk, PayloadAction, createSlice } from '@reduxjs/toolkit';
import { Unlock, UnlockList } from '../types';
import { store } from '../store';
import { addSkillSlot } from './gameSlice';
import { updateSliceVersion } from './common';
import unlocks, { unlockConditions } from '../conf/unlockConf';
import { unlockAchievement } from '../utils/gameUtil';
import { startAnimation } from './animationSlice';

const initialState: UnlockList = unlocks;

export const doUnlock = createAsyncThunk(
  'unlocks/updateUnlock',
  async (
    {
      attribute,
      property,
      value,
    }: { attribute: string; property: keyof Unlock; value: any },
    { dispatch },
  ) => {
    // set the unlock value in store
    dispatch(updateUnlock({ attribute, property, value }));
    // add order to the item
    const types = ['resource', 'skill', 'upgrade', 'achievement'];
    const { achievements } = store.getState();
    types.forEach((type) => {
      if (
        unlockConditions[attribute]?.type === type ||
        (type === 'achievement' && achievements[attribute])
      ) {
        const items = (store.getState() as { [key: string]: any })[
          `${type}s`
        ] as { [key: string]: any };
        const maxOrder = Math.max(
          ...Object.values(items).map((item) => item.order || 0),
        );
        dispatch({
          type: `${type}s/update${type.charAt(0).toUpperCase() + type.slice(1)}`,
          payload: {
            [type]: attribute,
            property: 'order',
            value: maxOrder + 1,
          },
        });
        if (type === 'skill') {
          // if game.skillslots does not contain "firstskill" add it
          if (!store.getState().game.skillSlots.firstskill) {
            dispatch(addSkillSlot('firstskill'));
          }
        }

        if (type === 'achievement') {
          const achievement = items[attribute];
          if (!achievement.isUnlocked) {
            unlockAchievement(attribute);
          }
        }
      }
    });

    // if the
    if (unlockConditions[attribute]?.type === 'feature') {
      store.dispatch(
        startAnimation({
          element: `unlock-${attribute}`,
          type: `featureUnlock`,
          value: 0,
          duration: 3000,
        }),
      );
    }
    // todo: add order to other models too

    return { attribute, property, value };
  },
);

export const unlockSlice = createSlice({
  name: 'unlocks',
  initialState,
  reducers: {
    updateUnlock: (
      state,
      action: PayloadAction<{
        attribute: string;
        property: keyof Unlock;
        value: any;
      }>,
    ) => {
      const { attribute, property, value } = action.payload;
      state[attribute][property] = value;
    },
    setSeen: (state, action: PayloadAction<string>) => {
      state[action.payload].isSeen = true;
    },
    setUnseen: (state, action: PayloadAction<string>) => {
      state[action.payload].isSeen = false;
    },
    resetUnlocks: () => {
      return initialState;
    },
    updateVersion: (state) => {
      return updateSliceVersion(state, initialState);
    },
  },
});

export const { updateUnlock, setSeen, setUnseen, resetUnlocks, updateVersion } =
  unlockSlice.actions;
export default unlockSlice.reducer;
