import { FC } from 'react';
import { useSelector } from 'react-redux';
import { Nav, Navbar } from 'react-bootstrap';
import type { RootState } from '../../store';
import { store } from '../../store';
import { updateModal, updateNavigation } from '../../store/navigationSlice';
import townIcon from '../../assets/img/town.svg';
import skillsIcon from '../../assets/img/skills.svg';
import itemsIcon from '../../assets/img/items.svg';
import { hasUnseen } from '../../utils';
import { playSfx } from '../../utils/sound';

const navItems = ['town', 'skills', 'items'];
interface IconsList {
  [key: string]: string;
}
const icons: IconsList = {
  items: itemsIcon,
  skills: skillsIcon,
  town: townIcon,
};

const TopMenu: FC<{}> = () => {
  const navigation = useSelector((state: RootState) => state.navigation);
  const unlocks = useSelector((state: RootState) => state.unlocks);

  return (
    <Navbar
      expand="lg"
      className="panel container header-menu w-100 mb-2 d-flex justify-content-between align-items-center"
    >
      <Nav className="me-auto">
        {navItems.map((item) => (
          <Nav.Link
            key={item}
            className={`main-nav-${item} ${navigation.mainPanel.current === item ? 'active' : ''} ${unlocks[item].isUnlocked ? '' : ' locked'} ${hasUnseen(item) ? ' new' : ''}`}
            disabled={!unlocks[item].isUnlocked}
            onMouseOver={() => {
              if (unlocks[item].isUnlocked) {
                playSfx('hover');
              }
            }}
            onClick={() => {
              if (unlocks[item].isUnlocked) {
                playSfx('click');
                store.dispatch(
                  updateNavigation({
                    navigation: 'mainPanel',
                    value: { current: item },
                  }),
                );
              }
            }}
          >
            <img src={icons[item]} alt="" />
            {item.charAt(0).toUpperCase() + item.slice(1)}
          </Nav.Link>
        ))}
      </Nav>
      <button
        type="button"
        className="btn btn-icon btn-settings"
        aria-label="Settings"
        onMouseOver={() => {
          playSfx('hover');
        }}
        onClick={() => {
          playSfx('motion');
          store.dispatch(
            updateModal({
              value: { show: true, type: 'settings' },
            }),
          );
        }}
      />
    </Navbar>
  );
};
export default TopMenu;
