// make react component that has a div with checkbox to hide tooltips and save buttton that closes the modal

import { FC, useState } from 'react';
import { Form } from 'react-bootstrap';
import { store } from '../../store';
import { confirmModal } from '../../store/navigationSlice';
import { updateSetting } from '../../store/settingsSlice';
import discord from '../../assets/img/discord.svg';
import { playSfx } from '../../utils/sound';
import ModalCloseBtn from './modalCloseBtn';

const SettingsModal: FC<{}> = () => {
  const [musicVolume, setMusicVolume] = useState(
    store.getState().settings.musicVolume,
  );
  const [sfxVolume, setSfxVolume] = useState(
    store.getState().settings.sfxVolume,
  );

  if (sfxVolume === undefined) {
    setSfxVolume(0);
  }
  if (musicVolume === undefined) {
    setMusicVolume(0);
  }

  const [useScientificNotation, setUseScientificNotation] = useState(
    store.getState().settings.useScientificNotation,
  );
  const handleCheckboxChange = (e: any) => {
    setUseScientificNotation(e.target.checked);
    store.dispatch(
      updateSetting({
        setting: 'useScientificNotation',
        value: e.target.checked,
      }),
    );
  };

  const handleMusicVolumeChange = (e: any) => {
    setMusicVolume(e.target.value);
    store.dispatch(
      updateSetting({
        setting: 'musicVolume',
        value: e.target.value,
      }),
    );
  };

  const handleSfxVolumeChange = (e: any) => {
    setSfxVolume(e.target.value);
    store.dispatch(
      updateSetting({
        setting: 'sfxVolume',
        value: e.target.value,
      }),
    );
  };

  return (
    <div className="modal-content">
      <div className="modal-header">
        <h5 className="modal-title">Settings</h5>
        <ModalCloseBtn />
      </div>
      <div className="modal-body">
        <div>
          <Form.Label className="mb-0 d-flex justify-content-between">
            <span>Music Volume</span>
            <span className="volume-value">
              <span className="num">{musicVolume}</span>%
            </span>
          </Form.Label>
          <Form.Range onChange={handleMusicVolumeChange} value={musicVolume} />
        </div>
        <div>
          <Form.Label className="mb-0 d-flex justify-content-between">
            <span>SFX Volume</span>
            <span className="volume-value">
              <span className="num">{sfxVolume}</span>%
            </span>
          </Form.Label>
          <Form.Range onChange={handleSfxVolumeChange} value={sfxVolume} />
        </div>
        <div className="sep-top pt-2 mt-1 d-flex justify-content-between w-100 text-nowrap  flex-wrap">
          <div className="form-check d-flex align-items-center">
            <label
              htmlFor="useScientificNotation"
              className="form-check-label ms-2 mt-1"
            >
              <input
                className="form-check-input"
                type="checkbox"
                id="useScientificNotation"
                name="useScientificNotation"
                onChange={handleCheckboxChange}
                checked={useScientificNotation}
              />
              Use scientific notation
            </label>
          </div>

          <button
            type="button"
            className="btn-text btn-data"
            onClick={() => {
              playSfx('motion');
              store.dispatch(
                confirmModal({
                  value: { show: true, type: 'manageData' },
                }),
              );
            }}
          >
            Manage game data
          </button>
        </div>
      </div>
      <div className="modal-footer flex-wrap">
        <div className="justify-content-between d-flex w-100">
          <button
            type="button"
            className="btn btn-primary"
            onClick={() => {
              playSfx('motion');
              store.dispatch(
                confirmModal({
                  value: {
                    show: true,
                    type: 'restartConfirm',
                  },
                }),
              );
            }}
          >
            Restart Game
          </button>
          <a
            className="btn btn-icon"
            href="https://discord.gg/h7VWQdh95z"
            target="_blank"
            rel="noreferrer"
          >
            <img src={discord} alt="Discord" />
          </a>
        </div>
        <div className="game-info">
          Game version: {store.getState().game.version}{' '}
          <button
            type="button"
            className="btn-text"
            onClick={() => {
              playSfx('motion');
              store.dispatch(
                confirmModal({
                  value: { show: true, type: 'credits' },
                }),
              );
            }}
          >
            Credits
          </button>
        </div>
      </div>
    </div>
  );
};
export default SettingsModal;
