import { FC, useState } from 'react';
import { store } from '../../store';
import LocationButton from './town/locationButton';
import { playSfx } from '../../utils/sound';
import { setNavigationValue } from '../../store/navigationSlice';

import townTemple from '../../assets/img/map-temple.png';
import townTownHall from '../../assets/img/map-townHall.png';
import townForest from '../../assets/img/map-forest.png';
import townLibrary from '../../assets/img/map-library.png';
import townMarket from '../../assets/img/map-market.png';
import townMines from '../../assets/img/map-mines.png';
import townHome from '../../assets/img/map-home.png';
import townSmithy from '../../assets/img/map-smithy.png';

const Town: FC<{}> = () => {
  const [hoveredLocation, setHoveredLocation] = useState<string | null>(null);

  const locations = [
    'temple',
    'townHall',
    'forest',
    'library',
    'market',
    'mines',
    'home',
    'smithy',
  ];

  // preload images
  const images = {
    temple: townTemple,
    townHall: townTownHall,
    forest: townForest,
    library: townLibrary,
    market: townMarket,
    mines: townMines,
    home: townHome,
    smithy: townSmithy,
  };

  return (
    <div className="upgrade-container town-container flex-grow-1 interact-container panel mb-3 w-100 pt-0 pb-0">
      <button
        type="button"
        aria-label="Back"
        className="btn btn-icon btn-back btn-has-icon"
        onMouseOver={() => {
          playSfx('hover');
        }}
        onClick={() => {
          playSfx('location');
          store.dispatch(
            setNavigationValue({
              navigation: 'mainPanel',
              property: 'current',
              value: 'location',
            }),
          );
        }}
      >
        <span>Return</span>
      </button>
      <div className="town-list">
        <div className="inner">
          {locations.map((location) => (
            <LocationButton
              key={location}
              location={location}
              onMouseEnter={() => setHoveredLocation(location)}
              onMouseLeave={() => setHoveredLocation(null)}
            />
          ))}
          {Object.entries(images).map(([key, image]) => (
            <div
              key={key}
              className={`${hoveredLocation === key || store.getState().location.current === key ? 'active' : 'hidden'} location`}
              style={{ backgroundImage: `url(${image})` }}
            />
          ))}
        </div>
      </div>
    </div>
  );
};
export default Town;
