// Generate all combinations of book recipes
ideaList.forEach((idea1) => {
  ideaList.forEach((idea2) => {
    const recipeKey = `book${idea1.displayName}${idea2.displayName}`;
    let bookType = 'book';
    if (idea1.name === idea2.name && idea1.name === 'magical') {
      bookType = `magicalBook`;
    } else if (
      idea1.name === 'great' &&
      ['good', 'kind', 'evil', 'great', 'magical'].includes(idea2.name)
    ) {
      bookType = 'greatBook';
    } else if (
      idea1.name === 'good' &&
      ['good', 'kind', 'evil', 'great', 'magical'].includes(idea2.name)
    ) {
      bookType = 'goodBook';
    }
    recipes.mental[recipeKey] = {
      name: bookType,
      type: 'resource',
      components: [
        { resource: 'paper', baseAmount: 10 },
        { resource: `${idea1.name}Idea`, baseAmount: 1 },
        { resource: `${idea2.name}Idea`, baseAmount: 1 },
      ],
    };
  });
});

