import {
  createSlice,
  createAsyncThunk,
  type PayloadAction,
} from '@reduxjs/toolkit';
import { pause, unpause } from './gameSlice';
import { updateSliceVersion } from './common';

interface Alert {
  message: string;
  time: number;
  id: string;
}

export interface NavigationState {
  // modal is an object with string properties
  modal: {
    type: string;
    show: boolean;
    uncloseable: boolean;
    params: { [key: string]: any };
  };
  confirm: {
    type: string;
    model?: string;
    show: boolean;
    uncloseable: boolean;
  };
  mainPanel: {
    current: string;
  };
  alerts: Alert[];
}

const initialState: NavigationState = {
  modal: {
    type: '',
    show: false,
    uncloseable: false,
    params: {},
  },
  confirm: {
    type: '',
    show: false,
    uncloseable: false,
  },
  mainPanel: {
    current: 'empty',
  },
  alerts: [],
};

export const updateModal = createAsyncThunk(
  'navigation/updateModal',
  async ({ value }: { value: any }, { dispatch }) => {
    dispatch(updateNavigation({ navigation: 'modal', value }));
    value.show ? dispatch(pause()) : dispatch(unpause());
  },
);
export const confirmModal = createAsyncThunk(
  'navigation/confirmModal',
  async ({ value }: { value: any }, { dispatch }) => {
    dispatch(updateNavigation({ navigation: 'confirm', value }));
  },
);

export const navigationSlice = createSlice({
  name: 'navigation',
  initialState,
  reducers: {
    updateNavigation: (
      state,
      action: PayloadAction<{ navigation: string; value: any }>,
    ) => {
      const { navigation, value } = action.payload;
      switch (navigation) {
        case 'modal':
          state.modal = { ...state.modal, ...value };
          break;
        case 'confirm':
          state.confirm = { ...state.confirm, ...value };
          break;
        default:
          state[navigation as keyof NavigationState] = value;
      }
    },
    setNavigationValue: (
      state,
      action: PayloadAction<{
        navigation: string;
        property: string;
        value: any;
      }>,
    ) => {
      const { navigation, property, value } = action.payload;
      (state[navigation as keyof NavigationState] as any)[property] = value;
    },
    resetNavigation: () => {
      return initialState;
    },
    updateVersion: (state) => {
      return updateSliceVersion(state, initialState);
    },
    addAlert(state, action: PayloadAction<Alert>) {
      state.alerts = [...state.alerts, action.payload];
    },
    removeAlert(state, action: PayloadAction<{ id: string }>) {
      state.alerts = state.alerts.filter(
        (alert) => alert.id !== action.payload.id,
      );
    },
    removeAllAlerts(state) {
      state.alerts = [];
    },
    setModalParam(state, action: PayloadAction<{ key: string; value: any }>) {
      if (!state.modal.params) {
        state.modal.params = {};
      }
      state.modal.params[action.payload.key] = action.payload.value;
    },
  },
});

// Action creators are generated for each case reducer function
export const {
  updateNavigation,
  setNavigationValue,
  resetNavigation,
  updateVersion,
  addAlert,
  removeAlert,
  removeAllAlerts,
  setModalParam,
} = navigationSlice.actions;

export default navigationSlice.reducer;
