import React, { FC, useEffect, useState, useMemo } from 'react';
import { useSelector } from 'react-redux';
import { Card } from 'react-bootstrap';
import { store, RootState } from '../../store';
import { getIcon, numberDisplay, textDisplay } from '../../utils';
import { buyUpgrade, areRequirementsMet } from '../../utils/upgradeUtil';
import { playSfx } from '../../utils/sound';
import { setSeen } from '../../store/unlockSlice';
import CostHandler from '../../utils/costHandler';
import { Cost } from '../../types';
import ButtonCost from '../util/buttonCost';
import AcquiredResource from '../util/acquiredResource';

interface UpgradeProps {
  upgradeName: string;
}

const UpgradeBox: FC<UpgradeProps> = ({ upgradeName }) => {
  const upgrade = useSelector(
    (state: RootState) => state.upgrades[upgradeName],
  );
  const locationsList = useSelector((state: RootState) => state.location.list);
  const unlock = useSelector((state: RootState) => state.unlocks[upgradeName]);

  // Subscribe to all resources that are in the cost
  const relevantResources = useMemo(() => {
    return Object.keys(upgrade.cost || {});
  }, [upgrade.cost]);

  const resourcesSum = useSelector((state: RootState) => {
    return relevantResources.reduce((sum, resource) => {
      let addValue = 0;
      if (state.resources[resource]) {
        addValue = state.resources[resource].amount;
      }
      if (resource.startsWith('ticket_')) {
        addValue = CostHandler.getTicketAmount(resource);
      }
      return sum + addValue;
    }, 0);
  });

  const requirementsMet = areRequirementsMet(upgrade.requirements);

  const [costHandler, setCostHandler] = React.useState<CostHandler | undefined>(
    undefined,
  );
  const [acquiredResources, setAcquiredResources] = useState<
    Record<string, any>
  >({});
  const [canAfford, setCanAfford] = useState(false);

  useEffect(() => {
    const handler = new CostHandler();
    if (upgrade.cost) {
      Object.entries(upgrade.cost).forEach(([key, value]) => {
        handler.addCost(key, (value as Cost).currentCost);
      });
    }
    setCostHandler(handler);
    if (handler) {
      setCanAfford(handler.canPayCosts());
    }
  }, [upgrade.cost]);

  useEffect(() => {
    if (!costHandler) return;
    const affordable = costHandler.canPayCosts();
    if (affordable !== canAfford) {
      setCanAfford(affordable);
    }
  }, [resourcesSum, costHandler, canAfford]);

  const addModDescription = () => {
    const descriptions: string[] = [];
    if (!upgrade.addMods) return '';
    upgrade.addMods.forEach((addMod) => {
      if (addMod.type === 'hidden') return;
      if (!addMod.description) descriptions.push(addMod.modObjectName);
      let { description } = addMod;
      if (!description) return;
      description = description.replace(
        'power',
        `<span class="num">${String(numberDisplay(upgrade.currentPower || 0))}</span>`,
      );
      description = description.replace(
        'powAmount',
        `<span class="num">${String(numberDisplay((upgrade.currentPower || 0) * upgrade.amount))}</span>`,
      );
      description = description.replace(
        'amountPower',
        `<span class="num">${String(numberDisplay((upgrade.currentPower || 0) ** upgrade.amount))}</span>`,
      );
      description = description.replace(
        'amountPlus1',
        `<span class="num">${String(numberDisplay(upgrade.amount + 1))}</span>`,
      );
      description = description.replace(
        '2amount',
        `<span class="num">${String(numberDisplay(2 ** upgrade.amount))}</span>`,
      );

      description = description.replace(
        '4amount',
        `<span class="num">${String(numberDisplay(4 ** upgrade.amount))}</span>`,
      );
      description = description.replace(
        '1_5amount',
        `<span class="num">${String(numberDisplay(1.5 ** upgrade.amount * 100))}%</span>`,
      );
      description = description.replace(
        'thousandPowAmount',
        `<span class="num">${String(numberDisplay(1000 ** upgrade.amount))}</span>`,
      );
      description = description.replace(
        'hundredPowAmount',
        `<span class="num">${String(numberDisplay(100 ** upgrade.amount))}</span>`,
      );
      if (upgrade.additionalPower) {
        Object.keys(upgrade.additionalPower).forEach((key) => {
          const power = upgrade.currentAdditionalPower
            ? upgrade.currentAdditionalPower[key]
            : 0;
          description = description.replace(
            `additionalPower-${key}`,
            `<span class="num">${String(numberDisplay(power))}</span>`,
          );
        });
      }
      descriptions.push(description);
    });
    return descriptions.join('<div class="mod-separator"></div>');
  };
  return (
    <div
      className={`upgrade-box col-12 col-sm-6 col-md-12 col-lg-6 col-xl-4${
        upgrade.limit && upgrade.amount >= upgrade.limit ? ' limit-reached' : ''
      }${!unlock.isSeen ? ' new' : ''}`}
      onMouseEnter={() => {
        if (!unlock.isSeen) {
          store.dispatch(setSeen(upgradeName));
        }
      }}
    >
      <AcquiredResource
        acquiredResources={acquiredResources}
        isOpen
        animationKey={`upgrade-acquired-${upgrade.name}`}
      />
      <Card
        style={
          {
            '--var-color': upgrade.currentColor ?? upgrade.color,
          } as React.CSSProperties
        }
      >
        <Card.Body>
          <div className="card-title d-flex align-items-center justify-content-between mb-2">
            <span className="d-flex">
              <span className="icon-container">
                <span
                  className={`model-icon ${upgrade.color}`}
                  style={{ WebkitMaskImage: `url(${getIcon(upgrade.icon)})` }}
                />
              </span>
              <span>{upgrade.displayName}</span>
              <span className="is-new text-shadow">(New)</span>
            </span>
            <div className="limit-amount">
              {numberDisplay(upgrade.amount)}
              {upgrade.limit && `/${upgrade.limit}`}
            </div>
          </div>
          <div
            className="descr flavor-text"
            dangerouslySetInnerHTML={{
              // replace power with currentPower
              __html: textDisplay(
                (upgrade.currentDescription ?? upgrade.description).replace(
                  'power',
                  String(numberDisplay(upgrade.currentPower || 0)),
                ),
              ),
            }}
          />
          {upgrade.requirements && !requirementsMet && (
            <div className="sep-top descr">
              <span className="red">Requires:</span>
              {upgrade.requirements.map((req, index) => (
                <div key={index} className="descr">
                  <span className="num">{numberDisplay(req.amount)}</span>{' '}
                  <span
                    dangerouslySetInnerHTML={{
                      __html:
                        req.objectType === 'Npc'
                          ? `Relationship with ${
                              locationsList[req.objectName]?.npc.displayName
                            }`
                          : textDisplay(req.objectName),
                    }}
                  />
                </div>
              ))}
            </div>
          )}
          {upgrade.addMods && upgrade.addMods.length > 0 && (
            <div className="sep-top descr">
              <span
                dangerouslySetInnerHTML={{
                  __html: textDisplay(addModDescription()),
                }}
              />
            </div>
          )}
        </Card.Body>
        <button
          type="button"
          className={`btn btn-primary buy-${upgradeName}`}
          onClick={() => {
            playSfx('upgrade');
            buyUpgrade(upgradeName, setAcquiredResources);
          }}
          onMouseEnter={() =>
            // if any cost is not payable, or limit is reached or requirements are not met, play a different sound
            !requirementsMet ||
            !canAfford ||
            (upgrade.limit !== undefined && upgrade.amount >= upgrade.limit)
              ? undefined
              : playSfx('buttonHover')
          }
          // if any cost is not payable, or limit is reached or requirements are not met, disable the button
          disabled={
            !requirementsMet ||
            !canAfford ||
            (upgrade.limit !== undefined && upgrade.amount >= upgrade.limit)
          }
        >
          <ButtonCost type="BUY" model={upgrade} />
        </button>
      </Card>
    </div>
  );
};
export default UpgradeBox;
