import { createSlice } from '@reduxjs/toolkit';
import type { PayloadAction } from '@reduxjs/toolkit';
import { Resource, ResourceList } from '../types';
import resources from '../conf/resourceConf';
import { updateSliceVersion } from './common';

const initialState: ResourceList = resources;

export const resourceSlice = createSlice({
  name: 'resources',
  initialState,
  reducers: {
    // reducer to change the value of a resource.
    // it has arguments: resource name, property name, and value
    updateResource: (
      state,
      action: PayloadAction<{
        resource: string;
        property: keyof Resource;
        value: any;
      }>,
    ) => {
      const { resource, property, value } = action.payload;
      (state[resource][property] as any) = value;
    },
    resetResources: () => {
      return initialState;
    },
    updateVersion: (state) => {
      return updateSliceVersion(state, initialState);
    },
  },
});

// Action creators are generated for each case reducer function
export const { updateResource, resetResources, updateVersion } =
  resourceSlice.actions;

export default resourceSlice.reducer;
