import { FC } from 'react';
import { useSelector } from 'react-redux';
import type { RootState } from '../../store';
import days, { EventAction } from '../../conf/dayConf';
import { store } from '../../store';
import { updateModal } from '../../store/navigationSlice';
import ModalCloseBtn from './modalCloseBtn';
import DynamicText from '../util/dynamicText';

const ActionResultModal: FC<{}> = () => {
  const game = useSelector((state: RootState) => state.game);
  const text = days[game.day].eventActions?.find(
    (act: EventAction) => act.type === game.dayAction,
  )?.result;
  return (
    <div className="modal-content">
      <div className="modal-header">
        <h5 className="modal-title">Day {game.day}</h5>
        <ModalCloseBtn />
      </div>
      <div className="modal-body">
        <DynamicText text={text || ''} />
      </div>

      <div className="modal-footer d-flex">
        <button
          type="button"
          className="btn btn-primary"
          onClick={() => {
            store.dispatch(
              updateModal({
                value: { show: false, type: '' },
              }),
            );
          }}
        >
          Continue
        </button>
      </div>
    </div>
  );
};
export default ActionResultModal;
