export const addTokens = (location: string, token: string, amount: number) => {
  store.dispatch(
    updateFeatureValue({
      location,
      property: token,
      value: storeValue('location', 'list', location).values[token] + amount,
    }),
  );
};

export const addAttribute = (
  attribute: string,
  amount: number,
  source: string,
) => {
  const current = storeValue('attributes', attribute, 'addAmount');
  store.dispatch(
    updateAttribute({
      attribute,
      property: 'addAmount',
      value: (current || 0) + amount,
    }),
  );
  if (!createAttributeSources()[source]) {
    source = 'other';
  }
  store.dispatch(
    addToSource({
      attribute,
      source,
      amount,
    }),
  );
  updateAttributes();
};

export const addResource = (
  resource: string,
  amount: number,
  skipAnimation: boolean = false,
) => {
  if (amount === 0 || isNaN(amount)) return;
  const addedResource = storeValue('resources', resource);
  const gainMultiplier = addedResource.gainMultiplier || 1;

  amount = amount * gainMultiplier;
  let newAmount = addedResource.amount + amount;
  if (
    addedResource.isCapped &&
    addedResource.currentCap &&
    newAmount > addedResource.currentCap
  ) {
    newAmount = addedResource.currentCap;
  }
  store.dispatch(
    updateResource({
      resource,
      property: 'amount',
      value: newAmount,
    }),
  );

  if (skipAnimation) return;

  store.dispatch(
    startAnimation({
      element: resource,
      type: '+',
      value: amount,
      duration: 2000,
    }),
  );
};

export const addTickets = (ticketName: string, amount: number) => {
  const rewardHandler = new RewardHandler([
    {
      resource: ticketName,
      amount,
    },
  ]);
  rewardHandler.giveRewards();
};

export const unlockItem = (item: string) => {
  const { unlocks } = store.getState();
  const { achievements } = store.getState();
  const currentUnlock = unlocks[item];

  if (currentUnlock?.isUnlocked || achievements[item]?.isUnlocked) return;

  store.dispatch(
    doUnlock({
      attribute: item,
      property: 'isUnlocked',
      value: true,
    }),
  );
  store.dispatch(setUnseen(item));
  // sendAlert('unlock', item);
  if (currentUnlock.unlocks) {
    currentUnlock.unlocks.forEach((unlock: string) => {
      unlockItem(unlock);
    });
  }
};

