export const unlockAchievement = (achievement: string) => {
  const currentAchievement = store.getState().achievements[achievement];
  if (currentAchievement?.isUnlocked) return;
  store.dispatch({
    type: 'achievements/updateAchievement',
    payload: {
      achievement,
      property: 'isUnlocked',
      value: true,
    },
  });
  store.dispatch({
    type: 'achievements/updateAchievement',
    payload: {
      achievement,
      property: 'isCurrentlyUnlocked',
      value: true,
    },
  });
  sendAlert('unlock', achievement);
};

export const setResourceValue = (resource: string, amount: number) => {
  const { resources } = store.getState();
  const currentResource = resources[resource];
  let newAmount = amount;
  if (currentResource.isCapped && currentResource.currentCap) {
    newAmount = Math.min(amount, currentResource.currentCap);
  }
  store.dispatch(
    updateResource({
      resource,
      property: 'amount',
      value: newAmount,
    }),
  );
};

export const getNpc = (location?: string) => {
  const currentLocation = location ?? storeValue('location', 'current');
  const locationData = storeValue('location', 'list')[currentLocation];
  const npc = structuredClone(locationData.npc);
  return npc;
};

export const npcInteraction = (
  dialogue: string | null,
  relationshipAdded: number,
  location?: string,
) => {
  const currentLocation = location ?? storeValue('location', 'current');
  const currentNpc = getNpc(currentLocation);

  // if relationship added is not a number, set it to 0
  if (typeof relationshipAdded !== 'number') {
    relationshipAdded = 0;
  }

  const npcValuesAdd = {
    dialogue: dialogue ?? currentNpc.dialogue,
    relationship: currentNpc.relationship + relationshipAdded,
    isNewDialogue: !!dialogue,
  };

  store.dispatch(
    updateNpc({
      location: currentLocation,
      npc: npcValuesAdd,
    }),
  );
};

export const getRewardAmount = (resource: Resource, rewardTier: number) => {
  let amount = resource.rewardAmount || balance.rewardAmountBase;
  if (resource.name === 'coins') {
    amount += rewardTier * 25;
    amount *= Math.random();
  } else {
    let exponent = rewardTier - (resource.tier ? (resource.tier - 1) * 3 : 0);
    if (exponent < 0) {
      exponent = 0;
    }
    amount *=
      (resource.rewardExponent ? resource.rewardExponent : 2.3) ** exponent *
      Math.random();
  }
  amount = Math.ceil(amount);
  amount = makeNumCircular(amount, 2);

  const minimumAmount = 1;

  // make sure spiritual resources have a minimum amount
  if (resource.type === 'spiritual') {
    amount += rewardTier + 10 - resource.tier * 10;
  }
  amount = Math.max(amount, minimumAmount);
  return amount;
};

