export const unlockedResourceTier = (rewardTier: number) => {
  return Math.ceil((rewardTier + 1) / 10) || 1;
};

export const createItem = (item: string) => {
  store.dispatch(
    addItem({
      item,
    }),
  );
};

export const addAcquiredResources = (
  key: string,
  setAcquiredResources: any,
  resources: any,
  animationType = 'upgrade-acquired',
) => {
  setAcquiredResources({
    [key]: resources,
  });
  store.dispatch(
    startAnimation({
      element: key,
      type: animationType,
      value: 0,
      duration: 3000,
    }),
  );
};
