import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { Tooltip } from 'react-tooltip';
import { RootState, store } from '../../store';
import { setTutorialStep } from '../../store/gameSlice';
import { updateModal } from '../../store/navigationSlice';

const Tutorial: React.FC = () => {
  const step = useSelector((state: RootState) => state.game.tutorialStep);
  const navigation = useSelector((state: RootState) => state.navigation);
  const location = useSelector((state: RootState) => state.location);
  const tooltipLocations = [
    '.btn-calendar',
    '.panel-challenge .requirements',
    '.btn-achievements',
    '.main-nav-town',
    '.btn-icon.home',
    '.upgrade-box:nth-child(2)',
    '.socialEnergy',
    '.btn-sleep',
    '.main-nav-town',
  ];
  const [tooltipLocation, setTooltipLocation] = useState('');
  const [tooltipIsOpen, setTooltipIsOpen] = useState(false);

  useEffect(() => {
    const isVisible = !!document.querySelector(tooltipLocations[step - 1]);
    if (isVisible) {
      setTooltipLocation(tooltipLocations[step - 1]);
      setTooltipIsOpen(true);
    } else if (!isVisible) {
      setTooltipIsOpen(false);
      setTooltipLocation('');
    }
  });

  useEffect(() => {
    switch (step) {
      case 4:
        if (navigation.mainPanel.current === 'town') {
          store.dispatch(setTutorialStep(5));
        }
        break;
      case 5:
        if (
          location.current === 'home' &&
          navigation.mainPanel.current === 'location'
        ) {
          store.dispatch(setTutorialStep(6));
        }
        break;
      default:
        break;
    }
  }, [navigation, location, step]);

  const renderContent = () => {
    switch (step) {
      case 1:
        return (
          <>
            <p>The time in the game is divided into days.</p>
            <button
              type="button"
              className="btn btn-primary btn-tiny"
              onClick={() => {
                store.dispatch(setTutorialStep(2));
              }}
            >
              Next &gt;
            </button>
          </>
        );
      case 2:
        return (
          <>
            <p>On some days there will be a challenge to overcome.</p>
            <p>If you fail it, the run will end.</p>
            <button
              type="button"
              className="btn btn-primary btn-tiny"
              onClick={() => {
                store.dispatch(setTutorialStep(3));
              }}
            >
              Next &gt;
            </button>
          </>
        );
      case 3:
        return (
          <>
            <p>If you are successful, you will unlock achievements.</p>
            <p>Achievements can provide a bonus on your next run.</p>
            <div className="d-flex justify-content-end">
              <button
                type="button"
                className="btn btn-primary btn-tiny"
                onClick={() => {
                  store.dispatch(setTutorialStep(4));
                }}
              >
                Next &gt;
              </button>
            </div>
          </>
        );
      case 4:
        return <>Click at the Town.</>;
      case 5:
        return (
          <>
            <p>
              Different town locations are relevant for different routes through
              the game.
            </p>
            To continue, click at Your home.
          </>
        );
      case 6:
        return (
          <>
            <p>
              Progress in the game is made by clicking buttons at Town
              locations.
            </p>
            <p>Clicking a button will cost resources and provide a reward.</p>
            <div className="d-flex justify-content-end">
              <button
                type="button"
                className="btn btn-primary btn-tiny"
                onClick={() => {
                  store.dispatch(setTutorialStep(7));
                }}
              >
                Next &gt;
              </button>
            </div>
          </>
        );
      case 7:
        return (
          <>
            <p>
              While you will soon have thousands of other resources, social
              energy will remain limited, so use it wisely.
            </p>
            <div className="d-flex justify-content-end">
              <button
                type="button"
                className="btn btn-primary btn-tiny"
                onClick={() => {
                  store.dispatch(setTutorialStep(8));
                }}
              >
                Next &gt;
              </button>
            </div>
          </>
        );
      case 8:
        return (
          <>
            <p>
              When you have used up all your energy for the day, click on END
              DAY. A new day will start with all your energy restored.
            </p>
            <p>(Don't do it yet)</p>
            <div className="d-flex justify-content-center">
              <button
                type="button"
                className="btn btn-primary btn-tiny"
                onClick={() => {
                  store.dispatch(setTutorialStep(9));
                }}
              >
                Next
              </button>
            </div>
          </>
        );
      case 9:
        return (
          <>
            <p>Now you are on your own.</p>
            <p>
              Can you find the right buttons to press to get through the game?
            </p>
            <button
              type="button"
              className="btn btn-primary btn-tiny"
              onClick={() => {
                store.dispatch(setTutorialStep(0));
              }}
            >
              Maybe
            </button>
          </>
        );
      default:
        return null;
    }
  };
  return (
    <Tooltip
      anchorSelect={tooltipLocation}
      id={`tooltip-tutorial-${step}`}
      place={step === 2 ? 'right' : 'bottom'}
      className={`tutorial step-${step}`}
      offset={5}
      isOpen={tooltipIsOpen}
    >
      <div className="title">
        <span>Tutorial</span>
        <span>
          ({step}/{tooltipLocations.length})
        </span>
      </div>
      {renderContent()}
    </Tooltip>
  );
};

export default Tutorial;
