import React from 'react';
import { useSelector } from 'react-redux';
import { Tooltip } from 'react-tooltip';
import type { RootState } from '../../../store';
import { Resource } from '../../../types';
import { getIcon } from '../../../utils';
import { playSfx } from '../../../utils/sound';

type ResourceSelectorProps = {
  singleSelectedResource: string | null;
  setSingleSelectedResource: (key: string) => void;
  resourceType: string;
  resourceLabel: string | null;
};

const ResourceSelector: React.FC<ResourceSelectorProps> = ({
  singleSelectedResource,
  setSingleSelectedResource,
  resourceType,
  resourceLabel,
}) => {
  const resources = useSelector((state: RootState) => state.resources);
  const unlocks = useSelector((state: RootState) => state.unlocks);

  return (
    <>
      <div className="resource-selector-title">
        {resourceLabel ? (
          <>
            <span>Select</span> {resourceLabel}:
          </>
        ) : (
          <>
            <span>{resourceType}</span> resources:
          </>
        )}
      </div>
      <div className="resource-selector">
        <ul className="selector-list">
          {Object.entries(resources as Record<string, Resource>)
            .filter(
              ([key, value]) =>
                unlocks[key].isUnlocked && resourceType === value.type,
            )
            .map(([key, value]) => {
              return (
                <li key={key} className="resource-item selector">
                  <input
                    checked={singleSelectedResource === key}
                    name="singleTradeResource"
                    type="radio"
                    id={`singleTrade${key}Check`}
                    value={key}
                    onChange={() => {
                      setSingleSelectedResource(key);
                      playSfx('click');
                    }}
                  />
                  <label
                    className="selector-icon has-tooltip"
                    htmlFor={`singleTrade${key}Check`}
                    onMouseEnter={() => playSfx('hover')}
                    data-tooltip-id={`tooltip-single-trade-list-${key}`}
                  >
                    <div
                      className="icon"
                      style={
                        {
                          '--var-color': value.color,
                          '--var-icon': `url(${getIcon(value.icon)})`,
                        } as React.CSSProperties
                      }
                    />
                    <Tooltip
                      className="wrap"
                      id={`tooltip-single-trade-list-${key}`}
                      place="top-start"
                    >
                      {value.displayName}
                    </Tooltip>
                  </label>
                </li>
              );
            })}
        </ul>
        {Object.entries(resources as Record<string, Resource>).filter(
          ([key, value]) =>
            unlocks[key].isUnlocked && resourceType === value.type,
        ).length === 0 && <div className="none-found">(none found yet)</div>}
      </div>
    </>
  );
};

export default ResourceSelector;
