import React from 'react';
import { store } from '../../store';
import { playSfx } from '../../utils/sound';
import { updateModal } from '../../store/navigationSlice';
import { setVersionChanged } from '../../store/gameSlice';

const ModalCloseBtn: React.FC = () => {
  return (
    <button
      type="button"
      className="btn-close"
      aria-label="Close"
      onMouseOver={() => {
        playSfx('hover');
      }}
      onClick={() => {
        playSfx('click');
        store.dispatch(
          updateModal({
            value: { show: false, type: '' },
          }),
        );
        store.dispatch(setVersionChanged(false));
      }}
    />
  );
};

export default ModalCloseBtn;
