import { configureStore, combineReducers } from '@reduxjs/toolkit';
import {
  persistStore,
  persistReducer,
  FLUSH,
  REHYDRATE,
  PAUSE,
  PERSIST,
  PURGE,
  REGISTER,
} from 'redux-persist';
import storage from 'redux-persist/lib/storage'; // defaults to localStorage for web
import locationReducer from './locationSlice';
import resourceReducer from './resourceSlice';
import upgradeReducer from './upgradeSlice';
import animationReducer from './animationSlice';
import attributeReducer from './attributeSlice';
import navigationReducer from './navigationSlice';
import settingsReducer from './settingsSlice';
import skillReducer from './skillSlice';
import achievementSlice from './achievementSlice';
import itemSlice from './itemSlice';
import gameReducer from './gameSlice';
import unlockReducer from './unlockSlice';
import questReducer from './questSlice';


const persistConfig = {
  key: 'quintillionQuest',
  storage,
};

const rootReducer = combineReducers({
  game: gameReducer,
  location: locationReducer,
  resources: resourceReducer,
  upgrades: upgradeReducer,
  animations: animationReducer,
  attributes: attributeReducer,
  navigation: navigationReducer,
  settings: settingsReducer,
  skills: skillReducer,
  achievements: achievementSlice,
  items: itemSlice,
  unlocks: unlockReducer,
  quests: questReducer,
});

const combinedReducer = (state: any, action: any) => {
  if (action.type === 'REPLACE_STATE') {
    return action.payload;
  }
  return rootReducer(state, action);
};

const persistedReducer = persistReducer(persistConfig, combinedReducer);

export const store = configureStore({
  reducer: persistedReducer,
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware({
      serializableCheck: {
        ignoredActions: [FLUSH, REHYDRATE, PAUSE, PERSIST, PURGE, REGISTER],
      },
    }),
});

export const persistor = persistStore(store);

export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;
