import React from 'react';
import { numberDisplay, textDisplay } from '../../utils';
import { areRequirementsMet } from '../../utils/upgradeUtil';
import { Model } from '../../types';

interface ButtonCostProps {
  type: string;
  model: Model;
}
const ButtonCost: React.FC<ButtonCostProps> = ({ type, model }) => {
  const cost = model.cost || model.costs || {};
  const requirements = model.requirements || [];
  let showPrice = true;
  return (
    <>
      {(() => {
        if (model.amount && model.limit && model.amount >= model.limit) {
          showPrice = false;
          if (model.limit === 1) {
            return 'You got it';
          }
          return 'You got it all';
        }
        if (Object.keys(cost).length > 0) {
          return `${type} (`;
        }
        if (requirements && !areRequirementsMet(requirements)) {
          return 'Not yet';
        }
        return 'Yes please';
      })()}
      {cost &&
        showPrice &&
        Object.entries(cost).map(([key, value]) => {
          const upgradeText = `-<span class="num">${value.currentCost && numberDisplay(value.currentCost)}</span>${textDisplay(key)}`;
          return (
            <span key={key} dangerouslySetInnerHTML={{ __html: upgradeText }} />
          );
        })}
      {showPrice && Object.keys(cost).length > 0 && ')'}
    </>
  );
};
export default ButtonCost;
