import { FC, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { Tooltip } from 'react-tooltip';
import { numberDisplay } from '../../utils';
import type { RootState } from '../../store';
import TooltipContent from '../util/tooltipContent';
import { addAttribute } from '../../utils/gameUtil';

interface AttributeProps {
  attributeName: string;
}

const AttributeBox: FC<AttributeProps> = ({ attributeName }) => {
  const attribute = useSelector(
    (state: RootState) => state.attributes[attributeName],
  );

  const [isHovered, setIsHovered] = useState(false);

  useEffect(() => {
    if (process.env.NODE_ENV !== 'development') return () => {};
    const handleKeyUp = (event: KeyboardEvent) => {
      if (isHovered && event.key === '-') {
        addAttribute(attribute.name, 1, 'cheats');
      }
      if (isHovered && event.key === '+') {
        addAttribute(attribute.name, 10, 'cheats');
      }
      if (isHovered && event.key === '*') {
        addAttribute(attribute.name, 100, 'cheats');
      }
    };
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keyup', handleKeyUp);
    };
  });
  return (
    <div
      className="col-6 attribute-box d-flex justify-content-between align-items-center"
      data-tooltip-id={`tooltip-${attributeName}`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <span>{attribute.displayName}</span>
      <span className="num">{numberDisplay(attribute.currentAmount)}</span>
      <Tooltip id={`tooltip-${attributeName}`} place="right" offset={0}>
        <TooltipContent content={attribute} />
      </Tooltip>
    </div>
  );
};
export default AttributeBox;
