import React, { useRef, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { getPlayerAttack } from '../../../../utils/location/fighting';
import { RootState } from '../../../../store';

interface LogItem {
  text: string;
  isPlayer: boolean;
}

interface BattleLogProps {
  battleLog: LogItem[];
}

const BattleLog: React.FC<BattleLogProps> = ({ battleLog }) => {
  // Create internal ref - no longer optional
  const logRef = useRef<HTMLDivElement>(null);
  const navigation = useSelector((state: RootState) => state.navigation);

  // Auto-scroll to bottom when log changes
  useEffect(() => {
    if (logRef.current) {
      logRef.current.scrollTop = logRef.current.scrollHeight;
    }
  }, [battleLog]);

  return (
    <div className="card battle-log">
      <div className="card-header d-flex justify-content-between align-items-center">
        <div>Logs</div>
        {!navigation.modal.show && (
          <div className="your-attack">Your ATK: {getPlayerAttack()}</div>
        )}
      </div>
      <div className="card-body battle-log-text" ref={logRef}>
        {battleLog.map((item, i) => (
          <div
            key={i + item.text}
            className={`battle-log-item${
              item.isPlayer ? ' player-text' : ' mob-text'
            }${item.text.includes('defeated') ? ' red' : ''}${
              item.text.includes('gain') ? ' green' : ''
            }`}
          >
            {item.text}
          </div>
        ))}
      </div>
    </div>
  );
};

export default BattleLog;
