import React, { FC } from 'react';
import { store } from '../../store';
import DynamicText from '../util/dynamicText';
import days from '../../conf/dayConf';
import { restartGame } from '../../utils/gameState';
import { textDisplay, getIcon } from '../../utils';
import { playSfx } from '../../utils/sound';

const GameOverModal: FC<{}> = () => {
  const dayNum = store.getState().game.day;
  const { achievements } = store.getState();
  const infoText = days[dayNum].gameOverText || '';
  return (
    <div className="modal-content game-over">
      <div className="modal-header">
        <h5 className="modal-title" title="Game Over">
          Game Over
        </h5>
      </div>
      <div className="modal-body">
        <DynamicText text={infoText} />

        {Object.values(achievements).some(
          (achievement) => achievement.isCurrentlyUnlocked,
        ) && (
          <div className="achievements-display-list sep-top mt-3">
            <h2 className="title">Unlocked:</h2>
            {Object.entries(achievements).map(([, achievement]) => {
              if (achievement.isCurrentlyUnlocked) {
                return (
                  <div
                    className="achievement-display card"
                    key={achievement.name}
                  >
                    <div
                      className="icon"
                      style={
                        {
                          '--var-color': achievement.color,
                          '--var-icon': `url(${getIcon(achievement.icon)})`,
                        } as React.CSSProperties
                      }
                    />
                    <div className="info">
                      <div className="name">{achievement.displayName}</div>
                      <div
                        className="description"
                        dangerouslySetInnerHTML={{
                          __html: textDisplay(achievement.description),
                        }}
                      />
                    </div>
                  </div>
                );
              }
              return null;
            })}
          </div>
        )}
      </div>
      <div className="modal-footer">
        <button
          type="button"
          className="btn btn-primary"
          onClick={() => {
            playSfx('press');
            restartGame();
          }}
        >
          Start a new game
        </button>
      </div>
    </div>
  );
};
export default GameOverModal;
