import { createSlice } from '@reduxjs/toolkit';
import type { PayloadAction } from '@reduxjs/toolkit';
import { Achievement, AchievementList } from '../types';
import achievements from '../conf/achievementConf';
import { updateSliceVersion } from './common';

const initialState: AchievementList = achievements;

export const achievementSlice = createSlice({
  name: 'achievements',
  initialState,
  reducers: {
    // reducer to change the value of a achievement.
    // it has arguments: achievement name, property name, and value
    updateAchievement: (
      state,
      action: PayloadAction<{
        achievement: string;
        property: keyof Achievement;
        value: any;
      }>,
    ) => {
      const { achievement, property, value } = action.payload;
      (state[achievement][property] as any) = value;
    },
    resetAchievements: (state) => {
      const newAchievements = structuredClone(initialState);
      Object.keys(newAchievements).forEach((key) => {
        newAchievements[key].isUnlocked = state[key]?.isUnlocked || false;
        newAchievements[key].isLastUsed = state[key]?.isLastUsed || false;
      });
      return newAchievements;
    },

    updateVersion: (state) => {
      return updateSliceVersion(state, initialState);
    },
  },
});

// Action creators are generated for each case reducer function
export const { updateAchievement, resetAchievements, updateVersion } =
  achievementSlice.actions;

export default achievementSlice.reducer;
