import { store } from '../store';
import { startAnimation } from '../store/animationSlice';
import { updateCost, updateUpgrade } from '../store/upgradeSlice';
import { updateAllCurrent } from './gameState';
import { insertAddMod, getPropertyModded } from './modUtil';
import { Modifier, ModConf, Requirement } from '../types';
import modList from '../conf/modConf';
import clickMods from '../conf/clickModConf';
import CostHandler from './costHandler';
import { Cost } from '../types';

export const buyUpgrade = (upgradeName: string, setAcquiredResources: any) => {
  const { dispatch } = store;
  const { upgrades } = store.getState();

  // get the upgrade from the list
  const upgrade = upgrades[upgradeName];

  // check if limit is reached
  if (upgrade.limit && upgrade.amount >= upgrade.limit) {
    return;
  }
  const costHandler = new CostHandler();
  // loop over all costs
  Object.entries(upgrade.cost || {}).forEach(([key, value]) => {
    costHandler.addCost(key, (value as Cost).currentCost);
  });

  // check if the player has enough resources
  if (!costHandler.canPayCosts()) {
    return;
  }

  const increasedObjects: { [key: string]: number } = {};
  upgrade.addMods?.forEach((mod) => {
    insertAddMod(mod);
    increasedObjects[mod.modObjectName] = upgrade.power;
  });

  upgrade.clickMods?.forEach((modName) => {
    const mod = clickMods[modName];
    mod({ upgrade, setAcquiredResources });
  });

  // reduce the amount of the upgrade cost from the resource
  costHandler.payAllCosts();

  // increase the amount of the upgrade
  dispatch(
    updateUpgrade({
      upgrade: upgradeName,
      property: 'amount',
      value: upgrade.amount + 1,
    }),
  );

  // loop over increased objects and animate them
  Object.entries(increasedObjects).forEach(([key, value]) => {
    dispatch(
      startAnimation({
        element: key,
        type: '+',
        value,
        duration: 500,
      }),
    );
  });

  // if limit was reached then add 1000 to sorting order
  if (upgrade.limit && upgrade.amount + 1 >= upgrade.limit) {
    dispatch(
      updateUpgrade({
        upgrade: upgradeName,
        property: 'order',
        // current order + 1000
        value: (upgrade.order || 0) + 1000,
      }),
    );
  }

  updateAllCurrent();
};

export const updateCurrentPrice = (): void => {
  const { dispatch } = store;
  const { upgrades } = store.getState();
  // loop over all upgrades
  Object.entries(upgrades).forEach(([upgrade, value]) => {
    if (!value.mods) {
      return;
    }
    // sort mods by priority ascending
    const mods = structuredClone(value.mods);
    mods.sort((a: ModConf, b: ModConf) => a.priority - b.priority);
    // loop value.cost and apply mods to each cost object
    Object.entries(value.cost || {}).forEach(([cost, costValue]) => {
      let newValue = costValue.cost;
      mods.forEach((mod: ModConf) => {
        if (
          !mod.modProperty.startsWith('cost') ||
          !mod.modProperty.endsWith(cost)
        )
          return;
        const modFunc: Modifier = modList[mod.modName];
        if (!modFunc) return;
        newValue = modFunc(newValue, mod.data);
      });
      dispatch(
        updateCost({
          upgrade,
          resource: cost,
          property: 'currentCost',
          value: newValue,
        }),
      );
    });
  });
};

export const updateProperties = (): void => {
  const { dispatch } = store;
  const { upgrades } = store.getState();
  // loop over all upgrades
  Object.entries(upgrades).forEach(([upgrade, value]) => {
    // sort mods by priority ascending
    if (!value.mods) {
      return;
    }
    const newValue = getPropertyModded(value, 'currentPower', value.power);
    dispatch(
      updateUpgrade({
        upgrade,
        property: 'currentPower',
        value: newValue,
      }),
    );

    if (value.additionalPower) {
      const newAdditionalPower = getPropertyModded(
        value,
        'currentAdditionalPower',
        value.additionalPower,
      );
      if (
        newAdditionalPower !== undefined &&
        value.additionalPower !== newAdditionalPower
      ) {
        dispatch(
          updateUpgrade({
            upgrade,
            property: 'currentAdditionalPower',
            value: newAdditionalPower,
          }),
        );
      }
    }

    if (value.limit) {
      const newLimit = getPropertyModded(value, 'limit', value.limit);
      if (newLimit !== undefined && value.limit !== newLimit) {
        dispatch(
          updateUpgrade({
            upgrade,
            property: 'limit',
            value: newLimit,
          }),
        );
      }
    }

    value.mods.forEach((mod: ModConf) => {
      // if mod name starts with 'cost' then update the cost
      if (mod.modProperty.startsWith('requirements')) {
        // example : modProperty: 'requirements::engagementRing::amount',
        const [_, objectName, propertyName] = mod.modProperty.split('::');
        const newRequirements = structuredClone(value.requirements || []);
        // find the requirement with the same objectName and property
        newRequirements.forEach((requirement, index) => {
          if (requirement.objectName === objectName) {
            // update the amount with the new value
            newRequirements[index][propertyName] = modList[mod.modName](
              requirement[propertyName],
              mod.data,
            );
          }
        });
        dispatch(
          updateUpgrade({
            upgrade,
            property: 'requirements',
            value: newRequirements,
          }),
        );
      }
    });
  });
};

export const updateUpgrades = (): void => {
  updateProperties();
  updateCurrentPrice();
};

export const areRequirementsMet = (requirements: Requirement[]): boolean => {
  if (!requirements) return true;
  const locations = store.getState().location.list;
  // loop over all requirements
  for (let i = 0; i < requirements.length; i += 1) {
    const requirement = requirements[i];
    switch (requirement.objectType) {
      case 'Npc':
        if (
          locations[requirement.objectName].npc.relationship <
          requirement.amount
        ) {
          return false;
        }
        break;
      case 'Attribute':
        if (
          store.getState().attributes[requirement.objectName].currentAmount <
          requirement.amount
        ) {
          return false;
        }
        break;
      case 'Upgrade':
        const upgrade = store.getState().upgrades[requirement.objectName];
        const propertyValue = upgrade[requirement.property];
        if (propertyValue < requirement.amount) {
          return false;
        }
        break;
      default:
        break;
    }
  }
  return true;
};

export const manageUpgrades = (): void => {
  const upgrades = store.getState().upgrades;
  const { dispatch } = store;
  Object.entries(upgrades).forEach(([upgradeName, upgrade]) => {
    // if amount reached limit, set group to 'Completed'
    if (
      upgrade.limit &&
      upgrade.amount + 1 >= upgrade.limit &&
      upgrade.group !== 'Completed'
    ) {
      dispatch(
        updateUpgrade({
          upgrade: upgradeName,
          property: 'group',
          value: 'Completed',
        }),
      );
    }
  });
};
