import React, { FC, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { Badge, Card } from 'react-bootstrap';
import { getIcon, numberDisplay } from '../../utils';
import type { RootState } from '../../store';
import { addResource } from '../../utils/gameUtil';
import Gps from './gps';
import { updateResource } from '../../store/resourceSlice';
import { store } from '../../store';

interface ResourceProps {
  resourceName: string;
  abbreviate?: boolean;
}

const ResourceBox: FC<ResourceProps> = ({ resourceName, abbreviate }) => {
  const resource = useSelector(
    (state: RootState) => state.resources[resourceName],
  );

  const [isHovered, setIsHovered] = useState(false);

  useEffect(() => {
    if (process.env.NODE_ENV !== 'development') return () => {};
    const handleKeyUp = (event: KeyboardEvent) => {
      if (isHovered && event.key === '+') {
        addResource(resourceName, 10000);
      }
      // if key is multiply key, multiply the value by 2
      if (isHovered && event.key === '*') {
        addResource(resourceName, resource.amount);
      }
      if (isHovered && event.key === '0') {
        store.dispatch(
          updateResource({
            resource: resourceName,
            property: 'amount',
            value: 0,
          }),
        );
      }
    };
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keyup', handleKeyUp);
    };
  });

  return (
    <div
      className="col-6 col-xl-4 mb-1 resource-box-wrapper p-0"
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <Card
        style={{ '--var-color': resource.color } as React.CSSProperties}
        className="resource-box"
        data-tooltip-id={`tooltip-${resourceName}`}
      >
        <Card.Body>
          <div className="d-flex justify-content-between align-items-center">
            <Card.Title className="">
              <span
                className={`model-icon ${resource.color}`}
                style={{ WebkitMaskImage: `url(${getIcon(resource.icon)})` }}
              />
              {abbreviate && resource.abbreviation
                ? resource.abbreviation
                : resource.displayName}
            </Card.Title>
            <Gps resource={resource} />
          </div>
          <Badge bg="light num">{numberDisplay(resource.amount)}</Badge>
        </Card.Body>
      </Card>
    </div>
  );
};
export default ResourceBox;
