import { FC } from 'react';
import { store } from '../../../store';
import { moveLocation, updateLocation } from '../../../store/locationSlice';
import { setNavigationValue } from '../../../store/navigationSlice';
import { playSfx } from '../../../utils/sound';
import { hasUnseen } from '../../../utils';

type LocationButtonProps = {
  location: string;
  onMouseEnter: () => void;
  onMouseLeave: () => void;
};

const LocationButton: FC<LocationButtonProps> = ({
  location,
  onMouseEnter,
  onMouseLeave,
}) => {
  // eslint-disable-next-line import/no-dynamic-require, global-require
  const btnIcon = require(`../../../assets/img/location/${location}.svg`);
  const currentLocation = store.getState().location.current;
  return (
    <button
      type="button"
      onMouseOver={() => {
        playSfx('hover');
        onMouseEnter();
      }}
      onMouseLeave={() => {
        onMouseLeave();
      }}
      className={`btn btn-icon ${
        location
      }${currentLocation === location ? ' active' : ''}
      ${hasUnseen(location) ? ' new' : ''}`}
      onClick={() => {
        playSfx('location');
        store.dispatch(moveLocation(location));
        store.dispatch(
          setNavigationValue({
            navigation: 'mainPanel',
            property: 'current',
            value: 'location',
          }),
        );
        const locationState = store.getState().location.list[location];
        const npc = structuredClone(locationState.npc);
        if (npc) {
          npc.dialogue = 'greeting';
          npc.isNewDialogue = true;
          store.dispatch(
            updateLocation({
              location,
              property: 'npc',
              value: npc,
            }),
          );
        }
      }}
    >
      <img src={btnIcon} alt="" />
      <span>
        {
          {
            home: 'Your home',
            temple: 'Temple',
            mines: 'Mines',
            forest: 'Forest',
            library: 'Library',
            townHall: 'Town Hall',
            smithy: 'Smithy',
            market: 'Market',
          }[location]
        }
      </span>
    </button>
  );
};
export default LocationButton;
