import { FC, useEffect } from 'react';
import { useSelector } from 'react-redux';
import type { RootState } from '../../store';
import { store } from '../../store';
import { startAnimation } from '../../store/animationSlice';

const ClickIndicator: FC<{}> = () => {
  const animations = useSelector((state: RootState) => state.animations);

  useEffect(() => {
    const handleClick = (e) => {
      // place the click indicator to the mouse position
      const clickIndicator = document.querySelector(
        '.click-indicator',
      ) as HTMLElement;
      if (clickIndicator === null) return;

      clickIndicator.style.left = `${e.clientX}px`;
      clickIndicator.style.top = `${e.clientY}px`;

      store.dispatch(
        startAnimation({
          element: 'clickIndicator',
          type: 'clickIndicator',
          value: 1,
          duration: 500,
        }),
      );
    };

    // Add click listener to document
    document.addEventListener('click', handleClick);

    // Cleanup function to remove the event listener
    return () => {
      document.removeEventListener('click', handleClick);
    };
  }, []);

  return (
    <div
      className={`click-indicator${
        animations.clickIndicator && animations.clickIndicator.active
          ? ' is-animating '
          : ' '
      }`}
    />
  );
};
export default ClickIndicator;
