import React, { FC, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { Tooltip } from 'react-tooltip';
import { store } from '../../store';
import { useAchievement, removeAchievement } from '../../store/gameSlice';
import { updateAchievement } from '../../store/achievementSlice';
import { updateModal } from '../../store/navigationSlice';
import { getIcon } from '../../utils';
import type { RootState } from '../../store';
import TooltipContent from '../util/tooltipContent';
import { playSfx } from '../../utils/sound';
import AchievementIcon from '../model/achievementIcon';
import balance from '../../conf/balanceConf';

const GameStartModal: FC<{}> = () => {
  const usedAchievements = useSelector(
    (state: RootState) => state.game.usedAchievements,
  );
  const achievements = useSelector((state: RootState) => state.achievements);

  // when this is first initialized, go over all achievements and do useAchievement for each that has isLastUsed: true
  useEffect(() => {
    setTimeout(() => {
      Object.entries(achievements).forEach(([name, achievement]) => {
        if (achievement.isLastUsed) {
          store.dispatch(useAchievement(name));
        }
      });
    }, 100);
  }, []);

  const selectorClick = (e: any) => {
    let name = e.target?.value;
    if (!name) name = e;
    // if usedAchievements has the name, remove it
    if (usedAchievements.includes(name)) {
      store.dispatch(removeAchievement(name));
      store.dispatch(
        updateAchievement({
          achievement: name,
          property: 'isLastUsed',
          value: false,
        }),
      );
    } else if (usedAchievements.length <= balance.achievements.appliedMax) {
      // eslint-disable-next-line react-hooks/rules-of-hooks
      store.dispatch(useAchievement(name));
      store.dispatch(
        updateAchievement({
          achievement: name,
          property: 'isLastUsed',
          value: true,
        }),
      );
    }
  };
  return (
    <div className="modal-content new-game">
      <div className="modal-header">
        <h5 className="modal-title">New game</h5>
      </div>
      <div className="modal-body">
        Applied achievements:
        <div className="achievement-list used-achievements card mb-3">
          <div className="card-body">
            {usedAchievements.map((name) => {
              return name in achievements ? (
                <AchievementIcon
                  name={name}
                  key={name}
                  onclick={() => {
                    playSfx('click');
                    selectorClick(name);
                  }}
                />
              ) : null;
            })}
            {usedAchievements.length === 0 && (
              <div className="empty-message">None. Select below</div>
            )}
          </div>
        </div>
        Choose up to {balance.achievements.appliedMax} to apply for this game:
        <div className="achievement-list achievement-select selector-list card">
          <div className="card-body">
            {Object.entries(achievements).map(([name, achievement]) => {
              if (achievement.isUnlocked) {
                return (
                  <div
                    className="achievement-selector selector"
                    key={name}
                    data-tooltip-id={`tooltip-achievement-list-${name}`}
                  >
                    <input
                      type="checkbox"
                      id={`${name}Check`}
                      value={name}
                      checked={usedAchievements.includes(name) || false}
                      onChange={(e) => {
                        playSfx('press');
                        selectorClick(e);
                      }}
                    />

                    {/* eslint-disable-next-line jsx-a11y/label-has-associated-control */}
                    <label
                      className="achievement-icon has-tooltip"
                      htmlFor={`${name}Check`}
                    >
                      <div
                        className="icon"
                        style={
                          {
                            '--var-color': achievement.color,
                            '--var-icon': `url(${getIcon(achievement.icon)})`,
                          } as React.CSSProperties
                        }
                        data-tooltip-id={`tooltip-achievement-list-${name}`}
                      />
                      <Tooltip id={`tooltip-achievement-list-${name}`}>
                        <TooltipContent content={achievement} />
                      </Tooltip>
                    </label>
                  </div>
                );
              }
              return null;
            })}
          </div>
        </div>
      </div>
      <div className="modal-footer">
        <button
          type="button"
          className="btn btn-primary"
          disabled={usedAchievements.length === 0}
          onClick={
            // close modal
            () => {
              playSfx('start');
              store.dispatch(
                updateModal({
                  value: { show: false, type: '' },
                }),
              );
            }
          }
        >
          Start the game
        </button>
      </div>
    </div>
  );
};
export default GameStartModal;
