import { store } from '../store';
import { addSkillSlot } from '../store/gameSlice';
import { RewardsArray } from '../types';
import { addResource, npcInteraction, addAttribute } from './gameUtil';
import { updateResource } from '../store/resourceSlice';
import { updateResources } from './gameState';
import { updateFeatureValue } from '../store/locationSlice';
import CostHandler from './costHandler';

class RewardHandler {
  rewards: RewardsArray;

  constructor(rewards: RewardsArray) {
    this.rewards = rewards;
  }

  giveRewards() {
    let rewardsGiven = false;
    this.rewards.forEach((reward: any) => {
      if (typeof reward === 'string') {
        return;
      }
      const { resource } = reward;
      const { attribute } = reward;
      const amount = reward.currentAmount || reward.amount;
      if (!resource && attribute) {
        addAttribute(attribute, amount, reward.source);
      } else {
        if (!resource || !amount) return;
        const isTicket = CostHandler.isTicket(resource);
        if (isTicket) {
          const current =
            store.getState().location.list[isTicket.locationName].values?.[
              isTicket.ticketName
            ];
          store.dispatch(
            updateFeatureValue({
              location: isTicket.locationName,
              property: isTicket.ticketName,
              value: current + amount,
            }),
          );
        } else {
          switch (resource) {
            case 'relationship':
              npcInteraction(null, amount, reward.attribute);
              break;
            case 'skillSlot':
              store.dispatch(addSkillSlot(reward.attribute));
              break;
            default:
              if (reward.property) {
                const { resources } = store.getState();
                store.dispatch(
                  updateResource({
                    resource,
                    property: reward.property,
                    value: resources[resource][reward.property] + amount,
                  }),
                );
                updateResources();
              } else {
                addResource(resource, amount);
              }
              break;
          }
        }
      }
      rewardsGiven = true;
    });
    return rewardsGiven;
  }

  getAcquiredResources() {
    const resources = [] as { resource: string; amount: number }[];
    this.rewards.forEach((reward: any) => {
      resources.push({
        resource: reward.resource,
        amount: reward.currentAmount || reward.amount,
      });
    });
    return resources;
  }
}

export default RewardHandler;
