import React, { FC, useEffect, useRef } from 'react';
import { useSelector } from 'react-redux';
import { RootState, store } from '../../store';
import StatusBox from '../model/statusBox';
import ResourceBox from '../model/resourceBox';
import MonsterDisplay from '../navigation/location/monster';
import dayConf from '../../conf/dayConf';
import SkillList from '../model/skillList';
import { updateModal, confirmModal } from '../../store/navigationSlice';
import {
  setValue,
  resetMonster,
  playerAttack,
  getPlayerAttack,
} from '../../utils/location/fighting';
import MonsterHealth from '../navigation/location/inc/monsterHealth';
import BattleLog from '../navigation/location/inc/battleLog';
import monsters from '../../conf/monsterConf';
import { Monster } from '../../types';
import FightAnimations from '../navigation/location/inc/fightAnimations';
import { playSfx } from '../../utils/sound';
import { commonActions, gameOverAction } from '../../conf/dayActions';

const FightModal: FC<{}> = () => {
  const potionsToShow = ['healthPotion', 'manaPotion'];
  const resources = useSelector((state: RootState) => state.resources);
  const values = useSelector(
    (state: RootState) => state.location.list.forest.values,
  );
  const unlocks = useSelector((state: RootState) => state.unlocks);
  const game = useSelector((state: RootState) => state.game);
  const skillSlot = useSelector((state: RootState) => state.game.skillSlots);
  const [battleStarted, setBattleStarted] = React.useState(0);
  const [battleLog, setBattleLog] = React.useState([] as any);
  const dayNum = game.day;
  const action = game.choices[dayNum];
  const [monster, setMonster] = React.useState<Monster | null>(null);

  const addToLog = (text: string, isPlayer: boolean) => {
    setBattleLog((prev) => [...prev, { text, isPlayer }]);
  };

  useEffect(() => {
    const day = dayConf[dayNum];
    const currentAction = day.eventActions?.find((act) => act.type === action);
    const monsterType = currentAction?.actionType || '';

    if (battleStarted === 0) {
      setMonster(monsters[monsterType]);
      setBattleStarted(1);
      setValue('battleIsActive', true);
      setValue('canDie', true);
      const chk = resetMonster(monsterType, dayNum + 3);
      if (chk) {
        setTimeout(() => {
          playerAttack(addToLog, setBattleStarted, true);
        }, 2000);
      }
    }
  }, []);

  return (
    <div className="modal-content fight-modal">
      <div className="modal-header">
        <h5 className="modal-title">
          Day {game.day}: {dayConf[game.day].eventDescription}
        </h5>
      </div>
      <div className="modal-body">
        <div className="battle-cont">
          <div className="night-bg" />
          <div className="ground" />
          <div className="row">
            <div className="col-7">
              <div className="battle">
                <div className="card-header">
                  <div className="monster-name">
                    {monster?.displayName}
                    <span className="stats">
                      (ATK:<span className="num">{values.monsterAttack}</span>)
                    </span>
                  </div>
                  <MonsterHealth
                    values={values}
                    battleStarted={battleStarted}
                  />
                </div>
                <div className="card-body position-relative">
                  <FightAnimations battleState={battleStarted} />
                  <MonsterDisplay />
                </div>
              </div>
            </div>
            <div className="col-5 battle-log-box">
              <BattleLog battleLog={battleLog} />
            </div>
          </div>
        </div>
        <div className="fight-you row">
          <div className="your-health col-5">
            <div className="your-attack">
              Your stats:
              <div>
                ATK: <span className="num">{getPlayerAttack()}</span>
              </div>
            </div>
            <StatusBox resourceName="healthPoints" />
            {unlocks.mana.isUnlocked && <StatusBox resourceName="mana" />}
          </div>
          <div className="your-potions col-3">
            Potions:
            <div className="potions row">
              {potionsToShow
                .filter((potion) => resources[potion].amount > 0)
                .map((potion) => (
                  <ResourceBox
                    resourceName={potion}
                    key={potion}
                    abbreviate={true}
                  />
                ))}
              {potionsToShow.every(
                (potion) => resources[potion].amount === 0,
              ) && <div className="none-found">None</div>}
            </div>
          </div>

          <div className="your-skills col-4">
            <div className="label">Skills:</div>
            {Object.keys(skillSlot).some((key) => skillSlot[key]) ? (
              battleStarted < 2 && <SkillList />
            ) : (
              <div className="none-found">None set</div>
            )}
          </div>
        </div>
      </div>
      <div className="modal-footer">
        {battleStarted > 1 && (
          <button
            type="button"
            className="btn btn-primary btn-small btn-continue"
            onClick={() => {
              store.dispatch(
                confirmModal({
                  value: {
                    type: '',
                    show: false,
                  },
                }),
              );
              playSfx('click');
              if (battleStarted === 2) {
                commonActions(action);
              } else {
                gameOverAction();
              }
            }}
          >
            Continue
          </button>
        )}
      </div>
    </div>
  );
};
export default FightModal;
