import { FC, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { Tooltip } from 'react-tooltip';
import { playSfx } from '../../../utils/sound';
import { store, RootState } from '../../../store';
import { setSeen } from '../../../store/unlockSlice';
import {
  generateTable,
  getFullCost,
  isCompleted,
  resetBoard,
  hasActiveCard,
  canBuyFlip,
  hasTwoActiveCards,
  flipCard,
} from '../../../utils/location/realize';
import CostHandler from '../../../utils/costHandler';
import balance from '../../../conf/balanceConf';
import AcquiredResource from '../../util/acquiredResource';
import { RealizeTableCell } from '../../../types';
import ModelIcon from '../../model/modelIcon';
import CostTooltip from '../../util/costTooltip';
import { numberDisplay, textDisplay } from '../../../utils';

const Realize: FC<{ isActive: boolean }> = ({ isActive }) => {
  const unlocks = useSelector((state: RootState) => state.unlocks);
  const resources = useSelector((state: RootState) => state.resources);
  const values = useSelector(
    (state: RootState) => state.location.list.temple.values,
  );
  const animations = useSelector((state: RootState) => state.animations);
  const [costHandler, setCostHandler] = useState<CostHandler>(null);

  const [btnCostHandler, setBtnCostHandler] = useState<CostHandler>(null);

  const [isTooltipOpen, setIsTooltipOpen] = useState<boolean>(false);
  const [acquiredResources, setAcquiredResources] = useState<
    Record<string, any>
  >({});

  const isHinted = (i, j) => {
    const hintDirections = values.hintDirections || [];
    const activeCell = hasActiveCard();

    if (!activeCell) return false;
    return (
      (hintDirections.includes('up') &&
        j === activeCell.j &&
        i < activeCell.i) ||
      (hintDirections.includes('down') &&
        j === activeCell.j &&
        i > activeCell.i) ||
      (hintDirections.includes('left') &&
        i === activeCell.i &&
        j < activeCell.j) ||
      (hintDirections.includes('right') &&
        i === activeCell.i &&
        j > activeCell.j)
    );
  };

  const hintAnimationNum = (i, j) => {
    return ((i + j) % 3) + 1;
  };

  useEffect(() => {
    // if on this tab, mark as seen
    if (!unlocks.realize.isSeen && isActive) {
      store.dispatch(setSeen('realize'));
    }

    if (!values.table?.length) {
      generateTable();
    }
  });

  useEffect(() => {
    const btnHandler = new CostHandler();
    btnHandler.addCost('socialEnergy', balance.realize.newTableCost);
    setBtnCostHandler(btnHandler);
  }, []);

  return (
    <div className="realize">
      <div className="realize-header">
        <h1>Realize</h1>
      </div>
      <div className="realize-body">
        <div className={`realize-table${isCompleted() ? ' completed' : ''}`}>
          <div className="realizations" data-tooltip-id="tooltip-realizations">
            <div className="realizations-icon" />
            <div className="realizations-quantity num">
              {values.realizations}
            </div>
            <Tooltip id="tooltip-realizations" place="top" className="wrap">
              Realizations
            </Tooltip>
          </div>
          {values.table?.map((row: any, i: number) => (
            <div key={i} className="realize-row">
              {row?.map((cell: RealizeTableCell, j: number) => (
                <div className="realize-cell" key={j}>
                  {!i && !j && (
                    <div className="level-number">
                      Level {values.tableCounter}
                    </div>
                  )}
                  <button
                    type="button"
                    className={`realize-card${
                      cell.open ? ' open' : ''
                    }${cell.active ? ' active' : ''} ${isHinted(i, j) ? `hinted anim-${hintAnimationNum(i, j)}` : ''}${animations[`cardWrong-${i}-${j}`] && animations[`cardWrong-${i}-${j}`].active ? ' is-wrong' : ''}${animations[`cardMatched-${i}-${j}`] && animations[`cardMatched-${i}-${j}`].active ? ' is-matched' : ''}${canBuyFlip() ? '' : ' cannot-flip'}`}
                    onMouseEnter={() => {
                      if (!cell.open && !cell.active && !hasTwoActiveCards()) {
                        setIsTooltipOpen(true);
                        setCostHandler(getFullCost(values.tableCounter));
                        playSfx('hover');
                      }
                    }}
                    onClick={() => {
                      if (
                        cell.open ||
                        cell.active ||
                        hasTwoActiveCards() ||
                        !canBuyFlip()
                      ) {
                        return;
                      }
                      setIsTooltipOpen(false);
                      playSfx('flip');
                      flipCard(i, j, setAcquiredResources);
                    }}
                    onMouseLeave={() => {
                      setIsTooltipOpen(false);
                    }}
                    data-tooltip-id={
                      !cell.open && !cell.active && !hasTwoActiveCards()
                        ? `tooltip-cost`
                        : undefined
                    }
                  >
                    <div className="flip-card card-back" />
                    <div className="flip-card card-front">
                      <AcquiredResource
                        acquiredResources={acquiredResources}
                        isOpen={cell.open}
                        animationKey={`card-${i}-${j}`}
                      />
                      <div className="card-content">
                        <ModelIcon model={resources[cell.rewardResource]} />
                        <div className="reward-amount">
                          <span className="num">
                            {numberDisplay(cell.rewardAmount)}
                          </span>
                        </div>
                      </div>
                    </div>
                  </button>
                </div>
              ))}
            </div>
          ))}
          <div className={`table-completed ${!isCompleted() ? ' d-none' : ''}`}>
            Completed{' '}
            {!values.isRedo && (
              <>(+{Math.ceil(values.tableCounter / 10)} WIS)</>
            )}
          </div>
        </div>
        <CostTooltip isTooltipOpen={isTooltipOpen} costHandler={costHandler} />
        <button
          type="button"
          className={`btn btn-primary btn-small btn-generate${isCompleted() ? '' : ' invisible'}`}
          disabled={!btnCostHandler?.canPayCosts()}
          onMouseEnter={() => {
            playSfx('hover');
          }}
          onClick={() => {
            playSfx('click');
            btnCostHandler?.payAllCosts();
            generateTable();
          }}
        >
          Next
          <span
            dangerouslySetInnerHTML={{
              __html: textDisplay('(-[[20]]socialEnergy)'),
            }}
          />
        </button>
        <button
          className={`btn btn-primary btn-small btn-generate btn-reset${isCompleted() ? '' : ' invisible'}`}
          disabled={!btnCostHandler?.canPayCosts()}
          onMouseEnter={() => {
            playSfx('hover');
          }}
          type="button"
          onClick={() => {
            playSfx('click');
            btnCostHandler?.payAllCosts();
            generateTable(false);
          }}
        >
          Redo{' '}
          <span
            dangerouslySetInnerHTML={{
              __html: textDisplay('(-[[20]]socialEnergy)'),
            }}
          />
        </button>
      </div>
    </div>
  );
};

export default Realize;
