const keepKeys = [
  'addAmount',
  'amount',
  'cap',
  'choices',
  'confirm',
  'cooldown',
  'current',
  'currentAmount',
  'currentCap',
  'currentColor',
  'currentCost',
  'currentDescription',
  'currentPower',
  'day',
  'dayAction',
  'dayStarted',
  'dayInitialized',
  'description',
  'dialogue',
  'flirtDays',
  'gainMultiplier',
  'gps',
  'group',
  'isLastUsed',
  'isUnlocked',
  'isCurrentlyUnlocked',
  'isPaused',
  'isSeen',
  'skillSlots',
  'lastUsed',
  'limit',
  'modal',
  'mods',
  'order',
  'relationship',
  'rewards',
  'usedAchievements',
  'alerts',
  'balanceMods',
  'values',
  'tutorialStep',
  'isLocked',
  'versionChanged',
  'requirements',
];

const updateSliceVersion = (state: any, initial: any): any => {
  // Create a new object that will maintain the initial state's property order
  const newState: any = {};
  let versionHasChanged = false;

  // First, copy all properties from initial state, replacing with current state values as appropriate
  // eslint-disable-next-line no-restricted-syntax
  for (const [key, value] of Object.entries(initial)) {
    if (keepKeys.includes(key)) {
      // Keep the existing state value if it exists
      newState[key] = state[key] !== undefined ? state[key] : value;
    } else if (
      typeof value === 'object' &&
      value !== null &&
      !Array.isArray(value)
    ) {
      if (
        typeof state[key] === 'object' &&
        state[key] !== null &&
        !Array.isArray(state[key])
      ) {
        newState[key] = updateSliceVersion(state[key], value);
      } else {
        // Deep clone to avoid reference issues
        newState[key] = JSON.parse(JSON.stringify(value));
      }
    } else {
      // For primitive values, use initial value
      newState[key] = value;

      // Handle version change detection
      if (key === 'version' && state[key] !== value) {
        versionHasChanged = true;
        console.log(`States version changed to ${value}`);
      }
    }
  }

  // Add any keep keys from state that weren't in initial
  Object.keys(state).forEach((key) => {
    if (
      keepKeys.includes(key) &&
      !Object.prototype.hasOwnProperty.call(newState, key)
    ) {
      newState[key] = state[key];
    }
  });

  if (versionHasChanged) {
    newState.versionChanged = true;
    console.log(`State version changed to ${newState.version}`);
  }
  return newState;
};

export { updateSliceVersion };
