import React from 'react';
import { useSelector } from 'react-redux';
import { Tooltip } from 'react-tooltip';
import { RootState, store } from '../../store';
import { setSeen } from '../../store/unlockSlice';
import { getIcon } from '../../utils';
import TooltipContent from '../util/tooltipContent';
import { playSfx } from '../../utils/sound';

interface AchievementIconProps {
  name: string;
  onclick?: () => void;
}

const AchievementIcon: React.FC<AchievementIconProps> = ({ name, onclick }) => {
  const achievements = useSelector((state: RootState) => state.achievements);
  const achievement = achievements[name];
  const usedAchievements = useSelector(
    (state: RootState) => state.game.usedAchievements,
  );
  const unlocks = useSelector((state: RootState) => state.unlocks);
  return (
    <>
      <div
        className={`achievement-icon${!achievement.isUnlocked ? ' locked' : ''}
          ${!unlocks[name]?.isSeen ? ' new' : ''}
          ${usedAchievements.includes(name) ? ' used' : ''}`}
        key={name}
        data-tooltip-id={`tooltip-achievement-${name}`}
        onMouseEnter={() => {
          playSfx('hover');
          if (!unlocks[name]?.isSeen) {
            store.dispatch(setSeen(name));
          }
        }}
        onClick={onclick}
      >
        <div
          className={`icon ${achievement.color}`}
          style={
            {
              '--var-color': achievement.color,
              '--var-icon': `url(${getIcon(achievement.icon)})`,
            } as React.CSSProperties
          }
        />
      </div>
      <Tooltip
        className={`large${!achievement.isUnlocked ? ' locked' : ''}
        ${usedAchievements.includes(name) ? ' used' : ''}`}
        id={`tooltip-achievement-${name}`}
      >
        <TooltipContent content={achievement} />
      </Tooltip>
    </>
  );
};

export default AchievementIcon;
