export const addAttributeMod = (
  attribute: string,
  amount: number,
  mod: string,
  model: string,
): AddModifier => {
  return {
    modObjectType: 'Attribute',
    modObjectName: attribute,
    modProperty: 'currentAmount',
    modName: mod,
    data: {
      identifier: model,
      amount,
    },
    priority: 0,
  };
};

