import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';

interface AnimationState {
  [key: string]: {
    type: string;
    value: number;
    duration: number;
    timeoutId: ReturnType<typeof setTimeout>;
    active: boolean;
  };
}

const initialState: AnimationState = {};

const animationSlice = createSlice({
  name: 'animations',
  initialState,
  reducers: {
    startAnimation: (
      state,
      action: PayloadAction<{
        element: string;
        newState: {
          type: string;
          value: number;
          duration: number;
          timeoutId: ReturnType<typeof setTimeout>;
          active: boolean;
        };
      }>,
    ) => {
      const { element, newState } = action.payload;
      // Clear existing timeout if it exists
      if (state[element]?.timeoutId) {
        clearTimeout(state[element].timeoutId);
        // Mark the element as inactive
        state[element].active = false;
      }
      // Set a temporary state to indicate the element is being reset
      state[element] = { ...newState, active: false };
    },
    resetAnimations: () => {
      return initialState;
    },
    finalizeAnimation: (
      state,
      action: PayloadAction<{
        element: string;
        newState: {
          type: string;
          value: number;
          duration: number;
          timeoutId: ReturnType<typeof setTimeout>;
          active: boolean;
        };
      }>,
    ) => {
      const { element, newState } = action.payload;
      // Set the new state and mark the element as active
      state[element] = { ...newState, active: true };
    },
    endAnimation: (state, action: PayloadAction<string>) => {
      const element = action.payload;
      delete state[element];
    },
  },
});

export const startAnimation = createAsyncThunk(
  'animations/startAnimation',
  async (
    {
      element,
      type,
      value,
      duration,
    }: { element: string; type: string; value: number; duration: number },
    { dispatch },
  ) => {
    const newState = {
      type,
      value,
      duration,
      timeoutId: setTimeout(() => {
        dispatch(animationSlice.actions.endAnimation(element));
      }, duration),
      active: true,
    };
    dispatch(animationSlice.actions.startAnimation({ element, newState }));
    // Wait for a short delay to allow the DOM to update
    await new Promise((resolve) => setTimeout(resolve, 50)); // Adjust the delay as needed

    // Finalize the animation state
    dispatch(animationSlice.actions.finalizeAnimation({ element, newState }));
  },
);

// Action creators are generated for each case reducer function
export const {
  startAnimation: startAnimationAction,
  finalizeAnimation,
  endAnimation,
  resetAnimations,
} = animationSlice.actions;
export const animationReducer = animationSlice.reducer;

export default animationSlice.reducer;
