import { store } from '../../store';
import { MineTile, MineGrid } from '../../types';
import balance from '../../conf/balanceConf';
import { updateFeatureValue } from '../../store/locationSlice';
import { startAnimation } from '../../store/animationSlice';
import { addResource, getRewardAmount } from '../gameUtil';
import CostHandler from '../costHandler';

const tileTypes = ['mithril', 'titanium', 'iron', 'stone'];

const getFullCost = (depth: number) => {
  const costHandler = new CostHandler();
  costHandler.addExpCost('physicalEnergy', 'mining', depth);
  costHandler.addCost('ticket_miningLicenses', depth);
  return costHandler;
};

const generateTileType = (currentDepth: number) => {
  const { minOdds } = balance.mining;
  const { maxOdds } = balance.mining;
  let tileType = tileTypes[tileTypes.length - 1];
  tileTypes.forEach((type) => {
    if (tileType !== tileTypes[tileTypes.length - 1]) {
      return;
    }
    if (
      currentDepth > balance.mining[`${type}MaxDepth`] ||
      currentDepth < balance.mining[`${type}MinDepth`]
    ) {
      return;
    }
    const range =
      balance.mining[`${type}MaxDepth`] - balance.mining[`${type}MinDepth`];
    const currentRowOdds =
      minOdds +
      ((maxOdds - minOdds) *
        (currentDepth - balance.mining[`${type}MinDepth`])) /
        range;

    if (Math.random() * 100 < currentRowOdds) {
      tileType = type;
    }
  });
  return tileType;
};

const setGridVisibility = (grid: MineGrid) => {
  const newGrid = structuredClone(grid);
  const { visibilityRange } = balance.mining;

  for (let i = 0; i < grid.length; i += 1) {
    for (let j = 0; j < grid[i].length; j += 1) {
      // if there is a tile with open: true within visibility range, set visible: true
      if (grid[i][j].open) {
        for (let x = i - visibilityRange; x <= i + visibilityRange; x += 1) {
          for (let y = j - visibilityRange; y <= j + visibilityRange; y += 1) {
            if (
              x >= 0 &&
              x < grid.length &&
              y >= 0 &&
              y < grid[i].length &&
              !newGrid[x][y].open
            ) {
              newGrid[x][y].visible = true;
            }
          }
        }
      }
      // set every tile that is adjacent to a tile.open=true to tile.clickable = true
      if (grid[i][j].open) {
        // Check the four directly adjacent tiles (up, down, left, right)
        const directions = [
          { x: -1, y: 0 }, // up
          { x: 1, y: 0 }, // down
          { x: 0, y: -1 }, // left
          { x: 0, y: 1 }, // right
        ];

        directions.forEach((dir) => {
          const x = i + dir.x;
          const y = j + dir.y;
          if (
            x >= 0 &&
            x < grid.length &&
            y >= 0 &&
            y < grid[i].length &&
            !newGrid[x][y].open &&
            x !== 0
          ) {
            newGrid[x][y].clickable = true;
          }
        });
      }
    }
  }
  return newGrid;
};

const generateTiles = (grid: MineGrid, currentGrid?: MineGrid) => {
  const deepestOpen = getDeepestOpenTile(grid);
  // always have rowsGenerated rows under the deepestOpen
  const newRowsToGenerate =
    balance.mining.rowsGenerated - (grid.length - deepestOpen - 1);
  let newGrid = structuredClone(currentGrid) || structuredClone(grid);

  let currentRowIndex = deepestOpen === -1 ? 0 : deepestOpen + 1;

  for (let i = 0; i < newRowsToGenerate; i += 1) {
    if (currentRowIndex >= balance.mining.maxDepth) {
      break;
    }
    const rowIndex = currentRowIndex;
    const newRow = Array.from({ length: balance.mining.cols }).map(() => {
      const type = generateTileType(rowIndex);
      return {
        type,
        open: false,
        visible: false,
      };
    });

    currentRowIndex += 1;
    newGrid.push(newRow);
  }

  newGrid = setGridVisibility(newGrid);

  store.dispatch(
    updateFeatureValue({
      location: 'mines',
      property: 'grid',
      value: newGrid,
    }),
  );
};

const openTile = (x: number, y: number, resources, grid: MineGrid) => {
  // if tile is not clickable then do nothing
  if (!grid[x][y].clickable || grid[x][y].open) {
    return false;
  }
  // if not enough licenses or physical energy, do nothing
  const costHandler = getFullCost(x);
  if (!costHandler.canPayCosts()) {
    return false;
  }

  costHandler.payAllCosts();

  const newGrid = structuredClone(grid);
  newGrid[x][y].open = true;

  // add resources you found on the tile
  const tileType = newGrid[x][y].type;
  const resource = resources[tileType];
  const amountAdded = getRewardAmount(resource, x);

  const addedResources = [];
  addedResources.push({
    resource: tileType,
    amount: amountAdded,
  });

  addResource(tileType, amountAdded);
  const diamondChance = Math.min(x, 20); // Cap at 20%
  const gotDiamond = Math.random() * 100 < diamondChance;
  if (gotDiamond) {
    addResource('diamond', 1);
    addedResources.push({
      resource: 'diamond',
      amount: 1,
    });
  }
  const gotOil = Math.random() * 100 < balance.mining.oilChance;
  if (gotOil) {
    const oilAmount = getRewardAmount(
      resources.oil,
      x - balance.mining.oilAmountReduction,
    );
    addResource('oil', 1);
    addedResources.push({
      resource: 'oil',
      amount: oilAmount,
    });
  }

  const goldChance = Math.min(x, 30); // Cap at 30%
  const gotGold = Math.random() * 150 < goldChance;
  if (gotGold) {
    const goldAmount = getRewardAmount(resources.gold, x);
    addResource('gold', goldAmount);
    addedResources.push({
      resource: 'gold',
      amount: goldAmount,
    });
  }
  store.dispatch(
    updateFeatureValue({
      location: 'mines',
      property: 'grid',
      value: newGrid,
    }),
  );
  // animate the loot
  store.dispatch(
    startAnimation({
      element: `tile-${x}-${y}`,
      type: 'tile',
      value: 0,
      duration: 3000,
    }),
  );

  generateTiles(grid, newGrid);
  return addedResources;
};

const getDeepestOpenTile = (grid: MineGrid) => {
  return (
    grid.length -
    1 -
    grid
      .slice()
      .reverse()
      .findIndex((row: MineTile[]) => row.some((tile: MineTile) => tile.open))
  );
};

export { generateTiles, openTile, getDeepestOpenTile, tileTypes, getFullCost };
