import { FC, useState } from 'react';
import { useSelector } from 'react-redux';
import { Navbar } from 'react-bootstrap';
import type { RootState } from '../../store';
import { Resource } from '../../types';
import StatusBox from './statusBox';

const StatusList: FC<{}> = () => {
  const resources = useSelector((state: RootState) => state.resources);
  const unlocks = useSelector((state: RootState) => state.unlocks);

  const [isCollapsed, setIsCollapsed] = useState(false);
  const handleToggle = () => {
    setIsCollapsed(!isCollapsed);
  };

  return (
    <div className="capped-resources-container">
      <Navbar expand="">
        <Navbar.Toggle
          className="d-flex justify-content-between w-100"
          aria-controls="capped-resources"
          onClick={handleToggle}
        >
          <h2 className="title">Status</h2>
          {/* eslint-disable-next-line jsx-a11y/anchor-is-valid */}
          <a className="btn btn-icon btn-toggle" aria-label="Toggle" />
        </Navbar.Toggle>

        <Navbar.Collapse in={!isCollapsed}>
          <div className="capped-resources" id="capped-resources">
            {
              // loop over all resources where iscapped is true
              Object.values(resources)
                .sort(
                  (a: Resource, b: Resource) => (a.order || 0) - (b.order || 0),
                ) // Add null check for 'order' property
                .filter(
                  (resource: Resource) =>
                    resource.isCapped && unlocks[resource.name].isUnlocked,
                )
                .map((resource: Resource) => (
                  <StatusBox resourceName={resource.name} key={resource.name} />
                ))
            }
          </div>
        </Navbar.Collapse>
      </Navbar>
    </div>
  );
};
export default StatusList;
