import React, { FC, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { RootState, store } from '../../../store';
import { setSeen } from '../../../store/unlockSlice';
import { textDisplay } from '../../../utils';
import ModelIcon from '../../model/modelIcon';
import {
  getCostHandler,
  initializeLevel,
  startLevel,
  setValue,
  resumeGame,
  restartLevel,
  rotate,
  moveLeft,
  moveRight,
  drop,
  clearGrid,
  touchClasses,
  isPopping,
  blocksLeft,
  attributeAdded,
} from '../../../utils/location/analyzing';
import { playSfx } from '../../../utils/sound';

const Analyzing: FC<{ isActive: boolean }> = ({ isActive }) => {
  const values = useSelector(
    (state: RootState) => state.location.list.library.values,
  );
  const unlocks = useSelector((state: RootState) => state.unlocks);
  const gameState = values.analyzeStatus;
  const resources = useSelector((state) => state.resources);
  const costHandler = getCostHandler();
  const requirementsMet = costHandler.canPayCosts();
  const [keypresses, setKeypresses] = React.useState<string[]>([]);
  const [scoreWasAdded, setScoreWasAdded] = React.useState(false);

  useEffect(() => {
    // if on this tab, mark as seen
    if (!unlocks.analyzing.isSeen && isActive) {
      store.dispatch(setSeen('analyzing'));
    }
  });

  // if the game is stopped, do initialization
  useEffect(() => {
    if (gameState === 'stopped') {
      initializeLevel();
    }
  }, [gameState]);

  // if leaving the tab, set game state to paused
  useEffect(() => {
    if (!isActive && gameState === 'running') {
      setValue('analyzeStatus', 'paused');
    } else if (isActive && gameState === 'paused') {
      setValue('analyzeStatus', 'running');
      // resume the game tick
      resumeGame();
      setValue('timeSessionStarted', Date.now());
    }
  }, [isActive]);

  useEffect(() => {
    const handleKeyUp = (event: KeyboardEvent) => {
      if (gameState !== 'running') return;

      let keyPressed = '';

      switch (event.key) {
        case 'w':
        case 'ArrowUp':
          rotate();
          keyPressed = 'w';
          break;
        case 'a':
        case 'ArrowLeft':
          moveLeft();
          keyPressed = 'a';
          break;
        case 'd':
        case 'ArrowRight':
          moveRight();
          keyPressed = 'd';
          break;
        case 's':
        case 'ArrowDown':
          drop();
          keyPressed = 's';
          break;
        default:
          return;
      }

      // Only update UI state if a valid key was pressed
      if (keyPressed) {
        event.preventDefault();
        setKeypresses((prev) => [...prev, keyPressed]);

        setTimeout(() => {
          // Remove the key from the keypresses after a short delay
          setKeypresses((prev) => prev.filter((key) => key !== keyPressed));
        }, 100);
      }
    };

    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [gameState]);

  useEffect(() => {
    if (values.addScore > 0) {
      setScoreWasAdded(true);
      const timer = setTimeout(() => {
        setScoreWasAdded(false);
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [values.addScore]);

  return (
    <div className="analyzing">
      <div className="analyzing-content">
        <div className="row">
          <div className="col-6 col-xl-5 field">
            <div className={`analyze-field state-${gameState}`}>
              <div className="level">
                Level{' '}
                {values.analyzeStatus === 'initialized'
                  ? values.currentLevel + 1
                  : values.currentLevel}
              </div>
              <div className="status">
                <div>
                  {(() => {
                    if (gameState === 'failed') {
                      return 'Analysis Failed';
                    }
                    if (gameState === 'won') {
                      return 'Level Completed';
                    }
                    if (gameState === 'completed') {
                      return 'Analysis Complete';
                    }
                    return 'Analysis Pending';
                  })()}
                </div>
              </div>
              {values.grid?.map((row, i) => {
                if (row.length === 0) return null;
                return row.map((cell, j) =>
                  cell ? (
                    <div
                      key={`${i}-${j}`}
                      className={`idea idea-${cell.replace('Idea', '').toLowerCase()} ${touchClasses(i, j)} ${isPopping(i, j) ? 'popping' : ''}`}
                      style={{
                        left: `${j * 16.66}% `,
                        top: `calc(${i * 8.33}% + 1px)`,
                      }}
                    >
                      <ModelIcon model={resources[cell]} />
                    </div>
                  ) : null,
                );
              })}
            </div>
          </div>
          <div className="col-6 col-xl-7 tools">
            <div className="analyzing-header">
              <h1>
                Analyzing
                <span
                  className={
                    values.analyzeStatus === 'completed' ? 'd-none' : ''
                  }
                >
                  Level{' '}
                  {values.currentLevel +
                    (values.analyzeStatus === 'initialized' ? 1 : 0)}
                </span>
              </h1>
              <div
                className={`analyzing-info ${gameState !== 'completed' ? 'd-none' : ''}`}
              >
                <p>You have completed all the levels. </p>
                <p>Congratulations! You are amazing.</p>
                <p>Your analysis powers sure are formidable!</p>
              </div>
              <div
                className={`analyzing-info ${gameState !== 'failed' ? 'd-none' : ''}`}
              >
                <div
                  className={`score ${values.requiredScore > values.score ? 'not-met' : 'met'}`}
                >
                  Final score:
                  <div className="num">{values.score}</div>
                </div>
                <div className="required-score">
                  Required<span className="d-none d-lg-inline"> score</span>:
                  <div className="num">{values.requiredScore}</div>
                </div>
                <p>
                  Your score was nice,
                  <br />
                  but not high enough.
                </p>

                <button
                  type="button"
                  className="btn btn-primary"
                  onMouseEnter={() => {
                    playSfx('hover');
                  }}
                  onClick={() => {
                    playSfx('click');
                    clearGrid();
                    restartLevel();
                  }}
                >
                  Retry
                </button>
              </div>
              <div
                className={`analyzing-info ${gameState !== 'won' ? 'd-none' : ''}`}
              >
                <div className="win">Success!</div>
                <div
                  className={`score ${values.requiredScore > values.score ? 'not-met' : 'met'}`}
                >
                  Final score:
                  <div className="num">{values.score}</div>
                </div>
                <div className="required-score">
                  Required score:
                  <div className="num">{values.requiredScore}</div>
                </div>
                <p>
                  You have acquired:
                  <br />
                  +
                  <span
                    dangerouslySetInnerHTML={{
                      __html: textDisplay(
                        `<span class="num">${attributeAdded(values.currentLevel)}</span> attrInt`,
                      ),
                    }}
                  />{' '}
                  and{' '}
                  <span
                    dangerouslySetInnerHTML={{
                      __html: textDisplay(
                        `<span class="num">${values.score}</span> coins`,
                      ),
                    }}
                  />{' '}
                </p>

                <button
                  type="button"
                  className="btn btn-primary"
                  onMouseEnter={() => {
                    playSfx('hover');
                  }}
                  onClick={() => {
                    playSfx('click');
                    initializeLevel();
                  }}
                >
                  Continue
                </button>

                {process.env.NODE_ENV === 'development' && (
                  <button
                    type="button"
                    className="btn btn-secondary"
                    onMouseEnter={() => {
                      playSfx('hover');
                    }}
                    onClick={() => {
                      playSfx('click');
                      clearGrid();
                      restartLevel();
                    }}
                  >
                    Restart Level
                  </button>
                )}
              </div>
              <div
                className={`analyzing-info ${gameState !== 'running' ? 'd-none' : ''}`}
              >
                <div className="row mb-2">
                  <div className="col-6">
                    <div className="next-brick">
                      {values.bricks.length > 0 ? (
                        <>
                          <span>
                            Next (
                            {values.totalBricks - values.bricks.length + 1}/
                            {values.totalBricks}):
                          </span>
                          <div
                            className={`idea idea-${values.bricks[0][1].replace('Idea', '').toLowerCase()}`}
                          >
                            <ModelIcon model={resources[values.bricks[0][1]]} />
                          </div>
                          <div
                            className={`idea idea-${values.bricks[0][0].replace('Idea', '').toLowerCase()}`}
                            style={{
                              top: '50px',
                            }}
                          >
                            <ModelIcon model={resources[values.bricks[0][0]]} />
                          </div>
                        </>
                      ) : (
                        <span>No more bricks</span>
                      )}
                    </div>
                    <div className="blocks-left">
                      <div className="label">Blocks left:</div>
                      <div className="blocks-list">
                        {(() => {
                          const blocks = blocksLeft();
                          const blockKeys = Object.keys(blocks);

                          // Check if there are no blocks left
                          if (blockKeys.length === 0) {
                            return <div className="no-blocks">None</div>;
                          }

                          // Check if there are soon no blocks left
                          if (
                            Object.values(blocks).reduce((a, b) => a + b, 0) ===
                            2
                          ) {
                            return <div className="no-blocks">Last ones</div>;
                          }

                          // Otherwise show the block list
                          return blockKeys.map((block, index) => (
                            <React.Fragment key={index}>
                              <div
                                className={`idea idea-${block.replace('Idea', '').toLowerCase()}`}
                              >
                                <ModelIcon model={resources[block]} />
                              </div>
                              <div className="num">x{blocks[block]}</div>
                            </React.Fragment>
                          ));
                        })()}
                      </div>
                    </div>
                  </div>
                  <div className="col-6">
                    <div className="score">
                      Score:
                      <div className="num">
                        {values.score}
                        <div
                          className={`add-score ${scoreWasAdded ? 'animating' : 'invisible'}`}
                        >
                          {values.addScore}
                        </div>
                      </div>
                    </div>
                    <div
                      className={`required-score ${values.requiredScore > values.score ? 'not-met' : 'met'}`}
                    >
                      Required score:
                      <div className="num">{values.requiredScore}</div>
                    </div>
                  </div>
                </div>

                <p
                  className="d-none d-lg-block"
                  style={{
                    fontSize: '1.4rem',
                  }}
                >
                  Match 4 or more of the same type.
                </p>
                <div className="virtual-keyboard">
                  <div className="label">Controls:</div>
                  <div className="row">
                    <div className="col-4" />
                    <div className="col-4">
                      <button
                        type="button"
                        className={`btn btn-rotate-left btn-secondary${keypresses.includes('q') ? ' active' : ''}`}
                        onClick={() => rotate()}
                      >
                        W<div>Rotate</div>
                      </button>
                    </div>
                    <div className="col-4" />
                  </div>
                  <div className="row">
                    <div className="col-4">
                      <button
                        type="button"
                        className={`btn btn-left btn-secondary${keypresses.includes('a') ? ' active' : ''}`}
                        onClick={() => moveLeft()}
                      >
                        A<div>Left</div>
                      </button>
                    </div>
                    <div className="col-4">
                      <button
                        type="button"
                        className={`btn btn-drop btn-secondary${keypresses.includes('s') ? ' active' : ''}`}
                        onClick={() => drop()}
                      >
                        S<div>Drop</div>
                      </button>
                    </div>
                    <div className="col-4">
                      <button
                        type="button"
                        className={`btn btn-right btn-secondary${keypresses.includes('d') ? ' active' : ''}`}
                        onClick={() => moveRight()}
                      >
                        D<div>Right</div>
                      </button>
                    </div>
                  </div>
                  <div className="none-found d-none d-sm-block text-center">
                    Use the above buttons,
                    <br /> WASD or arrow keys
                  </div>
                </div>
              </div>
              <div
                className={`analyzing-info ${gameState !== 'initialized' ? 'd-none' : ''}`}
              >
                <div>Required to start the level:</div>
                <ul className="analyzing-requirements requirements">
                  {Object.keys(costHandler.getCostList()).map((resource) => (
                    <li
                      key={resource}
                      className={`requirement ${resources[resource].amount >= costHandler.getCostList()[resource].currentCost ? 'met' : 'missing'}`}
                      dangerouslySetInnerHTML={{
                        __html: textDisplay(
                          `<span class="num">${costHandler.getCostList()[resource].currentCost} </span>x ${resource}<span class="none-found">(${resources[resource].amount}</span>)`,
                        ),
                      }}
                    />
                  ))}
                </ul>
                <p>
                  To win the level, you must score{' '}
                  <span className="num">{values.requiredScore}</span> points.
                </p>
                <p
                  style={{
                    fontSize: '1.4rem',
                  }}
                >
                  Match 4 or more of the same type.
                </p>
                <p>
                  To get more points, remove as many blocks with one move as
                  possible.
                </p>
                <p>
                  Winning the level will permanently grant +
                  <span
                    dangerouslySetInnerHTML={{
                      __html: textDisplay(
                        `<span class="num">${attributeAdded(
                          values.currentLevel + 1,
                        )}</span> attrInt`,
                      ),
                    }}
                  />{' '}
                  and{' '}
                  <span
                    dangerouslySetInnerHTML={{
                      __html: textDisplay('coins'),
                    }}
                  />{' '}
                  equal to your score.
                </p>
                {gameState === 'initialized' && (
                  <button
                    type="button"
                    className="btn btn-primary"
                    disabled={!requirementsMet}
                    onMouseEnter={() => {
                      playSfx('hover');
                    }}
                    onClick={() => {
                      if (requirementsMet) {
                        playSfx('click');
                        startLevel();
                      }
                    }}
                  >
                    Start level
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Analyzing;
