import { useEffect, useState, useRef } from 'react';
import { MemoryRouter as Router, Routes, Route } from 'react-router-dom';
import { useSelector, useDispatch } from 'react-redux';
import { Container, Row, Col } from 'react-bootstrap';
import type { RootState } from '../store';
import { store } from '../store';

import Modal from '../components/modal/modal';
import { setGameInitialized } from '../store/gameSlice';
import { resetAnimations } from '../store/animationSlice';
import Sound from '../utils/sound';
import { useTick as tick, gpsTempTick } from '../utils/gps';
import {
  initializeDay,
  updateVersion,
  updateAllCurrent,
  restartGame,
  startCalcs,
  endDay,
  revertDay,
} from '../utils/gameState';

import TopMenu from '../components/layout/topMenu';
import BottomMenu from '../components/layout/bottomMenu';
import AttributeList from '../components/model/attributeList';
import StatusList from '../components/model/statusList';
import ResourceList from '../components/model/resourceList';
import Navigation from '../components/navigation';
import Alerts from '../components/util/alerts';
import ClickIndicator from '../components/util/clickIndicator';
import ErrorModal from '../components/modal/errorModal';
import Tutorial from '../components/util/tutorial';
import Challenge from '../components/layout/challenge';
import { updateLocation } from '../store/locationSlice';

const Game = () => {
  const [loadingState, setLoadingState] = useState({
    domLoaded: false,
    gameInitialized: false,
    assetsLoaded: false,
  });
  const [componentInitialized, setComponentInitialized] = useState(false);

  const targetRate: number = 200;
  const lastTickRef = useRef<number>(0);
  const lastSecondTickRef = useRef<number>(0);
  const runningRef = useRef<boolean>(false);

  const gameState = useSelector((state: RootState) => state.game);

  const dispatch = useDispatch();

  useEffect(() => {
    dispatch(resetAnimations());
  }, [dispatch]);

  // Check if everything is loaded
  const isLoading =
    !loadingState.domLoaded ||
    !loadingState.gameInitialized ||
    !loadingState.assetsLoaded;
  const startTick = () => {
    if (runningRef.current) {
      lastTickRef.current = Date.now();
      runningRef.current = true;
      lastSecondTickRef.current = Date.now();
      const repeater = () => {
        if (!runningRef.current) {
          return;
        }
        const timeDelta = Date.now() - lastTickRef.current;
        tick(timeDelta);
        lastTickRef.current = Date.now();

        // this one only runs once per second
        const secondTimeDelta = Date.now() - lastSecondTickRef.current;
        if (secondTimeDelta >= 1000) {
          gpsTempTick(Math.floor(secondTimeDelta / 1000));
          lastSecondTickRef.current = Date.now();
        }

        setTimeout(() => {
          repeater();
        }, targetRate);
      };
      setTimeout(() => {
        repeater();
      }, targetRate);
    }
  };
  useEffect(() => {
    let isCtrlPressed = false;
    let isAltPressed = false;

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Control' || event.key === 'Meta') {
        isCtrlPressed = true;
      } else if (event.key === 'Alt') {
        isAltPressed = true;
      }
    };

    const handleKeyUp = (event: KeyboardEvent) => {
      // Handle Ctrl+Alt+U for updating all current values
      if (event.key === 'u' && isCtrlPressed && isAltPressed) {
        updateAllCurrent();
        console.log('Updated all current values');
      }

      // Add handler for Ctrl+Alt+R to restart the game
      if (event.key === 'r' && isCtrlPressed && isAltPressed) {
        // Import the restartGame function
        restartGame();
        console.log('Game restarted');
      }

      // ctrl alt q for startCalcs
      if (event.key === 'q' && isCtrlPressed && isAltPressed) {
        startCalcs();
        console.log('Started calculations');
      }

      // ctrl alt d for nextDay
      if (event.key === 'd' && isCtrlPressed && isAltPressed) {
        endDay();
        console.log('Skipped day');
      }
      // ctrl alt p for previousDay
      if (event.key === 'p' && isCtrlPressed && isAltPressed) {
        revertDay();
        console.log('Previous day');
      }

      // Reset key states
      if (event.key === 'Control' || event.key === 'Meta') {
        isCtrlPressed = false;
      } else if (event.key === 'Alt') {
        isAltPressed = false;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  useEffect(() => {
    try {
      if (!gameState.gameInitialized) {
        store.dispatch(setGameInitialized(true));
        updateVersion();
        setLoadingState((prev) => ({ ...prev, gameInitialized: true }));
      }

      if (!gameState.dayInitialized && !isLoading) {
        initializeDay();
      }

      // Set up the game ticker when initialization is complete
      if (!isLoading && !runningRef.current) {
        runningRef.current = true;
        startTick();
      }

      // Handle pause state
      if (gameState.isPaused) {
        runningRef.current = false;
      } else if (!isLoading) {
        runningRef.current = true;
      }
    } catch (e) {
      console.error('Game initialization error:', e);
      setLoadingState((prev) => ({ ...prev, gameInitialized: true }));
    }
  }, [
    gameState.gameInitialized,
    gameState.isPaused,
    isLoading,
    gameState.dayInitialized,
  ]);

  useEffect(() => {
    // Function to set domLoaded to true
    const setDomLoaded = () => {
      setLoadingState((prev) => ({ ...prev, domLoaded: true }));
    };

    // Check if DOM is already loaded
    if (document.readyState === 'complete') {
      setDomLoaded();
    } else {
      // Add event listener for DOM loading
      window.addEventListener('load', setDomLoaded);

      // Backup timeout in case event doesn't fire
      const timeoutId = setTimeout(() => {
        setDomLoaded();
      }, 3000);

      // Clean up
      return () => {
        window.removeEventListener('load', setDomLoaded);
        clearTimeout(timeoutId);
      };
    }
  }, []);

  useEffect(() => {
    // Instead of checking for DOM elements, use a timeout or different approach
    const timeoutId = setTimeout(() => {
      setLoadingState((prev) => ({ ...prev, assetsLoaded: true }));
    }, 1000); // Give it a second to load basic assets

    return () => clearTimeout(timeoutId);
  }, []);

  useEffect(() => {
    return () => {
      runningRef.current = false;
    };
  }, []);

  if (isLoading) {
    return (
      <div
        style={{
          minHeight: '100vh',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        <div className="panel p-5" style={{ color: '#000' }}>
          Loading...
        </div>
      </div>
    );
  }
  return (
    <>
      <Sound />
      <Container className="d-flex flex-column main-container">
        <Row className="pt-2 flex-grow-1 flex-column flex-md-row">
          <Col
            md={6}
            lg={4}
            xs={12}
            className="main-col-left d-flex flex-column"
          >
            <Challenge />
            <div className="panel panel-character">
              <div className="panel-body container">
                <AttributeList />
                <StatusList />
                <ResourceList />
              </div>
            </div>
            <div />
          </Col>
          <Col
            md={6}
            lg={8}
            xs={12}
            className="d-flex flex-column justify-content-center main-col-right"
          >
            <TopMenu />
            <Navigation />
            <BottomMenu />
          </Col>
        </Row>
      </Container>
      <Tutorial />
      <Alerts />
      <ClickIndicator />
      <Modal />
      <Modal purpose="confirm" />
      {gameState.hasError && <ErrorModal />}
    </>
  );
};

export default function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<Game />} />
      </Routes>
    </Router>
  );
}
