import { createSlice } from '@reduxjs/toolkit';
import type { PayloadAction } from '@reduxjs/toolkit';
import { Upgrade, UpgradeList, Cost } from '../types';
import upgrades from '../conf/upgradeConf';
import { updateSliceVersion } from './common';

const initialState: UpgradeList = upgrades;

export const upgradeSlice = createSlice({
  name: 'upgrades',
  initialState,
  reducers: {
    updateUpgrade: (
      state,
      action: PayloadAction<{
        upgrade: string;
        property: keyof Upgrade;
        value: any;
      }>,
    ) => {
      const { upgrade, property, value } = action.payload;
      (state[upgrade][property] as any) = value;
    },
    updateCost: (
      state,
      action: PayloadAction<{
        upgrade: string;
        resource: string;
        property: keyof Cost;
        value: any;
      }>,
    ) => {
      const { upgrade, resource, property, value } = action.payload;
      (state[upgrade].cost[resource][property] as any) = value;
    },
    resetUpgrades: () => {
      return initialState;
    },
    updateVersion: (state) => {
      return updateSliceVersion(state, initialState);
    },
  },
});

// Action creators are generated for each case reducer function
export const { updateUpgrade, resetUpgrades, updateCost, updateVersion } =
  upgradeSlice.actions;

export default upgradeSlice.reducer;
