import { FC } from 'react';
import { setHasError } from '../../store/gameSlice';
import { restartGame } from '../../utils/gameState';
import { store } from '../../store';
import discord from '../../assets/img/discord.svg';
import { playSfx } from '../../utils/sound';

interface ErrorModalProps {
  resetError: () => void | undefined;
}

const ErrorModal: FC<ErrorModalProps> = ({ resetError }) => {
  return (
    <div className="modal fade open show" style={{ display: 'block' }}>
      <div className="modal-dialog">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">An error has occured</h5>
          </div>
          <div className="modal-body">
            <p>You may be able to ignore the error and continue.</p>
            <p>
              If the error persists, try restarting the game. It will keep your
              achievements.
            </p>
            <div className="d-flex justify-content-between">
              <p>You can also report the error to the developer in Discord.</p>
              <a
                className="btn btn-icon"
                href="https://discord.gg/mPYEknkDMZ"
                target="_blank"
                rel="noreferrer"
              >
                <img src={discord} alt="Discord" />
              </a>
            </div>
          </div>
          <div className="modal-footer d-flex justify-content-between">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={() => {
                restartGame();
                store.dispatch(setHasError(false));
                if (resetError) resetError();
                playSfx('motion');
              }}
            >
              Restart the game
            </button>
            <button
              type="button"
              className="btn btn-primary"
              onClick={() => {
                playSfx('click');
                store.dispatch(setHasError(false));
                if (resetError) resetError();
              }}
            >
              Continue
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};
export default ErrorModal;
