import { store } from '../store';
import { updateSkill } from '../store/skillSlice';
import clickMods from '../conf/clickModConf';
import CostHandler from './costHandler';
import RewardHandler from './rewardHandler';
import { startAnimation } from '../store/animationSlice';

export const useSkill = (
  skill: string,
  setAcquiredResources: (resources: Record<string, any>) => boolean,
) => {
  // find if the skill is in the skillSlots
  const { skillSlots } = store.getState().game;
  const skillSlot = Object.keys(skillSlots).find(
    (key) => skillSlots[key] === skill,
  );
  if (!skillSlot) return false;

  // check if the skill is on cooldown by comparing its lastUsed and currentCooldown
  const { skills } = store.getState();
  const currentSkill = skills[skill];
  const { currentCooldown, lastUsed } = currentSkill;
  const currentTime = new Date().getTime();
  const timeSinceUse = currentTime - lastUsed;
  if (lastUsed && timeSinceUse < currentCooldown * 1000) return false;

  // check if there is enough resource for its cost
  const { resources } = store.getState();
  const { costResource, currentCost } = currentSkill;
  if (costResource) {
    const currentResource = resources[costResource];
    if (currentResource.amount < currentCost) return false;

    // use the skill by reducing its cost
    CostHandler.payCost(costResource, currentCost);
  }

  // give rewards
  const { rewards } = currentSkill;
  const key = `skill-acquired-${skill}`;
  if (rewards) {
    const rewardHandler = new RewardHandler(rewards);
    const gaveRewards = rewardHandler.giveRewards();
    if (gaveRewards) {
      setAcquiredResources({ [key]: rewardHandler.getAcquiredResources() });
    }
  }

  store.dispatch(
    startAnimation({
      element: key,
      type: 'skill-acquired',
      value: 0,
      duration: 3000,
    }),
  );

  // activate click mods
  currentSkill.clickMods?.forEach((modName: any) => {
    const mod = clickMods[modName];
    mod(setAcquiredResources);
  });

  // set lastUsed to currentTime
  store.dispatch(
    updateSkill({
      skill,
      property: 'lastUsed',
      value: currentTime,
    }),
  );

  return true;
};

export const hasEmptySkillSlot = () => {
  const skills = store.getState().game.skillSlots;
  // skillSlots is an object. check if any is null
  const hasEmpty = Object.keys(skills).some((key) => skills[key] === null);
  return hasEmpty;
};
