import React, { FC, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { Tooltip } from 'react-tooltip';
import { RootState, store } from '../../../store';
import UpgradeBox from '../../model/upgradeBox';
import { setSeen } from '../../../store/unlockSlice';

const Invest: FC<{ isActive: boolean }> = ({ isActive }) => {
  const values = useSelector(
    (state: RootState) => state.location.list.townHall.values,
  );
  const actions = useSelector(
    (state: RootState) => state.location.list.townHall.features.invest.actions,
  );
  const unlocks = useSelector((state: RootState) => state.unlocks);

  const unlockedActions = actions.filter(
    (action) => unlocks[action.name]?.isUnlocked,
  );

  useEffect(() => {
    // if on this tab, mark as seen
    if (!unlocks.invest.isSeen && isActive) {
      store.dispatch(setSeen('invest'));
    }
  });

  return (
    <div className="invest">
      <div className="invest-header">
        <h1>Invest</h1>
        <div className="funds" data-tooltip-id="tooltip-funds">
          <div className="funds-icon" />
          <div className="funds-quantity num">{values.funds}</div>
          <Tooltip id="tooltip-funds" place="top" className="wrap">
            Funds
          </Tooltip>
        </div>
      </div>
      <div className="invest-body row panel-list">
        {unlockedActions.map((action) => (
          <UpgradeBox key={action.name} upgradeName={action.name} />
        ))}
      </div>
      {unlockedActions.length === 0 && (
        <div className="none-found">No investments currently available.</div>
      )}
    </div>
  );
};

export default Invest;
