import { FC } from 'react';
import { confirmModal } from '../../store/navigationSlice';
import { restartGame } from '../../utils/gameState';
import { store } from '../../store';
import { playSfx } from '../../utils/sound';

const RestartConfirmModal: FC<{}> = () => {
  return (
    <div className="modal-content">
      <div className="modal-header">
        <h5 className="modal-title">Restart Game?</h5>
      </div>
      <div className="modal-body">
        <p>
          The current game will be lost. All you will keep are your
          achievements.
        </p>
      </div>
      <div className="modal-footer d-flex justify-content-between">
        <button
          type="button"
          className="btn btn-secondary"
          onClick={() => {
            playSfx('click');
            store.dispatch(
              confirmModal({
                value: {
                  show: false,
                  type: '',
                },
              }),
            );
          }}
        >
          Cancel
        </button>
        <button
          type="button"
          className="btn btn-primary"
          onClick={() => {
            playSfx('press');
            restartGame();
          }}
        >
          Start a new game
        </button>
      </div>
    </div>
  );
};
export default RestartConfirmModal;
