import { useState, useEffect, FC } from 'react';
import { useSelector } from 'react-redux';
import { Nav, Tab } from 'react-bootstrap';
import { Tooltip } from 'react-tooltip';
import { itemSlotList } from '../../conf/itemConf';
import { ItemSlot, Item } from '../../types';
import { RootState, store } from '../../store';
import { getIcon, hasUnseen, textDisplay } from '../../utils';
import { equipItem, setSeen } from '../../store/itemSlice';
import ItemBox from '../model/itemBox';
import { playSfx } from '../../utils/sound';
import { getBalanceModded } from '../../utils/modUtil';

const Town: FC<{}> = () => {
  const items = useSelector((state: RootState) => state.items);
  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const [isCollapsed, setIsCollapsed] = useState(true);
  const handleToggle = () => {
    setIsCollapsed(!isCollapsed);
  };

  useEffect(() => {
    if (selectedItem && !selectedItem.isSeen) {
      store.dispatch(
        setSeen({ name: selectedItem.name, uuid: selectedItem.uuid || '' }),
      );
    }
  }, [selectedItem]);

  return (
    <div className="items-container flex-grow-1 has-tabs has-headline interact-container panel mb-3 w-100 pt-0 pb-0">
      <div className="items-list container">
        <div className="headline">Items</div>
        <Tab.Container id="left-tabs-example" defaultActiveKey="armor">
          <Nav variant="tabs" className="flex-row">
            {Object.keys(itemSlotList).map((slot: string) => (
              <Nav.Item key={slot}>
                <Nav.Link
                  eventKey={slot}
                  className={hasUnseen(`itemSlot::${slot}`) ? 'new' : ''}
                  data-tooltip-id={`tooltip-tab-${slot}`}
                  onMouseOver={() => {
                    playSfx('hover');
                  }}
                  onClick={() => {
                    playSfx('click');
                  }}
                >
                  <img
                    // eslint-disable-next-line import/no-dynamic-require, global-require
                    src={require(`../../assets/img/item/${slot}.svg`)}
                    alt=""
                  />
                  <Tooltip
                    place="left"
                    className="wrap"
                    id={`tooltip-tab-${slot}`}
                  >
                    {itemSlotList[slot as ItemSlot].plural}
                  </Tooltip>
                </Nav.Link>
              </Nav.Item>
            ))}
          </Nav>

          <div className="row d-block d-lg-flex">
            <div className="col-sm-12 col-md-12 col-lg-6 items-info-col">
              <h2 className="title d-none d-lg-block">Equipped items:</h2>
              <div className="equipped-items">
                {Object.keys(itemSlotList).map((slot: string) => {
                  const equipSlot = items.equipped[slot as ItemSlot];
                  let itemInSlot;
                  if (equipSlot !== undefined)
                    itemInSlot = items.list[equipSlot.name][equipSlot.id];
                  return (
                    <ItemBox
                      item={itemInSlot}
                      setSelectedItem={setSelectedItem}
                      isEquipped={slot}
                      key={slot}
                    />
                  );
                })}
              </div>

              <h2 className="title d-none d-lg-block">Item information:</h2>
              <div className="item-info">
                {selectedItem ? (
                  <div className="item-information">
                    <div className="text-center">
                      <img src={getIcon(selectedItem.icon)} alt="" />
                      <div className="item-name">
                        {selectedItem.displayName}
                      </div>
                      <div
                        className="item-attribute"
                        dangerouslySetInnerHTML={{
                          __html: textDisplay(
                            `+[[${selectedItem.attributeAmount}]]${
                              selectedItem.attribute
                            }`,
                          ),
                        }}
                      />
                    </div>
                    <div className="item-description-column">
                      <div className="item-description">
                        {selectedItem.description}
                      </div>

                      <div className="text-end">
                        {items.equipped[selectedItem.slot] &&
                        items.equipped[selectedItem.slot]?.uuid ===
                          selectedItem.uuid ? (
                          <div className="equipped">Equipped</div>
                        ) : (
                          <button
                            type="button"
                            className="btn btn-primary"
                            onMouseOver={() => {
                              playSfx('hover');
                            }}
                            onClick={() => {
                              playSfx('equip');
                              store.dispatch(
                                equipItem({
                                  item: selectedItem,
                                  uuid: selectedItem.uuid || '',
                                }),
                              );
                            }}
                          >
                            Equip
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                ) : (
                  <div className="empty">
                    Select an item to view its details
                  </div>
                )}
              </div>
              <div
                className={`info-text${isCollapsed ? ' collapsed' : ''}`}
                onClick={handleToggle}
              >
                <p>
                  Attribute bonus:
                  <br />
                  The highest value from items you own. It does not have to be
                  equipped.
                </p>
                <p>
                  Other modifiers:
                  <br />
                  Only from equipped items.
                </p>
              </div>
            </div>
            <div className="col-sm-12 col-md-12 col-lg-6 items-list-col">
              <Tab.Content>
                {Object.keys(itemSlotList).map((slot: string) => (
                  <Tab.Pane eventKey={slot} key={slot}>
                    <h2 className="title">
                      {itemSlotList[slot as keyof typeof itemSlotList].plural}
                    </h2>
                    <div className="scroll-container container">
                      <div className="row">
                        {(() => {
                          const filteredItems = Object.keys(items.list)
                            .map((key: string) => {
                              const itemsOfType = Object.values(
                                items.list[key],
                              ).filter((item: Item) => item.slot === slot);
                              if (itemsOfType.length === 0) {
                                return null;
                              }
                              return (
                                <div className="item-type col-12" key={key}>
                                  <div className="item-list-title">
                                    {items.list[key][1]?.displayName || key} (
                                    {Object.keys(items.list[key]).length}/
                                    {getBalanceModded('craftingLimit')})
                                  </div>
                                  <div className="item-list">
                                    {itemsOfType.map((item: Item) => (
                                      <ItemBox
                                        item={item}
                                        setSelectedItem={setSelectedItem}
                                        key={item.uuid}
                                      />
                                    ))}
                                  </div>
                                </div>
                              );
                            })
                            .filter(Boolean);
                          if (filteredItems.length === 0) {
                            return (
                              <div>No items of this type acquired yet</div>
                            );
                          }

                          return filteredItems;
                        })()}
                      </div>
                    </div>
                  </Tab.Pane>
                ))}
              </Tab.Content>
            </div>
          </div>
        </Tab.Container>
      </div>
    </div>
  );
};
export default Town;
