import { store } from '../../store';
import questTemplates from '../../conf/questConf';
import { setQuests, updateQuest } from '../../store/questSlice';
import { updateFeatureValue } from '../../store/locationSlice';
import { startAnimation } from '../../store/animationSlice';
import { getRewardAmount } from '../gameUtil';
import { getBalanceModded } from '../modUtil';
import balance from '../../conf/balanceConf';
import { QuestList, Quest } from '../../types';
import CostHandler from '../costHandler';
import RewardHandler from '../rewardHandler';

const getQuestsCompleted = () => {
  const { values } = store.getState().location.list.townHall;
  const { questsCompleted } = values;
  return questsCompleted;
};
const getCurrentTier = () => {
  const tier = Math.floor(
    getQuestsCompleted() / balance.upgrades.townHall.questsPerTier,
  );
  return tier || 1;
};

const getMainQuests = () => {
  return store.getState().location.list.townHall.values.mainQuests || [];
};

const createQuest = (currentQuests: QuestList) => {
  const { resources } = store.getState();
  const currentTier = getCurrentTier();
  const completedMainQuests = getMainQuests();
  const { unlocks } = store.getState();
  // find a random one from quest templates where tier is less than or equal to currentTier
  const quests = questTemplates.filter(
    (quest) =>
      quest.tier <= currentTier &&
      (!quest.maxTier || currentTier <= quest.maxTier) &&
      (!quest.requirement || unlocks[quest.requirement].isUnlocked) &&
      (quest.isMainQuest ? !completedMainQuests.includes(quest.name) : true) &&
      currentQuests.every(
        (currentQuest) => !currentQuest || currentQuest.name !== quest.name,
      ),
  );
  if (!quests.length) return null;
  const randomQuest = structuredClone(
    quests[Math.floor(Math.random() * quests.length)],
  );
  const newQuest = {
    ...randomQuest,
    isLocked: false,
  };
  // loop over costs and set value as getRewardAmount
  Object.keys(newQuest.costs).forEach((key) => {
    if (newQuest.costs[key].currentCost) return;
    const cost = getRewardAmount(resources[key], currentTier);
    newQuest.costs[key] = { cost, currentCost: cost };
  });

  // loop over rewards and set value as getRewardAmount
  newQuest.rewards.forEach((reward, index) => {
    const { resource } = reward;
    if (resource === 'skillSlot') {
      newQuest.rewards[index].amount = 1;
      newQuest.rewards[index].currentAmount = 1;
    } else if (resource === 'relationship') {
      const amount = getBalanceModded('questRewardRelationship');
      newQuest.rewards[index].amount = amount;
      newQuest.rewards[index].currentAmount = amount;
    } else if (reward.property) {
      newQuest.rewards[index].currentAmount = reward.amount;
    } else if (resource) {
      const amount = getRewardAmount(resources[resource], currentTier);
      newQuest.rewards[index].amount = amount;
      newQuest.rewards[index].currentAmount = amount;
    }
  });
  return newQuest;
};

const generateQuests = () => {
  const { quests } = store.getState();
  const newQuests = structuredClone(quests);

  // First, start animations to hide any visible quests
  for (let i = 0; i < balance.upgrades.townHall.getQuestsCount; i += 1) {
    if (!quests[i] || !quests[i].isLocked) {
      // Start with hiding animation first
      store.dispatch(
        startAnimation({
          element: `quest-${i}-hidden`,
          type: 'quest',
          value: 0,
          duration: i * 500 + 300,
        }),
      );
    }
  }

  // THEN update Redux state after a small delay
  setTimeout(() => {
    // Create new quests
    for (let i = 0; i < balance.upgrades.townHall.getQuestsCount; i += 1) {
      if (!quests[i] || !quests[i].isLocked) {
        newQuests[i] = createQuest(newQuests);
      }
    }

    // Update Redux with new quests (they'll be invisible due to the hidden class)
    store.dispatch(setQuests(newQuests));

    // THEN start the reveal animations with staggered timing
    for (let i = 0; i < balance.upgrades.townHall.getQuestsCount; i += 1) {
      if (!quests[i] || !quests[i].isLocked) {
        setTimeout(() => {
          store.dispatch(
            startAnimation({
              element: `quest-${i}`,
              type: 'quest',
              value: 0,
              duration: 500,
            }),
          );
        }, i * 500);
      } else {
        setTimeout(() => {
          store.dispatch(
            startAnimation({
              element: `quest-${i}-vibrate`,
              type: 'quest',
              value: 0,
              duration: 500,
            }),
          );
        }, i * 500);
      }
    }
  }, 200); // Small delay to ensure hiding animations are applied
};

const submitQuest = (index: number, costHandler: CostHandler) => {
  costHandler.payAllCosts();
  const quest = store.getState().quests[index];
  const rewardHandler = new RewardHandler(quest.rewards);
  rewardHandler.giveRewards();

  store.dispatch(
    updateQuest({
      index,
      property: 'isCompleted',
      value: true,
    }),
  );
  store.dispatch(
    updateQuest({
      index,
      property: 'isLocked',
      value: false,
    }),
  );
  if (quest.isMainQuest) {
    const mainQuests = getMainQuests();
    const setMainQuests = [...mainQuests, quest.name];
    store.dispatch(
      updateFeatureValue({
        location: 'townHall',
        property: 'mainQuests',
        value: setMainQuests,
      }),
    );
  }

  const questsCompleted = getQuestsCompleted() + 1;
  store.dispatch(
    updateFeatureValue({
      location: 'townHall',
      property: 'questsCompleted',
      value: questsCompleted,
    }),
  );
};

const canSubmit = (quest: Quest, costHandler: CostHandler) => {
  return !quest.isCompleted && costHandler && costHandler.canPayCosts();
};

export {
  generateQuests,
  createQuest,
  getQuestsCompleted,
  getCurrentTier,
  canSubmit,
  submitQuest,
};
