import { updateResource } from '../store/resourceSlice';
import { store } from '../store';
import { checkForUnlocks } from './gameState';
import { getPropertyModded } from './modUtil';
import { addResource } from './gameUtil';
import { Resource } from '../types';

export const useTick = (timeDelta: number) => {
  const { resources } = store.getState();
  // loop over all resources
  Object.entries(resources).forEach(([resource, value]) => {
    addResource(resource, (value as Resource).gps * (timeDelta / 1000), true);
  });
  checkForUnlocks();
};

export const gpsTempTick = (secondsSinceLast: number) => {
  const maxOfflineSeconds = 2;
  const effectiveSeconds = Math.min(secondsSinceLast, maxOfflineSeconds);

  const { resources } = store.getState();
  const { upgrades } = store.getState();
  Object.entries(resources).forEach(([resource]) => {
    const { mods } = resources[resource];
    const convertMods = mods?.filter(
      (mod: any) => mod.modProperty === 'convert',
    );
    convertMods?.forEach((mod: any) => {
      const modData = mod.data;
      const { upgrade } = modData;
      const resourceTypeToTake = resource;
      const resourceAmountToTake =
        upgrades[upgrade].currentAdditionalPower.convert;
      const resourceTypeToGive = modData.convertTo;
      const resourceAmountToGive = upgrades[upgrade].currentPower;

      let didTake = false;
      // if there is enough to take, then take it
      if (
        resources[resourceTypeToTake].amount >= resourceAmountToTake &&
        modData.isEnabled
      ) {
        // take the resource
        addResource(
          resourceTypeToTake,
          -1 * resourceAmountToTake * effectiveSeconds,
          true,
        );
        // give the resource
        addResource(
          resourceTypeToGive,
          resourceAmountToGive * effectiveSeconds,
          true,
        );
        didTake = true;
      }

      // update the mod for gpsTemp for both where data.upgrade === upgrade
      [resourceTypeToTake, resourceTypeToGive].forEach((resourceName) => {
        const modList = resources[resourceName].mods;
        const modListChange = structuredClone(modList);
        modListChange?.forEach((changeMod: any, index: number) => {
          if (changeMod.data?.upgrade === upgrade) {
            modListChange[index].data.isActive = didTake;
          }
        });
        store.dispatch(
          updateResource({
            resource: resourceName,
            property: 'mods',
            value: modListChange,
          }),
        );
      });
    });
  });
  updateGps();
};

export const updateGps = (): void => {
  const { dispatch } = store;
  const { resources } = store.getState();
  // loop over all resources
  Object.entries(resources).forEach(([resource, value]) => {
    const moddedValue = getPropertyModded(value, 'gps', 0);
    dispatch(
      updateResource({
        resource,
        property: 'gps',
        value: Math.floor(moddedValue),
      }),
    );

    const moddedValueTemp = getPropertyModded(value, 'gpsTemp', 0);
    dispatch(
      updateResource({
        resource,
        property: 'gpsTemp',
        value: Math.floor(moddedValueTemp),
      }),
    );
  });
};
