import { FC, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { store, RootState } from '../../store';
import DynamicText from '../util/dynamicText';
import { setSeen } from '../../store/unlockSlice';
import { setModalParam } from '../../store/navigationSlice';
import days from '../../conf/dayConf';
import { playSfx } from '../../utils/sound';
import ModalCloseBtn from './modalCloseBtn';
import ChallengeRequirements from '../util/challengeRequirements';
import choices from '../../conf/choicesConf';
import { numberDisplay } from '../../utils';

const CalendarModal: FC<{}> = () => {
  const modalParams = useSelector(
    (state: RootState) => state.navigation.modal.params,
  );
  const selectedDay = modalParams?.selectedDay || 0;
  const setSelectedDay = (value: number) => {
    store.dispatch(setModalParam({ key: 'selectedDay', value }));
  };
  const [displayText, setDisplayText] = useState('');
  const [hasChallenge, setHasChallenge] = useState(false);
  const game = useSelector((state: RootState) => state.game);
  const achievements = useSelector((state: RootState) => state.achievements);
  const unlocks = useSelector((state: RootState) => state.unlocks);

  // go over all days and find the latest day for which the achievement is unlocked
  let latestSeenDay = 0;

  // loop over days
  days.forEach((day, index) => {
    // if the day has an event
    if (day.event) {
      if (!latestSeenDay) {
        latestSeenDay = index;
      }
      if (game.day + 5 >= index) {
        latestSeenDay = index;
      }
      // loop over the event achievements
      day.eventActions?.forEach((action) => {
        const { achievement } = action;
        if (!achievement) return;
        if (achievement === 'lostGame') return;
        // if the achievement is unlocked
        if (achievements[achievement] && achievements[achievement].isUnlocked) {
          // set the latest day
          latestSeenDay = index;
        }
      });
    }
  });

  useEffect(() => {
    let newDisplayText = 'Just a regular day.';
    const dayInfo = days[selectedDay];
    setHasChallenge(false);
    if (dayInfo.event) {
      if (dayInfo.event !== 'choice') {
        if (!unlocks[dayInfo.event].isSeen) {
          store.dispatch(setSeen(dayInfo.event));
        }
      }
      if (selectedDay > latestSeenDay && dayInfo.event !== 'end') {
        newDisplayText = '???';
      } else if (selectedDay <= game.day && dayInfo.event === 'choice') {
        const dayChoices = game.choices[selectedDay];
        if (dayChoices && Array.isArray(dayChoices) && dayChoices.length > 0) {
          newDisplayText = `You gained:<br><br>`;
          dayChoices.forEach((choice: any) => {
            if (choice.isSelected) {
              newDisplayText += ` ${choices[choice.name].description.replace('{{num}}', `<span class="num">${numberDisplay(choice.value)}</span>`)}`;
            }
          });
        }
      } else {
        newDisplayText = dayInfo.eventDescription || 'An event takes place.';
      }
      if (selectedDay <= latestSeenDay) {
        if (dayInfo.event !== 'choice') {
          setHasChallenge(true);
        }
      }
    }
    setDisplayText(newDisplayText);
  }, [selectedDay, latestSeenDay]);

  return (
    <div className="modal-content">
      <div className="modal-header">
        <h5 className="modal-title">Calendar</h5>
        <ModalCloseBtn />
      </div>
      <div className="modal-body">
        <div className="row">
          <div className="col-sm-5 order-sm-2">
            <div className="calendar-day-info">
              {selectedDay === 0 ? (
                <p>Select a day to see more information about it.</p>
              ) : (
                <>
                  <h4>Day {selectedDay}:</h4>
                  <DynamicText text={displayText} />
                  {hasChallenge && (
                    <ChallengeRequirements dayInfo={days[selectedDay]} />
                  )}
                </>
              )}
            </div>
          </div>
          <div className="calendar-list col-sm-7 order-sm-1">
            {days.map((day, index) => {
              return index === 0 ? null : (
                <div
                  className={`day day-${index} has-tooltip${
                    index < game.day ? ' past' : ''
                  }${index === game.day ? ' current' : ''}${
                    index > game.day ? ' future' : ''
                  }${index === selectedDay ? ' selected' : ''}${
                    day.event ? ' has-event' : ''
                  }${day.event ? ' has-event' : ''}`}
                  // eslint-disable-next-line react/no-array-index-key
                  key={index}
                >
                  <button
                    type="button"
                    className="day-number"
                    onMouseOver={() => {
                      playSfx('hover');
                    }}
                    onClick={() => {
                      playSfx('click');
                      setSelectedDay(index);
                    }}
                  >
                    {index}
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
};
export default CalendarModal;
