import { FC, useEffect, useRef } from 'react';
import { store } from '../../store';
import { useSelector } from 'react-redux';
import type { RootState } from '../../store';
import { textDisplay } from '../../utils';
import { removeAlert, removeAllAlerts } from '../../store/navigationSlice';
import { playSfx } from '../../utils/sound';

const Alerts: FC<{}> = () => {
  const alerts = useSelector((state: RootState) => state.navigation.alerts);
  const alertsRef = useRef(alerts);
  const animations = useSelector((state: RootState) => state.animations);

  // Update ref when alerts change
  useEffect(() => {
    alertsRef.current = alerts;
  }, [alerts]);

  // check every minute, if an alert is 5 minutes long, then remove it
  useEffect(() => {
    const interval = setInterval(() => {
      const currentTime = Date.now();
      const expiredAlerts = alertsRef.current.filter((alert) => {
        const elapsedTime = currentTime - alert.time;
        return elapsedTime >= 60 * 1000;
      });

      expiredAlerts.forEach((alert) => {
        store.dispatch(removeAlert({ id: alert.id }));
      });
    }, 1000);

    return () => {
      clearInterval(interval);
    };
  }, []);

  return (
    <div className="alerts-container">
      <button
        type="button"
        className={`btn btn-default btn-icon btn-small btn-close-all${
          alerts.length < 2 ? ' d-none' : ''
        }`}
        data-dismiss="alert"
        aria-label="Close"
        onMouseEnter={() => {
          playSfx('hover');
        }}
        onClick={() => {
          playSfx('click');
          store.dispatch(removeAllAlerts());
        }}
      >
        <span>Close all</span>
      </button>

      {alerts?.map((alert, index) => (
        <div
          key={index}
          className={`alert alert-dismissible${
            animations[`alert-${alert.id}`] ? ' is-animating ' : ' '
          }${animations[`alert-${alert.id}`] ? `alert-${animations[`alert-${alert.id}`].type}` : 'alert-default'}`}
        >
          <span
            dangerouslySetInnerHTML={{
              __html: textDisplay(alert.message),
            }}
          />
          <button
            type="button"
            className="btn-close bs-close"
            data-dismiss="alert"
            aria-label="Close"
            onClick={() => {
              store.dispatch(removeAlert({ id: alert.id }));
            }}
          >
            &nbsp;
          </button>
        </div>
      ))}
    </div>
  );
};
export default Alerts;
