import React, { useEffect } from 'react';
import { useState } from 'react';
import { useSelector } from 'react-redux';
import { Tooltip } from 'react-tooltip';
import { store, RootState } from '../../../store';
import { setSeen } from '../../../store/unlockSlice';
import ModelIcon from '../../model/modelIcon';
import { btnClick, btnHover, playSfx } from '../../../utils/sound';
import ResourceSelector from './resourceSelector';
import { Item, Resource } from '../../../types';
import {
  findRecipe,
  getRequiredAmount,
  resourceSlots,
  getTimesCrafted,
  getRecipeModel,
  createCostHandler,
  craftItem,
  canCraft,
  additionalCostBalance,
  additionalCostResource,
  getMaxAttribute,
} from '../../../utils/location/crafting';
import { Recipe, RecipeType } from '../../../conf/recipeConf';
import { itemList } from '../../../conf/itemConf';
import { numberDisplay, textDisplay } from '../../../utils';
import CostHandler from '../../../utils/costHandler';
import { getBalanceModded } from '../../../utils/modUtil';
import { get } from 'node:http';

type CraftingProps = {
  isActive: boolean;
  type: RecipeType;
};

const featureNames: Record<string, string> = {
  material: 'crafting',
  spiritual: 'imbue',
  mental: 'writing',
};

function isItem(model: Item | Resource | null): model is Item {
  return model !== null && 'slot' in model;
}

const Crafting: React.FC<CraftingProps> = ({ isActive, type }) => {
  const unlocks = useSelector((state: RootState) => state.unlocks);
  const resources = useSelector((state: RootState) => state.resources);
  const animations = useSelector((state: RootState) => state.animations);

  const [selectedResources, setSelectedResources] = useState<string[]>([]);
  const [selectedSlot, setSelectedSlot] = useState<number | null>(null);
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const [recipeModel, setRecipeModel] = useState<Item | Resource | null>(null);
  const [timesCrafted, setTimesCrafted] = useState<number>(0);
  const [requiredAmounts, setRequiredAmounts] = useState<number[]>([]);
  const [costHandler, setCostHandler] = useState<CostHandler | null>(null);
  const [craftAmount, setCraftAmount] = useState<number>(1);
  const [useMaxAmount, setUseMaxAmount] = useState<boolean>(false);

  const itemLimit = getBalanceModded('craftingLimit');

  const setAllRequiredAmounts = (
    useResources?,
    useRecipe?: Recipe,
    useTimesCrafted?: number,
  ) => {
    const currentRecipe = useRecipe || recipe;
    const currentResources = useResources || selectedResources;
    const currentTimesCrafted =
      useTimesCrafted !== undefined ? useTimesCrafted : timesCrafted;
    if (!currentRecipe) return;
    setRequiredAmounts(
      currentResources.map(
        (resource) =>
          getRequiredAmount(currentRecipe, resource, currentTimesCrafted) *
          craftAmount,
      ),
    );
  };

  const setResourceWithKey = (key: number, value: string) => {
    const newResources = selectedResources.slice();
    newResources[key] = value;
    setSelectedResources(newResources);
    const recipeResult = findRecipe(newResources, type);
    if (recipeResult) {
      setCraftAmount(1);
      setUseMaxAmount(false);
    }

    if (recipeResult) {
      const newTimesCrafted = getTimesCrafted(recipeResult);

      setRecipe(recipeResult);
      setTimesCrafted(newTimesCrafted);
      setRecipeModel(getRecipeModel(recipeResult));

      const newCostHandler = createCostHandler(recipeResult, type);
      setCostHandler(newCostHandler);
      newCostHandler?.setAmount(craftAmount);
      setAllRequiredAmounts(newResources, recipeResult, newTimesCrafted);
    } else {
      setRecipe(null);
      setRecipeModel(null);
      setCostHandler(null);
      setTimesCrafted(0);
      setRequiredAmounts([]);
    }
  };

  const setResource0 = (value: string) => setResourceWithKey(0, value);
  const setResource1 = (value: string) => setResourceWithKey(1, value);
  const setResource2 = (value: string) => setResourceWithKey(2, value);

  const getResourceSetter = (slot: number | null) => {
    switch (slot) {
      case 0:
        return setResource0;
      case 1:
        return setResource1;
      case 2:
        return setResource2;
      default:
        return () => {};
    }
  };

  const haveEnoughResource = (index: number) => {
    // check if a previous index has the same resource, and how much is left over from that
    const previousIndex = selectedResources
      .slice(0, index)
      .findIndex((resource) => resource === selectedResources[index]);
    if (previousIndex !== -1) {
      return (
        requiredAmounts[index] <=
        resources[selectedResources[index]]?.amount -
          requiredAmounts[previousIndex]
      );
    }
    return (
      requiredAmounts[index] <= resources[selectedResources[index]]?.amount
    );
  };

  useEffect(() => {
    // if on this tab, mark as seen
    if (!unlocks[featureNames[type]].isSeen && isActive) {
      store.dispatch(setSeen(featureNames[type]));
    }
  });

  useEffect(() => {
    if (useMaxAmount) {
      setCraftAmount(costHandler?.getMaxAmount() || 1);
    }
    costHandler?.setAmount(craftAmount);
    setAllRequiredAmounts();
  }, [craftAmount, useMaxAmount]);

  // Define the amount options array
  const amountOptions = [
    { id: 'amount1', value: 1, label: '1' },
    { id: 'amount10', value: 10, label: '10' },
    { id: 'amount100', value: 100, label: '100' },
    { id: 'amountMax', value: 'max', label: 'Max' },
  ];

  const fixDescription = (description: string) => {
    // Put a span around each word with a unique key
    return description
      .split(' ')
      .map((word, index) => <span key={`${word}-${index}`}>{word}</span>)
      .reduce((prev, curr, i) => (
        // Join with spaces between elements
        <>
          {prev} {curr}
        </>
      ));
  };

  return (
    <div className="crafting">
      <h1>
        {featureNames[type].charAt(0).toUpperCase() +
          featureNames[type].slice(1)}
      </h1>

      <Tooltip id="crafting-tooltip" place="left">
        Gain +{timesCrafted + 1} permanent{' '}
        <span
          dangerouslySetInnerHTML={{
            __html:
              recipe &&
              recipe.type === 'item' &&
              textDisplay(itemList[recipe.name].attribute),
          }}
        />{' '}
        as a bonus for crafting it.
      </Tooltip>
      <div className="resource-selector-container">
        <div
          className={`resource-slots-info${selectedSlot !== null ? ' d-none' : ''}`}
        >
          Select a slot to add a resource
        </div>
        {selectedSlot !== null && (
          <ResourceSelector
            resourceType={resourceSlots[type][selectedSlot].type || ''}
            singleSelectedResource={selectedResources[selectedSlot] || null}
            setSingleSelectedResource={getResourceSetter(selectedSlot)}
            resourceLabel={resourceSlots[type][selectedSlot].description}
          />
        )}
      </div>
      <div className="resource-slots">
        {resourceSlots[type].map((slot, index) => (
          <div
            key={index}
            className={`resource-slot${selectedSlot === index ? ' selected' : ''}`}
            style={
              {
                '--var-item-color': selectedResources[index]
                  ? resources[selectedResources[index]].color
                  : 'transparent',
              } as React.CSSProperties
            }
          >
            <div className="connector connector-top" />
            <div
              className={`connector connector-bottom${selectedResources.length > 1 ? '' : ' d-none'}`}
            />
            <button
              className={`resource-button${
                resourceSlots[type].length - 2 === index ? ' core' : ''
              }`}
              type="button"
              aria-label="Select resource"
              onMouseEnter={btnHover}
              onClick={() => {
                btnClick();
                setSelectedSlot(index);
              }}
            >
              {selectedResources[index] && (
                <ModelIcon model={resources[selectedResources[index]]} />
              )}
            </button>
            <div
              className={`description${
                resourceSlots[type].length - 2 === index ? ' core' : ''
              }`}
            >
              {fixDescription(slot.description)}
            </div>
            <div
              className={`selected-resource${
                selectedResources[index] ? '' : ' none-found'
              }`}
            >
              {selectedResources[index]
                ? resources[selectedResources[index]].displayName
                : 'not selected'}
            </div>
            <div
              className={`resource-amounts${!haveEnoughResource(index) ? ' red' : ' green'}`}
            >
              {selectedResources[index] && !recipe && 'Owned:'}
              {selectedResources[index] ? (
                <span className="num">
                  {numberDisplay(resources[selectedResources[index]]?.amount)}
                </span>
              ) : null}
              {selectedResources[index] && recipe ? (
                <span className="num">
                  / {numberDisplay(requiredAmounts[index])}
                </span>
              ) : null}
            </div>
          </div>
        ))}
      </div>
      <div
        className={`recipe${animations.justCrafted && animations.justCrafted.active ? ' just-crafted' : ''}`}
        style={
          { '--var-item-color': recipeModel?.color } as React.CSSProperties
        }
      >
        {recipe && recipeModel ? (
          <div className="recipe-item-info">
            <div className="info-label">Current recipe:</div>
            <div className="recipe-name">
              <div className="crafted-notification num">
                <div>+ {craftAmount}</div>
              </div>
              <div />
              <ModelIcon model={recipeModel} />
              {recipeModel.displayName}{' '}
              {recipe && recipe.type === 'resource' && (
                <span>
                  (<span className="num">x{numberDisplay(craftAmount)}</span>)
                </span>
              )}
              {isItem(recipeModel) && (
                <span className={timesCrafted >= itemLimit ? 'red' : ''}>
                  <span className="num">
                    {timesCrafted}/
                    {isItem(recipeModel) && recipeModel.limit
                      ? recipeModel.limit
                      : itemLimit}
                  </span>
                  {timesCrafted >= itemLimit ? '(MAX)' : ''}
                </span>
              )}
            </div>
            <div className="recipe-attributes">
              {isItem(recipeModel) ? (
                <>
                  <span
                    dangerouslySetInnerHTML={{
                      __html: textDisplay(recipeModel.attribute),
                    }}
                  />
                  <span className="num">
                    + {recipeModel.minAttribute} ...{' '}
                    {getMaxAttribute(recipeModel, timesCrafted)}
                  </span>
                </>
              ) : (
                <div className="radio-switch craft-amount-switch">
                  {amountOptions.map((option) => (
                    <label
                      key={option.id}
                      htmlFor={option.id}
                      className="radio-label form-check-label"
                    >
                      <input
                        type="radio"
                        name="amount"
                        className="d-none"
                        id={option.id}
                        value={option.value.toString()}
                        checked={
                          option.value === 'max'
                            ? useMaxAmount
                            : craftAmount === option.value && !useMaxAmount
                        }
                        onChange={() => {
                          if (option.value === 'max') {
                            setUseMaxAmount(!useMaxAmount);
                          } else {
                            setUseMaxAmount(false);
                            setCraftAmount(option.value as number);
                            costHandler?.setAmount(option.value as number);
                          }
                          setAllRequiredAmounts();
                        }}
                      />
                      <span onMouseEnter={btnHover} onClick={btnClick}>
                        {option.label}
                      </span>
                    </label>
                  ))}
                </div>
              )}
            </div>
            <button
              className="btn btn-primary craft-button btn-small"
              type="button"
              disabled={
                (costHandler ? !canCraft(recipe, costHandler) : true) ||
                (animations.justCrafted && animations.justCrafted.active)
              }
              onMouseEnter={btnHover}
              data-tooltip-id={
                recipe && recipe.type === 'item' && 'crafting-tooltip'
              }
              onClick={() => {
                if (!costHandler) return;
                playSfx('craft');
                craftItem(recipe, costHandler, type === 'material');
              }}
            >
              Craft{' '}
              {recipe &&
                (recipe.type === 'item' ||
                  type === 'mental' ||
                  Object.keys(costHandler?.getCostList()).length > 3) && (
                  <span>
                    (
                    <span className="num">
                      -
                      {numberDisplay(
                        getBalanceModded(
                          additionalCostBalance[type][recipe.type],
                        ) * craftAmount,
                      )}
                    </span>
                    <span
                      className="resource"
                      dangerouslySetInnerHTML={{
                        __html: textDisplay(additionalCostResource[type]),
                      }}
                    />
                    )
                  </span>
                )}
            </button>
          </div>
        ) : (
          // if there are all selectedResources but no recipe, show no recipe found
          selectedResources.length > 1 && (
            <div className="none-found text-center">No recipe found</div>
          )
        )}
      </div>
    </div>
  );
};

export default Crafting;
