import { FC, useState, useRef } from 'react';
import { persistStore } from 'redux-persist';
import { store } from '../../store';
import { playSfx } from '../../utils/sound';
import icons from '../../conf/icons';
import {
  confirmModal,
  updateModal,
  updateNavigation,
} from '../../store/navigationSlice';
import { sendAlert } from '../../utils/alertUtil';

const persistor = persistStore(store);

const getPersistedState = async () => {
  return new Promise((resolve, reject) => {
    persistor.flush().then(() => {
      const state = localStorage.getItem('persist:quintillionQuest');
      if (state) {
        resolve(JSON.parse(state));
      } else {
        reject('No persisted state found');
      }
    });
  });
};

const downloadStateAsFile = async () => {
  try {
    const state = await getPersistedState();
    const stateStr = JSON.stringify(state, null, 2);
    const base64StateStr = btoa(stateStr);

    const blob = new Blob([base64StateStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    a.download = 'quintillionSave.dat';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    sendAlert('Game data saved.', 'gameSave');
  } catch (error) {
    console.error('Failed to download state:', error);
  }
};

const GameDataModal: FC<{}> = () => {
  const [fileError, setFileError] = useState<string | null>(null);
  const [fileContent, setFileContent] = useState<any>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const content = e.target?.result as string;
        setFileError(null);
        try {
          const decodedContent = atob(content);
          const parsedContent = JSON.parse(decodedContent);
          // go over each key in parsedContent and replace it with JSON.parse(parsedContent[key])
          // this is to handle nested JSON strings in the state
          Object.keys(parsedContent).forEach((key) => {
            try {
              parsedContent[key] = JSON.parse(parsedContent[key]);
            } catch (error) {
              // do nothing
            }
          });

          if (parsedContent.game.version !== store.getState().game.version) {
            setFileError(
              'WARNING: The save file is from a different version of the game',
            );
          }
          setFileContent(parsedContent);
        } catch (error) {
          setFileError('Invalid file format. Please upload a valid file.');
          setFileContent(null);
        }
      };
      reader.readAsText(file);
    }
  };

  const confirmReplaceState = () => {
    if (fileContent) {
      // replace achievements in fileContent with the current achievements
      const currentAchievements = store.getState().achievements;
      fileContent.achievements = currentAchievements;
      store.dispatch({ type: 'REPLACE_STATE', payload: fileContent });
      setFileContent(null);
      setFileError(null);
      store.dispatch(
        confirmModal({
          value: {
            show: false,
            type: '',
          },
        }),
      );
      store.dispatch(
        updateModal({
          value: { show: false, type: '' },
        }),
      );
      store.dispatch(
        updateNavigation({
          navigation: 'mainPanel',
          value: { current: 'town' },
        }),
      );

      sendAlert('Loaded saved game data.', 'gameLoad');
    }
  };

  const handleCancel = () => {
    setFileContent(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = ''; // Clear the file input
    }
    setFileError(null);
  };

  return (
    <div className="modal-content">
      <div className="modal-header">
        <h5 className="modal-title">Game data</h5>
      </div>
      <div className="modal-body">
        <div className="row">
          <div className="col-12 col-sm-6">
            <button
              type="button"
              className="btn btn-icon btn-save btn-text"
              onMouseOver={() => {
                playSfx('hover');
              }}
              onClick={() => {
                playSfx('click');
                downloadStateAsFile();
              }}
            >
              Save data as file
            </button>
          </div>
          <div className="col-12 col-sm-6">
            <label
              htmlFor="uploadSave"
              className="upload-label"
              onMouseOver={() => {
                playSfx('hover');
              }}
            >
              <img src={icons.upload} alt="Upload" />
              Load data from file
            </label>
            <input
              type="file"
              id="uploadSave"
              className="d-none"
              onChange={handleFileUpload}
              ref={fileInputRef}
            />
            {fileError && (
              <div className="alert form-alert alert-danger">{fileError}</div>
            )}
            {fileContent && (
              <div className="alert form-alert alert-warning flex-wrap">
                <p>Replace current game data? This is irreversible.</p>
                <div className="d-flex justify-content-between">
                  <button
                    type="button"
                    className="btn btn-secondary btn-small me-1"
                    onClick={handleCancel}
                  >
                    Cancel
                  </button>
                  <button
                    type="button"
                    className="btn btn-primary btn-small"
                    onClick={confirmReplaceState}
                  >
                    Replace data
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
      <div className="modal-footer d-flex justify-content-between">
        <span />
        <button
          type="button"
          className="btn btn-secondary"
          onClick={() => {
            playSfx('click');
            store.dispatch(
              confirmModal({
                value: {
                  show: false,
                  type: '',
                },
              }),
            );
          }}
        >
          Close
        </button>
      </div>
    </div>
  );
};
export default GameDataModal;
