import { FC } from 'react';
import { useSelector } from 'react-redux';
import { numberDisplay } from '../../utils';
import type { RootState } from '../../store';
import { Resource } from '../../types';

interface ResourceProps {
  resource: Resource;
}

const Gps: FC<ResourceProps> = ({ resource }) => {
  const animations = useSelector((state: RootState) => state.animations);
  const resourceName = resource.name;
  const resources = useSelector((state: RootState) => state.resources);
  const num = resource.gps + (resource.gpsTemp ? resource.gpsTemp : 0);
  return (
    <div
      className={`gps has-animation${animations[resourceName] && animations[resourceName].active ? ' animating' : ''}`}
    >
      <div className="default">
        {num ? (
          <>
            {num > 0 ? '+' : ''}
            <span className="num">{numberDisplay(num)}</span>
            /s
          </>
        ) : (
          <>&nbsp;</>
        )}
        {resources[resourceName].gainMultiplier &&
        resources[resourceName].gainMultiplier > 1 ? (
          <>
            {' '}
            {!num ? 'gain ' : ''}
            <span className="num">
              x{numberDisplay(resources[resourceName].gainMultiplier)}
            </span>{' '}
          </>
        ) : (
          ''
        )}
      </div>
      <div
        className={`animated${
          animations[resourceName] &&
          animations[resourceName].active &&
          animations[resourceName].type === '-'
            ? ' is-animating'
            : ''
        }`}
      >
        <span className="num">
          -
          {animations[resourceName]
            ? numberDisplay(animations[resourceName].value)
            : ''}
        </span>
      </div>
      <div
        className={`animated${
          animations[resourceName] &&
          animations[resourceName].active &&
          animations[resourceName].type === '+'
            ? ' is-animating'
            : ''
        }`}
      >
        <span className="num">
          +
          {animations[resourceName]
            ? numberDisplay(animations[resourceName].value)
            : ''}
        </span>
      </div>
    </div>
  );
};
export default Gps;
