export const updateVersion = (): void => {
  [
    'achievement',
    'attribute',
    'game',
    'location',
    'navigation',
    'resource',
    'skill',
    'unlock',
    'upgrade',
  ].forEach((type) => {
    // require action so you can dispatch it
    // eslint-disable-next-line import/no-dynamic-require, global-require
    const { updateVersion } = require(`../store/${type}Slice`);
    store.dispatch(updateVersion());
  });
};

export const updateResources = (): void => {
  const { resources } = store.getState();
  // loop over all resources
  Object.entries(resources).forEach(([resource, value]) => {
    if (isNaN(value.amount)) {
      // fix it and set to 0
      store.dispatch(
        updateResource({
          resource,
          property: 'amount',
          value: 0,
        }),
      );
    }

    let gainMultiplier = 1;
    gainMultiplier = getPropertyModded(
      value,
      'gainMultiplier',
      gainMultiplier,
    );
    if (gainMultiplier !== value.gainMultiplier) {
      store.dispatch(
        updateResource({
          resource,
          property: 'gainMultiplier',
          value: gainMultiplier,
        }),
      );
    }

    if (!value.isCapped) return;
    let newCap = value.cap || 0;
    // sort mods by priority ascending
    const mods = structuredClone(value.mods);
    mods.sort((a: ModConf, b: ModConf) => a.priority - b.priority);
    mods.forEach((mod: ModConf, i) => {
      if (mod.modProperty !== 'currentCap') return;
      const modFunc: Modifier = modList[mod.modName];
      newCap = modFunc(newCap, mod.data);
    });
    store.dispatch(
      updateResource({
        resource,
        property: 'currentCap',
        value: newCap,
      }),
    );
  });
};

export const updateAchievements = (): void => {
  const { achievements } = store.getState();
  const { unlocks } = store.getState();
  // loop over all achievements if they are unlocked set unlock to true
  Object.entries(achievements).forEach(([achievement, value]) => {
    if (value.isUnlocked && !unlocks[achievement].isUnlocked) {
      store.dispatch(
        updateUnlock({
          attribute: achievement,
          property: 'isUnlocked',
          value: true,
        }),
      );
    }
    if (value.name === 'tutorialCompleted' && value.isUnlocked) {
      store.dispatch(setTutorialStep(0));
    }
  });
};

export const updateAttributes = (): void => {
  const { attributes } = store.getState();
  // loop over all attributes
  Object.entries(attributes).forEach(([attribute, value]) => {
    // sort mods by priority ascending
    const mods = structuredClone(value.mods);
    mods.sort((a: ModConf, b: ModConf) => a.priority - b.priority);
    let newValue = value.amount;
    newValue += value.addAmount || 0;
    // calculate currentAmount based on mods. loop over all mods and apply them.
    // for the arguments to each mod, we pass the accumulated value and the attribute object.

    const sources: {
      [key: string]: number;
    } = {};
    mods.forEach((mod: ModConf) => {
      if (mod.modProperty !== 'currentAmount') return;
      const oldValue = newValue;
      const modFunc: Modifier = modList[mod.modName];
      newValue = modFunc(newValue, mod.data);
      if (mod.modName === 'itemAddsAttribute') {
        sources.item = newValue - oldValue;
      } else if (mod.modName.startsWith('choice')) {
        sources.event = newValue - oldValue;
      } else if (mod.modName.startsWith('achievement')) {
        sources.achievement = newValue - oldValue;
      }
    });

    store.dispatch(
      updateAttribute({
        attribute,
        property: 'currentAmount',
        value: newValue,
      }),
    );
    Object.keys(sources).forEach((source) => {
      store.dispatch(
        addToSource({
          attribute,
          source,
          amount: sources[source],
          setValue: true,
        }),
      );
    });
  });
  updateResources();
};

export const updateSkills = (): void => {
  const { skills } = store.getState();
  const propertiesToUpdate = [
    'currentPower',
    'currentCost',
    'currentCooldown',
    'rewards',
  ];

  Object.entries(skills as SkillList).forEach(([skill, value]) => {
    const mods = structuredClone(value.mods);
    if (!mods) return;
    mods.sort((a: ModConf, b: ModConf) => a.priority - b.priority);
    propertiesToUpdate.forEach((property) => {
      if (!(property in value)) return;
      let newValue: any = null;
      if (property.startsWith('rewards')) {
        newValue = structuredClone(value.rewards);
      } else {
        newValue = value[property.replace('current', '').toLowerCase()];
      }
      mods.forEach((mod: ModConf) => {
        const modPropertyMatch = mod.modProperty.startsWith(property);
        if (!modPropertyMatch) return;
        const modFunc: Modifier = modList[mod.modName];
        if (property === 'rewards') {
          const resource = mod.modProperty.split('::')[1];
          let currentAmount = newValue.find(
            (reward: Reward) => reward.resource === resource,
          )?.amount;
          currentAmount = modFunc(currentAmount, mod.data);
          newValue = newValue.map((reward: Reward) => {
            if (reward.resource === resource) {
              return { ...reward, currentAmount };
            }
            return reward;
          });
        } else {
          newValue = modFunc(newValue, mod.data);
        }
      });
      store.dispatch(
        updateSkill({
          skill,
          property,
          value: newValue,
        }),
      );
    });
  });
};

export const updateItems = (): void => {};

export const updateAllCurrent = (): void => {
  updateAchievements();
  updateUpgrades();
  updateAttributes();
  updateSkills();
  updateGps();
};

export const restartGame = () => {
  const { dispatch } = store;
  dispatch(resetUnlocks());
  dispatch(resetAttributes());
  dispatch(resetResources());
  dispatch(resetUpgrades());
  dispatch(resetLocations());
  dispatch(resetSkills());
  dispatch(resetItems());
  dispatch(resetGame());
  dispatch(resetNavigation());
  dispatch(resetAnimations());
  dispatch(resetQuests());
  dispatch(resetAchievements());
  updateAllCurrent();
};

export const startCalcs = () => {
  const { dispatch } = store;

  // add all mods from achievements
  // loop over all achievements in use
  const gameAchievements = store.getState().game.usedAchievements;
  const { achievements } = store.getState();
  gameAchievements?.forEach((achievement) => {
    const achievementConf = achievements[achievement];
    achievementConf?.addMods.forEach((mod: AddModifier) => {
      insertAddMod(mod);
    });
  });

  updateAttributes();

  const { resources } = store.getState();

  // loop over all resources and loop over their mods, apply them
  Object.keys(resources).forEach((resourceName) => {
    const resource = resources[resourceName];
    let newCap = resource.cap || 0;
    const { amount } = resource;
    let newAmount = amount;
    const mods = structuredClone(resource.mods);
    // reorder mods by priority ascending
    mods?.sort((a: ModConf, b: ModConf) => a.priority - b.priority);
    mods?.forEach((mod, i) => {
      if (mod.modProperty === 'amount') {
        if (mod.data && mod.data.isApplied) return;
        const modifier = modList[mod.modName] as Modifier;
        newAmount = modifier(newAmount, mod.data);
        if (mod.data && mod.data.isApplied === false) {
          mod.data.isApplied = true;
          mods[i] = mod;
          store.dispatch(
            updateResource({
              resource: resourceName,
              property: 'mods',
              value: mods,
            }),
          );
        }
      }
      if (mod.modProperty === 'currentCap') {
        const modifier = modList[mod.modName] as Modifier;
        newCap = modifier(newCap, mod.data);
      }
    });
    if (resource.isCapped) {
      dispatch(
        updateResource({
          resource: resourceName,
          property: 'currentCap',
          value: newCap,
        }),
      );
      if (newAmount < newCap && newCap) {
        newAmount = newCap;
      }
    }
    if (resource.amount !== newAmount) {
      dispatch(
        updateResource({
          resource: resourceName,
          property: 'amount',
          value: newAmount,
        }),
      );
    }
  });

  // apply relationship mods
  const locations = store.getState().location.list;
  Object.keys(locations).forEach((location) => {
    const newNpc = getNpc(location);
    if (!newNpc) return;
    let didChange = false;
    const { mods } = newNpc;
    mods?.forEach((mod) => {
      if (mod.data.isApplied) return;
      if (mod.modProperty === 'relationship') {
        const modifier = modList[mod.modName] as Modifier;
        newNpc.relationship = modifier(newNpc.relationship, mod.data);
        newNpc.mods.forEach((chMod: any, key: number) => {
          if (mod.data.identifier === chMod.data.identifier) {
            newNpc.mods[key].data.isApplied = true;
          }
        });
        didChange = true;
      }
    });
    if (didChange) {
      store.dispatch(
        updateNpc({
          location,
          npc: newNpc,
        }),
      );
    }
  });

  // reset all skill cooldowns
  const { skills } = store.getState();
  Object.keys(skills).forEach((skill) => {
    dispatch(
      updateSkill({
        skill,
        property: 'lastUsed',
        value: 0,
      }),
    );
  });
};

const generateChoices = (day: number) => {
  // get those that were already used so that they are not repeated
  const previousChoices = store.getState().game.choices || {};
  const unlocks = store.getState().unlocks;
  const previousChoiceNames: string[] = [];
  Object.values(previousChoices).forEach((choicePrevs: any) => {
    choicePrevs.forEach((choice) => {
      if (choice.isSelected) {
        previousChoiceNames.push(choice.name);
      }
    });
  });

  // loop over all choices and check if they are available
  const tempChoices: { [key: string]: ChoiceConf } = {};
  Object.entries(choices).forEach(
    ([choiceName, choiceConf]: [string, ChoiceConf]) => {
      if (
        (choiceConf.minDay && choiceConf.minDay > day) ||
        (choiceConf.maxDay && choiceConf.maxDay < day) ||
        previousChoiceNames.includes(choiceName) ||
        (choiceConf.requirement && !unlocks[choiceConf.requirement].isUnlocked)
      ) {
        return;
      }
      tempChoices[choiceName] = choiceConf;
    },
  );

  // find 3 random choices from the choices object and add to choiceList array
  const choiceNames: string[] = [];
  while (choiceNames.length < balance.numChoiceOptions) {
    const choiceName =
      Object.keys(tempChoices)[
        Math.floor(Math.random() * Object.keys(tempChoices).length)
      ];
    if (!choiceNames.includes(choiceName)) {
      choiceNames.push(choiceName);
    }
  }
  //  get array of ChoiceData and set the value randombly between min and max
  const choiceList = choiceNames.map((choice) => {
    const choiceConf = choices[choice];
    let num = 0;
    if (choiceConf.numReward && choiceConf.data?.resource) {
      const resource = store.getState().resources[choiceConf.data.resource];
      num = getRewardAmount(
        resource,
        day +
          Math.max(
            choiceConf.data.minIncrease ?? 3,
            Math.floor(Math.random() * 5),
          ),
      );
    } else if (choiceConf.numMin && choiceConf.numMax) {
      num = Math.floor(
        Math.random() * (choiceConf.numMax - choiceConf.numMin + 1) +
          choiceConf.numMin,
      );
    }
    return {
      name: choice,
      value: num,
    };
  });

  return choiceList;
};

export const endDay = () => {
  const { dispatch } = store;
  manageUpgrades();
  dispatch(nextDay());
  dispatch(setDayStarted(false));
  dispatch(setDayInitialized(false));
};

export const revertDay = () => {
  const { dispatch } = store;
  dispatch(previousDay());
  dispatch(setDayStarted(false));
  dispatch(setDayInitialized(false));
};

export const initializeDay = () => {
  const { dispatch } = store;
  const currentDay = store.getState().game.day;
  const { usedAchievements } = store.getState().game;
  const { achievements } = store.getState();
  if (
    currentDay === 1 &&
    usedAchievements.length === 0 &&
    Object.keys(achievements).some((key) => achievements[key].isUnlocked)
  ) {
    dispatch(
      updateModal({
        value: {
          type: 'gameStart',
          show: true,
          uncloseable: true,
        },
      }),
    );
    return;
  }
  startCalcs();

  const hasEvent = days[currentDay].event;
  if (hasEvent === 'choice') {
    const choiceList = generateChoices(currentDay);
    dispatch(setChoicesForDay(choiceList));
  }
  dispatch(
    updateModal({
      value: {
        type: 'dayStart',
        show: true,
        uncloseable: hasEvent,
      },
    }),
  );
  if (!hasEvent) {
    dispatch(setDayStarted(true));
  }
  dispatch(setDayInitialized(true));
  updateAllCurrent();
};

export const checkForUnlocks = () => {
  const { unlocks } = store.getState();
  // loop over all unlock  and check if they should be unlocked
  Object.entries(unlocks)
    .filter(([, value]) => !value.isUnlocked)
    .forEach(([unlock]) => {
      if (unlockConditions[unlock] && unlockConditions[unlock].condition()) {
        unlockItem(unlock);
      }
    });
};
