import { FC, useEffect, useState, useRef } from 'react';
import { useSelector } from 'react-redux';
import { Nav, Tab } from 'react-bootstrap';
import { store, type RootState } from '../../store';
import UpgradeBox from '../model/upgradeBox';
import {
  getDialogue,
  getPortrait,
  hasUnseen,
  numberDisplay,
  textDisplay,
} from '../../utils';
import { Dialogue } from '../../conf/dialogueConf';
import { playSfx } from '../../utils/sound';
import Trade from './location/trade';
import Mining from './location/mining';
import Fighting from './location/fighting';
import { updateLocation } from '../../store/locationSlice';
import { setNavigationValue } from '../../store/navigationSlice';
import Realize from './location/realize';
import Crafting from './location/crafting';
import Reading from './location/reading';
import Quests from './location/quests';
import Invest from './location/invest';
import Analyzing from './location/analyzing';
import balance from '../../conf/balanceConf';

const Location: FC<{}> = ({}) => {
  const locations = useSelector((state: RootState) => state.location);
  const upgrades = useSelector((state: RootState) => state.upgrades);
  const unlocks = useSelector((state: RootState) => state.unlocks);
  const animations = useSelector((state: RootState) => state.animations);
  const npc = locations.list[locations.current]?.npc;
  const [dialogueCharsShown, setDialogueCharsShown] = useState(0);
  const dialogueCharsShownRef = useRef(0);
  const dialogueShowIntervalRef = useRef<number | null>(null);
  const [dialogue, setDialogue] = useState<Dialogue | null>(null);
  const [activeTab, setActiveTab] = useState('activity');

  // if animations contains one with type = featureUnlock show overlay
  const isUnlocking = Object.values(animations).some(
    (animation) => animation.type === 'featureUnlock' && animation.active,
  );

  const relationshipLevel = () => {
    const proposed = upgrades[`${locations.current}Propose`]?.amount || 0;
    if (proposed) {
      return 'Partner';
    }
    const relationship = npc?.relationship || 0;
    if (relationship > balance[`${locations.current}CloseRp`]) {
      return 'Close';
    }
    if (relationship > balance[`${locations.current}FriendlyRp`]) {
      return 'Friendly';
    }
    return 'Neutral';
  };

  useEffect(() => {
    if (!npc || !npc.isNewDialogue) {
      return;
    }
    const newDialogue = getDialogue(dialogue?.text);
    if (!newDialogue) {
      return;
    }

    setDialogue(null);

    store.dispatch(
      updateLocation({
        location: locations.current,
        property: 'npc',
        value: { ...npc, isNewDialogue: false },
      }),
    );

    setTimeout(() => {
      setDialogueCharsShown(0);
      dialogueCharsShownRef.current = 0;
      setDialogue(newDialogue);

      if (dialogueShowIntervalRef.current !== null) {
        clearInterval(dialogueShowIntervalRef.current);
        dialogueShowIntervalRef.current = null;
      }

      const intervalNum = window.setInterval(() => {
        dialogueCharsShownRef.current += 1;
        setDialogueCharsShown(dialogueCharsShownRef.current);

        if (
          dialogueCharsShownRef.current >= newDialogue.text.length &&
          dialogueShowIntervalRef.current !== null
        ) {
          clearInterval(dialogueShowIntervalRef.current);
          dialogueShowIntervalRef.current = null;
        }
      }, 33);

      dialogueShowIntervalRef.current = intervalNum;
    }, 10);

    return () => {
      // Clean up the interval when the component unmounts or re-renders
      if (dialogueShowIntervalRef.current !== null) {
        clearInterval(dialogueShowIntervalRef.current);
      }
    };
  }, [npc]);

  return (
    <div
      className={`location-container container has-tabs has-headline flex-grow-1 panel mb-3 pt-2 ${
        locations.current
      } tab-${activeTab}`}
    >
      <div className="headline">
        <button
          type="button"
          aria-label="Back"
          className="btn btn-icon btn-back"
          onMouseOver={() => {
            playSfx('hover');
          }}
          onClick={() => {
            playSfx('click');
            setActiveTab('activity');
          }}
        >
          {locations.list[locations.current].displayName}
        </button>
      </div>
      <Tab.Container
        id="tab-container"
        activeKey={activeTab}
        onSelect={(k) => setActiveTab(k || '')}
      >
        <Nav
          variant="tabs"
          className={`${isUnlocking ? ' unlocking' : ''} flex-row`}
        >
          <Nav.Item
            onMouseOver={() => {
              playSfx('hover');
            }}
            onClick={() => {
              playSfx('click');
            }}
          >
            <Nav.Link
              eventKey="activity"
              className={`${hasUnseen(`${locations.current}::activity`) ? ' new' : ''}`}
            >
              <span className="d-none d-lg-inline">Activities</span>
              <span className="d-inline d-lg-none">Activity</span>
            </Nav.Link>
          </Nav.Item>
          {locations.list[locations.current].upgrades.length > 0 && (
            <Nav.Item
              onMouseOver={() => {
                playSfx('hover');
              }}
              onClick={() => {
                playSfx('click');
              }}
            >
              <Nav.Link
                eventKey="upgrade"
                className={`${hasUnseen(`${locations.current}::upgrade`) ? ' new' : ''}`}
              >
                <span className="d-none d-lg-inline">Upgrades</span>
                <span className="d-inline d-lg-none">Upgrade</span>
              </Nav.Link>
            </Nav.Item>
          )}
          {Object.keys(locations.list[locations.current].features ?? {}).map(
            (feature: string) => (
              <Nav.Item
                onMouseOver={() => {
                  if (unlocks[feature].isUnlocked) {
                    playSfx('hover');
                  }
                }}
                onClick={() => {
                  if (unlocks[feature].isUnlocked) {
                    playSfx('click');
                  }
                }}
                key={feature}
                className={`${animations[`unlock-${feature}`] && animations[`unlock-${feature}`].active ? ' unlocking' : ''}`}
              >
                <Nav.Link
                  eventKey={feature}
                  className={`${unlocks[feature].isUnlocked ? '' : ' locked'} ${hasUnseen(feature) ? ' new' : ''} ${animations[`unlock-${feature}`] && animations[`unlock-${feature}`].active ? ' unlocking' : ''}`}
                  disabled={!unlocks[feature].isUnlocked}
                >
                  <span className="d-none d-lg-inline">
                    {
                      locations.list[locations.current].features?.[feature]
                        ?.displayName
                    }
                  </span>
                  <span className="d-inline d-lg-none">
                    {locations.list[locations.current].features?.[feature]
                      ?.abbreviation ||
                      locations.list[locations.current].features?.[feature]
                        ?.displayName}
                  </span>
                </Nav.Link>
              </Nav.Item>
            ),
          )}
          <div className={`unlock-overlay ${isUnlocking ? 'active' : ''}`} />
        </Nav>
        <Tab.Content>
          <Tab.Pane eventKey="activity">
            {npc && (
              <div className="npc-box d-flex flex-row">
                <div className="portrait">
                  <img
                    src={getPortrait(
                      npc.name,
                      dialogue ? dialogue.portrait : 'neutral',
                    )}
                    alt=""
                  />
                  <div className="name">{npc.displayName}</div>
                  <div className="profession">{npc.profession}</div>
                  <div className="relationship">
                    Relationship: {numberDisplay(npc.relationship)}
                  </div>
                  <div className="relationship-level">
                    {relationshipLevel()}
                  </div>
                </div>
                <div
                  className={`dialogue d-flex justify-content-center flex-column${
                    dialogue ? '' : ' silent'
                  }`}
                >
                  <div className="name">{npc.displayName} says:</div>
                  <div className="dialogue-text">
                    {dialogue?.text.slice(0, dialogueCharsShownRef.current)}
                  </div>
                </div>
              </div>
            )}
            <div className="scroll-container container">
              <div className="row panel-list">
                {(() => {
                  // First sort the activities
                  const sortedActivities = locations.list[
                    locations.current
                  ].activities
                    .filter((upgrade: string) => unlocks[upgrade]?.isUnlocked)
                    .sort((a: string, b: string) => {
                      // if limit is reached, then put to the end
                      const aLimitReached =
                        upgrades[a].limit &&
                        upgrades[a].amount >= upgrades[a].limit
                          ? 1
                          : 0;
                      const bLimitReached =
                        upgrades[b].limit &&
                        upgrades[b].amount >= upgrades[b].limit
                          ? 1
                          : 0;

                      if (aLimitReached !== bLimitReached) {
                        return aLimitReached - bLimitReached;
                      }

                      // Then sort by group alphabetically
                      const aGroup = upgrades[a]?.group || '';
                      const bGroup = upgrades[b]?.group || '';

                      // Special case: "Completed" group should always be last
                      if (aGroup === 'Completed' && bGroup !== 'Completed') {
                        return 1; // a is "Completed", so it comes after b
                      }
                      if (aGroup !== 'Completed' && bGroup === 'Completed') {
                        return -1; // b is "Completed", so it comes after a
                      }

                      // For all other groups, sort alphabetically
                      if (aGroup !== bGroup) {
                        return aGroup.localeCompare(bGroup);
                      }

                      // Finally sort by order property
                      return (
                        (upgrades[a]?.order || 0) - (upgrades[b]?.order || 0)
                      );
                    });

                  // If no activities, show message
                  if (sortedActivities.length === 0) {
                    return (
                      <div className="col-12">
                        No activities currently available
                      </div>
                    );
                  }

                  // Then render with group headers
                  const result = [];
                  let currentGroup = null;

                  sortedActivities.forEach((upgrade: string) => {
                    const upgradeGroup = upgrades[upgrade]?.group || '';

                    // Add a group header if the group has changed
                    if (upgradeGroup !== currentGroup) {
                      currentGroup = upgradeGroup;
                      if (currentGroup) {
                        result.push(
                          <div
                            className={`col-12 group-separator group-${currentGroup}`}
                            key={`group-${currentGroup}`}
                          >
                            <h3
                              className="group-header"
                              dangerouslySetInnerHTML={{
                                __html: textDisplay(currentGroup, true),
                              }}
                            />
                          </div>,
                        );
                      }
                    }

                    // Add the upgrade component
                    result.push(
                      <UpgradeBox upgradeName={upgrade} key={upgrade} />,
                    );
                  });

                  return result;
                })()}
              </div>
            </div>
          </Tab.Pane>
          <Tab.Pane eventKey="upgrade">
            <div className="scroll-container container">
              <div className="row panel-list">
                {(() => {
                  // First sort the upgrades
                  const sortedUpgrades = locations.list[
                    locations.current
                  ].upgrades
                    .filter((upgrade: string) => unlocks[upgrade].isUnlocked)
                    .sort((a: string, b: string) => {
                      // Then sort by group alphabetically
                      const aGroup = upgrades[a]?.group || '';
                      const bGroup = upgrades[b]?.group || '';

                      // Special case: "Completed" group should always be last
                      if (aGroup === 'Completed' && bGroup !== 'Completed') {
                        return 1; // a is "Completed", so it comes after b
                      }
                      if (aGroup !== 'Completed' && bGroup === 'Completed') {
                        return -1; // b is "Completed", so it comes after a
                      }

                      // For all other groups, sort alphabetically
                      if (aGroup !== bGroup) {
                        return aGroup.localeCompare(bGroup);
                      }

                      // Finally sort by order property
                      return (
                        (upgrades[a]?.order || 0) - (upgrades[b]?.order || 0)
                      );
                    });

                  // If no upgrades, show message
                  if (sortedUpgrades.length === 0) {
                    return (
                      <div className="col-12">
                        No upgrades currently available
                      </div>
                    );
                  }

                  // Then render with group headers
                  const result = [];
                  let currentGroup = null;

                  sortedUpgrades.forEach((upgrade: string) => {
                    const upgradeGroup = upgrades[upgrade]?.group || '';

                    // Add a group header if the group has changed
                    if (upgradeGroup !== currentGroup) {
                      currentGroup = upgradeGroup;
                      if (currentGroup) {
                        result.push(
                          <div
                            className={`col-12 group-separator group-${currentGroup}`}
                            key={`group-${currentGroup}`}
                          >
                            <h3
                              className="group-header"
                              dangerouslySetInnerHTML={{
                                __html: textDisplay(currentGroup, true),
                              }}
                            />
                          </div>,
                        );
                      }
                    }

                    // Add the upgrade component
                    result.push(
                      <UpgradeBox upgradeName={upgrade} key={upgrade} />,
                    );
                  });

                  return result;
                })()}
              </div>
            </div>
          </Tab.Pane>
          {Object.keys(locations.list[locations.current].features ?? {}).map(
            (feature: string) => (
              <Tab.Pane eventKey={feature} key={feature}>
                <div className="scroll-container container">
                  <div className="row">
                    {
                      {
                        trade: <Trade isActive={activeTab === 'trade'} />,
                        invest: <Invest isActive={activeTab === 'invest'} />,
                        mining: <Mining isActive={activeTab === 'mining'} />,
                        fighting: (
                          <Fighting isActive={activeTab === 'fighting'} />
                        ),
                        reading: <Reading isActive={activeTab === 'reading'} />,
                        analyzing: (
                          <Analyzing isActive={activeTab === 'analyzing'} />
                        ),
                        realize: <Realize isActive={activeTab === 'realize'} />,
                        crafting: (
                          <Crafting
                            isActive={activeTab === 'crafting'}
                            type="material"
                          />
                        ),
                        imbue: (
                          <Crafting
                            isActive={activeTab === 'imbue'}
                            type="spiritual"
                          />
                        ),
                        writing: (
                          <Crafting
                            isActive={activeTab === 'writing'}
                            type="mental"
                          />
                        ),
                        quests: <Quests isActive={activeTab === 'quests'} />,
                      }[feature]
                    }
                  </div>
                </div>
              </Tab.Pane>
            ),
          )}
        </Tab.Content>
      </Tab.Container>
    </div>
  );
};

export default Location;
