import { FC, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import type { RootState } from '../../store';
import { store } from '../../store';
import { updateModal, confirmModal } from '../../store/navigationSlice';
import SettingsModal from './settingsModal';
import DayStartModal from './dayStartModal';
import GameOverModal from './gameOverModal';
import SkillAddConfirmModal from './skillAddConfirmModal';
import RestartConfirmModal from './restartConfirmModal';
import GameStartModal from './gameStartModal';
import CalendarModal from './calendarModal';
import ActionResultModal from './actionResultModal';
import CreditsModal from './creditsModal';
import AchievementsModal from './achievementsModal';
import GameDataModal from './gameDataModal';
import FightModal from './fightModal';
import VersionChangeModal from './versionChangeModal';
import { setVersionChanged } from '../../store/gameSlice';

type ModalProps = {
  purpose?: string;
};

const Modal: FC<ModalProps> = ({ purpose }) => {
  const navigation = useSelector((state: RootState) => state.navigation);
  const modalSetup =
    purpose === 'confirm' ? navigation.confirm : navigation.modal;
  const gameVersionChanged = useSelector(
    (state: RootState) => state.game.versionChanged,
  );
  const [isOpen, setIsOpen] = useState(modalSetup.show);
  useEffect(() => {
    const timeoutId = setTimeout(() => {
      setIsOpen(modalSetup.show);
    }, 10);

    return () => {
      clearTimeout(timeoutId);
    };
  }, [modalSetup.show]);

  useEffect(() => {
    if (gameVersionChanged && !isOpen) {
      store.dispatch(
        updateModal({
          value: { show: true, type: 'versionChange' },
        }),
      );
    }
  }, [gameVersionChanged, isOpen]);

  // if you press ctrl + alt + q it will close the modal
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (process.env.NODE_ENV !== 'development') return () => {};
      if (event.ctrlKey && event.altKey && event.key === 'q') {
        store.dispatch(
          updateModal({
            value: { show: false, type: '' },
          }),
        );
        store.dispatch(
          confirmModal({
            value: { show: false, type: '' },
          }),
        );
        store.dispatch(setVersionChanged(false));
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  return (
    // make modal visible if show is true
    <div
      className={`modal ${isOpen ? 'open' : ''} ${modalSetup.show ? 'show' : ''} ${modalSetup.uncloseable ? 'uncloseable' : ''} ${purpose || ''}`}
      tabIndex={-1}
      role="button"
      style={{ display: modalSetup.show ? 'block' : 'none' }}
      onClick={(event) => {
        // if the click was exactly on this element and not child then close modal
        if (
          event.target === event.currentTarget &&
          !modalSetup.uncloseable &&
          !navigation.confirm.show
        ) {
          store.dispatch(setVersionChanged(false));
          store.dispatch(
            updateModal({
              value: { show: false, type: '' },
            }),
          );
        }
      }}
    >
      <div className="modal-dialog">
        {
          {
            settings: <SettingsModal />,
            dayStart: <DayStartModal />,
            gameOver: <GameOverModal />,
            skillAddConfirm: <SkillAddConfirmModal />,
            restartConfirm: <RestartConfirmModal />,
            fight: <FightModal />,
            credits: <CreditsModal />,
            gameStart: <GameStartModal />,
            calendar: <CalendarModal />,
            actionResult: <ActionResultModal />,
            achievements: <AchievementsModal />,
            manageData: <GameDataModal />,
            versionChange: <VersionChangeModal />,
          }[modalSetup.type]
        }
      </div>
    </div>
  );
};

export default Modal;
