import React, { FC, useEffect } from 'react';
import { ProgressBar } from 'react-bootstrap';
import { useSelector } from 'react-redux';
import { Tooltip } from 'react-tooltip';
import { store, type RootState } from '../../store';
import TooltipContent from '../util/tooltipContent';
import { numberDisplay, textDisplay } from '../../utils';
import Gps from './gps';
import { addResource } from '../../utils/gameUtil';
import { updateResource } from '../../store/resourceSlice';

interface ResourceProps {
  resourceName: string;
}

const Status: FC<ResourceProps> = ({ resourceName }) => {
  const resource = useSelector(
    (state: RootState) => state.resources[resourceName],
  );
  const [isHovered, setIsHovered] = React.useState(false);

  useEffect(() => {
    if (process.env.NODE_ENV !== 'development') return () => {};
    const handleKeyUp = (event: KeyboardEvent) => {
      if (isHovered && event.key === '+') {
        addResource(resourceName, 10000);
      }
      // if key is multiply key, multiply the value by 2
      if (isHovered && event.key === '*') {
        addResource(resourceName, resource.amount);
      }
      if (isHovered && event.key === '0') {
        store.dispatch(
          updateResource({
            resource: resourceName,
            property: 'amount',
            value: 0,
          }),
        );
      }
    };
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keyup', handleKeyUp);
    };
  });

  return (
    <div
      className={`capped-resource-box ${resourceName}`}
      style={{ '--var-color': resource.color } as React.CSSProperties}
      data-tooltip-id={`tooltip-resource-${resourceName}`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <div className="d-flex align-items-center justify-content-between">
        <div
          dangerouslySetInnerHTML={{
            __html: textDisplay(`${resourceName}::full`),
          }}
        />
        <Gps resource={resource} />
      </div>
      <div className="progress-box">
        <ProgressBar
          striped
          animated
          now={resource.amount}
          max={resource.currentCap}
        />
        <div className="progress-label num">
          {numberDisplay(resource.amount)} /{' '}
          {numberDisplay(resource.currentCap as number)}
        </div>
      </div>

      <Tooltip id={`tooltip-resource-${resourceName}`} place="right-end">
        <TooltipContent content={resource} />
      </Tooltip>
    </div>
  );
};

export default Status;
