import { FC, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { Tooltip } from 'react-tooltip';
import { store, RootState } from '../../../store';
import { setSeen } from '../../../store/unlockSlice';
import { MineTile } from '../../../types';
import balance from '../../../conf/balanceConf';
import { playSfx } from '../../../utils/sound';
import {
  openTile,
  generateTiles,
  getDeepestOpenTile,
  tileTypes,
  getFullCost,
} from '../../../utils/location/mines';
import ModelIcon from '../../model/modelIcon';
import AcquiredResources from '../../util/acquiredResource';
import CostHandler from '../../../utils/costHandler';
import CostTooltip from '../../util/costTooltip';

const Mining: FC<{ isActive: boolean }> = ({ isActive }) => {
  const resources = useSelector((state: RootState) => state.resources);
  const unlocks = useSelector((state: RootState) => state.unlocks);
  const grid = useSelector(
    (state: RootState) => state.location.list.mines.values?.grid,
  );
  const licenses = useSelector(
    (state: RootState) => state.location.list.mines.values?.miningLicenses,
  );

  const [acquiredResources, setAcquiredResources] = useState<
    Record<string, any>
  >({});
  const [isTooltipOpen, setIsTooltipOpen] = useState<boolean>(false);
  const [costHandler, setCostHandler] = useState<CostHandler>(null);

  const tileOpenHandler = (i: number, j: number) => {
    const ret = openTile(i, j, resources, grid);
    if (ret) {
      setIsTooltipOpen(false);
      setAcquiredResources({
        ...acquiredResources,
        [`tile-${i}-${j}`]: ret,
      });
    }
  };

  useEffect(() => {
    // if on this tab, mark as seen
    if (!unlocks.mining.isSeen && isActive) {
      store.dispatch(setSeen('mining'));
    }
    if (isActive) {
      // if not enough tiles generated, do it
      const deepestOpen = getDeepestOpenTile(grid);
      if (
        grid.length - deepestOpen < balance.mining.rowsGenerated &&
        deepestOpen < balance.mining.maxDepth
      ) {
        generateTiles(grid);
      }
    }
  });
  return (
    <div className="mining">
      <div className="mining-grid">
        <div
          className="miningLicenses-info"
          data-tooltip-id="tooltip-mining-licenses"
        >
          <div className="miningLicenses">
            <div className="miningLicenses-icon" />
            <div className="license-quantity num">{licenses}</div>
          </div>
          <Tooltip id="tooltip-mining-licenses" place="top" className="wrap">
            Mining Licenses
          </Tooltip>
        </div>
        {grid?.map((row: MineTile[], i: number) => (
          <div className="mine-row" key={i}>
            {row.map((tile: MineTile, j: number) => (
              <div
                className={`mine-tile ${tile.visible ? 'visible' : ''}
                  ${tile.open ? 'open' : ''} ${tile.clickable ? 'clickable' : ''}`}
                key={`tile-${i}-${j}`}
              >
                <AcquiredResources
                  acquiredResources={acquiredResources}
                  isOpen={tile.open}
                  animationKey={`tile-${i}-${j}`}
                />

                <div
                  role="button"
                  aria-label="tile"
                  className={`tile-box ${tile.type}`}
                  tabIndex={0}
                  onClick={() => {
                    if (tile.clickable && !tile.open) {
                      playSfx('click');
                      tileOpenHandler(i, j);
                    }
                  }}
                  onMouseEnter={() => {
                    if (tile.clickable && !tile.open) {
                      setCostHandler(getFullCost(i));
                      setIsTooltipOpen(true);
                      playSfx('hover');
                    }
                  }}
                  onMouseLeave={() => {
                    setIsTooltipOpen(false);
                  }}
                  data-tooltip-id={
                    tile.clickable && !tile.open ? `tooltip-cost` : undefined
                  }
                >
                  {tileTypes.includes(tile.type) &&
                    tile.type !== tileTypes[tileTypes.length - 1] && (
                      <ModelIcon model={resources[tile.type]} />
                    )}
                </div>
              </div>
            ))}
          </div>
        ))}
      </div>

      <CostTooltip costHandler={costHandler} isTooltipOpen={isTooltipOpen} />
    </div>
  );
};
export default Mining;
