import { FC, useEffect, useState, useRef } from 'react';
import { useSelector } from 'react-redux';
import { Navbar } from 'react-bootstrap';
import { Tooltip } from 'react-tooltip';
import type { RootState } from '../../store';
import { Resource } from '../../types';
import ResourceBox from './resourceBox';
import TooltipContent from '../util/tooltipContent';

const ResourceList: FC<{}> = () => {
  const [resourcesMaxHeight, setResourcesMaxHeight] = useState(0);
  const resizeObserverRef = useRef<ResizeObserver | null>(null);
  const attributesContainerRef = useRef<HTMLElement | null>(null);
  const cappedResourcesContainerRef = useRef<HTMLElement | null>(null);

  const handleResize = () => {
    // if window width is less than 768px, set max height to 100%
    if (window.innerWidth < 768) {
      setResourcesMaxHeight(window.innerHeight / 3);
      return;
    }

    const attributesContainer =
      attributesContainerRef.current ||
      document.querySelector('.attributes-container');
    if (attributesContainer)
      attributesContainerRef.current = attributesContainer as HTMLElement;

    const cappedResourcesContainer =
      cappedResourcesContainerRef.current ||
      document.querySelector('.capped-resources-container');
    if (cappedResourcesContainer)
      cappedResourcesContainerRef.current =
        cappedResourcesContainer as HTMLElement;

    const attributesHeight = attributesContainer?.clientHeight || 0;
    const cappedResourcesHeight = cappedResourcesContainer?.clientHeight || 0;

    setResourcesMaxHeight(
      window.innerHeight - attributesHeight - cappedResourcesHeight - 235,
    );
  };

  const [isCollapsed, setIsCollapsed] = useState(false);
  const handleToggle = () => {
    setIsCollapsed(!isCollapsed);
  };

  useEffect(() => {
    // Set up ResizeObserver to watch for height changes
    resizeObserverRef.current = new ResizeObserver(() => {
      handleResize();
    });

    // Get the containers
    const attributesContainer = document.querySelector('.attributes-container');
    const cappedResourcesContainer = document.querySelector(
      '.capped-resources-container',
    );

    // Store references for faster access later
    if (attributesContainer) {
      attributesContainerRef.current = attributesContainer as HTMLElement;
      resizeObserverRef.current.observe(attributesContainer);
    }

    if (cappedResourcesContainer) {
      cappedResourcesContainerRef.current =
        cappedResourcesContainer as HTMLElement;
      resizeObserverRef.current.observe(cappedResourcesContainer);
    }

    // Also handle window resize
    window.addEventListener('resize', handleResize);

    // Initial calculation
    setTimeout(handleResize, 10);

    // Cleanup
    return () => {
      window.removeEventListener('resize', handleResize);
      if (resizeObserverRef.current) {
        resizeObserverRef.current.disconnect();
      }
    };
  }, []);

  const resources = useSelector((state: RootState) => state.resources);
  const unlocks = useSelector((state: RootState) => state.unlocks);

  return (
    <div className="resources-container">
      <Navbar expand="">
        <Navbar.Toggle
          className="d-flex justify-content-between w-100"
          aria-controls="resources-wrapper"
          onClick={handleToggle}
        >
          <h2 className="title">Resources</h2>
          {/* eslint-disable-next-line jsx-a11y/anchor-is-valid */}
          <a className="btn btn-icon btn-toggle" aria-label="Toggle" />
        </Navbar.Toggle>
        <Navbar.Collapse in={!isCollapsed}>
          <div className="resources-wrapper" id="resources-wrapper">
            <div
              className="resources"
              style={{ maxHeight: resourcesMaxHeight }}
            >
              {['currency', 'material', 'spiritual', 'mental', 'potion'].map(
                (type: string) => (
                  <div key={type} className="row pb-2">
                    {(Object.values(resources) as Resource[])
                      .sort(
                        (a: Resource, b: Resource) =>
                          (a.order || 0) - (b.order || 0),
                      ) // Add null check for 'order' property
                      .filter(
                        (resource: Resource) =>
                          !resource.isCapped &&
                          unlocks[resource.name].isUnlocked &&
                          resource.type === type,
                      )
                      .map((resource: Resource) => (
                        <ResourceBox
                          resourceName={resource.name}
                          key={resource.name}
                        />
                      ))}
                  </div>
                ),
              )}
            </div>
          </div>
          {(Object.values(resources) as Resource[]).map(
            (resource: Resource) => (
              <Tooltip
                key={resource.name}
                id={`tooltip-${resource.name}`}
                place="top"
                offset={0}
              >
                <TooltipContent content={resource} />
              </Tooltip>
            ),
          )}
        </Navbar.Collapse>
      </Navbar>
    </div>
  );
};
export default ResourceList;
