import React, { FC } from 'react';
import { useSelector } from 'react-redux';
import { Tooltip } from 'react-tooltip';
import { RootState } from '../../store';
import { Item, ItemSlot } from '../../types';
import { getIcon, textDisplay } from '../../utils';
import { itemSlotList } from '../../conf/itemConf';
import { playSfx } from '../../utils/sound';

interface ItemProps {
  item: Item | undefined;
  setSelectedItem: (item: Item) => void;
  isEquipped?: string;
}

const ItemBox: FC<ItemProps> = ({ item, setSelectedItem, isEquipped }) => {
  const items = useSelector((state: RootState) => state.items);
  return (
    <button
      type="button"
      className={`item-slot${item ? ' has-item' : ''}${
        isEquipped ? ` equip-slot has-tooltip slot-${isEquipped}` : ''
      }${item !== undefined && !item.isSeen ? ' new' : ''}`}
      style={
        item
          ? ({
              '--var-color': item.color,
            } as React.CSSProperties)
          : {}
      }
      onClick={
        item
          ? () => {
              playSfx('click');
              setSelectedItem(item);
            }
          : undefined
      }
      data-tooltip-id={`tooltip-item-${isEquipped ? `equip-${isEquipped}-` : ''}${item?.uuid}`}
      onMouseOver={
        item
          ? () => {
              playSfx('hover');
            }
          : undefined
      }
    >
      {item && (
        <>
          <span
            className={`model-icon ${item.color}`}
            style={{
              WebkitMaskImage: `url(${getIcon(item.icon)})`,
            }}
          />
          <div
            className="item-attr"
            dangerouslySetInnerHTML={{
              __html: textDisplay(
                `[[${item.attributeAmount}]]${item.attribute}`,
              ),
            }}
          />
        </>
      )}
      <Tooltip
        place="top"
        id={`tooltip-item-${isEquipped ? `equip-${isEquipped}-` : isEquipped}${item?.uuid}`}
      >
        {isEquipped
          ? `Equipped ${itemSlotList[isEquipped as ItemSlot].singular}:`
          : ''}
        {isEquipped && <br />}
        {item ? 'Click to view details' : 'None equipped'}
      </Tooltip>
      {!isEquipped &&
        item &&
        items.equipped[item.slot as ItemSlot]?.uuid === item?.uuid && (
          <div className="equipped">E</div>
        )}
    </button>
  );
};

export default ItemBox;
