import React, { FC, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { Tooltip } from 'react-tooltip';
import { RootState, store } from '../../../store';
import UpgradeBox from '../../model/upgradeBox';
import { setSeen } from '../../../store/unlockSlice';

const Reading: FC<{ isActive: boolean }> = ({ isActive }) => {
  const values = useSelector(
    (state: RootState) => state.location.list.library.values,
  );
  const actions = useSelector(
    (state: RootState) => state.location.list.library.features.reading.actions,
  );
  const unlocks = useSelector((state: RootState) => state.unlocks);

  useEffect(() => {
    // if on this tab, mark as seen
    if (!unlocks.reading.isSeen && isActive) {
      store.dispatch(setSeen('reading'));
    }
  });

  return (
    <div className="reading">
      <div className="reading-header">
        <h1>Reading</h1>

        <div
          className="recommendations"
          data-tooltip-id="tooltip-recommendations"
        >
          <div className="recommendations-icon" />
          <div className="recommendations-quantity num">
            {values.recommendations}
          </div>
          <Tooltip id="tooltip-recommendations" place="top" className="wrap">
            Book recommendations
          </Tooltip>
        </div>
      </div>
      <div className="reading-body row panel-list">
        {actions
          .filter((action) => unlocks[action.name]?.isUnlocked)
          .map((action) => (
            <UpgradeBox key={action.name} upgradeName={action.name} />
          ))}
      </div>
    </div>
  );
};

export default Reading;
