/* eslint-disable no-continue */
import { store } from '../../store';
import { updateFeatureValue } from '../../store/locationSlice';
import { RealizeTableCell, Resource, CostList, Cost } from '../../types';
import { startAnimation } from '../../store/animationSlice';
import balance from '../../conf/balanceConf';
import { playSfx } from '../sound';
import {
  addAttribute,
  addResource,
  getRewardAmount,
  unlockedResourceTier,
} from '../gameUtil';
import CostHandler from '../costHandler';
import { getBalanceModded } from '../modUtil';

const findRandomEmptyCell = (table: RealizeTableCell[][]) => {
  const { values } = store.getState().location.list.temple;
  const height = values.tableHeight;
  const width = values.tableWidth;
  let i = 0;
  let j = 0;
  let attempts = 0;
  const maxAttempts = 1000;
  while (attempts < maxAttempts) {
    attempts += 1;
    i = Math.floor(Math.random() * height);
    j = Math.floor(Math.random() * width);
    if (!table[i][j].rewardResource) {
      break;
    }
  }
  return { i, j };
};

// matching is either on the same row or column in a straight line
const findRandomMatchingEmptyCell = (
  table: RealizeTableCell[][],
  i: number,
  j: number,
) => {
  const { values } = store.getState().location.list.temple;
  const height = values.tableHeight;
  const width = values.tableWidth;
  let cell = null;

  // find a random cell, not just next to it. can be further away
  let attempts = 0;
  const maxAttempts = 1000;

  while (attempts < maxAttempts) {
    attempts += 1;
    const direction = Math.random() < 0.5 ? 'row' : 'column';
    const sign = Math.random() < 0.5 ? -1 : 1;
    const distance = Math.floor(Math.random() * 5) + 1;
    if (direction === 'row') {
      const newRow = i + sign * distance;
      if (newRow >= 0 && newRow < height) {
        if (!table[newRow][j].rewardResource) {
          cell = { i: newRow, j };
          break;
        }
      }
    } else {
      const newColumn = j + sign * distance;
      if (newColumn >= 0 && newColumn < width) {
        if (!table[i][newColumn].rewardResource) {
          cell = { i, j: newColumn };
          break;
        }
      }
    }
  }

  return cell;
};

const setValue = (property: string, value: any) => {
  store.dispatch(
    updateFeatureValue({
      location: 'temple',
      property,
      value,
    }),
  );
};

const setCellValue = (i: number, j: number, property: string, value: any) => {
  const table = structuredClone(
    store.getState().location.list.temple.values.table,
  );
  table[i][j][property] = value;
  setValue('table', table);
};

// retuns array of resources
const rewardResourceList = () => {
  const { values } = store.getState().location.list.temple;
  const count = values.tableCounter;
  const { resources } = store.getState();
  const list: Resource[] = [];

  Object.keys(resources).forEach((key) => {
    if (
      resources[key].isCapped ||
      (resources[key].type !== 'material' &&
        resources[key].type !== 'spiritual') ||
      key === 'coins' ||
      resources[key].tier > unlockedResourceTier(count) ||
      resources[key].limited
    )
      return;
    list.push(resources[key]);
  });
  return list;
};

const generateTable = (increaseCounter: boolean = true) => {
  const { values } = store.getState().location.list.temple;
  const table = [];

  let { tableHeight, tableWidth } = values;

  let { tableCounter } = values;
  const rewardTier = Math.floor(tableCounter / 10) + 1;

  if (increaseCounter) {
    const { levelsPerSize } = balance.realize;
    if (tableCounter % levelsPerSize === 0) {
      if (tableHeight < tableWidth && tableHeight < balance.realize.maxHeight) {
        tableHeight += 1;
        setValue('tableHeight', tableHeight);
      } else if (tableWidth < balance.realize.maxWidth) {
        tableWidth += 1;
        setValue('tableWidth', tableWidth);
      }
    }
    tableCounter += 1;
    setValue('tableCounter', tableCounter);
    setValue('isRedo', false);
  } else {
    setValue('isRedo', true);
  }

  for (let i = 0; i < tableHeight; i += 1) {
    const row = [];
    for (let j = 0; j < tableWidth; j += 1) {
      const cell: RealizeTableCell = {
        open: false,
        active: false,
        rewardResource: '',
        rewardAmount: 0,
      };
      row.push(cell);
    }
    table.push(row);
  }

  // first add all spiritual resources because they are always available
  const resources = rewardResourceList();
  // randomize the order
  resources.sort(() => Math.random() - 0.5);

  const spiritualAddedFromTier: Record<number, boolean> = {};
  for (let i = 0; i < resources.length; i += 1) {
    const resource = resources[i];
    if (resource.type !== 'spiritual') {
      continue;
    }

    // include all spiritual resources from the current tier but only one from each other tier
    if (spiritualAddedFromTier[resource.tier] && resource.tier !== rewardTier) {
      continue;
    }

    spiritualAddedFromTier[resource.tier] = true;
    const cell = findRandomEmptyCell(table);
    const matching = findRandomMatchingEmptyCell(table, cell.i, cell.j);
    if (matching) {
      const amount = getRewardAmount(resource, tableCounter);
      table[cell.i][cell.j].rewardResource = resource.name;
      table[cell.i][cell.j].rewardAmount = amount;
      table[matching.i][matching.j].rewardResource = resource.name;
      table[matching.i][matching.j].rewardAmount = amount;
    }
  }

  for (let i = 0; i < tableHeight; i += 1) {
    for (let j = 0; j < tableWidth; j += 1) {
      const cell = table[i][j];
      if (!cell.rewardResource) {
        const matching = findRandomMatchingEmptyCell(table, i, j);
        if (matching) {
          const resource = resources.pop();
          if (!resource) {
            continue;
          }
          let amount = getRewardAmount(resource, tableCounter);
          if (resource.type === 'spiritual') {
            amount += tableCounter % 10;
          }
          cell.rewardResource = resource.name;
          cell.rewardAmount = amount;
          table[matching.i][matching.j].rewardResource = resource.name;
          table[matching.i][matching.j].rewardAmount = amount;
        }
      }
    }
  }

  // go over all cells again and fill the empty ones with coins
  for (let i = 0; i < tableHeight; i += 1) {
    for (let j = 0; j < tableWidth; j += 1) {
      const cell = table[i][j];
      if (!cell.rewardResource) {
        cell.rewardResource = 'coins';
        cell.rewardAmount = getRewardAmount(
          store.getState().resources.coins,
          tableCounter,
        );
      }
    }
  }
  store.dispatch(
    updateFeatureValue({
      location: 'temple',
      property: 'table',
      value: table,
    }),
  );
};

const hasActiveCard = () => {
  const cards = getActiveCards();
  return cards.length === 1 ? cards[0] : false;
};

const hasTwoActiveCards = () => {
  const cards = getActiveCards();
  return cards.length === 2;
};

const getActiveCards = () => {
  const { table } = store.getState().location.list.temple.values;
  const activeCards = [];
  for (let i = 0; i < table.length; i += 1) {
    for (let j = 0; j < table[i].length; j += 1) {
      if (table[i][j].active) {
        activeCards.push({ i, j });
      }
    }
  }
  return activeCards;
};

const addAnimation = (i: number, j: number, type: string) => {
  store.dispatch(
    startAnimation({
      element: `card${type}-${i}-${j}`,
      type: `card${type}`,
      value: 0,
      duration: 1000,
    }),
  );
};

// for testing
const resetBoard = () => {
  const { table } = store.getState().location.list.temple.values;
  for (let i = 0; i < table.length; i += 1) {
    for (let j = 0; j < table[i].length; j += 1) {
      setCellValue(i, j, 'active', false);
      setCellValue(i, j, 'open', false);
    }
  }
};

const getFullCost = (depth: number) => {
  const costHandler = new CostHandler();
  costHandler.addExpCost('focus', 'realize', depth);
  costHandler.addCost('ticket_realizations', depth);
  return costHandler;
};

const addCardResources = (x: number, y: number, setAcquiredResources: any) => {
  const card = store.getState().location.list.temple.values.table[x][y];
  const resource = card.rewardResource;
  const amount = card.rewardAmount;
  const key = `card-${x}-${y}`;
  const addedResources = [];
  addResource(resource, amount);
  addedResources.push({ resource, amount });
  setAcquiredResources({ [key]: addedResources });
  store.dispatch(
    startAnimation({
      element: key,
      type: 'card',
      value: 0,
      duration: 3000,
    }),
  );
};

const isCompleted = () => {
  const { table } = store.getState().location.list.temple.values;
  for (let i = 0; i < table.length; i += 1) {
    for (let j = 0; j < table[i].length; j += 1) {
      if (!table[i][j].open) {
        return false;
      }
    }
  }
  return true;
};

const canBuyFlip = () => {
  const { values } = store.getState().location.list.temple;
  const fullCost = getFullCost(values.tableCounter);
  return fullCost.canPayCosts();
};

const flipCard = (i: number, j: number, setAcquiredResources: any) => {
  const { values } = store.getState().location.list.temple;
  const { table } = values;
  const twoActive = hasTwoActiveCards();
  const isCoins = table[i][j].rewardResource === 'coins';
  const active = hasActiveCard();
  const costHandler = getFullCost(values.tableCounter);
  if (
    twoActive ||
    (active && table[active.i][active.j].rewardResource === 'coins') ||
    !costHandler.canPayCosts()
  ) {
    return;
  }
  setCellValue(i, j, 'active', true);
  costHandler.payAllCosts();

  if (active || isCoins) {
    setTimeout(() => {
      let activeCard = table[i][j];
      if (active) {
        activeCard = table[active.i][active.j];
      }
      if (
        activeCard.rewardResource === 'coins' ||
        (activeCard.rewardResource === table[i][j].rewardResource &&
          activeCard.rewardAmount === table[i][j].rewardAmount)
      ) {
        addAnimation(i, j, 'Matched');
        setCellValue(i, j, 'open', true);
        setCellValue(i, j, 'active', false);
        playSfx('correct');
        if (active) {
          addAnimation(active.i, active.j, 'Matched');
          setCellValue(active.i, active.j, 'open', true);
          setCellValue(active.i, active.j, 'active', false);
          addCardResources(i, j, setAcquiredResources);
          if (isCompleted() && !values.isRedo) {
            addAttribute(
              'attrWis',
              Math.ceil(values.tableCounter / 10),
              'realize',
            );
          }
        }
      } else {
        addAnimation(i, j, isCoins ? 'Matched' : 'Wrong');
        if (active) addAnimation(active.i, active.j, 'Wrong');
        playSfx('wrong');
        setTimeout(() => {
          setCellValue(i, j, 'active', false);
          if (isCoins) {
            setCellValue(i, j, 'open', true);
            addCardResources(i, j, setAcquiredResources);
            if (isCompleted()) {
              addAttribute(
                'attrWis',
                Math.ceil(values.tableCounter / 10),
                'realize',
              );
            }
          }
          if (active) setCellValue(active.i, active.j, 'active', false);
        }, 1000);
      }
    }, 500);
  } else {
    const numHintDirections = getBalanceModded('realizePossibleDirections');
    const possibleDirections = ['up', 'down', 'left', 'right'];
    if (numHintDirections < 4) {
      const hintDirections = [];
      hintDirections.push(correctDirection());
      while (hintDirections.length < numHintDirections) {
        const randomDirection =
          possibleDirections[Math.floor(Math.random() * 4)];
        if (!hintDirections.includes(randomDirection)) {
          hintDirections.push(randomDirection);
        }
      }
      setValue('hintDirections', hintDirections);
    }
  }
};

const correctDirection = () => {
  const activeCell = hasActiveCard();
  if (!activeCell) return '';
  const { table } = store.getState().location.list.temple.values;
  for (let i = 0; i < table.length; i += 1) {
    for (let j = 0; j < table[i].length; j += 1) {
      if (
        table[i][j].rewardResource ===
          table[activeCell.i][activeCell.j].rewardResource &&
        table[i][j].rewardAmount ===
          table[activeCell.i][activeCell.j].rewardAmount &&
        (i !== activeCell.i || j !== activeCell.j)
      ) {
        if (i < activeCell.i) return 'up';
        if (i > activeCell.i) return 'down';
        if (j < activeCell.j) return 'left';
        if (j > activeCell.j) return 'right';
      }
    }
  }
  return '';
};

export {
  generateTable,
  setValue,
  setCellValue,
  findRandomEmptyCell,
  findRandomMatchingEmptyCell,
  rewardResourceList,
  flipCard,
  hasActiveCard,
  hasTwoActiveCards,
  isCompleted,
  resetBoard,
  canBuyFlip,
  getFullCost,
};
