import { store } from '../store';
import { addAlert } from '../store/navigationSlice';
import { startAnimation } from '../store/animationSlice';

// eslint-disable-next-line import/prefer-default-export
export const sendAlert = (
  type: string,
  id: string,
  data?: {
    [key: string]: any;
  },
) => {
  // if there is already alert with that name then return
  const { alerts } = store.getState().navigation;
  if (
    alerts.find(
      (alert) =>
        alert.id === id && alert.time && Date.now() - alert.time < 2500,
    )
  )
    return;

  // update navigation of alert to the string
  const { resources } = store.getState();
  const { upgrades } = store.getState();
  const { skills } = store.getState();
  const { unlocks } = store.getState();
  const { achievements } = store.getState();
  let modelType;
  let modelName;
  const alertType = 'default';
  let messageText = '';
  switch (type) {
    case 'unlock':
      if (resources[id]) {
        modelType = 'resource';
        modelName = resources[id].name;
      } else if (upgrades[id]) {
        modelType = 'upgrade';
        modelName = upgrades[id].name;
      } else if (skills[id]) {
        modelType = 'skill';
        modelName = skills[id].name;
      } else if (achievements[id]) {
        modelType = 'achievement';
        modelName = achievements[id].displayName;
      } else {
        modelType = 'feature';

        // if unlock has display name, show it, otherwise change id first letter to uppercase
        modelName =
          unlocks[id]?.displayName || id.charAt(0).toUpperCase() + id.slice(1);
      }
      messageText = `Unlocked new ${modelType}: ${modelName}`;
      break;
    case 'resource':
      messageText = `You have acquired: <span class="num">${data.amount}</span> ${data.resource}`;
      break;
    default:
      messageText = type;
      break;
  }
  const newAlert = {
    message: messageText,
    time: Date.now(),
    id,
  };
  store.dispatch(addAlert(newAlert));
  // start animation
  store.dispatch(
    startAnimation({
      element: `alert-${id}`,
      type: alertType,
      value: 1,
      duration: 2000,
    }),
  );
};
