import { FC, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from '../../store';
import { textDisplay, getIcon } from '../../utils';
import { Model } from '../../types';
import CostHandler from '../../utils/costHandler';

interface TooltipProps {
  content: Model | string;
}

const TooltipContent: FC<TooltipProps> = ({ content }) => {
  const skill = useSelector((state: RootState) =>
    typeof content !== 'string' &&
    Object.prototype.hasOwnProperty.call(content, 'cooldown')
      ? state.skills[content.name]
      : null,
  );
  const [currentCooldown, setCurrentCooldown] = useState(0);
  let description = '';

  if (typeof content === 'string') {
    description = content;
  } else if (content.tooltipDescription) {
    description = content.tooltipDescription;
  } else {
    description = content.description;
  }

  if (typeof content !== 'string') {
    if ('isUnlocked' in content) {
      description = '';
      description += `<div class="name header">${content.displayName}</div>`;
      description += `<div class="name used">If used:</div>${content.description}</div>`;
      if ('unlockDescription' in content && content.unlockDescription) {
        description += `<div class="name mt-2">Unlocked when:</div>${content.unlockDescription}`;
      }
      if (
        'extraDescription' in content &&
        content.extraDescription &&
        content.isUnlocked
      ) {
        description += `:<div>${content.extraDescription}</div>`;
      }
    }
    if ('tier' in content && !content.isCapped) {
      description += '<div class="sep"></div>';
      description += `<div class="property"><span class="property-label">Type:</span> ${content.type}</div>`;
      description += `<div class="property"><span class="property-label">Tier:</span> ${content.tier}</div>`;
    }
  }

  useEffect(() => {
    if (!skill) return;
    const updateCooldown = () => {
      const cooldown = Math.max(
        0,
        parseFloat(
          (
            (skill.lastUsed + skill.currentCooldown * 1000 - Date.now()) /
            1000
          ).toFixed(2),
        ),
      );
      setCurrentCooldown(cooldown);
    };

    // Update cooldown immediately
    updateCooldown();

    // Set interval to update cooldown every second
    const interval = setInterval(updateCooldown, 90);

    // Cleanup interval on component unmount
    return () => clearInterval(interval);
  }, [skill]);

  if (skill) {
    const skillIcon = getIcon(skill.icon);
    const cost = new CostHandler();
    if (skill.costResource) {
      cost.addCost(skill.costResource, skill.currentCost);
    }
    const canBuy = cost.canPayCosts();
    description = `<div class="${canBuy ? '' : ' disabled '}skill-tooltip d-flex justify-content-between mb-2"><div class="skill-name" style="--data-icon: url('${skillIcon}');">${
      skill.displayName
    }</div><div class="${canBuy ? '' : 'disabled'}">${currentCooldown ? `<span class="currentCooldown">${currentCooldown}</span>/` : ''}${skill.currentCooldown}s</div></div>${description
      .replace(
        '{{currentCost}}',
        `&nbsp;<span class="num cost${canBuy ? '' : ' disabled'}">[[${skill.currentCost}]]</span>`,
      )
      .replace('{{currentPower}}', `[[${skill.currentPower}]]`)}`;
    const rewardContent: string[] = [];
    skill.rewards?.forEach((reward) => {
      rewardContent.push(
        typeof reward === 'string'
          ? reward
          : `<span class="num">${reward.currentAmount ? reward.currentAmount : reward.amount}</span> ${reward.resource} `,
      );
    });
    description = description.replace('{{rewards}}', rewardContent.join(', '));
  }

  let sources = '';
  let sourceCount = 0;
  if (typeof content !== 'string' && content.sources) {
    sources += '<table class="sources-table">';
    Object.values(content.sources).forEach((source) => {
      if (!source.amount && source.displayName !== 'Base') return;
      sourceCount += 1;
      sources += `<tr><td>${source.displayName}</td><td class="num">${source.amount}</td></tr>`;
    });
    sources += '</table>';
  }
  if (sourceCount > 1) {
    description += sources;
  }

  return (
    <span
      dangerouslySetInnerHTML={{
        __html: textDisplay(description),
      }}
    />
  );
};
export default TooltipContent;
