import { FC } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from '../../store';
import ModalCloseBtn from './modalCloseBtn';
import AchievementIcon from '../model/achievementIcon';

const AchievementsModal: FC<{}> = () => {
  const achievements = useSelector((state: RootState) => state.achievements);
  return (
    <div className="modal-content">
      <div className="modal-header">
        <h5 className="modal-title">Achievements</h5>
        <ModalCloseBtn />
      </div>
      <div className="modal-body">
        <div className="achievement-list all-achievements card mb-3">
          {Object.entries(achievements).map(([name, achievement]) => {
            if (achievement.isUnlocked) {
              return <AchievementIcon name={name} key={name} />;
            }
            return null;
          })}
          {Object.entries(achievements).map(([name, achievement]) => {
            if (!achievement.isUnlocked) {
              return <AchievementIcon name={name} key={name} />;
            }
            return null;
          })}
        </div>
      </div>
    </div>
  );
};
export default AchievementsModal;
