import React from 'react';
import { connect } from 'react-redux';
import { setHasError } from '../store/gameSlice';
import ErrorModal from '../components/modal/errorModal';

interface ErrorBoundaryProps {
  children: React.ReactNode;
  dispatch: any;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

class ErrorBoundary extends React.Component<
  ErrorBoundaryProps,
  ErrorBoundaryState
> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError() {
    return { hasError: true };
  }

  componentDidMount() {
    window.addEventListener('error', this.handleGlobalError);
    window.addEventListener('unhandledrejection', this.handleGlobalRejection);
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.log(error, info);
    const { dispatch } = this.props;
    dispatch(setHasError(true));
  }

  componentWillUnmount() {
    window.removeEventListener('error', this.handleGlobalError);
    window.removeEventListener(
      'unhandledrejection',
      this.handleGlobalRejection,
    );
  }

  handleGlobalRejection = (event: PromiseRejectionEvent) => {
    console.log(event.reason);
    const { dispatch } = this.props;
    dispatch(setHasError(true));
  };

  handleGlobalError = (event: ErrorEvent) => {
    console.log(event.error);
    const { dispatch } = this.props;
    dispatch(setHasError(true));
  };

  resetError = () => {
    this.setState({ hasError: false });
  };

  render() {
    const { hasError } = this.state;
    if (hasError) {
      return <ErrorModal resetError={this.resetError} />;
    }
    return this.props.children;
  }
}

export default connect()(ErrorBoundary);
