import { FC } from 'react';
import { useSelector } from 'react-redux';
import { Nav, Tab } from 'react-bootstrap';
import type { RootState } from '../../store';
import { hasUnseen } from '../../utils';
import SkillItem from '../model/skillItem';
import type { Skill, Upgrade } from '../../types';
import ModelIcon from '../model/modelIcon';
import UpgradeBox from '../model/upgradeBox';

const Skills: FC<{}> = () => {
  const skills = useSelector((state: RootState) => state.skills) as Record<
    string,
    Skill
  >;
  const skillSlots = useSelector((state: RootState) => state.game.skillSlots);
  const unlocks = useSelector((state: RootState) => state.unlocks);
  const upgrades = useSelector((state: RootState) => state.upgrades);
  return (
    <div className="skills-container container pt-3 has-tabs flex-grow-1 interact-container panel mb-3 w-100">
      <Tab.Container id="left-tabs-example" defaultActiveKey="list">
        <Nav variant="tabs" className="flex-row">
          <Nav.Item>
            <Nav.Link eventKey="list">Skills</Nav.Link>
          </Nav.Item>
          {Object.keys(skillSlots)
            .reverse()
            .map((slot) => (
              <Nav.Item key={slot} className="skill-tab">
                <Nav.Link
                  eventKey={slot}
                  className={
                    skillSlots[slot] && hasUnseen(skillSlots[slot]) ? 'new' : ''
                  }
                >
                  {skillSlots[slot] ? (
                    <>
                      <ModelIcon model={skills[skillSlots[slot]]} />
                      <span className="short">
                        {skills[skillSlots[slot]].abbreviation ??
                          skills[skillSlots[slot]].displayName}
                      </span>
                      <span className="long">
                        {skills[skillSlots[slot]].displayName}
                      </span>
                    </>
                  ) : (
                    '...'
                  )}
                </Nav.Link>
              </Nav.Item>
            ))}
        </Nav>
        <Tab.Content>
          <Tab.Pane eventKey="list">
            <div className="row">
              <div className="scroll-container container">
                <div className="row panel-list">
                  {Object.values(skills)
                    .filter((skill: Skill) => unlocks[skill.name].isUnlocked)
                    // sort so that assigned skills are last
                    .sort((a: Skill, b: Skill) =>
                      Object.values(skillSlots).includes(a.name) ? 1 : -1,
                    )
                    .map((skill: Skill) => (
                      <SkillItem key={skill.name} skillName={skill.name} />
                    ))}
                </div>
              </div>
            </div>
          </Tab.Pane>

          {Object.keys(skillSlots).map((slot) => (
            <Tab.Pane eventKey={slot} key={slot}>
              <div className="scroll-container container">
                {skillSlots[slot] ? (
                  <>
                    <SkillItem skillName={skillSlots[slot] || ''} />
                    <h4 className="skill-upgrades-title">Upgrades:</h4>
                    <div className="row panel-list">
                      {skills[skillSlots[slot]].upgrades?.map(
                        (upgradeName: string) => {
                          const upgrade = upgrades[upgradeName] as Upgrade;
                          if (unlocks[upgrade.name].isUnlocked) {
                            return (
                              <UpgradeBox
                                key={upgrade.name}
                                upgradeName={upgrade.name}
                              />
                            );
                          }
                        },
                      )}
                    </div>
                    {!skills[skillSlots[slot]].upgrades?.some(
                      (upgradeName: string) => {
                        const upgrade = upgrades[upgradeName] as Upgrade;
                        return unlocks[upgrade.name].isUnlocked;
                      },
                    ) && <div className="none-found">None available</div>}
                  </>
                ) : (
                  <div className="skill-box col-12 col-sm-6 col-md-12 col-lg-6">
                    <div className="card">
                      <div className="card-body">Empty skill Slot</div>
                    </div>
                  </div>
                )}
              </div>
            </Tab.Pane>
          ))}
        </Tab.Content>
      </Tab.Container>
    </div>
  );
};
export default Skills;
