import React, { useEffect, useMemo } from 'react';
import { useSelector, shallowEqual } from 'react-redux';
import { createSelector } from 'reselect';
import { Card } from 'react-bootstrap';
import { RootState, store } from '../../store';
import { Quest } from '../../types';
import { getIcon, numberDisplay, textDisplay } from '../../utils';
import ButtonCost from '../util/buttonCost';
import { updateQuest } from '../../store/questSlice';
import { playSfx } from '../../utils/sound';
import CostHandler from '../../utils/costHandler';
import { canSubmit, submitQuest } from '../../utils/location/questsUtil';

interface QuestBoxProps {
  quest: Quest;
  index: number;
}

const QuestBox: React.FC<QuestBoxProps> = ({ quest, index }) => {
  const animations = useSelector((state: RootState) => state.animations);
  const locations = useSelector((state: RootState) => state.location.list);

  const rewardDisplay = (reward: any) => {
    if (!reward.resource && reward.attribute) {
      return (
        <span>
          <span className="num">+{numberDisplay(reward.amount)}</span>{' '}
          <span
            dangerouslySetInnerHTML={{
              __html: textDisplay(reward.attribute),
            }}
          />
        </span>
      );
    }
    if (reward.resource === 'relationship') {
      return (
        <span>
          <span className="num">+{numberDisplay(reward.amount)}</span>{' '}
          {locations[reward.attribute]?.abbreviation
            ? locations[reward.attribute]?.abbreviation
            : locations[reward.attribute]?.displayName}{' '}
          relationship
        </span>
      );
    }

    if (reward.resource === 'skillSlot') {
      return <span>Extra skill slot</span>;
    }
    let addText = '';
    if (reward.property && reward.property === 'cap') {
      addText = 'max ';
    }
    return (
      <span>
        <span className="num">+{numberDisplay(reward.amount)}</span>{' '}
        <span
          dangerouslySetInnerHTML={{
            __html: textDisplay(addText + reward.resource),
          }}
        />
      </span>
    );
  };
  // Create a memoized selector for the quest's resources
  const selectRelevantResources = useMemo(() => {
    return createSelector(
      [(state: RootState) => state.resources],
      (resources) => {
        if (!quest.costs) return {};

        const result = {};
        Object.keys(quest.costs).forEach((resourceName) => {
          result[resourceName] = resources[resourceName]?.amount || 0;
        });
        return result;
      },
    );
  }, [quest.costs]); // Only recreate selector when quest.costs changes

  // Use the memoized selector with shallowEqual for comparison
  const relevantResources = useSelector(selectRelevantResources, shallowEqual);

  const [costHandler, setCostHandler] = React.useState<CostHandler>(null);
  const [justCompleted, setJustCompleted] = React.useState(false);
  const prevCompletedRef = React.useRef(quest.isCompleted);

  const canSubmitQuest = React.useMemo(() => {
    if (!costHandler || !quest.costs) return false;
    return canSubmit(quest, costHandler);
  }, [quest, costHandler, relevantResources]);

  useEffect(() => {
    if (quest.costs) {
      const handler = new CostHandler();
      Object.keys(quest.costs).forEach((resource) => {
        const cost = quest.costs[resource];
        handler.addCostObject(resource, cost);
      });
      setCostHandler(handler);
    }
  }, [quest.costs]);

  useEffect(() => {
    // Only set justCompleted if it wasn't completed before but is now
    if (quest.isCompleted && !prevCompletedRef.current) {
      setJustCompleted(true);
      setTimeout(() => {
        setJustCompleted(false);
      }, 2000);
    }

    // Update ref value with current completion state
    prevCompletedRef.current = quest.isCompleted;
  }, [quest.isCompleted]);
  return (
    <div
      className={`quest-box col-12
        ${quest.isLocked ? ' locked' : ''}
        ${quest.isCompleted ? ' completed' : ''}
        ${justCompleted ? ' just-completed' : ''}
        ${animations[`quest-${index}`] && animations[`quest-${index}`].active ? ' is-new' : ''}
        ${animations[`quest-${index}-vibrate`] && animations[`quest-${index}-vibrate`].active ? ' vibrate' : ''}
        ${animations[`quest-${index}-hidden`] && animations[`quest-${index}-hidden`].active ? ' invisible' : ''}
      `}
    >
      <span className="completed-overlay">Completed</span>
      <Card style={{ '--var-color': quest.color } as React.CSSProperties}>
        <Card.Body>
          <div className="row">
            <div className="col-lg-6">
              {' '}
              <div className="card-title d-flex align-items-center justify-content-between">
                <span className="d-flex">
                  <span className="icon-container">
                    <span
                      className="model-icon"
                      style={{ WebkitMaskImage: `url(${getIcon(quest.icon)})` }}
                    />
                  </span>
                  <span>{quest.displayName}</span>
                </span>
              </div>
              <div
                className="descr flavor-text"
                dangerouslySetInnerHTML={{
                  // replace power with currentPower
                  __html: textDisplay(quest.description),
                }}
              />
            </div>
            <div className="col-lg-6 quest-action">
              <button
                className="btn btn-icon btn-lock"
                type="button"
                onMouseEnter={() => {
                  playSfx('hover');
                }}
                onClick={() => {
                  store.dispatch(
                    updateQuest({
                      index,
                      property: 'isLocked',
                      value: !quest.isLocked,
                    }),
                  );
                  playSfx('click');
                }}
              >
                Lock
              </button>
              <div className="quest-rewards">
                {quest.rewards.map((reward, i) => (
                  <div key={i} className="reward">
                    {rewardDisplay(reward)}
                  </div>
                ))}
              </div>
              <button
                className="btn btn-primary btn-submit btn-small"
                type="button"
                onMouseEnter={() => {
                  playSfx('buttonHover');
                }}
                disabled={!canSubmitQuest}
                onClick={() => {
                  submitQuest(index, costHandler);
                  playSfx('success');
                }}
              >
                {quest.costs && <ButtonCost type="Complete" model={quest} />}
              </button>
            </div>
          </div>
        </Card.Body>
      </Card>
    </div>
  );
};

export default QuestBox;
