import { FC, useEffect, useRef } from 'react';
import { useSelector } from 'react-redux';
import { Howl } from 'howler';
import { RootState, store } from '../store';
import bgFile from '../assets/audio/LateNightRadio.mp3';
import sfxHover from '../assets/audio/hover.mp3';
import sfxClick from '../assets/audio/click.wav';
import sfxBuy from '../assets/audio/buy.wav';
import sfxStart from '../assets/audio/start.wav';
import sfxMotion from '../assets/audio/motion.wav';
import sfxLocation from '../assets/audio/location.wav';
import sfxEquip from '../assets/audio/equip.wav';
import sfxButtonHover from '../assets/audio/buttonHover.wav';
import sfxButtonClick from '../assets/audio/buttonClick.wav';
import sfxPress from '../assets/audio/press.wav';
import upgrade1 from '../assets/audio/upgrade1.wav';
import upgrade2 from '../assets/audio/upgrade2.wav';
import upgrade3 from '../assets/audio/upgrade3.wav';
import fightHit from '../assets/audio/fightHit.wav';
import fightHit2 from '../assets/audio/fightHit2.wav';
import kill from '../assets/audio/kill.wav';
import death from '../assets/audio/death.wav';
import flip from '../assets/audio/flip.wav';
import correct from '../assets/audio/correct.wav';
import wrong from '../assets/audio/wrong.wav';
import craft from '../assets/audio/craft.mp3';
import success from '../assets/audio/success.wav';
import skill from '../assets/audio/skill.wav';
import move from '../assets/audio/move.wav';
import drop from '../assets/audio/drop.wav';
import rotate from '../assets/audio/rotate.wav';
import brickPop from '../assets/audio/brickPop.wav';
import brickDrop from '../assets/audio/brickDrop.wav';

let lastPlayedHover = 0;
let upgradeCount = 0;
let upgradeTime = Date.now();

const Sound: FC<{}> = () => {
  const musicVolume = useSelector(
    (state: RootState) => state.settings.musicVolume,
  );
  const music = useRef<Howl | null>(null);

  if (!music.current) {
    music.current = new Howl({
      src: [bgFile],
      loop: true,
      volume: musicVolume / 100,
    });
  }

  useEffect(() => {
    music.current?.play();
    return () => {
      music.current?.stop();
    };
  }, []);

  useEffect(() => {
    music.current?.volume(musicVolume / 100);
  }, [musicVolume]);

  return null;
};
export default Sound;

export const playSfx = (src: string) => {
  let volume = store.getState().settings.sfxVolume;
  let file;
  switch (src) {
    case 'hover':
      file = sfxHover;
      if (Date.now() - lastPlayedHover < 200) {
        return;
      }
      lastPlayedHover = Date.now();
      volume *= 0.4;
      break;
    case 'click':
      file = sfxClick;
      break;
    case 'press':
      file = sfxPress;
      break;
    case 'buy':
      file = sfxBuy;
      break;
    case 'start':
      file = sfxStart;
      break;
    case 'success':
      file = success;
      break;
    case 'motion':
      file = sfxMotion;
      break;
    case 'location':
      file = sfxLocation;
      break;
    case 'equip':
      file = sfxEquip;
      break;
    case 'buttonHover':
      file = sfxButtonHover;
      break;
    case 'buttonClick':
      file = sfxButtonClick;
      break;
    case 'fightHit':
      file = fightHit;
      break;
    case 'fightHit2':
      file = fightHit2;
      break;
    case 'kill':
      file = kill;
      break;
    case 'death':
      file = death;
      break;
    case 'flip':
      file = flip;
      break;
    case 'correct':
      file = correct;
      break;
    case 'wrong':
      file = wrong;
      break;
    case 'craft':
      file = craft;
      break;
    case 'skill':
      file = skill;
      break;
    case 'move':
      file = move;
      break;
    case 'drop':
      file = drop;
      break;
    case 'rotate':
      file = rotate;
      break;
    case 'brickPop':
      file = brickPop;
      break;
    case 'brickDrop':
      file = brickDrop;
      break;

    case 'upgrade':
      if (Date.now() - upgradeTime < 1000) {
        upgradeCount += 1;
      } else {
        upgradeCount = 1;
      }
      upgradeTime = Date.now();

      file = upgrade1;
      if (upgradeCount === 2) {
        file = upgrade2;
      } else if (upgradeCount > 2) {
        file = upgrade3;
      }
      break;

    default:
      return;
  }
  const sound = new Howl({
    src: [file],
    volume: volume ? volume / 100 : 0,
  });
  sound.play();
};

export const btnHover = () => {
  playSfx('hover');
};

export const btnClick = () => {
  playSfx('click');
};
