import { FC, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { Form } from 'react-bootstrap';
import { store, RootState } from '../../../store';
import { setSeen } from '../../../store/unlockSlice';
import { numberDisplay, textDisplay } from '../../../utils';
import { playSfx } from '../../../utils/sound';
import ResourceSelector from './resourceSelector';
import { getBalanceModded } from '../../../utils/modUtil';
import { confirmTrade } from '../../../utils/location/tradeUtil';
import balance from '../../../conf/balanceConf';

const Trade: FC<{ isActive: boolean }> = ({ isActive }) => {
  const unlocks = useSelector((state: RootState) => state.unlocks);
  const location = useSelector(
    (state: RootState) => state.location.list.market,
  );
  const feature = useSelector(
    (state: RootState) => state.location.list.market.features?.trade,
  );
  const resources = useSelector((state: RootState) => state.resources);
  const [singleSelectedResource, setSingleSelectedResource] = useState<
    string | null
  >(null);
  const [singleTradeType, setSingleTradeType] = useState<'buy' | 'sell'>(
    'sell',
  );
  const [singleTradeAmount, setSingleTradeAmount] = useState(0);

  const tradeMax = Number(location.values?.tradeMax) || 0;
  let tradeRate = singleSelectedResource
    ? resources[singleSelectedResource][
        singleTradeType === 'buy' ? 'buyPrice' : 'sellPrice'
      ] || 0
    : 0;
  if (singleTradeType === 'sell') {
    tradeRate = 1 / tradeRate;
  }
  const priceMultiplier = Number(location.values?.priceMultiplier) || 1;
  let coinsAmount = Math.round(
    singleTradeType === 'buy'
      ? (((singleTradeAmount * tradeMax) / 100) * tradeRate) /
          priceMultiplier || 0
      : (singleTradeAmount * tradeMax) / 100 || 0,
  );
  let resourceAmount = Math.round(
    singleTradeType === 'buy'
      ? (singleTradeAmount * tradeMax) / 100
      : (((singleTradeAmount * tradeMax) / 100) * tradeRate) /
          priceMultiplier || 0,
  );

  // if selling and coins amount > 0, then resource amount is at least 1
  if (singleTradeType === 'sell' && coinsAmount > 0 && resourceAmount === 0) {
    resourceAmount = 1;
  }

  useEffect(() => {
    // if on this tab, mark as seen

    if (!unlocks.trade.isSeen && isActive) {
      store.dispatch(setSeen('trade'));
    }

    if (!singleSelectedResource) {
      const firstResource = Object.entries(resources).find(
        ([key, value]) => unlocks[key].isUnlocked && value.type === 'material',
      );
      if (firstResource) {
        setSingleSelectedResource(firstResource[0]);
      }
    }
  });
  const handleSingleTradeAmountChange = (e: any) => {
    setSingleTradeAmount(e.target.value);
  };

  return (
    <div className="trade">
      {feature?.actions.map((action, i) => {
        const { isUnlocked } = unlocks[action.name];
        return isUnlocked ? (
          <div key={i} className="action card">
            <div className="card-body">
              <h2 className="title mb-2 d-lg-none">{action.displayName}</h2>
              <div className="row">
                <div className="col-lg-6 order-lg-last">
                  <div className="selector-list trade-type">
                    <div className="selector">
                      <input
                        name="singleTradeType"
                        type="radio"
                        id="singleTradeTypeBuy"
                        value="buy"
                        checked={singleTradeType === 'buy'}
                        onChange={() => {
                          setSingleTradeType('buy');
                          playSfx('click');
                        }}
                      />
                      <label
                        htmlFor="singleTradeTypeBuy"
                        className="selector-text"
                        onMouseEnter={() => playSfx('hover')}
                      >
                        Buy
                      </label>
                    </div>
                    <div className="selector">
                      <input
                        name="singleTradeType"
                        type="radio"
                        id="singleTradeTypeSell"
                        value="sell"
                        checked={singleTradeType === 'sell'}
                        onChange={() => {
                          setSingleTradeType('sell');
                          playSfx('click');
                        }}
                      />
                      <label
                        htmlFor="singleTradeTypeSell"
                        className="selector-text"
                        onMouseEnter={() => playSfx('hover')}
                      >
                        Sell
                      </label>
                    </div>
                  </div>
                  <ResourceSelector
                    singleSelectedResource={singleSelectedResource}
                    setSingleSelectedResource={setSingleSelectedResource}
                    resourceType="material"
                  />
                </div>
                <div className="col-lg-6 order-lg-first pb-2">
                  <h2 className="title mb-2 d-none d-lg-block">
                    {action.displayName}
                  </h2>
                  <div className="mt-2">
                    Maximum output:{' '}
                    <span className="num">{numberDisplay(tradeMax)}</span>
                  </div>
                  <div className={`${singleSelectedResource ? '' : ' d-none'}`}>
                    <div className="transaction sep-top mt-2 pb-2">
                      {singleTradeType === 'buy' ? 'Buying' : 'Selling'}:<br />
                      <span className="nobr">
                        <span className="num">
                          {numberDisplay(resourceAmount)}
                        </span>{' '}
                        <span
                          className="resource"
                          dangerouslySetInnerHTML={{
                            __html: textDisplay(singleSelectedResource),
                          }}
                        />
                      </span>{' '}
                      for{' '}
                      <span className="nobr">
                        <span className="num">
                          {numberDisplay(coinsAmount)}
                        </span>{' '}
                        <span
                          className="resource"
                          dangerouslySetInnerHTML={{
                            __html: textDisplay('coins'), // coins is a resource
                          }}
                        />
                      </span>
                    </div>
                    <div className="amount-range sep-top pt-2">
                      <div className="d-flex justify-content-between amount-label">
                        <div className="num">{numberDisplay(0)}</div>
                        <div className="num">{numberDisplay(tradeMax)}</div>
                      </div>
                      <Form.Range
                        value={singleTradeAmount}
                        onChange={handleSingleTradeAmountChange}
                      />
                    </div>
                  </div>
                </div>
              </div>
              <div
                className={`none-found ${singleSelectedResource ? 'd-none' : ''}`}
              >
                No tradeable resources
              </div>
              <button
                type="button"
                className={`btn btn-primary btn-small
                  ${singleSelectedResource ? '' : ' d-none'}`}
                onClick={() => {
                  playSfx('success');
                  confirmTrade(
                    singleTradeType,
                    singleSelectedResource || '',
                    resourceAmount,
                    coinsAmount,
                  );
                }}
                onMouseEnter={() => playSfx('hover')}
                disabled={
                  singleTradeAmount <= 0 ||
                  (singleTradeType === 'buy' &&
                    coinsAmount > resources.coins.amount) ||
                  (singleTradeType === 'sell' &&
                    resourceAmount >
                      resources[singleSelectedResource].amount) ||
                  balance.trade.socialEnergyCost > resources.socialEnergy.amount
                }
              >
                Confirm Trade (
                <span className="num">
                  -{getBalanceModded('trade.socialEnergyCost')}
                </span>
                <span
                  className="resource"
                  dangerouslySetInnerHTML={{
                    __html: textDisplay('socialEnergy'),
                  }}
                />
                )
              </button>
            </div>
          </div>
        ) : null;
      })}
    </div>
  );
};

export default Trade;
