import React, { FC, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { RootState, store } from '../../../store';
import { setSeen } from '../../../store/unlockSlice';
import QuestBox from '../../model/questBox';
import UpgradeBox from '../../model/upgradeBox';

const Quests: FC<{ isActive: boolean }> = ({ isActive }) => {
  const values = useSelector(
    (state: RootState) => state.location.list.townHall.values,
  );
  const unlocks = useSelector((state: RootState) => state.unlocks);
  const questList = useSelector((state: RootState) => state.quests);
  const [isCollapsed, setIsCollapsed] = useState(true);
  const handleToggle = () => {
    setIsCollapsed(!isCollapsed);
  };
  const actions = useSelector(
    (state: RootState) =>
      state.location.list.townHall.features?.quests?.actions,
  );
  useEffect(() => {
    // if on this tab, mark as seen
    if (!unlocks.quests.isSeen && isActive) {
      store.dispatch(setSeen('quests'));
    }
  });

  return (
    <div className="quests">
      <div className="quests-header pt-2 row panel-list justify-content-between">
        {actions
          .filter((action) => unlocks[action.name].isUnlocked)
          .map((action) => (
            <UpgradeBox key={action.name} upgradeName={action.name} />
          ))}
        <div className="col-12 col-sm-6 col-md-12 col-lg-6">
          <div
            className={`info-text${isCollapsed ? ' collapsed' : ''}`}
            onClick={handleToggle}
          >
            <div className="title">
              Quests completed: {values.questsCompleted}
            </div>
            <p>
              Quests requirements and rewards increase as you complete more
              quests.
            </p>
            <p>
              Some quests only become available as you have completed a certain
              number of them.
            </p>
          </div>
        </div>
      </div>
      <div className="quests-body">
        <div className="d-flex justify-content-between align-items-end">
          <div className="list-title">Current quests:</div>
          <div className={`lock-info${questList.length < 1 ? ' d-none' : ''}`}>
            Locked quests will not be rerolled
          </div>
        </div>
        <div className="row panel-list">
          {questList.map(
            (quest: Quest, i: number) =>
              quest && (
                <QuestBox key={quest.name + i} quest={quest} index={i} />
              ),
          )}
          {questList.length < 1 && (
            <span className="none-found">
              None yet. Use the button above to get started.
            </span>
          )}
        </div>
      </div>
    </div>
  );
};

export default Quests;
