import { createSlice } from '@reduxjs/toolkit';
import type { PayloadAction } from '@reduxjs/toolkit';
import { Skill, SkillList } from '../types';
import skills from '../conf/skillConf';
import { updateSliceVersion } from './common';

const initialState: SkillList = skills;

export const skillSlice = createSlice({
  name: 'skills',
  initialState,
  reducers: {
    // reducer to change the value of a skill.
    // it has arguments: skill name, property name, and value
    updateSkill: (
      state,
      action: PayloadAction<{
        skill: string;
        property: keyof Skill;
        value: any;
      }>,
    ) => {
      const { skill, property, value } = action.payload;
      (state[skill][property] as any) = value;
    },
    resetSkills: () => {
      return initialState;
    },
    updateVersion: (state) => {
      return updateSliceVersion(state, initialState);
    },
  },
});

// Action creators are generated for each case reducer function
export const { updateSkill, resetSkills, updateVersion } = skillSlice.actions;

export default skillSlice.reducer;
