export type ModelType = 'Resource' | 'Upgrade' | 'Attribute' | 'Skill';
export type ObjectType = ModelType | 'Location' | 'Balance' | 'Npc';

export interface ModData {
  [key: string]: string | number | boolean;
}

export type Modifier = (x: number, data?: ModData) => number;

export interface ModList {
  [key: string]: Modifier;
}

export interface AddModifier {
  modObjectType: ObjectType;
  modObjectName: string;
  modProperty: string;
  modName: string;
  priority: number;
  description?: string;
  type?: string;
  data?: ModData;
}

export interface ModConf {
  modName: string;
  priority: number;
  modProperty: string;
  data?: ModData;
}

export interface Model {
  name: string;
  displayName: string;
  abbreviation?: string;
  color: string;
  icon: string;
  description: string;
  tooltipDescription?: string;
  order?: number;
  mods?: ModConf[];
}

export interface ModelList {
  [key: string]: Model;
}

export interface Resource extends Model {
  amount: number;
  gps: number; // growth per second
  gpsTemp?: number; // temporary growth per second (from conversions)
  isCapped?: boolean;
  cap?: number;
  currentCap?: number;
  gainMultiplier?: number;
  sellPrice?: number;
  buyPrice?: number;
  rewardAmount?: number;
  rewardExponent?: number;
  tier: number;
  type?: string;
  limited?: boolean;
}

export interface ResourceList {
  [key: string]: Resource;
}

export interface Cost {
  cost: number;
  currentCost: number;
}

export interface CostList {
  [key: string]: Cost;
}

export interface Reward {
  attribute?: string;
  resource?: string;
  amount?: number;
  currentAmount?: number;
  maxAmount?: number;
  currentMaxAmount?: number;
}

export interface Requirement {
  objectType: ObjectType;
  objectName: string;
  property: string;
  amount: number;
}

export interface Upgrade extends Model {
  currentColor?: string;
  currentDescription?: string;
  group?: string;
  amount: number;
  limit?: number;
  requirements?: Requirement[];
  cost: CostList;
  addMods?: AddModifier[];
  clickMods?: string[];
  power: number;
  currentPower: number;
  additionalPower?: { [key: string]: number };
  currentAdditionalPower?: { [key: string]: number };
  rewards?: Reward[];
}

export interface UpgradeList {
  [key: string]: Upgrade;
}

export interface AttributeSource {
  displayName: string;
  amount: number;
}

export type SourcesList = {
  [key: string]: AttributeSource;
};

export interface Attribute extends Model {
  amount: number;
  currentAmount: number;
  addAmount?: number;
  sources: SourcesList;
}

export interface AttributeList {
  [key: string]: Attribute;
}

export type RewardsArray = (string | Reward)[];

export interface Skill extends Model {
  cooldown: number;
  currentCooldown: number;
  lastUsed: number;
  cost?: number;
  currentCost?: number;
  costResource?: string;
  power?: number;
  currentPower?: number;
  rewards?: RewardsArray;
  upgrades?: string[];
  clickMods?: string[];
  type?: string;
}

export interface SkillList {
  [key: string]: Skill;
}

export interface Npc {
  name: string;
  displayName: string;
  relationship: number;
  profession: string;
  dialogue?: string;
  isNewDialogue?: boolean;
  flirtDays?: number[];
  mods: ModConf[];
}

export interface Action {
  name: string;
  displayName?: string;
  addMods?: AddModifier[];
  clickMods?: string[];
}

export interface Feature {
  name: string;
  displayName: string;
  abbreviation?: string;
  actions: Action[];
}

export interface Location {
  displayName: string;
  abbreviation?: string;
  activities: string[];
  upgrades: string[];
  features?: {
    [key: string]: Feature;
  };
  npc?: Npc;
  values?: {
    [key: string]: any;
  };
}

export interface LocationList {
  [key: string]: Location;
}

export interface Animation {
  type: string;
  value: number;
  duration: number;
  timeoutId: number;
}

export interface AnimationsList {
  [key: string]: Animation;
}

export type TextSwitch = () => string;

export interface Unlock {
  isUnlocked?: boolean;
  isSeen?: boolean;
  children?: string[];
  unlocks?: string[];
  displayName?: string;
  // condition is a function
  condition?: () => boolean;
}

export type UnlockList = {
  [key: string]: Unlock;
};

export interface Achievement extends Model {
  isUnlocked: boolean;
  isCurrentlyUnlocked: boolean;
  isLastUsed: boolean;
  unlockDescription: string;
  extraDescription?: string;
  addMods: AddModifier[];
}

export interface AchievementList {
  [key: string]: Achievement;
}

export type ItemSlot =
  | 'armor'
  | 'weapon'
  | 'jewelry'
  | 'stressToy'
  | 'tome'
  | 'talisman';

export enum ModPool {
  potato = 'potato',
  weapon = 'weapon',
  armor = 'armor',
  talisman = 'talisman',
  stressToy = 'stressToy',
  tome = 'tome',
  jewelry = 'jewelry',
}

export interface Item extends Model {
  uuid?: string;
  slot: ItemSlot;
  limit?: number;
  attribute: string;
  minAttribute: number;
  maxAttribute: number;
  attributeAmount?: number;
  isSeen?: boolean;
  // array of strings
  modPool: ModPool[];
}

// is an object with keys of 1 to 5 with values of Item
export interface ItemList {
  [key: number]: Item;
}

export interface MineTile {
  type: string;
  open: boolean;
  visible?: boolean;
  clickable?: boolean;
}

// grid is an array of arrays of MineTile
export type MineGrid = MineTile[][];

export interface LootChance {
  item: string;
  chance: number;
  amount?: number;
}

export interface Monster {
  name: string;
  displayName: string;
  sprite: string;
  attack: number;
  health: number;
  loot: LootChance[];
}

export interface RealizeTableCell {
  rewardResource: string;
  rewardAmount: number;
  open: boolean;
  active: boolean;
}

export interface Quest extends Model {
  isLocked: boolean;
  costs: CostList;
  rewards: RewardsArray;
  tier: number;
  maxTier?: number;
  isMainQuest?: boolean;
  isCompleted?: boolean;
  requirement: string;
}

export type QuestList = Quest[];
