import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { QuestList } from '../types';
import { updateSliceVersion } from './common';

const initialState: QuestList = [];

export const questSlice = createSlice({
  name: 'quests',
  initialState,
  reducers: {
    updateQuest: (
      state,
      action: PayloadAction<{ index: number; property: string; value: any }>,
    ) => {
      const { index, property, value } = action.payload;
      (state[index] as any)[property] = value;
    },
    setQuests: (state, action: PayloadAction<QuestList>) => {
      return action.payload;
    },
    resetQuests: () => {
      return initialState;
    },
    updateVersion: (state) => {
      return updateSliceVersion(state, initialState);
    },
  },
});

// Action creators are generated for each case reducer function
export const { updateQuest, setQuests, resetQuests, updateVersion } =
  questSlice.actions;

export default questSlice.reducer;
