import { FC } from 'react';
import { Tooltip } from 'react-tooltip';
import CostHandler from '../../utils/costHandler';
import { textDisplay } from '../../utils';

const CostTooltip: FC<{ costHandler: CostHandler; isTooltipOpen: boolean }> = ({
  costHandler,
  isTooltipOpen,
}) => {
  return (
    <Tooltip
      id="tooltip-cost"
      place="top"
      className="wrap"
      isOpen={isTooltipOpen}
    >
      <div className="tile-cost">
        {costHandler &&
          Object.entries(costHandler.getCostList()).map(
            ([resource, cost], index) => {
              let isTicket = '';
              if (resource.startsWith('ticket_')) {
                [, isTicket] = resource.split('_');
              }

              return (
                <div key={resource} className="d-inline-flex">
                  <div
                    key={resource}
                    className={`num ${!index ? '' : 'second'}
                    ${!CostHandler.canPayCost(resource, cost) ? ' red' : ''}`}
                  >
                    -{cost.currentCost}
                  </div>
                  {isTicket ? (
                    <div className={`ticket ${isTicket}`}>
                      <div className={`${isTicket}-icon`} />
                    </div>
                  ) : (
                    <div
                      dangerouslySetInnerHTML={{
                        __html: textDisplay(resource),
                      }}
                    />
                  )}
                </div>
              );
            },
          )}
      </div>
    </Tooltip>
  );
};
export default CostTooltip;
