// import all sprites from the assets folder (djinn-bandit, golem, mandrake, rat, red-ogre, shade, wasp, werewolf, yeti)
import React from 'react';
import { useSelector } from 'react-redux';
import type { RootState } from '../../../store';
import monsters from '../../../conf/monsterConf';

const Monster: React.FC = () => {
  const values = useSelector(
    (state: RootState) => state.location.list.forest.values,
  );

  const monsterType = values?.monsterType;
  const monsterState = values?.monsterState;

  const monster = monsters[monsterType];
  if (!monster) {
    return null;
  }

  return (
    <div className="monster">
      <div
        className={`monster-sprite ${monster.name} state-${monsterState}`}
        style={
          {
            backgroundImage: `url('${monster.sprite}')`,
          } as React.CSSProperties
        }
      />
    </div>
  );
};

export default Monster;
