import { FC } from 'react';
import { confirmModal } from '../../store/navigationSlice';
import { assignSkillSlot } from '../../store/gameSlice';
import { store } from '../../store';
import { playSfx } from '../../utils/sound';

const SkillAddConfirmModal: FC<{}> = () => {
  const modalSetup = store.getState().navigation.confirm;
  return (
    <div className="modal-content">
      <div className="modal-header">
        <h5 className="modal-title">Assign skill?</h5>
      </div>
      <div className="modal-body">
        <p>
          You have a limited amount of skill slots that cannot be reassigned.
        </p>
      </div>
      <div className="modal-footer d-flex justify-content-between">
        <button
          type="button"
          className="btn btn-secondary"
          onMouseEnter={() => {
            playSfx('hover');
          }}
          onClick={() => {
            playSfx('click');
            store.dispatch(
              confirmModal({
                value: {
                  show: false,
                  type: '',
                },
              }),
            );
          }}
        >
          Cancel
        </button>
        <button
          type="button"
          className="btn btn-primary"
          onMouseEnter={() => {
            playSfx('hover');
          }}
          onClick={() => {
            playSfx('click');
            store.dispatch(
              assignSkillSlot({
                skill: modalSetup.model,
              }),
            );
            store.dispatch(
              confirmModal({
                value: {
                  show: false,
                  type: '',
                },
              }),
            );
          }}
        >
          Proceed
        </button>
      </div>
    </div>
  );
};
export default SkillAddConfirmModal;
