import { FC, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { Tooltip } from 'react-tooltip';
import { getIcon } from '../../utils';
import type { RootState } from '../../store';
import { store } from '../../store';
import { setNavigationValue } from '../../store/navigationSlice';
import TooltipContent from '../util/tooltipContent';
import { useSkill } from '../../utils/skillUtil';
import btnFrame from '../../assets/img/btn-frame.svg';
import { playSfx } from '../../utils/sound';
import CostHandler from '../../utils/costHandler';
import AcquiredResource from '../util/acquiredResource';

interface SkillProps {
  skillName: string;
}

const SkillBox: FC<SkillProps> = ({ skillName }) => {
  const skill = useSelector((state: RootState) =>
    skillName !== 'empty' ? state.skills[skillName] : null,
  );
  const [cooldownHeight, setCooldownHeight] = useState(0);
  const [isTooltipOpen, setIsTooltipOpen] = useState(false);

  const [acquiredResources, setAcquiredResources] = useState<
    Record<string, any>
  >({});

  const [canBuy, setCanBuy] = useState(false);
  useEffect(() => {
    const interval = setInterval(() => {
      if (skill) {
        const cost = new CostHandler();
        if (skill.costResource) {
          cost.addCost(skill.costResource, skill.currentCost);
        }
        setCanBuy(cost.canPayCosts());
        let cooldownPercentage;
        if (!skill.lastUsed) {
          cooldownPercentage = 0;
        } else {
          // compares current time with skill.lastUsed
          cooldownPercentage = Math.round(
            Math.min(
              100,
              ((skill.lastUsed + skill.currentCooldown * 1000 - Date.now()) /
                (skill.currentCooldown * 1000)) *
                100,
            ),
          );
        }
        setCooldownHeight(cooldownPercentage);
      }
    }, 100);

    return () => clearInterval(interval);
  }, [skill]);

  const clickEmpty = () => {
    playSfx('click');
    store.dispatch(
      setNavigationValue({
        navigation: 'mainPanel',
        property: 'current',
        value: 'skills',
      }),
    );
  };

  return (
    <>
      <button
        type="button"
        className={`btn btn-icon btn-skill has-tooltip ${!skill || canBuy ? '' : ' disabled'} ${skill ? skill.name : 'empty'}${cooldownHeight > 0 ? ' on-cooldown' : ''}`}
        // if empty navigate to skills, else use skill
        onClick={() => {
          if (skill) {
            setIsTooltipOpen(false);
            const used = useSkill(skill.name || '', setAcquiredResources);
            if (used) playSfx('skill');
          } else {
            clickEmpty();
          }
        }}
        onMouseOver={() => {
          playSfx('hover');
        }}
        data-tooltip-id={`tooltip-skillbox-${skillName}`}
        onMouseEnter={() => setIsTooltipOpen(true)}
        onMouseLeave={() => setIsTooltipOpen(false)}
      >
        {skill && (
          <img src={getIcon(skill.icon)} alt="" className="skill-icon" />
        )}

        <img src={btnFrame} className="btn-frame" alt="" />
        <div
          className={`skill-cooldown no-hover ${cooldownHeight > 0 ? '' : 'd-none'}`}
          style={{ height: `${cooldownHeight}%` }}
        />
        <AcquiredResource
          acquiredResources={acquiredResources}
          isOpen
          animationKey={`skill-acquired-${skillName}`}
        />
      </button>

      <Tooltip
        id={`tooltip-skillbox-${skillName}`}
        isOpen={isTooltipOpen}
        positionStrategy="fixed"
      >
        <TooltipContent
          content={skill || 'Empty skill slot.<br>Click to assign a skill.'}
        />
      </Tooltip>
    </>
  );
};

export default SkillBox;
