import { FC, useState } from 'react';
import { useSelector } from 'react-redux';
import { store } from '../../store';
import { updateModal } from '../../store/navigationSlice';
import DynamicText from '../util/dynamicText';
import days from '../../conf/dayConf';
import choices from '../../conf/choicesConf';
import dayActions from '../../conf/dayActions';
import type { RootState } from '../../store';
import { playSfx } from '../../utils/sound';
import { getIcon, numberDisplay } from '../../utils';
import ModalCloseBtn from './modalCloseBtn';
import dayConf from '../../conf/dayConf';

const DayStartModal: FC<{}> = () => {
  const navigation = useSelector((state: RootState) => state.navigation);
  const attributes = useSelector((state: RootState) => state.attributes);
  const resources = useSelector((state: RootState) => state.resources);
  const dayNum = useSelector((state: RootState) => state.game.day);
  const gameChoices = useSelector((state: RootState) => state.game.choices);

  const [selectedChoice, setSelectedChoice] = useState<string | null>(null);
  const [selectedAction, setSelectedAction] = useState<string | null>(null);

  return (
    <div className="modal-content">
      <div className="modal-header">
        <h5 className="modal-title">Day {dayNum}</h5>
        {!navigation.modal.uncloseable && <ModalCloseBtn />}
      </div>
      <div className="modal-body">
        <div className="choice-description">
          <DynamicText text={days[dayNum].description} />
        </div>
        {days[dayNum].event && days[dayNum].event === 'choice' && (
          <div className="choices-container row">
            {gameChoices[dayNum]?.map((choice) => {
              const choiceConf = choices[choice.name];
              return (
                <button
                  type="button"
                  className={`btn btn-icon choice-box col-6 text-center${
                    selectedChoice === choice.name ? ' selected' : ''
                  }`}
                  key={choice.name}
                  onMouseOver={() => {
                    playSfx('hover');
                  }}
                  onClick={() => {
                    playSfx('press');
                    setSelectedChoice(choice.name);
                  }}
                >
                  <div className="choice-box-inner">
                    <div className="choice-name">
                      <div>{choiceConf.displayName}</div>
                    </div>
                    <div className="icon">
                      <img
                        src={getIcon(choiceConf.icon)}
                        alt={choiceConf.displayName}
                      />
                    </div>
                    <div className="reward">
                      <DynamicText
                        text={choiceConf.description.replace(
                          '{{num}}',
                          `<span class="num">${numberDisplay(choice.value)}</span>`,
                        )}
                      />
                    </div>
                  </div>
                </button>
              );
            })}
          </div>
        )}

        {days[dayNum].event && days[dayNum].event !== 'choice' && (
          <div className="day-actions">
            <div className="text-shadow text-center pt-2">Your action:</div>
            <div className="choices-container row justify-content-center mt-1">
              {days[dayNum].eventActions?.map((action, index) => {
                if (
                  action.condition &&
                  attributes[action.condition.attribute].currentAmount +
                    attributes.attrLck.currentAmount <
                    action.condition.amount
                )
                  return null;
                if (
                  action.cost &&
                  resources[action.cost.resource].amount < action.cost.amount
                )
                  return null;

                const colSize = days[dayNum].eventActions.length !== 3 ? 6 : 4;
                return (
                  <button
                    key={index}
                    type="button"
                    aria-label="Action"
                    className={`btn btn-icon choice-box col-${colSize} text-center${
                      selectedAction === action.type ? ' selected' : ''
                    }`}
                    onClick={() => {
                      playSfx('press');
                      setSelectedAction(action.type);
                    }}
                  >
                    <div className="choice-box-inner">
                      <div className="icon">
                        <img src={getIcon(action.icon)} alt={action.text} />
                      </div>
                      <div className="choice-name">
                        <div>{action.text}</div>
                      </div>
                      <span className="requirement">
                        {action.cost && (
                          <>
                            <span className="num">-{action.cost.amount}</span>
                            <DynamicText text={action.cost.resource} />
                          </>
                        )}
                        {action.condition && (
                          <div className="d-flex flex-wrap align-items-center justify-content-center">
                            <div>
                              <DynamicText text={action.condition.attribute} />:
                            </div>
                            <div>
                              <span className="num">
                                {
                                  attributes[action.condition.attribute]
                                    .currentAmount
                                }
                                +{attributes.attrLck.currentAmount}
                              </span>{' '}
                            </div>
                            <div>
                              (req:
                              <span className="num">
                                {action.condition.amount}
                              </span>
                              )
                            </div>
                          </div>
                        )}
                      </span>
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        )}
      </div>
      <div
        className={`modal-footer flex-column align-items-${(() => {
          if (dayNum && days[dayNum].event) {
            return 'center';
          }
          return 'end';
        })()}`}
      >
        {!days[dayNum].event && (
          <button
            type="button"
            className="btn btn-primary"
            onMouseOver={() => {
              playSfx('hover');
            }}
            onClick={() => {
              playSfx('click');
              store.dispatch(
                updateModal({
                  value: { show: false, type: '' },
                }),
              );
            }}
          >
            Continue
          </button>
        )}
        {days[dayNum].event && (
          <button
            type="button"
            aria-label="Choice"
            className="btn btn-primary"
            disabled={!selectedChoice && !selectedAction}
            onMouseOver={() => {
              playSfx('hover');
            }}
            onClick={() => {
              playSfx('press');
              if (dayConf[dayNum].event === 'choice') {
                if (selectedChoice) {
                  dayActions.choose(dayNum, selectedChoice);
                }
              } else {
                dayActions[selectedAction as string](
                  dayNum,
                  selectedAction as string,
                );
              }
            }}
          >
            Choose
          </button>
        )}
      </div>
    </div>
  );
};
export default DayStartModal;
