import CostHandler from '../costHandler';
import { addResource, npcInteraction } from '../gameUtil';
import { getBalanceModded } from '../modUtil';
import balance from '../../conf/balanceConf';

const confirmTrade = (
  tradeType: string,
  resource: string,
  resourceAmount: number,
  coinsAmount: number,
) => {
  let resourceTaken = resource;
  let takenAmount = resourceAmount;
  let resourceGiven = 'coins';
  let givenAmount = coinsAmount;
  if (tradeType === 'buy') {
    resourceTaken = 'coins';
    takenAmount = coinsAmount;
    resourceGiven = resource;
    givenAmount = resourceAmount;
  }
  const costHandler = new CostHandler();
  costHandler.addCost(resourceTaken, takenAmount);
  costHandler.addCost(
    'socialEnergy',
    getBalanceModded('trade.socialEnergyCost'),
  );
  costHandler.payAllCosts();

  addResource(resourceGiven, givenAmount);
  npcInteraction(null, balance.interactionRelationship);
};

export { confirmTrade };
