import { store } from '../store';
import { updateResource } from '../store/resourceSlice';
import { updateUpgrade } from '../store/upgradeSlice';
import { addToSource, updateAttribute } from '../store/attributeSlice';
import { updateNpc } from '../store/locationSlice';
import { addBalanceMod } from '../store/gameSlice';
import { updateSkill } from '../store/skillSlice';
import { ModConf, AddModifier, Modifier } from '../types';
import balance from '../conf/balanceConf';
import modList from '../conf/modConf';

const modExists = (existingMods: ModConf[], newMod: ModConf): boolean => {
  if (!existingMods || existingMods.length === 0) {
    return false;
  }

  return existingMods.some((modConf) => {
    // Case 1: Both mods don't have identifiers, compare by modName
    const noIdentifierMatch =
      !modConf.data?.identifier &&
      !newMod.data?.identifier &&
      modConf.modName === newMod.modName;

    // Case 2: Both mods have identifiers, compare by identifier
    const identifierMatch =
      modConf.data?.identifier !== undefined &&
      modConf.data.identifier === newMod.data?.identifier;

    // Return true if either condition is met
    return noIdentifierMatch || identifierMatch;
  });
};

export const insertAddMod = (mod: AddModifier) => {
  console.log(mod);
  const { dispatch } = store;
  const newMod: ModConf = {
    modName: mod.modName,
    priority: mod.priority,
    modProperty: mod.modProperty,
    data: mod.data,
  };
  const { resources } = store.getState();
  const { upgrades } = store.getState();
  const { attributes } = store.getState();
  const locations = store.getState().location.list;
  const { skills } = store.getState();
  switch (mod.modObjectType) {
    case 'Resource':
      // only add the mod if it doesn't already exist
      if (
        resources[mod.modObjectName].mods &&
        modExists(resources[mod.modObjectName].mods, newMod)
      ) {
        return;
      }
      const newMods = structuredClone(resources[mod.modObjectName].mods || []);
      newMods.push(newMod);
      dispatch(
        updateResource({
          resource: mod.modObjectName,
          property: 'mods',
          value: newMods,
        }),
      );
      break;
    case 'Upgrade':
      // only add the mod if it doesn't already exist
      if (
        upgrades[mod.modObjectName].mods &&
        modExists(upgrades[mod.modObjectName].mods, newMod)
      ) {
        return;
      }
      dispatch(
        updateUpgrade({
          upgrade: mod.modObjectName,
          property: 'mods',
          value: [...upgrades[mod.modObjectName].mods, newMod],
        }),
      );
      break;
    case 'Attribute':
      // only add the mod if it doesn't already exist
      if (modExists(attributes[mod.modObjectName].mods, newMod)) {
        return;
      }
      dispatch(
        updateAttribute({
          attribute: mod.modObjectName,
          property: 'mods',
          value: [...attributes[mod.modObjectName].mods, newMod],
        }),
      );
      break;
    case 'Npc':
      // only add the mod if it doesn't already exist
      if (modExists(locations[mod.modObjectName]?.npc?.mods, newMod)) {
        return;
      }
      dispatch(
        updateNpc({
          location: mod.modObjectName,
          npc: {
            mods: [...(locations[mod.modObjectName]?.npc?.mods || []), newMod],
          },
        }),
      );
      break;
    case 'Balance':
      // only add the mod if it doesn't already exist
      if (modExists(store.getState().game.balanceMods, newMod)) {
        return;
      }
      dispatch(addBalanceMod(newMod));
      break;
    case 'Skill':
      // only add the mod if it doesn't already exist
      if (
        skills[mod.modObjectName].mods &&
        modExists(skills[mod.modObjectName].mods, newMod)
      ) {
        return;
      }
      dispatch(
        updateSkill({
          skill: mod.modObjectName,
          property: 'mods',
          value: [...skills[mod.modObjectName].mods, newMod],
        }),
      );
      break;
    default:
      break;
  }
};

export const getBalanceModded = (name: string) => {
  // split at the first period to get the parent object
  const split = name.split('.');
  const parent = split.length > 1 ? split[0] : null;
  let value = parent ? balance[parent][split[1]] : balance[name];
  const { balanceMods } = store.getState().game;
  balanceMods.forEach((mod: ModConf) => {
    if (mod.modProperty === name) {
      const modifier = modList[mod.modName] as Modifier;
      value = modifier(value, mod.data);
    }
  });
  return value;
};

export const getPropertyModded = (
  object: any,
  property: string,
  initialValue: number,
) => {
  const mods = structuredClone(object.mods);
  let newValue = initialValue !== undefined ? initialValue : object[property];
  if (!mods) {
    return newValue;
  }
  mods.sort((a: ModConf, b: ModConf) => a.priority - b.priority);
  mods.forEach((mod: ModConf) => {
    if (mod.modProperty !== property) return;
    if (mod.data && mod.data.isActive === false) return;
    if (mod.data && mod.data.isApplied) return;
    const modFunc: Modifier = modList[mod.modName];
    if (!modFunc) return;
    if (newValue.convert) {
      newValue = {
        convert: modFunc(newValue.convert, mod.data),
      };
    } else {
      newValue = modFunc(newValue, mod.data);
    }
  });
  return newValue;
};
