import { FC } from 'react';
import { useSelector } from 'react-redux';
import { Tooltip } from 'react-tooltip';
import { endDay } from '../../utils/gameState';
import SkillList from '../model/skillList';
import { updateModal } from '../../store/navigationSlice';
import { store, RootState } from '../../store';
import { playSfx } from '../../utils/sound';

const BottomMenu: FC<{}> = () => {
  const dayNum = useSelector((state: RootState) => state.game.day);
  const achievements = useSelector((state: RootState) => state.achievements);
  const unlockedAchievements = Object.values(achievements).filter(
    (achievement) => achievement.isUnlocked,
  );
  const unlocks = useSelector((state: RootState) => state.unlocks);
  const tutorialStep = useSelector(
    (state: RootState) => state.game.tutorialStep,
  );

  const unseenAchievements = Object.keys(achievements).filter(
    (achievement) =>
      achievements[achievement].isUnlocked && !unlocks[achievement]?.isSeen,
  );

  return (
    <div className="panel container footer-menu w-100 d-flex justify-content-between align-items-center">
      <button
        aria-label="Achievements"
        type="button"
        className={`btn btn-icon btn-achievements${
          unseenAchievements.length ? ' new' : ''
        }`}
        data-tooltip-id="tooltip-achievements"
        onMouseOver={() => {
          playSfx('hover');
        }}
        onClick={() => {
          playSfx('motion');
          store.dispatch(
            updateModal({
              value: { show: true, type: 'achievements' },
            }),
          );
        }}
      >
        <span className="num">
          {unlockedAchievements.length}/{Object.keys(achievements).length}
        </span>
      </button>
      <Tooltip
        id="tooltip-achievements"
        className="wrap"
        place="top"
        offset={5}
      >
        Achievements
      </Tooltip>

      <div className="day-info">
        <button
          type="button"
          className="btn btn-icon btn-calendar me-auto"
          data-tooltip-id="tooltip-calendar"
          onMouseOver={() => {
            playSfx('hover');
          }}
          onClick={() => {
            playSfx('motion');
            store.dispatch(
              updateModal({
                value: { show: true, type: 'calendar' },
              }),
            );
          }}
        >
          <span className="btn-text">
            Day <span className="num">{dayNum}</span>
          </span>
        </button>
        <Tooltip
          id="tooltip-calendar"
          place="top"
          className={`wrap${tutorialStep === 1 ? ' d-none' : ''}`}
          offset={5}
        >
          Check upcoming events
        </Tooltip>
      </div>

      <div className="ms-auto d-flex skill-btn-wrapper">
        <SkillList />
      </div>
      <div className="btn-sleep-wrapper">
        <button
          type="button"
          className="btn btn-icon btn-sleep"
          data-tooltip-id="tooltip-end-day"
          onMouseOver={() => {
            playSfx('hover');
          }}
          onClick={() => {
            playSfx('start');
            endDay();
          }}
        >
          <span className="btn-text">End day</span>
        </button>
      </div>
      <Tooltip id="tooltip-end-day" place="top" offset={10}>
        End the day.
        <br />
        Restore your status.
        <br />A new day will start.
      </Tooltip>
    </div>
  );
};
export default BottomMenu;
