import { ModList } from '../types';
import { storeValue } from '../utils';
import { Upgrade, Attribute, ModData } from '../types';
import balance from './balanceConf';
import { getBalanceModded } from '../utils/modUtil';
import { npcData } from './achievementConf';

const modList: ModList = {
  // general
  strAffectsPECap: (x: number, data) => {
    const obj = storeValue('attributes', 'attrStr') as Attribute;
    const upgrade = storeValue('upgrades', data?.upgrade) as Upgrade;
    let ret = x;
    if (upgrade?.amount) {
      ret += obj.currentAmount * upgrade.power * upgrade.amount;
    } else {
      ret += obj.currentAmount * 10;
    }
    return ret;
  },
  conAffectsPECap: (x: number, data) => {
    const obj = storeValue('attributes', 'attrCon') as Attribute;
    const upgrade = storeValue('upgrades', data?.upgrade) as Upgrade;
    let ret = x;
    if (upgrade?.amount) {
      ret += obj.currentAmount * upgrade.power * upgrade.amount;
    } else {
      ret += obj.currentAmount * 10;
    }
    return ret;
  },
  conAffectsHPCap: (x: number, data) => {
    const obj = storeValue('attributes', 'attrCon') as Attribute;
    const upgrade = storeValue('upgrades', data?.upgrade) as Upgrade;
    let ret = x;
    if (upgrade?.amount) {
      ret += obj.currentAmount * upgrade.power * upgrade.amount;
    } else {
      ret += obj.currentAmount * 2;
    }
    return ret;
  },
  intAffectsMECap: (x: number, data) => {
    const obj = storeValue('attributes', 'attrInt') as Attribute;
    const upgrade = storeValue('upgrades', data?.upgrade) as Upgrade;
    let ret = x;
    if (upgrade?.amount) {
      ret += obj.currentAmount * upgrade.power * upgrade.amount;
    } else {
      ret += obj.currentAmount * 10;
    }
    return ret;
  },
  intAffectsManaCap: (x: numbe, data) => {
    const obj = storeValue('attributes', 'attrInt') as Attribute;
    const upgrade = storeValue('upgrades', data?.upgrade) as Upgrade;
    let ret = x;
    if (upgrade?.amount) {
      ret += obj.currentAmount * upgrade.power * upgrade.amount;
    } else {
      ret += obj.currentAmount * 10;
    }
    return ret;
  },
  wisAffectsFocusCap: (x: number, data) => {
    const obj = storeValue('attributes', 'attrWis') as Attribute;
    const upgrade = storeValue('upgrades', data?.upgrade) as Upgrade;
    let ret = x;
    if (upgrade?.amount) {
      ret += obj.currentAmount * upgrade.power * upgrade.amount;
    } else {
      ret += obj.currentAmount * 10;
    }
    return ret;
  },
  wisAffectsMECap: (x: number, data) => {
    const obj = storeValue('attributes', 'attrWis') as Attribute;
    const upgrade = storeValue('upgrades', data?.upgrade) as Upgrade;
    let ret = x;
    if (upgrade?.amount) {
      ret += obj.currentAmount * upgrade.power * upgrade.amount;
    } else {
      ret += obj.currentAmount * 10;
    }
    return ret;
  },
  chaAffectsSECap: (x: number) => {
    const obj = storeValue('attributes', 'attrCha') as Attribute;
    x += obj.currentAmount * 10;
    return x;
  },

  // general
  cost2x: (x: number, data) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x * 2 ** obj.amount;
  },
  increaseEnergyCap: (x: number, data) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x + obj.currentPower * obj.amount;
  },
  pow1_5: (x: number, data) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x * 1.5 ** obj.amount;
  },

  pow2: (x: number, data) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x * 2 ** obj.amount;
  },
  pow4: (x: number, data) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x * 4 ** obj.amount;
  },
  multiply5: (x: number, data) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x * 5 * obj.amount;
  },
  plus1: (x: number, data) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x + obj.amount;
  },
  timesAmount: (x: number, data) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x + x * obj.amount;
  },
  plusPower: (x: number, data) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x + obj.currentPower * obj.amount;
  },
  timesPower: (x: number, data) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x * obj.currentPower * obj.amount;
  },
  timesPowerExp: (x: number, data) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x * obj.currentPower ** obj.amount;
  },
  hundredPowAmount: (x: number, data) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x * 100 ** obj.amount;
  },
  thousandPowAmount: (x: number, data) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x * 1000 ** obj.amount;
  },
  tenPowAmount: (x: number, data) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x * 10 ** obj.amount;
  },
  minus1: (x: number) => {
    return x - 1;
  },

  craftingLimit: () => {
    return getBalanceModded('craftingLimit');
  },
  craftingCostReduction: (x: number) => {
    return x / getBalanceModded('craftingCostReduction');
  },

  // npc
  engagementRingAmount: (x: number) => {
    let amount = 1;
    const upgrades = storeValue('upgrades') as any;
    if (!upgrades) return amount;
    npcData.forEach((npc) => {
      const propose = upgrades[`${npc.location}Propose`] as Upgrade;
      amount += propose?.amount || 0;
    });
    return amount;
  },

  // home
  paperMakerPaperGpsTemp: (x: number, data?: ModData) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x + obj.currentPower;
  },
  paperMakerWoodGpsTemp: (x: number, data?: ModData) => {
    const obj = storeValue('upgrades', data?.upgrade) as Upgrade;
    return x - (obj.currentAdditionalPower?.convert || 0);
  },

  // town hall
  // library

  // temple
  hangOutMaxFocus: (x: number) => {
    const obj = storeValue('upgrades', 'templeHangOut') as Upgrade;
    return x + balance.hangOut.templeReward * obj.amount;
  },

  // mines
  minerStone: (x: number) => {
    const obj = storeValue('upgrades', 'minerStone') as Upgrade;
    return x + obj.amount * obj.currentPower;
  },
  minerIron: (x: number) => {
    const obj = storeValue('upgrades', 'minerIron') as Upgrade;
    return x + obj.amount * obj.currentPower;
  },
  minerTitanium: (x: number) => {
    const obj = storeValue('upgrades', 'minerTitanium') as Upgrade;
    return x + obj.amount * obj.currentPower;
  },
  minerMithril: (x: number) => {
    const obj = storeValue('upgrades', 'minerMithril') as Upgrade;
    return x + obj.amount * obj.currentPower;
  },

  // forest
  hireLumberjack: (x: number) => {
    const obj = storeValue('upgrades', 'hireLumberjack') as Upgrade;
    return x + obj.amount * obj.currentPower;
  },
  hireHunter: (x: number) => {
    const obj = storeValue('upgrades', 'hireHunter') as Upgrade;
    return x + obj.amount * obj.currentPower;
  },

  // balance
  defaultPlayerAttack: (x: number) => {
    const str = storeValue('attributes', 'attrStr') as Attribute;
    const lck = storeValue('attributes', 'attrLck') as Attribute;
    x = str.currentAmount + lck.currentAmount;
    return x;
  },

  // choice mods
  choiceAttrStr: (x: number, data: ModData) => {
    x += data.value as number;
    return x;
  },
  choiceAttrInt: (x: number, data: ModData) => {
    x += data.value as number;
    return x;
  },
  choiceAttrCon: (x: number, data: ModData) => {
    x += data.value as number;
    return x;
  },
  choiceAttrWis: (x: number, data: ModData) => {
    x += data.value as number;
    return x;
  },
  choiceAttrLck: (x: number, data: ModData) => {
    x += data.value as number;
    return x;
  },

  // achievement mods
  startWithCoins: (x: number) => {
    x += balance.achievements.rentPaid.amount;
    return x;
  },
  startWithDebt: (x: number) => {
    x -= balance.achievements.rentNotPaid.amount;
    return x;
  },
  allChattedChatRelationship: (x: number) => {
    x += balance.allChattedChatRelationship;
    return x;
  },
  firstChatRelationship: (x: number) => {
    x += balance.achievements.tutorialCompleted.amount;
    return x;
  },
  startWithRelationship: (x: number, data: any) => {
    return x + (typeof data.amount === 'number' ? data.amount : 0);
  },
  achievementAttribute: (x: number, data: ModData = { amount: 0 }) => {
    return x + (typeof data.amount === 'number' ? data.amount : 0);
  },

  itemAddsAttribute: (x: number, data: ModData) => {
    const { attribute } = data;
    const items = storeValue('items', 'list') as any;

    // loop through items and add find the highest attribute amount
    let maxAttribute = 0;
    Object.values(items).forEach((itemList: any) => {
      Object.values(itemList).forEach((item: any) => {
        if (
          item.attribute === attribute &&
          item.attributeAmount > maxAttribute
        ) {
          maxAttribute = item.attributeAmount;
        }
      });
    });
    x += maxAttribute;
    return x;
  },

  addChoiceNum: (x: number, data: any) => {
    const { value } = data;
    x += value;
    return x;
  },
  timesChoiceNum: (x: number, data: any) => {
    const { value } = data;
    return x * value;
  },
};

export default modList;
