// react component
import { FC } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from '../../store';
import ModelIcon from '../model/modelIcon';
import { displayName, iconName } from '../../utils/index';

const AcquiredResource: FC<{
  acquiredResources: Record<string, any>;
  isOpen: boolean;
  animationKey: string;
}> = ({ acquiredResources, isOpen, animationKey }) => {
  const resources = useSelector((state: RootState) => state.resources);
  const animations = useSelector((state: RootState) => state.animations);
  return (
    <div className="acquired-resources-container no-hover">
      {isOpen && (
        <div
          className={`acquired-resources ${animations[animationKey] && animations[animationKey].active ? ' is-animating' : ''}`}
        >
          {acquiredResources[animationKey] &&
            acquiredResources[animationKey].map((loot: any) => (
              <div
                key={`${animationKey}-${loot.resource}-${loot.amount}`}
                className="acquired-resource"
              >
                <div className="resource-quantity num">
                  {loot.amount > 0 ? '+' : ''}
                  {loot.amount}
                </div>
                <div className="resource">
                  {!loot.text ? (
                    <ModelIcon model={iconName(loot.resource, resources)} />
                  ) : null}
                </div>
                <div className="resource-name">
                  {loot.text
                    ? loot.text
                    : displayName(loot.resource, loot.amount, resources)}
                </div>
              </div>
            ))}
        </div>
      )}
    </div>
  );
};

export default AcquiredResource;
