import React, { FC } from 'react';
import { useSelector } from 'react-redux';
import { DayConf } from '../../conf/dayConf';
import { RootState } from '../../store';
import { textDisplay, numberDisplay } from '../../utils';

interface ChallengeRequirementsProps {
  dayInfo: DayConf;
}

const ChallengeRequirements: FC<ChallengeRequirementsProps> = ({ dayInfo }) => {
  // Get resources and attributes from Redux store
  const resources = useSelector((state: RootState) => state.resources);
  const attributes = useSelector((state: RootState) => state.attributes);

  const requirementItems: Array<{
    text: string;
    isMet: boolean;
    amount: number;
    resource?: string;
    attribute?: string;
    type: 'resource' | 'attribute' | 'fight';
  }> = [];

  // Process requirements
  dayInfo.eventActions?.forEach((action: any) => {
    if (action.cost) {
      const resourceAmount =
        resources[action.cost.resource]?.[
          resources[action.cost.resource].isCapped ? 'currentCap' : 'amount'
        ] || 0;
      requirementItems.push({
        text: action.cost.resource,
        amount: action.cost.amount,
        resource: action.cost.resource,
        isMet: resourceAmount >= action.cost.amount,
        type: 'resource',
      });
    } else if (action.condition) {
      const attributeValue =
        (attributes[action.condition.attribute]?.currentAmount || 0) +
        attributes.attrLck.currentAmount;
      requirementItems.push({
        text: action.condition.attribute,
        amount: action.condition.amount,
        attribute: action.condition.attribute,
        isMet: attributeValue >= action.condition.amount,
        type: 'attribute',
      });
    } else if (action.icon !== 'dead') {
      requirementItems.push({
        text: 'Win a fight',
        amount: 0,
        isMet: false,
        type: 'fight',
      });
    }
  });

  if (requirementItems.length === 0) {
    return null;
  }

  return (
    <div className="challenge-requirements">
      <div className="requirement-title">Required to pass:</div>
      <ul className="day-requirements requirements">
        {requirementItems.map((req, index) => (
          <React.Fragment key={`req-${index}`}>
            <li className={`${req.type} ${req.isMet ? 'met' : 'missing'}`}>
              {req.type !== 'fight' ? (
                <>
                  <span className="num">{numberDisplay(req.amount)}</span>{' '}
                  <span
                    dangerouslySetInnerHTML={{ __html: textDisplay(req.text) }}
                  />
                </>
              ) : (
                req.text
              )}
            </li>
            {index < requirementItems.length - 1 && <li className="or">or</li>}
          </React.Fragment>
        ))}
      </ul>
    </div>
  );
};

export default ChallengeRequirements;
