Object.keys(resources).forEach((resource) => {
  if (!unlocks[resource]) {
    unlocks[resource] = {};
  }
});

Object.keys(achievements).forEach((achievement) => {
  unlocks[achievement] = {
    isSeen: true,
  };
});

Object.keys(locations).forEach((location) => {
  unlocks[`${location}Chat`] = unlocks.chat;
});

Object.keys(upgrades).forEach((upgrade) => {
  if (!unlocks[upgrade])
    unlocks[upgrade] = {
      isUnlocked: false,
    };
});

Object.keys(skills).forEach((skill) => {
  if (!unlocks[skill]) {
    unlocks[skill] = {
      isSeen: true,
    };
  }
});

dayConf.forEach((day) => {
  if (day.event && day.event !== 'choice') {
    unlocks[day.event] = {
      isSeen: false,
    };
  }
});

export default unlocks;

