import React from 'react';
import { useSelector } from 'react-redux';
import { RootState } from '../../../../store';
import attack from '../../../../assets/img/location/forest/attack.gif';

type AnimationProps = {
  battleState: number;
};

const FightAnimations: React.FC<AnimationProps> = ({ battleState }) => {
  const values = useSelector(
    (state: RootState) => state.location.list.forest.values,
  );
  const health = useSelector(
    (state: RootState) => state.resources.healthPoints,
  );
  const animations = useSelector((state: RootState) => state.animations);

  return (
    <>
      <img
        src={attack}
        alt="attack"
        className={`attack-animation${values.monsterState === 'hurt' ? '' : ' d-none'}`}
      />
      <div
        className={`damage-numbers damage-by-player${animations.damageByPlayer && animations.damageByPlayer.active ? ' animating' : ''}`}
      >
        {animations.damageByPlayer && animations.damageByPlayer.value}
      </div>
      <div
        className={`damage-numbers damage-by-monster${animations.damageByMonster && animations.damageByMonster.active ? ' animating' : ''}`}
      >
        {animations.damageByMonster && animations.damageByMonster.value}
      </div>
      <div className={`you-died${health.amount === 0 ? ' visible' : ''}`}>
        <div>You died</div>
      </div>
    </>
  );
};

export default FightAnimations;
