Object.keys(locations).forEach((location) => {
  if (location === 'home') return; // Skip home as it's handled separately
  upgrades[`${location}Chat`] = upgrades.chat;
  const locationHangOut = structuredClone(upgrades.hangOut);
  locationHangOut.description = `${upgrades.hangOut.description} ${hangOutDescription[location]}`;
  locationHangOut.name = `${location}HangOut`;
  upgrades[`${location}HangOut`] = locationHangOut;
  upgrades[`${location}Flirt`] = upgrades.flirt;
  const locationPropose = structuredClone(upgrades.propose);
  locationPropose.description = `${upgrades.propose.description} ${proposeDescription[location]}`;
  locationPropose.name = `${location}Propose`;
  upgrades[`${location}Propose`] = locationPropose;
});

