import { createSlice } from '@reduxjs/toolkit';
import versions from '../conf/versionConf';
import { updateSliceVersion } from './common';
import { ModConf } from '../types';

export interface ChoiceData {
  name: string;
  value: number;
  isSelected: boolean;
}

export interface GameState {
  version: string;
  versionChanged: boolean;
  gameInitialized: boolean;
  isPaused: boolean;
  hasError: boolean;
  tutorialStep: number;
  day: number;
  dayAction: string;
  dayStarted: boolean;
  dayInitialized: boolean;
  skillSlots: {
    [key: string]: string | null;
  };
  usedAchievements: string[];
  choices: {
    [key: string]: ChoiceData[] | string;
  };
  balanceMods: ModConf[];
}

const initialState: GameState = {
  version: versions[0].number,

  versionChanged: undefined,
  gameInitialized: false,
  isPaused: false,
  hasError: false,
  day: 1,
  tutorialStep: 1,
  dayAction: '',
  dayStarted: false,
  dayInitialized: false,
  skillSlots: {},
  usedAchievements: [],
  choices: {},
  balanceMods: [
    {
      modName: 'defaultPlayerAttack',
      priority: 0,
      modProperty: 'fighting.playerAttack',
    },
  ],
};

export const gameSlice = createSlice({
  name: 'game',
  initialState,
  reducers: {
    nextDay: (state) => {
      state.day += 1;
    },
    previousDay: (state) => {
      state.day -= 1;
    },
    setDayStarted: (state, action) => {
      state.dayStarted = action.payload;
    },
    resetGame: () => {
      return initialState;
    },
    setGameInitialized: (state, action) => {
      state.gameInitialized = action.payload;
    },
    setDayInitialized: (state, action) => {
      state.dayInitialized = action.payload;
    },
    setDayAction: (state, action) => {
      state.dayAction = action.payload;
    },
    setVersionChanged: (state, action) => {
      state.versionChanged = action.payload;
    },
    pause: (state) => {
      state.isPaused = true;
    },
    unpause: (state) => {
      state.isPaused = false;
    },
    addSkillSlot(state, action) {
      state.skillSlots[action.payload] = null;
    },
    assignSkillSlot(state, action) {
      // loop through skill slots and assign the first empty one
      Object.keys(state.skillSlots).some((slot) => {
        if (state.skillSlots[slot] === null) {
          state.skillSlots[slot] = action.payload.skill;
          return true;
        }
        return false;
      });
    },
    useAchievement(state, action) {
      if (!state.usedAchievements.includes(action.payload)) {
        state.usedAchievements?.push(action.payload);
      }
    },
    removeAchievement(state, action) {
      state.usedAchievements = state.usedAchievements?.filter(
        (a) => a !== action.payload,
      );
    },
    updateVersion: (state) => {
      return updateSliceVersion(state, initialState);
    },
    setHasError: (state, action) => {
      state.hasError = action.payload;
    },
    setChoicesForDay: (state, action) => {
      state.choices[state.day] = action.payload;
    },
    setSelectedChoice: (state, action) => {
      const { day } = state;
      state.choices[day] = state.choices[day].map((choice) => {
        choice.isSelected = choice.name === action.payload;
        return choice;
      });
    },
    setActionChoice: (state, action) => {
      state.choices[state.day] = action.payload;
    },
    addBalanceMod: (state, action) => {
      state.balanceMods.push(action.payload);
    },
    setTutorialStep: (state, action) => {
      state.tutorialStep = action.payload;
    },
  },
});

// Action creators are generated for each case reducer function
export const {
  nextDay,
  previousDay,
  setDayStarted,
  resetGame,
  setGameInitialized,
  setDayInitialized,
  pause,
  unpause,
  addSkillSlot,
  assignSkillSlot,
  useAchievement,
  removeAchievement,
  setDayAction,
  updateVersion,
  setHasError,
  setChoicesForDay,
  setSelectedChoice,
  addBalanceMod,
  setTutorialStep,
  setActionChoice,
  setVersionChanged,
} = gameSlice.actions;

export default gameSlice.reducer;
