import { createSlice } from '@reduxjs/toolkit';
import type { PayloadAction } from '@reduxjs/toolkit';
import { Attribute, AttributeList } from '../types';
import attributes from '../conf/attributeConf';
import { updateSliceVersion } from './common';
import { act } from 'react';

const initialState: AttributeList = attributes;

export const attributeSlice = createSlice({
  name: 'attributes',
  initialState,

  reducers: {
    // reducer to change the value of a attribute.
    // it has arguments: attribute name, property name, and value
    updateAttribute: (
      state,
      action: PayloadAction<{
        attribute: string;
        property: keyof Attribute;
        value: any;
      }>,
    ) => {
      const { attribute, property, value } = action.payload;
      (state[attribute][property] as any) = value;
    },
    addToSource: (
      state,
      action: PayloadAction<{
        attribute: string;
        source: string;
        amount: number;
        setValue?: boolean;
      }>,
    ) => {
      const { attribute, source, amount, setValue } = action.payload;
      const current = state[attribute].sources[source].amount;
      const newAmount = setValue ? amount : current + amount;
      state[attribute].sources[source].amount = newAmount;
    },

    // se
    // set back to inital state
    resetAttributes: () => {
      return initialState;
    },
    updateVersion: (state) => {
      return updateSliceVersion(state, initialState);
    },
  },
});

// Action creators are generated for each case reducer function
export const { updateAttribute, resetAttributes, addToSource, updateVersion } =
  attributeSlice.actions;

export default attributeSlice.reducer;
