import { FC } from 'react';
import { useSelector } from 'react-redux';
import type { RootState } from '../../store';
import SkillBtn from './skillBtn';
import skills from '../../conf/skillConf';

const SkillList: FC<{}> = () => {
  const skillSlot = useSelector((state: RootState) => state.game.skillSlots);
  const modalType = useSelector(
    (state: RootState) => state.navigation.modal.type,
  );

  return (
    // loop over all skill slots
    Object.keys(skillSlot)
      .reverse()
      .map((key) => {
        const skillName = skillSlot[key] || 'empty';
        // If modal type is 'dayStart', only show fight-type skills
        if (modalType === 'dayStart') {
          if (skillName === 'empty' || skills[skillName]?.type !== 'fight') {
            return null; // Don't render non-fight skills
          }
        }

        return <SkillBtn skillName={skillName} key={key} />;
      })
      .filter(Boolean) // Remove null entries
  );
};

export default SkillList;
