import { useSelector } from 'react-redux';
import React, { useEffect } from 'react';
import { store, RootState } from '../../../store';
import { setSeen } from '../../../store/unlockSlice';
import Monster from './monster';
import monsters from '../../../conf/monsterConf';
import { startsWithVowel } from '../../../utils';
import { playSfx } from '../../../utils/sound';
import balance from '../../../conf/balanceConf';
import {
  pickEncounter,
  resetMonster,
  playerAttack,
  getDepthWidth,
  getDepth,
  gotoNextLevel,
  goToLevel,
  getButtonCost,
  setValue,
  getTotalCost,
} from '../../../utils/location/fighting';
import MonsterHealth from './inc/monsterHealth';
import BattleLog from './inc/battleLog';
import FightAnimations from './inc/fightAnimations';
import { npcInteraction } from '../../../utils/gameUtil';

type FightingProps = {
  isActive: boolean;
};
type BattleLogItem = {
  text: string;
  isPlayer: boolean;
};

const Fighting: React.FC<FightingProps> = ({ isActive }) => {
  const unlocks = useSelector((state: RootState) => state.unlocks);
  const values = useSelector(
    (state: RootState) => state.location.list.forest.values,
  );

  const [battleStarted, setBattleStarted] = React.useState(0);
  const [battleLog, setBattleLog] = React.useState([] as BattleLogItem[]);

  const resources = useSelector((state: RootState) => state.resources);

  const redoLevelCost = React.useMemo(
    () => getButtonCost(values.currentLevel),
    [values.currentLevel, resources],
  );

  const goDeeperCost = React.useMemo(
    () => getButtonCost(values.currentLevel + 1),
    [values.currentLevel, resources],
  );

  let monster = monsters[values.monsterType];

  const addToLog = (text: string, isPlayer: boolean) => {
    setBattleLog((prev) => [...prev, { text, isPlayer }]);
  };

  const startLevel = (level?: number) => {
    const useLevel = level || values.currentLevel;

    // reduce the cost from resources
    const costHandler = getTotalCost(useLevel);
    costHandler.payAllCosts();
    npcInteraction(null, balance.interactionRelationship, 'forest');
    setBattleStarted(1);
    setValue('battleIsActive', true);
    setValue('canDie', false);
    const monsterType = pickEncounter(useLevel);
    monster = monsters[monsterType];
    addToLog(
      `You encounter a${
        startsWithVowel(monster.displayName) ? 'n' : ''
      } ${monster.displayName}!`,
      false,
    );
    resetMonster(monsterType, useLevel);
    setTimeout(() => {
      playerAttack(addToLog, setBattleStarted);
    }, 2000);
  };

  const redoLevel = () => {
    startLevel();
  };

  const goDeeper = () => {
    let newLevel = values.currentLevel;
    if (values.unlockedLevel > values.currentLevel) {
      newLevel = gotoNextLevel(addToLog);
    }
    startLevel(newLevel);
  };

  useEffect(() => {
    // if on this tab, mark as seen
    if (!unlocks.fighting.isSeen && isActive) {
      store.dispatch(setSeen('fighting'));
    }
  });

  useEffect(() => {
    if (!isActive) {
      setValue('battleIsActive', false);
    }
  }, [isActive]);

  // if component is unloaded, set battle active to false
  useEffect(() => {
    return () => {
      setValue('battleIsActive', false);
    };
  }, []);

  useEffect(() => {
    addToLog(
      `You are in Forest Depth ${getDepth(values.currentLevel)} (Level ${
        values.currentLevel
      })`,
      true,
    );
  }, []);

  return (
    <div className="fighting">
      <ul className="depth-list">
        {[1, 2, 3, 4, 5].map((depth) => (
          <li
            key={depth}
            className={`depth-item${getDepth(values.unlockedLevel) < depth ? ' locked' : ''}${getDepth(values.currentLevel) === depth ? ' current' : ''}`}
            role="button"
            onMouseEnter={() => {
              const unlockedDepth = getDepth(values.unlockedLevel);
              const currentDepth = getDepth(values.currentLevel);
              if (
                unlockedDepth > depth ||
                (unlockedDepth === depth && currentDepth !== unlockedDepth)
              )
                playSfx('hover');
            }}
            onClick={() => {
              const unlockedDepth = getDepth(values.unlockedLevel);
              const currentDepth = getDepth(values.currentLevel);
              if (unlockedDepth >= depth && currentDepth !== depth) {
                playSfx('click');
                const depthMax = depth * 10;
                setValue('battleIsActive', false);
                setBattleStarted(0);
                goToLevel(
                  values.unlockedLevel >= depthMax
                    ? depthMax
                    : values.unlockedLevel,
                  addToLog,
                );
              }
            }}
          >
            <span className="depth-name">Depth {depth}</span>
            <div
              className="depth-completed"
              style={{
                width: getDepthWidth(depth),
              }}
            />
          </li>
        ))}
      </ul>
      <div className="row">
        <div className="col-12 col-md-12 col-lg-4 battle-log-box">
          <BattleLog battleLog={battleLog} />
        </div>
        <div className="col-12 col-md-12 col-lg-8">
          <div className="card battle">
            <div className="card-header">
              <div className="monster-name">
                {!battleStarted ? (
                  `Forest Depths (Level ${values.currentLevel})`
                ) : (
                  <>
                    {monster.displayName}
                    <span className="stats">
                      (ATK:<span className="num">{values.monsterAttack}</span>)
                    </span>
                  </>
                )}
              </div>
              <MonsterHealth values={values} battleStarted={battleStarted} />
            </div>
            <div className="card-body position-relative">
              <div className="forest-bg" />
              <FightAnimations battleState={battleStarted} />
              {battleStarted ? <Monster /> : null}
              {battleStarted === 1 ? null : (
                <div className="monster prepare">
                  {values.unlockedLevel === 1 ? null : (
                    <button
                      type="button"
                      className="btn btn-primary btn-redo btn-small"
                      disabled={!redoLevelCost.haveEnough}
                      onMouseEnter={() => {
                        if (redoLevelCost.haveEnough) {
                          playSfx('hover');
                        }
                      }}
                      onClick={() => {
                        if (redoLevelCost.haveEnough) {
                          playSfx('click');
                          redoLevel();
                        }
                      }}
                    >
                      Redo Level{' '}
                      <span
                        dangerouslySetInnerHTML={{
                          __html: redoLevelCost.text,
                        }}
                      />
                    </button>
                  )}
                  {battleStarted === 3 ||
                  values.unlockedLevel - values.currentLevel > 1 ||
                  values.currentLevel > balance.fighting.maxLevel - 1 ? null : (
                    <button
                      type="button"
                      className="btn btn-primary btn-small"
                      disabled={!goDeeperCost.haveEnough}
                      onMouseEnter={() => {
                        if (goDeeperCost.haveEnough) {
                          playSfx('hover');
                        }
                      }}
                      onClick={() => {
                        if (goDeeperCost.haveEnough) {
                          playSfx('click');
                          goDeeper();
                        }
                      }}
                    >
                      Go Deeper{' '}
                      <span
                        dangerouslySetInnerHTML={{
                          __html: goDeeperCost.text,
                        }}
                      />
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Fighting;
