import React, { FC, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { Card } from 'react-bootstrap';
import { Tooltip } from 'react-tooltip';
import { store } from '../../store';
import type { RootState } from '../../store';
import { getIcon, numberDisplay, textDisplay } from '../../utils';
import { hasEmptySkillSlot } from '../../utils/skillUtil';
import { confirmModal } from '../../store/navigationSlice';
import { playSfx } from '../../utils/sound';

interface SkillProps {
  skillName: string;
}

const SkillItem: FC<SkillProps> = ({ skillName }) => {
  const unlocks = useSelector((state: RootState) => state.unlocks);
  const skill = useSelector((state: RootState) => state.skills[skillName]);
  const skillSlots = useSelector((state: RootState) => state.game.skillSlots);
  useEffect(() => {
    const unlock = unlocks[skillName];
    if (!unlock.isSeen) {
      store.dispatch({ type: 'unlocks/setSeen', payload: skillName });
    }
  });
  const skillIsAssigned = () => {
    return Object.values(skillSlots).includes(skillName);
  };
  return (
    <div className="skill-box col-12 col-sm-6 col-md-12 col-lg-6">
      <Card style={{ '--var-color': skill.color } as React.CSSProperties}>
        <h3 className="d-flex align-items-center justify-content-between title">
          <div className="d-flex align-items-end">
            <div>
              <span
                className="model-icon"
                style={{ WebkitMaskImage: `url(${getIcon(skill.icon)})` }}
              />
              {skill.displayName}
            </div>
            <div className="cooldown">
              (<div className="num">{numberDisplay(skill.currentCooldown)}</div>
              s cooldown)
            </div>
          </div>
          <button
            type="button"
            aria-label="Assign to skillbar"
            className={`btn btn-assign btn-icon${
              hasEmptySkillSlot() && !skillIsAssigned() ? '' : ' d-none'
            }`}
            onMouseEnter={() => {
              playSfx('hover');
            }}
            onClick={() => {
              playSfx('motion');
              store.dispatch(
                confirmModal({
                  value: {
                    show: true,
                    type: 'skillAddConfirm',
                    model: skillName,
                  },
                }),
              );
            }}
            data-tooltip-id={`tooltip-assign-${skillName}`}
          />
          <Tooltip id={`tooltip-assign-${skillName}`} place="right">
            Assign to skillbar
          </Tooltip>
        </h3>
        <Card.Body>
          <div
            className="description"
            dangerouslySetInnerHTML={{
              __html: textDisplay(
                skill.description.replace(/\{\{(\w+)\}\}/g, (match, p1) => {
                  if (p1 === 'currentPower') {
                    return `<span class="num">${numberDisplay(skill.currentPower)}</span>`;
                  }
                  if (p1 === 'currentCost') {
                    return `<span class="num">${numberDisplay(skill.currentCost)}</span>`;
                  }
                  if (p1 === 'rewards') {
                    return skill.rewards
                      .map(
                        (reward) =>
                          `<span class="num">${numberDisplay(reward.amount || 0)}</span> ${textDisplay(reward.resource || '')}`,
                      )
                      .join(', ');
                  }
                  return match;
                }),
              ),
            }}
          />
          <div className="sep-top row skill-values dynamic-text">
            <div className="col-5">
              Cost:
              <br />
              {skill.currentCost && (
                <>
                  -
                  <span className="num">
                    {skill.currentCost ? numberDisplay(skill.currentCost) : ''}
                  </span>
                </>
              )}{' '}
              <span
                dangerouslySetInnerHTML={{
                  __html: textDisplay(
                    skill.name === 'drink' ? 'a potion' : skill.costResource,
                  ),
                }}
              />
            </div>
            <div className="col-7 text-end">
              Gain:
              <br />
              {skill.rewards?.map((reward, index) =>
                typeof reward === 'string' ? (
                  <div
                    key={`string-reward-${index}`}
                    dangerouslySetInnerHTML={{
                      __html: textDisplay(
                        reward.replace(
                          '{{currentPower}}',
                          `<span class="num">${numberDisplay(skill.currentPower)}</span>`,
                        ),
                      ),
                    }}
                  />
                ) : (
                  <div key={reward.resource}>
                    +
                    <span className="num">
                      {numberDisplay(reward.currentAmount || 0)}
                    </span>{' '}
                    <span
                      dangerouslySetInnerHTML={{
                        __html: textDisplay(reward.resource || ''),
                      }}
                    />
                  </div>
                ),
              )}
            </div>
          </div>
        </Card.Body>
      </Card>
    </div>
  );
};
export default SkillItem;
