import balance from '../conf/balanceConf';
import { store } from '../store';
import { updateResource } from '../store/resourceSlice';
import { updateFeatureValue } from '../store/locationSlice';
import { Cost, CostList } from '../types';
import { makeNumCircular, storeValue } from '.';
import { startAnimation } from '../store/animationSlice';

export const ticketList: { [key: string]: string } = {
  mines: 'miningLicenses',
  temple: 'realizations',
  library: 'recommendations',
  townHall: 'funds',
};

export const ticketNames: { [key: string]: string } = {
  miningLicenses: 'Mining Licenses',
  realizations: 'Realizations',
  recommendations: 'Recommendations',
  funds: 'Funds',
};

class CostHandler {
  costList: CostList;

  amount: number;

  constructor() {
    this.costList = {};
    this.amount = 1;
  }

  getCostList() {
    return this.costList;
  }

  addExpCost(resource: string, type: string, level: number) {
    const costValue = CostHandler.getExpCost(type, level);
    const cost: Cost = {
      cost: costValue,
      currentCost: costValue,
    };
    this.costList[resource] = cost;
  }

  static getExpCost(type: string, level: number) {
    return makeNumCircular(
      balance[type].baseCost * balance[type].costMultiplier ** level,
      2,
    );
  }

  addCostObject(resource: string, cost: Cost) {
    this.costList[resource] = cost;
  }

  addCost(resource: string, amount: number) {
    const cost: Cost = {
      cost: amount,
      currentCost: amount,
    };
    // if already exists, add to the current cost
    if (this.costList[resource]) {
      this.costList[resource].currentCost += amount;
      return;
    }
    this.costList[resource] = cost;
  }

  setAmount(amount: number) {
    this.amount = amount;
  }

  getAmount() {
    return this.amount;
  }

  getMaxAmount() {
    let maxAmount = Infinity;
    Object.entries(this.costList).forEach(([resource, cost]) => {
      const ticketInfo = CostHandler.isTicket(resource);
      if (ticketInfo) {
        const locationData = storeValue(
          'location',
          'list',
          ticketInfo.locationName,
        );
        if (!locationData || !locationData.values) {
          return;
        }
        const amount = Math.floor(
          locationData.values[ticketInfo.ticketName] / cost.currentCost,
        );
        if (amount < maxAmount) {
          maxAmount = amount;
        }
      } else {
        const current = storeValue('resources', resource, 'amount');
        const amount = Math.floor(current / cost.currentCost);
        if (amount < maxAmount) {
          maxAmount = amount;
        }
      }
    });
    return maxAmount;
  }

  static getTicketAmount(ticketString: string) {
    const ticketName = ticketString.split('_')[1];
    const locationName = Object.keys(ticketList).find(
      (key) => ticketList[key] === ticketName,
    );
    const locationData = storeValue('location', 'list', locationName);
    if (!locationData || !locationData.values) {
      return false;
    }
    return locationData.values[ticketName];
  }

  static canPayCost(resource: string, cost: Cost, amount: number = 1) {
    const { resources } = store.getState();
    if (resource.startsWith('ticket_')) {
      const ticketAmount = CostHandler.getTicketAmount(resource);
      if (!ticketAmount) {
        return false;
      }
      if (ticketAmount < cost.currentCost * amount) {
        return false;
      }
    } else if (resources[resource].amount < cost.currentCost * amount) {
      return false;
    }
    return true;
  }

  canPayCosts() {
    let canPay = true;
    Object.entries(this.costList).forEach(([resource, cost]) => {
      const canPayCurrent = CostHandler.canPayCost(resource, cost, this.amount);
      if (!canPayCurrent) {
        canPay = false;
      }
    });
    return canPay;
  }

  static isTicket(
    resource: string,
  ): { locationName: string; ticketName: string } | false {
    if (!resource.startsWith('ticket_')) {
      return false;
    }
    const ticketName = resource.split('_')[1];
    const locationName =
      Object.keys(ticketList).find((key) => ticketList[key] === ticketName) ||
      '';
    return { locationName, ticketName };
  }

  static payCost(resource: string, amount: number) {
    const current = storeValue('resources', resource, 'amount');

    store.dispatch(
      updateResource({
        resource,
        property: 'amount',
        value: current - amount,
      }),
    );

    store.dispatch(
      startAnimation({
        element: resource,
        type: '-',
        value: amount,
        duration: 2000,
      }),
    );
    return true;
  }

  static payTickets(location: string, ticket: string, amount: number) {
    const current = storeValue('location', 'list', location).values?.[ticket];
    if (current >= amount) {
      store.dispatch(
        updateFeatureValue({
          location,
          property: ticket,
          value: current - amount,
        }),
      );
      return true;
    }
    return false;
  }

  payAllCosts() {
    Object.entries(this.costList).forEach(([resource, cost]) => {
      const ticketInfo = CostHandler.isTicket(resource);
      if (ticketInfo) {
        CostHandler.payTickets(
          ticketInfo.locationName,
          ticketInfo.ticketName,
          cost.currentCost * this.amount,
        );
      } else {
        CostHandler.payCost(resource, cost.currentCost * this.amount);
      }
    });
  }
}

export default CostHandler;
