import { createSlice } from '@reduxjs/toolkit';
import type { PayloadAction } from '@reduxjs/toolkit';
import { Location, LocationList, Npc } from '../types';
import locationsList from '../conf/locationConf';
import { updateSliceVersion } from './common';

export interface LocationState {
  current: string;
  list: LocationList;
}

const initialState: LocationState = {
  current: 'home',
  list: locationsList,
};

export const locationSlice = createSlice({
  name: 'location',
  initialState,
  reducers: {
    moveLocation: (state, action: PayloadAction<string>) => {
      state.current = action.payload;
    },
    updateLocation: (
      state,
      action: PayloadAction<{
        location: string;
        property: keyof Location;
        value: any;
      }>,
    ) => {
      const { location, property, value } = action.payload;
      state.list[location][property] = value;
    },
    updateFeatureValue: (
      state,
      action: PayloadAction<{
        location: string;
        property: string;
        value: any;
      }>,
    ) => {
      const { location, property, value } = action.payload;
      state.list[location].values![property] = value;
    },
    resetLocations: () => {
      return initialState;
    },
    updateVersion: (state) => {
      return updateSliceVersion(state, initialState);
    },
    updateNpc: (
      state,
      action: PayloadAction<{ location: string; npc: { [key: string]: any } }>,
    ) => {
      const { location, npc } = action.payload;
      state.list[location].npc = { ...state.list[location].npc, ...npc } as Npc;
    },
  },
});

// Action creators are generated for each case reducer function
export const {
  updateLocation,
  moveLocation,
  resetLocations,
  updateVersion,
  updateFeatureValue,
  updateNpc,
} = locationSlice.actions;

export default locationSlice.reducer;
