export const setValue = (property: string, value: any) => {
  store.dispatch(
    updateFeatureValue({
      location: 'library',
      property,
      value,
    }),
  );
};

export const generateBricks = (level: number) => {
  const levelConf = structuredClone(levels[level]);
  const bricks = [];
  const availableResources: string[] = [];
  const additionalBricks = getBalanceModded('additionalAnalysis') || 0;
  const currentResources = Object.keys(levelConf.resources);
  for (let i = 0; i < additionalBricks * 2; i += 1) {
    // pick one of the current resources
    const randomResource =
      currentResources[Math.floor(Math.random() * currentResources.length)];
    availableResources.push(randomResource);
  }

  currentResources.forEach((resource) => {
    const count = levelConf.resources[resource];
    for (let i = 0; i < count; i += 1) {
      availableResources.push(resource);
    }
  });
  const shuffledResources = [...availableResources].sort(
    () => Math.random() - 0.5,
  );
  while (shuffledResources.length > 0) {
    const brick = [];
    if (shuffledResources.length > 0) {
      brick.push(shuffledResources.pop());
    }
    if (shuffledResources.length > 0) {
      brick.push(shuffledResources.pop());
    } else if (brick.length === 1) {
      brick.push(brick[0]);
    }
    if (brick.length === 2) {
      bricks.push(brick);
    }
  }
  setValue('bricks', bricks);
  setValue('totalBricks', bricks.length);
};

const setRequirements = (level: number) => {
  // multiply the resources by 2 for each level
  const { values } = store.getState().location.list.library;
  const requirements = [];
  Object.keys(levels[level].resources).forEach((resource) => {
    requirements.push({
      resource,
      amount: levels[level].resources[resource] * 2 ** (level - 1),
    });
  });
  setValue('requirements', requirements);
};

export const initializeLevel = () => {
  const { values } = store.getState().location.list.library;
  if (values.analyzeStatus !== 'stopped' && values.analyzeStatus !== 'won') {
    return;
  }
  const nextLevel = values.currentLevel + 1;
  if (!levels[nextLevel]) {
    setValue('analyzeStatus', 'completed');
    return;
  }
  clearGrid();
  generateBricks(nextLevel);
  setRequirements(nextLevel);
  setValue('analyzeStatus', 'initialized');
  setValue('score', 0);
  setValue('requiredScore', levels[nextLevel].score);
};

export const getCostHandler = () => {
  const { values } = store.getState().location.list.library;
  const costHandler = new CostHandler();
  values.requirements.forEach((req) => {
    costHandler.addCost(req.resource, req.amount);
  });
  costHandler.addCost('mentalEnergy', 10 * 2 ** values.currentLevel);
  return costHandler;
};

export const restartLevel = () => {
  const { values } = store.getState().location.list.library;
  setValue('analyzeStatus', 'stopped');
  setValue('currentLevel', values.currentLevel - 1);
};

const timeElapsed = () => {
  const { values } = store.getState().location.list.library;
  let timeElapsedValue = values.timeElapsed || 0;
  if (values.analyzeStatus === 'running') {
    timeElapsedValue += Date.now() - values.timeSessionStarted;
  }
  return timeElapsedValue;
};

const updateGridWithCurrentBrick = (newBrickData: any) => {
  const { values } = store.getState().location.list.library;
  const grid = structuredClone(values.grid);
  const { floatingBrick } = values;
  const currentBrick = newBrickData || values.currentBrick;

  // go over grid and remove floating brick
  // floatinbrick is a 2D array with the current brick's position, eg [[0, 0], [1, 0]]
  if (currentBrick.status !== 'falling' && currentBrick.status !== 'settling') {
    setValue('floatingBrick', []);
    setValue('currentBrick', currentBrick);
    return;
  }

  for (let i = 0; i < floatingBrick.length; i += 1) {
    const [x, y] = floatingBrick[i];
    if (grid[y] && grid[y][x]) {
      grid[y][x] = null; // remove the floating brick from the grid
    }
  }

  // Build the new floating brick positions
  const newFloatingBrick = [
    [currentBrick.x, currentBrick.y],
    [currentBrick.x2, currentBrick.y2],
  ];

  // add current brick to the grid from new floating brick
  for (let i = 0; i < newFloatingBrick.length; i += 1) {
    const [x, y] = newFloatingBrick[i];

    if (y > -1) {
      grid[y][x] = currentBrick.resources[i];
    }
  }

  // update grid
  setValue('grid', grid);
  setValue('floatingBrick', newFloatingBrick);
  setValue('currentBrick', currentBrick);
};

export const clearGrid = () => {
  const { values } = store.getState().location.list.library;
  const grid = [];
  for (let i = 0; i < gridHeight; i += 1) {
    grid[i] = [];
    for (let j = 0; j < gridWidth; j += 1) {
      grid[i][j] = null;
    }
  }
  setValue('grid', grid);
};

const setGridTouches = () => {
  const { values } = store.getState().location.list.library;
  const gridTouches: {
    [y: number]: {
      [x: number]: {
        topLeft: boolean;
        topRight: boolean;
        bottomLeft: boolean;
        bottomRight: boolean;
      };
    };
  } = {};
  // for each grid cell that is not empty,
  //  set object {topLeft, topRight, bottomLeft, bottomRight} with either true or false
  // depending on whether the cell touches a cell with the same resource
  for (let y = 0; y < gridHeight; y += 1) {
    for (let x = 0; x < gridWidth; x += 1) {
      const cell = values.grid[y]?.[x];
      if (cell) {
        // for top left, check both top and left
        const topLeft =
          (values.grid[y - 1] && values.grid[y - 1][x] === cell) ||
          (values.grid[y] && values.grid[y][x - 1] === cell);
        // for top right, check both top and right
        const topRight =
          (values.grid[y - 1] && values.grid[y - 1][x] === cell) ||
          (values.grid[y] && values.grid[y][x + 1] === cell);
        // for bottom left, check both bottom and left
        const bottomLeft =
          (values.grid[y + 1] && values.grid[y + 1][x] === cell) ||
          (values.grid[y] && values.grid[y][x - 1] === cell);
        // for bottom right, check both bottom and right
        const bottomRight =
          (values.grid[y + 1] && values.grid[y + 1][x] === cell) ||
          (values.grid[y] && values.grid[y][x + 1] === cell);
        const obj = {
          topLeft,
          topRight,
          bottomLeft,
          bottomRight,
        };
        if (!gridTouches[y]) {
          gridTouches[y] = {};
        }
        gridTouches[y][x] = obj;
      }
    }
  }
  setValue('gridTouches', gridTouches);
};
const checkForPops = () => {
  const { values } = store.getState().location.list.library;
  const { grid } = values;
  const gridPops: { [y: number]: { [x: number]: boolean } } = {};
  let popped = false;

  // Track which cells we've already processed
  const visited = Array(gridHeight)
    .fill(false)
    .map(() => Array(gridWidth).fill(false));

  // Process each cell in the grid
  for (let y = 0; y < gridHeight; y += 1) {
    for (let x = 0; x < gridWidth; x += 1) {
      // Skip empty cells or already visited cells
      if (!grid[y]?.[x] || visited[y][x]) {
        continue;
      }

      // Run BFS to find connected component
      const cellType = grid[y][x];
      const component = findConnectedComponent(grid, x, y, cellType, visited);
      // If component has 4 or more cells, mark for popping
      if (component.length >= 4) {
        component.forEach(([cx, cy]) => {
          if (!gridPops[cy]) gridPops[cy] = {};
          gridPops[cy][cx] = true;
          popped = true;
        });
      }
    }
  }

  // temporary: compare gridPops and values.gridPops, if the same, do not update
  const existingGridPops = values.gridPops || {};
  if (JSON.stringify(existingGridPops) === JSON.stringify(gridPops)) {
    return false;
  }

  // Update the gridPops state if we found any matches
  if (popped) {
    setValue('gridPops', gridPops);
  }

  return popped;
};

/**
 * Find all cells connected to (startX, startY) with the same value
 * Uses Breadth-First Search for efficiency
 */
const findConnectedComponent = (
  grid: any[][],
  startX: number,
  startY: number,
  cellType: string,
  visited: boolean[][],
): [number, number][] => {
  // The directions: up, right, down, left (no diagonals)
  const directions = [
    [0, -1],
    [1, 0],
    [0, 1],
    [-1, 0],
  ];

  // Use a queue for BFS
  const queue: [number, number][] = [[startX, startY]];
  const component: [number, number][] = [[startX, startY]];
  visited[startY][startX] = true;

  while (queue.length > 0) {
    const [x, y] = queue.shift()!;

    // Check each adjacent cell using forEach instead of for...of and avoid continue
    directions.forEach(([dx, dy]) => {
      const nx = x + dx;
      const ny = y + dy;

      // Only process valid adjacent cells
      if (
        nx >= 0 &&
        nx < gridWidth &&
        ny >= 0 &&
        ny < gridHeight &&
        !visited[ny][nx] &&
        grid[ny][nx] === cellType
      ) {
        // Mark as visited and add to component
        visited[ny][nx] = true;
        queue.push([nx, ny]);
        component.push([nx, ny]);
      }
    });
  }

  return component;
};

export const isPopping = (i: number, j: number) => {
  const { values } = store.getState().location.list.library;
  const { gridPops } = values;
  if (!gridPops || !gridPops[i] || !gridPops[i][j]) return false;
  return true;
};

// if there are empty spaces between bricks anywhere, move all bricks above them down.
// there can be multiple empty spaces in a column, so we need to check each column
const settleBricks = () => {
  const { values } = store.getState().location.list.library;
  const grid = structuredClone(values.grid);
  for (let x = 0; x < gridWidth; x += 1) {
    let emptyRow = -1; // Track the first empty row in this column
    for (let y = gridHeight - 1; y >= 0; y -= 1) {
      if (grid[y][x] === null) {
        if (emptyRow === -1) {
          emptyRow = y; // Found the first empty row
        }
      } else if (emptyRow !== -1) {
        // We found a non-empty cell below an empty cell, so we need to move it down
        grid[emptyRow][x] = grid[y][x];
        grid[y][x] = null; // Clear the original position
        emptyRow -= 1; // Move the empty row up
      }
    }
  }
  setValue('grid', grid);
};

const addScore = (bricksCleared: Record<string, number>, chains: number) => {
  const { values } = store.getState().location.list.library;
  let numBricks = 0;
  let groupBonusAdd = 0;
  Object.keys(bricksCleared).forEach((key) => {
    const currentGroup = bricksCleared[key] || 0;
    numBricks += currentGroup;
    groupBonusAdd += groupBonus[currentGroup] || 0;
  });
  const chainBonusAdd = chainPower[chains] || chainPower[19];
  const colorBonusAdd =
    colorBonus[Object.keys(bricksCleared).length] || colorBonus[1];

  const addScoreNum = Math.floor(
    scoreBase * numBricks * (chainBonusAdd + colorBonusAdd + groupBonusAdd),
  );

  setValue('addScore', addScoreNum);
  setValue('score', values.score + addScoreNum);
};

const removePoppedBricks = () => {
  const { values } = store.getState().location.list.library;
  const { gridPops } = values;
  if (!gridPops) return;

  const clearedBricks = {};
  const newGrid = structuredClone(values.grid);
  Object.keys(gridPops).forEach((y) => {
    Object.keys(gridPops[y]).forEach((x) => {
      const brickType = newGrid[y][x];
      if (!clearedBricks[brickType]) {
        clearedBricks[brickType] = 0;
      }
      newGrid[y][x] = null;
      clearedBricks[brickType] += 1;
    });
  });
  setValue('grid', newGrid);
  setValue('gridPops', {});
  let { chains } = values;
  chains += 1;
  setValue('chains', chains);
  addScore(clearedBricks, chains);
};

const gameTick = () => {
  const { values } = store.getState().location.list.library;
  if (values.analyzeStatus === 'running') {
    /*if (timeElapsed() > 60) {
      setValue('analyzeStatus', 'failed');
      return;
    }*/

    let nextBrick = null;
    if (values.currentBrick.resources.length === 0) {
      nextBrick = getNextBrick();
    }

    const currentBrick =
      nextBrick || store.getState().location.list.library.values.currentBrick;
    if (!currentBrick) {
      return;
    }

    const millisecondsElapsed = currentBrick.lastTickTime
      ? Date.now() - currentBrick.lastTickTime
      : 0;

    const newBrickData = {
      ...currentBrick,
      lastTickTime: Date.now(),
    };
    switch (currentBrick.status) {
      case 'settling':
      case 'falling':
        const speed = currentBrick.speed || defaultSpeed;
        const tempY =
          (currentBrick.tempY || 0) + (millisecondsElapsed / speed) * 100;
        newBrickData.tempY = tempY;
        if (tempY >= 100) {
          newBrickData.y += 1;
          newBrickData.y2 += 1;
          newBrickData.tempY = 0;
          const nextY = newBrickData.y;
          const nextY2 = newBrickData.y2;
          const collisionGrid = structuredClone(values.grid);
          values.floatingBrick.forEach(([x, y]) => {
            if (collisionGrid[y] && collisionGrid[y][x] !== null) {
              collisionGrid[y][x] = null;
            }
          });
          const nextWouldCollide =
            nextY + 1 >= gridHeight ||
            collisionGrid[nextY + 1]?.[newBrickData.x] !== null ||
            nextY2 + 1 >= gridHeight ||
            collisionGrid[nextY2 + 1]?.[newBrickData.x2] !== null;
          if (nextWouldCollide) {
            newBrickData.status = 'settling';
          }
          const wouldCollide =
            nextY >= gridHeight ||
            collisionGrid[nextY]?.[newBrickData.x] !== null ||
            nextY2 >= gridHeight ||
            collisionGrid[nextY2]?.[newBrickData.x2] !== null;
          if (wouldCollide) {
            newBrickData.status = 'settlingBricks';
            playSfx('brickDrop');
            setGridTouches();
          }
        }
        break;

      case 'checkingPops':
        if (checkForPops()) {
          newBrickData.status = 'popping';
          newBrickData.tempY = 0;
        } else {
          newBrickData.tempY = 0;
          newBrickData.status = 'completed';
          setValue('chains', 0);
          if (currentIsOutOfBounds()) {
            endGame();
          }
        }
        break;

      case 'popping':
        // wait here for 1 second
        // check millisecondsElapsed and add it to tempY so that 1 second elapses
        newBrickData.tempY +=
          (currentBrick.tempY || 0) + (millisecondsElapsed / 1000) * 100;
        if (newBrickData.tempY >= 100) {
          playSfx('brickPop');
          removePoppedBricks();
          newBrickData.status = 'settlingBricks';
        }
        break;

      case 'settlingBricks':
        settleBricks();
        setGridTouches();
        newBrickData.status = 'checkingPops';
        break;

      case 'completed':
        // wait
        newBrickData.tempY += (millisecondsElapsed / 1000) * 100;
        if (newBrickData.tempY >= 100 || values.bricks.length !== 0) {
          newBrickData.resources = [];
        }
        break;

      default:
        break;
    }
    updateGridWithCurrentBrick(newBrickData);

    window.setTimeout(() => {
      gameTick();
    }, 100);
    // Logic for running analysis
  } else if (values.timeSessionStarted > 0) {
    setValue('timeElapsed', timeElapsed());
    setValue('timeSessionStarted', 0);
  }
};

export const startLevel = () => {
  const { values } = store.getState().location.list.library;
  if (values.analyzeStatus !== 'initialized') {
    return false;
  }
  const costHandler = getCostHandler();
  if (!costHandler.canPayCosts()) {
    return false;
  }
  costHandler.payAllCosts();

  setValue('currentLevel', values.currentLevel + 1);
  setValue('analyzeStatus', 'running');
  setValue('timeSessionStarted', Date.now());
  setValue('gridPops', {});
  setValue('gridTouches', {});
  setValue('currentBrick', {
    ...values.currentBrick,
    lastTickTime: Date.now(),
  });

  // start gameTick
  window.setTimeout(() => {
    gameTick();
  }, 100);
};

export const resumeGame = () => {
  window.setTimeout(() => {
    gameTick();
  }, 100);
};

const endGame = () => {
  const { values } = store.getState().location.list.library;
  if (values.analyzeStatus !== 'running') {
    return;
  }
  setGridTouches();
  if (values.score >= values.requiredScore) {
    setValue('analyzeStatus', 'won');
    addAttribute('attrInt', attributeAdded(values.currentLevel), 'analyzing');
    addResource('coins', values.score);
  } else {
    setValue('analyzeStatus', 'failed');
  }
};

export const attributeAdded = (level: number) => {
  return Math.ceil(level / 10);
}

const getNextBrick = () => {
  const { values } = store.getState().location.list.library;
  if (values.bricks.length === 0 || currentIsOutOfBounds()) {
    endGame();
    return null;
  }

  const newBricks = structuredClone(values.bricks);
  const nextBrick = newBricks.shift();
  setValue('bricks', newBricks);

  const newBrick = structuredClone(nextBrick);
  // find the last level that has speed defined
  let speed = defaultSpeed;
  Object.keys(levels).forEach((level) => {
    if (level > values.currentLevel) return;
    if (levels[level].speed) {
      speed = levels[level].speed;
    }
  });

  const currentBrick = {
    resources: newBrick,
    x: 2,
    y: 0,
    x2: 2,
    y2: -1,
    tempY: 0,
    rotation: 0,
    speed,
    status: 'falling',
    lastTickTime: Date.now(),
  };

  setValue('currentBrick', currentBrick);
  return currentBrick;
};

// Updated function to check if game should end
const currentIsOutOfBounds = () => {
  const { values } = store.getState().location.list.library;
  const { grid, currentBrick } = values;

  // 1. Check if the current brick has parts outside the visible area
  if (currentBrick.y2 < 0 || currentBrick.y < 0) {
    return true;
  }

  // 2. Check if the spawn position is already occupied
  // This checks if the standard spawn position (y=0, x=2) is blocked
  if (grid[0] && grid[0][2] !== null) {
    return true;
  }

  return false;
};

export const rotate = () => {
  const { values } = store.getState().location.list.library;
  const { currentBrick } = values;
  const { x, y, rotation } = currentBrick;

  playSfx('rotate');

  // Create a clean grid for collision detection
  const grid = structuredClone(values.grid);

  // Clear current brick positions for collision checking
  if (
    currentBrick.y >= 0 &&
    grid[currentBrick.y] &&
    grid[currentBrick.y][currentBrick.x] !== null
  ) {
    grid[currentBrick.y][currentBrick.x] = null;
  }
  if (
    currentBrick.y2 >= 0 &&
    grid[currentBrick.y2] &&
    grid[currentBrick.y2][currentBrick.x2] !== null
  ) {
    grid[currentBrick.y2][currentBrick.x2] = null;
  }

  // Calculate new rotation (clockwise: 0→1→2→3→0)
  const newRotation = (rotation + 1) % 4;

  // Calculate new position for extra brick based on rotation
  let newX2, newY2;

  // Starting from x,y (central block), position the extra brick:
  switch (newRotation) {
    case 0: // Extra brick above the central block
      newX2 = x;
      newY2 = y - 1;
      break;
    case 1: // Extra brick to the right of central block
      newX2 = x + 1;
      newY2 = y;
      break;
    case 2: // Extra brick below the central block
      newX2 = x;
      newY2 = y + 1;
      break;
    case 3: // Extra brick to the left of central block
      newX2 = x - 1;
      newY2 = y;
      break;
  }

  // Check if the new position is valid (inside grid and not occupied)
  let canRotate = true;
  let xOffset = 0;
  let yOffset = 0;

  // Check if new position is valid
  const isPositionValid = (testX: number, testY: number): boolean => {
    return (
      testX >= 0 &&
      testX < gridWidth &&
      testY >= 0 &&
      testY < gridHeight &&
      (!grid[testY] || grid[testY][testX] === null)
    );
  };

  // First check if we're in bounds and the position is empty
  if (!isPositionValid(newX2, newY2)) {
    canRotate = false;

    // Handle wall kicks for rotations 1 and 3
    if (newRotation === 1) {
      // Trying to rotate to position 1 (second block to the right)
      if (newX2 >= gridWidth || (grid[newY2] && grid[newY2][newX2] !== null)) {
        // If we're at the right edge or the position is occupied,
        // try moving the whole brick one space to the left
        xOffset = -1;

        // Check if moving left is valid for both blocks
        if (
          x - 1 >= 0 &&
          isPositionValid(x - 1, y) &&
          isPositionValid(newX2 - 1, newY2)
        ) {
          canRotate = true;
        }
      }
    } else if (newRotation === 3) {
      // Trying to rotate to position 3 (second block to the left)
      if (newX2 < 0 || (grid[newY2] && grid[newY2][newX2] !== null)) {
        // If we're at the left edge or the position is occupied,
        // try moving the whole brick one space to the right
        xOffset = 1;

        // Check if moving right is valid for both blocks
        if (
          x + 1 < gridWidth &&
          isPositionValid(x + 1, y) &&
          isPositionValid(newX2 + 1, newY2)
        ) {
          canRotate = true;
        }
      }
    } else if (newRotation === 2 && newY2 >= gridHeight) {
      // For rotation 2, if extra brick would be below grid, move up
      yOffset = -1;
      if (isPositionValid(x, y - 1) && isPositionValid(newX2, newY2 - 1)) {
        canRotate = true;
      }
    } else if (newRotation === 0 && newY2 < 0) {
      // For rotation 0, if extra brick would be above grid, move down
      yOffset = 1;
      if (isPositionValid(x, y + 1) && isPositionValid(newX2, newY2 + 1)) {
        canRotate = true;
      }
    }

    // If still can't rotate, try alternative positions
    if (!canRotate) {
      // For horizontal orientations, try vertical placement
      if (newRotation === 1 || newRotation === 3) {
        // Try vertical placement above or below
        xOffset = 0;
        newX2 = x;
        newY2 = newRotation === 1 ? y - 1 : y + 1; // Try above for rotation 1, below for rotation 3

        if (isPositionValid(newX2, newY2)) {
          canRotate = true;
        } else {
          // Try the opposite vertical direction
          newY2 = newRotation === 1 ? y + 1 : y - 1;
          if (isPositionValid(newX2, newY2)) {
            canRotate = true;
          }
        }
      } else if (newRotation === 0 || newRotation === 2) {
        // For vertical orientations, try horizontal placement
        newX2 = x + 1; // Try right side first
        newY2 = y;

        if (isPositionValid(newX2, newY2)) {
          canRotate = true;
        } else {
          // Try left side
          newX2 = x - 1;
          if (isPositionValid(newX2, newY2)) {
            canRotate = true;
          }
        }
      }
    }
  }

  // Apply rotation if possible
  if (canRotate) {
    setValue('currentBrick', {
      ...currentBrick,
      rotation: newRotation,
      x: x + xOffset,
      y: y + yOffset,
      x2: newX2 + xOffset,
      y2: newY2 + yOffset,
    });

    updateGridWithCurrentBrick();
  }
};

const tryMove = (direction: 'left' | 'right') => {
  const { values } = store.getState().location.list.library;
  const { currentBrick } = values;
  const xChange = direction === 'left' ? -1 : 1;
  playSfx('move');
  // Calculate new positions after movement
  const newX = currentBrick.x + xChange;
  const newX2 = currentBrick.x2 + xChange;

  // Boundary check
  if (newX < 0 || newX >= gridWidth || newX2 < 0 || newX2 >= gridWidth) {
    return;
  }

  // Create a clean grid for collision detection
  const grid = structuredClone(values.grid);

  // Make sure all grid rows exist
  for (let y = 0; y < gridHeight; y++) {
    if (!grid[y]) {
      grid[y] = Array(gridWidth).fill(null);
    }
  }

  // Clear current brick positions from grid for collision checking
  if (grid[currentBrick.y] && grid[currentBrick.y][currentBrick.x] !== null) {
    grid[currentBrick.y][currentBrick.x] = null;
  }

  if (
    grid[currentBrick.y2] &&
    grid[currentBrick.y2][currentBrick.x2] !== null
  ) {
    grid[currentBrick.y2][currentBrick.x2] = null;
  }

  // Check for collisions at new positions
  let canMove = true;

  // Check first block
  if (
    newX < 0 ||
    newX >= gridWidth ||
    currentBrick.y < 0 ||
    currentBrick.y >= gridHeight ||
    grid[currentBrick.y][newX] !== null
  ) {
    canMove = false;
  }

  // Check second block
  if (
    canMove &&
    (newX2 < 0 ||
      newX2 >= gridWidth ||
      (currentBrick.y2 >= 0 && // Only check grid collision if block is in the grid
        currentBrick.y2 < gridHeight &&
        grid[currentBrick.y2][newX2] !== null))
  ) {
    canMove = false;
  }

  if (!canMove) {
    return;
  }

  // If we get here, it's safe to move
  setValue('currentBrick', {
    ...currentBrick,
    x: newX,
    x2: newX2,
  });

  updateGridWithCurrentBrick();
};

export const moveLeft = () => {
  tryMove('left');
};

export const moveRight = () => {
  tryMove('right');
};

// Add this at the top of your file with other declarations
let dropTimeoutId: number | null = null;

export const drop = () => {
  const { values } = store.getState().location.list.library;

  playSfx('drop');

  // Clear any existing timeout to prevent multiple resets
  if (dropTimeoutId !== null) {
    window.clearTimeout(dropTimeoutId);
    dropTimeoutId = null;
  }

  // First speed increase - create a new object instead of modifying the original
  setValue('currentBrick', {
    ...values.currentBrick,
    speed: (values.currentBrick.speed || defaultSpeed) / 10,
  });

  // Schedule reset of speed after 1 second
  dropTimeoutId = window.setTimeout(() => {
    // Get fresh state to avoid working with stale data
    const currentState = store.getState().location.list.library.values;

    // Create another new object for the speed reset
    setValue('currentBrick', {
      ...currentState.currentBrick,
      speed: levels[currentState.currentLevel]?.speed || defaultSpeed,
    });

    // Reset the timeout ID since it's complete
    dropTimeoutId = null;
  }, 500);
};

export const isCurrentBrick = (i: number, j: number) => {
  const { values } = store.getState().location.list.library;
  const falling = values.currentBrick;
  if (
    !falling ||
    (falling.status !== 'falling' && falling.status !== 'settling')
  ) {
    return false;
  }
  return (
    (falling.x === j && falling.y === i) ||
    (falling.x2 === j && falling.y2 === i)
  );
};

export const touchClasses = (i: number, j: number) => {
  const { values } = store.getState().location.list.library;
  if (isCurrentBrick(i, j)) {
    return '';
  }
  const touchRow = values.gridTouches ? values.gridTouches[i] : null;
  if (!touchRow || !touchRow[j]) return '';
  const touches = values.gridTouches[i]?.[j];
  const classes = [];
  if (touches.topLeft) classes.push('touch-top-left');
  if (touches.topRight) classes.push('touch-top-right');
  if (touches.bottomLeft) classes.push('touch-bottom-left');
  if (touches.bottomRight) classes.push('touch-bottom-right');
  return classes.join(' ') || '';
};

export const blocksLeft = () => {
  const { values } = store.getState().location.list.library;

  // return object with keys of resource and values of how many blocks left
  const blocksLeft: Record<string, number> = {};
  values.bricks.forEach((brick) => {
    // brick is an array of resources, e.g. ['goodIdea', 'badIdea']
    brick.forEach((resource) => {
      if (!blocksLeft[resource]) {
        blocksLeft[resource] = 0;
      }
      blocksLeft[resource] += 1;
    });
  });
  return blocksLeft;
};
