import { store } from '../store';
import { ModelList, ItemList, Item } from '../types';
import dialogue, { Dialogue } from '../conf/dialogueConf';
import icons from '../conf/icons';
import Colors from '../conf/colors';
import CostHandler, { ticketNames, ticketList } from './costHandler';

// icons are in folder ../assets/icons
// import the file and return a reference to it
export const getIcon = (name: string) => {
  return icons[name];
};

export const storeValue: any = (
  type: string,
  name?: string,
  prop?: string,
): any => {
  const state: any = store.getState();
  const typeValue: any = state[type];
  if (name && prop) {
    return typeValue[name][prop];
  }
  if (name) {
    return typeValue[name];
  }
  return typeValue;
};

// changes the number so that there are only placesToKeep numbers that are not zero
export const makeNumCircular = (num: number, placesToKeep: number): number => {
  num = Math.round(num);
  const numberLength = num.toString().length;
  const multiplier = 10 ** Math.round(Math.max(numberLength - placesToKeep, 0));
  const smaller = num / multiplier;
  const rounder = Math.round(smaller);
  const bigger = rounder * multiplier;
  return bigger;
};

export const numberDisplay = (num: number): string => {
  if (num === null || Number.isNaN(num)) return '*ERROR*';
  // show the number with no decimal places. if the number is greater than 10k, show it in scientific notation
  if (Math.abs(num) > 999999) {
    const useScientificNotation = storeValue(
      'settings',
      'useScientificNotation',
    );
    if (useScientificNotation) {
      return num.toExponential(2);
    }
    const suffixes = [
      '',
      'k',
      'M',
      'B',
      'T',
      'Q',
      'QQ',
      'S',
      'SS',
      'O',
      'N',
      'D',
      'UD',
      'DD',
      'TD',
      'QD',
      'QQD',
      'SD',
      'SSD',
      'OD',
      'ND',
      'V',
      'UV',
      'DV',
      'TV',
      'QV',
      'QQV',
      'SV',
      'SSV',
      'OV',
      'NV',
      'T',
    ];

    const suffixNum = Math.min(
      Math.floor(Math.log10(Math.abs(num)) / 3),
      suffixes.length - 1
    );

    let shortValue: any = parseFloat(
      (suffixNum !== 0 ? num / (1000 ** suffixNum) : num).toPrecision(3),
    );

    if (shortValue % 1 !== 0) {
      shortValue = shortValue.toFixed(2);
    }
    return shortValue + suffixes[suffixNum];
  }
  if (Number.isNaN(num)) return '*ERROR*';
  return num ? num.toFixed(0) : 0;
};

export const textDisplay = (text: string): string => {
  const state: any = store.getState();
  // combine state models and attributes into one modelList
  const modelList: ModelList = {
    ...state.resources,
    ...state.attributes,
    ...state.upgrades,
  };
  const { unlocks } = state;
  // loop that modellist
  let outText = text;
  Object.keys(modelList).forEach((key) => {
    const regex = new RegExp(`\\b(${key}::full|${key}::half|${key})\\b`, 'g');
    outText = outText?.replace(regex, (match) => {
      const model = modelList[key];
      let displayText: string;
      if (!unlocks[model.name].isUnlocked) {
        displayText = '???';
      } else if (match.endsWith('::full')) {
        displayText = model.displayName;
      } else if (match.endsWith('::half')) {
        [displayText] = model.displayName.split(' ');
      } else {
        displayText = model.abbreviation || model.displayName;
      }

      const iconStyle =
        model.icon && unlocks[model.name].isUnlocked
          ? `--var-icon-display: inline-block; --var-icon: url('${getIcon(model.icon)}'); `
          : '--var-icon-display: none; ';
      // get the type of the model
      const className = Object.prototype.hasOwnProperty.call(model, 'amount')
        ? 'resource'
        : 'attribute';
      return `<span class="highlighted ${className}" style="--var-color: ${model.color === 'shiny' ? 'white' : model.color}; ${iconStyle}">${displayText}</span>`;
    });
  });

  Object.values(ticketList).forEach((ticket) => {
    const regex = new RegExp(`\\b(ticket_${ticket})(::full)?\\b`, 'g');
    const ticketColors = {
      realization: Colors.yellow,
    };
    const ticketAbbreviations = {
      realization: 'Realztn',
      miningLicense: 'License',
      recommendation: 'Recomm',
      fund: 'Funds',
    };
    outText = outText?.replace(regex, (match, base, fullSuffix) => {
      const ticketName = ticket.substring(0, ticket.length - 1);
      const color = ticketColors[ticketName] || Colors.white;
      let displayText = fullSuffix
        ? ticket
        : ticketAbbreviations[ticketName] || ticket;
      displayText = displayText.replace('ngLi', 'ng Li');

      return `<span class="highlighted resource ticket ${ticketName}" style="--var-color: ${color}; --var-icon-display: inline-block; --var-icon: url('${getIcon(ticketName)}')">${displayText}</span>`;
    });
  });

  // replace text between [[ ]] in displayText with <span class="num">[[text]]</span>
  outText = outText?.replace(/\[\[(.*?)\]\]/g, (match, p1) => {
    const num = numberDisplay(parseFloat(p1));
    return `<span class="num">${num.includes('ERROR') ? p1 : num}</span>`;
  });

  return outText;
};

// does the variable have any unseen children
export const hasUnseen = (varName: string): boolean => {
  const { unlocks } = store.getState();

  // check if item slot has unseen items
  if (varName.startsWith('itemSlot')) {
    const slot = varName.split('::')[1];
    const items = store.getState().items.list;
    if (!items) return false;
    return Object.values(items).some((itemList: ItemList) => {
      return Object.values(itemList).some((item: Item) => {
        return item.slot === slot && !item.isSeen;
      });
    });
  }

  if (varName.endsWith('::activity')) {
    const locationName = varName.split('::')[0];
    const location = store.getState().location.list[locationName];
    const { activities } = location;
    return activities.some((activity: string) => hasUnseen(activity));
  }

  if (varName.endsWith('::upgrade')) {
    const locationName = varName.split('::')[0];
    const location = store.getState().location.list[locationName];
    const { upgrades } = location;
    return upgrades.some((upgrade: string) => hasUnseen(upgrade));
  }

  const unlock = unlocks[varName];
  if (!unlock) return false;
  if (unlock.children) {
    // only check children of skills if they are assigned to skillbar
    if (unlocks.skills.children.includes(varName)) {
      const { skillSlots } = store.getState().game;
      if (Object.values(skillSlots).includes(varName)) {
        return unlock.children.some((child: string) => hasUnseen(child));
      }
    } else {
      return unlock.children.some((child: string) => hasUnseen(child));
    }
  }
  return !unlocks[varName].isSeen && unlocks[varName].isUnlocked;
};

export const startsWithVowel = (word: string): boolean => {
  return ['a', 'e', 'i', 'o', 'u'].includes(word.charAt(0).toLowerCase());
};

export const getDialogue = (
  previousDialogue: String | undefined,
): Dialogue | undefined => {
  const { location } = store.getState();
  const { npc } = location.list[location.current];
  if (npc) {
    const { relationship } = npc;
    const dialogueList = dialogue[npc.name][npc?.dialogue || 'greeting'];
    if (!dialogueList) return undefined;
    // loop over dialogueList and return the last one that has a relationship less than or equal to the current relationship
    let dialogueOptions: any;
    let i = 0;
    Object.keys(dialogueList).forEach((key: string) => {
      // Fix: Change the parameter type to string
      const k = parseInt(key, 10);
      if (k <= relationship || i === 0) {
        dialogueOptions = dialogueList[k];
      }
      i += 1;
    });

    // return a random dialogue from the list
    const dialogueKeys = Object.keys(dialogueOptions);
    const dSize = dialogueKeys.length;
    let newKey;
    let newText;
    [newText] = dialogueOptions;

    // Ensure the loop runs at least once
    do {
      // Select a random key
      newKey = dialogueKeys[Math.floor(Math.random() * dSize)];
      newText = dialogueOptions[newKey];
    } while (newText.text === previousDialogue && dSize > 1);

    return newText;
  }
  // code here
  return undefined;
};

export const getPortrait = (npcName: string, portrait: string): string => {
  // eslint-disable-next-line import/no-dynamic-require, global-require
  if (npcName && portrait)
    return require(`../assets/portrait/${npcName}/${portrait}.png`);
  return '';
};

// convert a string to a very long number. eg 2.3e+7 to 23000000
export const longNumber = (num: string): number => {
  const numArray = num.split('e+');
  return parseFloat(numArray[0]) * 10 ** parseInt(numArray[1], 10);
};

export const startWithVowel = (text: string): boolean => {
  const vowels = ['a', 'e', 'i', 'o', 'u'];
  return vowels.includes(text.charAt(0).toLowerCase());
};

export const displayName = (
  text: string,
  amount: number,
  group: any,
): string => {
  const isTicket = CostHandler.isTicket(text);
  if (isTicket) {
    const ticketName = ticketNames[isTicket.ticketName] || isTicket.ticketName;
    // if amount is 1, remove "s" from the end of the ticket name
    return amount === 1 ? ticketName.slice(0, -1) : ticketName;
  }
  if (group && group[text]) {
    return group[text].displayName;
  }
  return text;
};

export const iconName = (text: string, group: any): string => {
  const isTicket = CostHandler.isTicket(text);
  if (isTicket) {
    return isTicket.ticketName.substring(0, isTicket.ticketName.length - 1);
  }
  if (group && group[text]) {
    return group[text];
  }
  return '';
};
