import { FC } from 'react';
import { useSelector } from 'react-redux';
import type { RootState } from '../../store';
import { store } from '../../store';
import { updateModal } from '../../store/navigationSlice';
import ModalCloseBtn from './modalCloseBtn';
import { setVersionChanged } from '../../store/gameSlice';
import { playSfx } from '../../utils/sound';

const VersionChangeModal: FC<{}> = () => {
  const gameVersion = useSelector((state: RootState) => state.game.version);
  return (
    <div className="modal-content">
      <div className="modal-header">
        <h5 className="modal-title">Game Version Updated</h5>
        <ModalCloseBtn />
      </div>
      <div className="modal-body">
        <p>
          The game has been updated to version{' '}
          <span className="text-shadow">{gameVersion}</span>.
        </p>
        <p>
          If there are any errors, they may be due to the current game data
          being incompatible with the new version.
        </p>
        <p>Restarting the run will reset the data and solve those problems.</p>
      </div>
      <div className="modal-footer">
        <button
          type="button"
          className="btn btn-primary"
          onMouseEnter={() => {
            playSfx('hover');
          }}
          onClick={() => {
            playSfx('click');
            store.dispatch(setVersionChanged(false));
            store.dispatch(
              updateModal({
                value: { show: false, type: '' },
              }),
            );
          }}
        >
          Continue
        </button>
      </div>
    </div>
  );
};
export default VersionChangeModal;
