import { store } from '../store';
import { storeValue } from '../utils';
import {
  Upgrade,
  Attribute,
  Skill,
  Resource,
  AddModifier,
  ModConf,
} from '../types';
import { updateFeatureValue, updateNpc } from '../store/locationSlice';
import { updateUpgrade } from '../store/upgradeSlice';
import { updateResource } from '../store/resourceSlice';
import balance from './balanceConf';
import {
  unlockItem,
  setResourceValue,
  getNpc,
  npcInteraction,
  addTokens,
  addResource,
  createItem,
  getRewardAmount,
  addTickets,
  addAcquiredResources,
} from '../utils/gameUtil';
import { getBalanceModded } from '../utils/modUtil';
import { addSkillSlot } from '../store/gameSlice';
import { ideaList, IdeaInfo } from './inc/ideaConf';
import { startAnimation } from '../store/animationSlice';
import Colors from './colors';
import { generateQuests } from '../utils/location/questsUtil';
import { pickEncounter, dropLoot } from '../utils/location/fighting';

// has optional argument data
interface clickMod {
  [key: string]: (data?: any) => void;
}

const modsList: clickMod = {
  chatResult: () => {
    const currentLocation = storeValue('location', 'current');
    const unlocks = storeValue('unlocks');
    let dialogue = 'chat';

    const { upgrades } = store.getState();

    let totalAllChats = 0;
    Object.keys(upgrades).forEach((upgrade) => {
      if (upgrade.includes('Chat')) {
        totalAllChats += upgrades[upgrade].amount;
      }
    });

    let additionalRelationship = 0;

    if (!totalAllChats) {
      additionalRelationship += getBalanceModded('firstChatRelationship');
    }

    switch (currentLocation) {
      case 'townHall':
        if (!unlocks.quests.isUnlocked) {
          unlockItem('quests');
          dialogue = 'introduction';
        }
        break;
      case 'market':
        if (!unlocks.trade.isUnlocked) {
          unlockItem('trade');
          dialogue = 'introduction';
        }
        break;
      case 'mines':
        if (!unlocks.mining.isUnlocked) {
          unlockItem('mining');
          dialogue = 'introduction';
        }
        break;
      case 'forest':
        if (!unlocks.fighting.isUnlocked) {
          unlockItem('fighting');
          dialogue = 'introduction';
        }
        break;
      case 'temple':
        if (!unlocks.realize.isUnlocked) {
          unlockItem('realize');
          dialogue = 'introduction';
        }
        break;
      case 'library':
        if (!unlocks.getRecommendation.isUnlocked) {
          unlockItem('getRecommendation');
          dialogue = 'introduction';
        }
        break;
      case 'smithy':
        if (!unlocks.crafting.isUnlocked) {
          unlockItem('crafting');
          dialogue = 'introduction';
        }
        break;
      default:
        break;
    }
    npcInteraction(
      dialogue,
      getBalanceModded('chatRelationship') + additionalRelationship,
    );
  },
  hangOutResult: (data) => {
    const currentLocation = storeValue('location', 'current');
    const unlocks = storeValue('unlocks');
    const upgrades = storeValue('upgrades');
    const dialogue = 'hangOut';
    data.upgradeName = `${currentLocation}HangOut`;
    data.key = `upgrade-acquired-${data.upgradeName}`;
    switch (currentLocation) {
      case 'townHall':
        // TODO
        break;
      case 'market':
        addResource('coins', balance.hangOut.marketReward);
        break;
      case 'mines':
        addResource('diamond', 1);
        break;
      case 'forest':
        const level = storeValue('location', 'list').forest.values.currentLevel;
        const useLevel = Math.floor(Math.random() * (level + 3));
        const encounter = pickEncounter(useLevel || 1);
        dropLoot(encounter, data.setAcquiredResources, data.key);
        break;
      case 'library':
        data.upgrade = upgrades.readBook;
        data.isMagical = true;
        modsList.readBookResult(data);
        break;
      case 'smithy':
        addResource('gold', 2);
        break;
      case 'temple':
        const resource = storeValue('resources', 'focus') as Resource;
        const mods = structuredClone(resource.mods);
        // if there is not mod with modName 'hangOutMaxFocus' add it
        // TODO: this is not required in final version. only for compatibility
        if (!mods.some((mod) => mod.modName === 'hangOutMaxFocus')) {
          mods.push({
            modName: 'hangOutMaxFocus',

            priority: 0,
            modProperty: 'currentCap',
          } as ModConf);
          store.dispatch(
            updateResource({
              resource: 'focus',
              property: 'mods',
              value: mods,
            }),
          );
        }
      default:
        break;
    }
    npcInteraction(dialogue, balance.hangOutRelationship);
  },
  flirtResult: () => {
    const newDialogue = 'flirt';
    const npc = getNpc();
    const location = storeValue('location', 'current');
    const { flirtDays } = npc;
    const currentDay = store.getState().game.day;

    // if flirtDays is not set or the array does not contain the current day, then add it
    if (!flirtDays || !flirtDays.includes(currentDay)) {
      npc.flirtDays = [...(flirtDays || []), currentDay];
      store.dispatch(updateNpc({ location, npc }));
    }
    npcInteraction(newDialogue, balance.flirtRelationship);
  },

  engagementRingResult: () => {
    createItem('engagementRing');
    npcInteraction('engagementRing', balance.interactionRelationship);
  },

  proposeResult: () => {
    const location = storeValue('location', 'current');
    switch (location) {
      case 'market':
        addResource('coins', balance.propose.marketReward);
        break;
      case 'townHall':
        addTickets('ticket_funds', balance.propose.townHallReward);
        break;
      case 'temple':
        addTickets('ticket_realizations', balance.propose.templeReward);
        break;
      case 'library':
        addTickets('ticket_recommendations', balance.propose.libraryReward);
        break;
      case 'forest':
        break;
      case 'mines':
        addTickets('ticket_miningLicenses', balance.propose.minesReward);
        break;
      case 'smithy':
        break;
      default:
        break;
    }
    npcInteraction('propose', balance.proposeRelationship);
  },

  // home
  carvePotatoesResult: () => {
    createItem('potato');
  },
  makePaperResult: () => {
    const upgrade = storeValue('upgrades', 'makePaper') as Upgrade;
    addResource('paper', upgrade.currentPower);
  },
  specializeResult: () => {
    store.dispatch(addSkillSlot('specialize'));
  },
  luckIsSkillResult: () => {
    store.dispatch(addSkillSlot('luckIsSkill'));
  },
  togglePaperMakerResult: () => {
    const upgrade = storeValue('upgrades', 'togglePaperMaker') as Upgrade;
    const isOn = upgrade.amount % 2 === 0;
    const description = !isOn
      ? 'The paper maker is currently running. Click to stop it'
      : 'The paper maker is currently stopped. Click to start it';
    const color = !isOn ? Colors.green : Colors.red;
    store.dispatch(
      updateUpgrade({
        upgrade: 'togglePaperMaker',
        property: 'currentDescription',
        value: description,
      }),
    );
    store.dispatch(
      updateUpgrade({
        upgrade: 'togglePaperMaker',
        property: 'currentColor',
        value: color,
      }),
    );

    const wood = storeValue('resources', 'wood') as Resource;
    const newMods = structuredClone(wood.mods);
    if (newMods) {
      const modIndex = newMods.findIndex(
        (mod) =>
          mod.data?.convertTo === 'paper' &&
          mod.data?.upgrade === 'buyPaperMaker',
      );
      if (modIndex !== -1) {
        if (newMods[modIndex].data) {
          newMods[modIndex].data.isEnabled = !isOn;
        }
        store.dispatch(
          updateResource({
            resource: 'wood',
            property: 'mods',
            value: newMods,
          }),
        );
      }
    }
  },

  // market
  powerTraderResult: () => {
    const previousValue = storeValue('location', 'list').market.values
      ?.priceMultiplier;
    store.dispatch(
      updateFeatureValue({
        location: 'market',
        property: 'priceMultiplier',
        value: 2 * previousValue,
      }),
    );
  },

  // town hall
  drawWaterResult: () => {
    const upgrade = storeValue('upgrades', 'drawWater') as Upgrade;
    const amount = getRewardAmount(
      store.getState().resources.water,
      upgrade.power,
    );
    addResource('water', amount);
    if (upgrade.amount >= upgrade.limit) {
      store.dispatch(
        updateUpgrade({
          upgrade: 'drawWater',
          property: 'currentDescription',
          value: 'The well has run out of water.',
        }),
      );
    }
  },

  getQuestsResult: () => {
    generateQuests();
    npcInteraction('quest', balance.upgrades.townHall.getQuestsRelationship);
  },

  negotiateFundsResult: () => {
    const upgrade = storeValue('upgrades', 'negotiateFunds') as Upgrade;
    const { funds } = storeValue('location', 'list').townHall.values;
    const amount = upgrade.currentPower;
    const newFunds = funds + amount;
    store.dispatch(
      updateFeatureValue({
        location: 'townHall',
        property: 'funds',
        value: newFunds,
      }),
    );
    npcInteraction('negotiateFunds', balance.interactionRelationship);
  },

  forgeryResult: () => {
    const skill = storeValue('skills', 'forgery') as Skill;
    let numMiningLicenses = storeValue('location', 'list').mines.values
      .miningLicenses;

    const licensesToAdd = skill.currentPower;
    numMiningLicenses += licensesToAdd;
    store.dispatch(
      updateFeatureValue({
        location: 'mines',
        property: 'miningLicenses',
        value: numMiningLicenses,
      }),
    );
  },

  // temple
  healServiceResult: () => {
    const upgrade = storeValue('upgrades', 'healService') as Upgrade;
    const health = storeValue('resources', 'healthPoints') as Resource;
    const power = upgrade.currentPower;
    const newHealth = health.amount + power;
    setResourceValue('healthPoints', newHealth);
    npcInteraction('heal', balance.upgrades.temple.healRelationship);
  },

  attendSessionResult: (data) => {
    const upgrade = storeValue('upgrades', 'attendSession') as Upgrade;
    const { temple } = storeValue('location', 'list');
    let { realizations } = temple.values;
    const { setAcquiredResources } = data;

    let added = upgrade.currentPower;
    let dialogue = 'attendSession';
    if (upgrade.amount === 0) {
      added += 9;
      dialogue = 'firstRealization';
    }

    realizations += added;

    npcInteraction(
      dialogue,
      Math.round(
        temple.npc.relationship *
          balance.upgrades.temple.attendSessionRelationship,
      ),
    );
    store.dispatch(
      updateFeatureValue({
        location: 'temple',
        property: 'realizations',
        value: realizations,
      }),
    );
    addAcquiredResources(
      'upgrade-acquired-attendSession',
      setAcquiredResources,
      [
        {
          resource: 'ticket_realizations',
          amount: added,
        },
      ],
    );
  },

  // library
  getRecommendationResult: (data) => {
    const upgrade = storeValue('upgrades', 'getRecommendation') as Upgrade;
    const { setAcquiredResources } = data;
    addTokens('library', 'recommendations', upgrade.power);
    npcInteraction(
      'recommendation',
      balance.upgrades.library.recommendationRelationship,
    );
    addAcquiredResources(
      'upgrade-acquired-getRecommendation',
      setAcquiredResources,
      [
        {
          resource: 'ticket_recommendations',
          amount: upgrade.power,
        },
      ],
    );
  },

  readBookResult: (data) => {
    const { upgrade } = data;
    const { setAcquiredResources } = data;
    const power = upgrade.currentPower;

    // Configure the threshold where we switch to the approximation method
    const POWER_THRESHOLD = 1000; // Adjust based on performance testing

    // Get the weighted idea list
    const weightPool = structuredClone(ideaList);
    weightPool.forEach((idea) => {
      idea.weight = getBalanceModded(`reading.${idea.name}IdeaWeight`);
      if (upgrade.name.includes(idea.displayName)) {
        idea.weight *= 5;
      }
      if (data.isMagical && idea.name === 'magical') {
        idea.weight *= 3;
      }
    });

    const loot: { [key: string]: number } = {};

    // Calculate total weight once
    const totalWeight = weightPool.reduce((sum, idea) => sum + idea.weight, 0);

    // APPROACH 1: Exact method for reasonable numbers
    if (power <= POWER_THRESHOLD) {
      // Existing implementation for small numbers
      for (let i = 0; i < power; i += 1) {
        const random = Math.random() * totalWeight;
        let currentWeight = 0;
        let chosenIdea: IdeaInfo | null = null;

        chosenIdea =
          weightPool.find((idea) => {
            currentWeight += idea.weight;
            return random < currentWeight;
          }) ?? null;

        if (chosenIdea !== null) {
          loot[chosenIdea.name] = (loot[chosenIdea.name] || 0) + 1;
        }
      }
    } else {
      const sortedIdeas = [...weightPool].sort((a, b) => a.weight - b.weight);
      sortedIdeas.forEach((idea) => {
        const expectedAmount = Math.floor((idea.weight / totalWeight) * power);
        const randomnessFactor = 1 + (Math.random() * 0.5 - 0.25);
        const finalAmount = Math.round(expectedAmount * randomnessFactor);
        loot[idea.name] = finalAmount;
      });
      const totalAllocated = Object.values(loot).reduce(
        (sum, val) => sum + val,
        0,
      );
      if (totalAllocated !== power) {
        const largestKey = Object.keys(loot).reduce((a, b) =>
          loot[a] > loot[b] ? a : b,
        );
        loot[largestKey] += power - totalAllocated;
      }
    }
    const key = data.key ? data.key : `upgrade-acquired-${upgrade.name}`;
    const addedResources = [];
    Object.entries(loot).forEach(([idea, amount]) => {
      addResource(`${idea}Idea`, amount);
      addedResources.push({ resource: `${idea}Idea`, amount });
    });
    addAcquiredResources(key, setAcquiredResources, addedResources);
  },

  // mines
  miningLicenseResult: (data) => {
    const { setAcquiredResources } = data;
    const upgrade = storeValue('upgrades', 'miningLicense') as Upgrade;
    let numMiningLicenses = storeValue('location', 'list').mines.values
      .miningLicenses;

    let licensesToAdd = upgrade.currentPower;
    let dialogue = 'license';
    if (upgrade.amount === 0) {
      licensesToAdd += 9;
      dialogue = 'firstLicense';
    }
    numMiningLicenses += licensesToAdd;

    store.dispatch(
      updateFeatureValue({
        location: 'mines',
        property: 'miningLicenses',
        value: numMiningLicenses,
      }),
    );
    npcInteraction(dialogue, balance.upgrades.mines.licenseRelationship);
    const key = `upgrade-acquired-${upgrade.name}`;
    addAcquiredResources(key, setAcquiredResources, [
      {
        resource: 'ticket_miningLicenses',
        amount: licensesToAdd,
      },
    ]);
  },
  addMinerResource: (data) => {
    const { upgrade } = data;
    const hireMiner = storeValue('upgrades', 'hireMiner') as Upgrade;
    const addMods = structuredClone(hireMiner.addMods);
    let resourceName = 'iron';
    switch (upgrade.name) {
      case 'minerMithril':
        resourceName = 'mithril';
        break;
      case 'minerTitanium':
        resourceName = 'titanium';
        break;
      default:
        break;
    }
    addMods?.push({
      modObjectType: 'Resource',
      modObjectName: resourceName,
      modProperty: 'gps',
      modName: upgrade.name,
      description: `+powAmount ${resourceName}/s`,
      priority: 0,
    } as AddModifier);
    store.dispatch(
      updateUpgrade({
        upgrade: 'hireMiner',
        property: 'addMods',
        value: addMods,
      }),
    );
  },

  // forest
  chopWoodResult: () => {
    const upgrade = storeValue('upgrades', 'chopWood') as Upgrade;
    addResource(
      'wood',
      getRewardAmount(
        store.getState().resources.wood,
        store.getState().upgrades.chopWood.currentPower,
      ),
    );
    if (upgrade.amount >= upgrade.limit) {
      store.dispatch(
        updateUpgrade({
          upgrade: 'chopWood',
          property: 'currentDescription',
          value: 'All the nearby trees have been cleared.',
        }),
      );
    }
  },

  // days
  choiceResourceResult: (data) => {
    const { resource } = data.data;
    const { value } = data;
    addResource(resource, value);
  },

  drinkResult: (setAcquiredResources) => {
    const { resources } = store.getState();
    // find all with type potion and amount > 0
    const potions = Object.keys(resources).filter((key) => {
      const resource = resources[key];
      return resource.type === 'potion' && resource.amount > 0;
    });

    let potionUsed: {
      potion: string;
      resource: string;
      amount: number;
    } | null = null;

    // if no potions return
    if (potions.length > 0) {
      ['health', 'mana'].forEach((resource) => {
        const havePotion = potions.find((potion) => {
          return potion === `${resource}Potion`;
        });
        if (havePotion) {
          const resourceName = resource === 'mana' ? 'mana' : 'healthPoints';
          const resourceAmount = resources[resourceName].amount;
          const resourceCap = resources[resourceName].currentCap;
          const isLessThanHalf = resourceAmount < resourceCap / 1.4;
          if (isLessThanHalf) {
            potionUsed = usePotion(`${resource}Potion`);
          }
        }
      });

      if (!potionUsed) {
        // loop over potions and use the first one applicable
        potions.forEach((potion) => {
          switch (potion) {
            case 'energyDrink':
              if (resources.focus.amount < resources.focus.currentCap / 2) {
                potionUsed = usePotion(potion);
              }
              break;
            case 'staminaPotion':
              if (
                resources.physicalEnergy.amount <
                resources.physicalEnergy.currentCap / 2
              ) {
                potionUsed = usePotion(potion);
              }
              break;
            case 'strengthPotion':
              potionUsed = usePotion(potion);
              break;
            case 'defensePotion':
              potionUsed = usePotion(potion);
              break;
            default:
              break;
          }
        });
      }
    }
    addAcquiredResources('skill-acquired-drink', setAcquiredResources, [
      potionUsed
        ? {
            resource: potionUsed.potion,
            amount: 1,
          }
        : {
            resource: 'potions',
            amount: 0,
          },
    ]);
  },
  alchemyResult: (setAcquiredResources) => {
    // pick a resource at random where amount > 0
    const { resources } = store.getState();
    const skill = store.getState().skills.alchemy;
    const unlockedTier = skill.currentPower;
    const materialResources = Object.keys(resources).filter((key) => {
      const resource = resources[key];
      return (
        resource.type === 'material' &&
        resource.amount > 0 &&
        resource.tier <= unlockedTier
      );
    });

    if (materialResources.length === 0) {
      return null;
    }
    const minimumAmount = getBalanceModded('alchemyMinimumAmount');
    const randomResource =
      materialResources[Math.floor(Math.random() * materialResources.length)];
    const resourceAmount = Math.round(resources[randomResource].amount);

    // conversion rate is sellPrice multiplied by up to 2 randomly
    const { sellPrice } = resources[randomResource];
    const coins = Math.ceil(
      Math.random() * minimumAmount +
        resourceAmount * sellPrice * (1 + Math.random()),
    );
    addResource('coins', coins);

    // set the used resource amount to 0
    store.dispatch(
      updateResource({
        resource: randomResource,
        property: 'amount',
        value: 0,
      }),
    );

    setAcquiredResources({
      'skill-acquired-alchemy': [
        {
          resource: randomResource,
          amount: Math.round(resourceAmount * -1),
        },
        {
          resource: 'coins',
          amount: coins,
        },
      ],
    });
  },
  fireballResult: (setAcquiredResources) => {
    addAcquiredResources('skill-acquired-fireball', setAcquiredResources, [
      {
        resource: 'Nothing happened',
        amount: null,
      },
    ]);
  },

  identifyResult: (setAcquiredResources) => {
    const ideas = ideaList;

    const oddsMultiplier = getBalanceModded('identifyOddsMultiplier');
    // multiply the weight for each other than the first one (most common) with the multiplier
    ideas.forEach((idea, index) => {
      if (index > 0) {
        idea.weight *= oddsMultiplier;
      }
    });

    // choose an idea according to their weight
    const totalWeight = ideas.reduce((sum, idea) => sum + idea.weight, 0);
    const random = Math.random() * totalWeight;
    let cumulativeWeight = 0;
    const chosenIdea =
      ideas.find((idea) => {
        cumulativeWeight += idea.weight;
        return random < cumulativeWeight;
      }) || ideas[0];
    const skill = storeValue('skills', 'identify') as Skill;
    const power = skill.currentPower;

    // at least half of power, up to power
    const amountGiven = Math.min(Math.max(Math.floor(power / 2), 1), power);

    // divide it according to the idea's weight
    const { weight } = chosenIdea;
    const weightedAmount = Math.round((amountGiven * weight * 2) / totalWeight);
    // at least 1
    let finalAmount = Math.max(weightedAmount, 1);
    // up to power
    finalAmount = Math.min(finalAmount, power);

    addResource(`${chosenIdea.name}Idea`, finalAmount);
    setAcquiredResources({
      'skill-acquired-identify': [
        {
          resource: `${chosenIdea.name}Idea`,
          amount: finalAmount,
        },
      ],
    });
  },

  conjureResult: (setAcquiredResources) => {
    const skill = storeValue('skills', 'conjure') as Skill;
    const power = skill.currentPower;
    const maxTier = getBalanceModded('conjureUnlockedTier');

    const resourceKeys = Object.keys(storeValue('resources')).filter((key) => {
      const resource = storeValue('resources', key);
      return (
        resource.type === 'material' &&
        resource.tier <= maxTier &&
        !resource.limited
      );
    });

    const randomResourceKey =
      resourceKeys[Math.floor(Math.random() * resourceKeys.length)];
    const randomResource = storeValue('resources', randomResourceKey);

    const amountBase = Math.max(5, power / 1000 ** (randomResource.tier - 1));
    const amountToGive = Math.ceil(amountBase * Math.random());

    addResource(randomResourceKey, amountToGive);

    setAcquiredResources({
      'skill-acquired-conjure': [
        {
          resource: randomResourceKey,
          amount: amountToGive,
        },
      ],
    });
  },
  materializeResult: (setAcquiredResources) => {
    const skill = storeValue('skills', 'materialize') as Skill;
    const maxTier = skill.currentPower;
    const spiritualResources = Object.keys(storeValue('resources')).filter(
      (key) => {
        const resource = storeValue('resources', key);
        return (
          resource.type === 'spiritual' &&
          resource.tier <= maxTier &&
          resource.amount > 0 &&
          !resource.limited
        );
      },
    );
    if (spiritualResources.length === 0) {
      setAcquiredResources({
        'skill-acquired-materialize': [
          {
            text: 'resources available',
            amount: 0,
          },
        ],
      });
      return;
    }
    const materialResources = Object.keys(storeValue('resources')).filter(
      (key) => {
        const resource = storeValue('resources', key);
        return (
          resource.type === 'material' &&
          resource.tier <= maxTier &&
          !resource.limited
        );
      },
    );
    const resourceToTake =
      spiritualResources[Math.floor(Math.random() * spiritualResources.length)];
    const takenResource = storeValue('resources', resourceToTake);
    const resourceToGive =
      materialResources[Math.floor(Math.random() * materialResources.length)];
    const amount = Math.ceil(takenResource.amount / 2);

    addResource(resourceToGive, amount);
    store.dispatch(
      updateResource({
        resource: resourceToTake,
        property: 'amount',
        value: takenResource.amount - amount,
      }),
    );

    setAcquiredResources({
      'skill-acquired-materialize': [
        {
          resource: resourceToTake,
          amount: -amount,
        },
        {
          resource: resourceToGive,
          amount,
        },
      ],
    });
  },
};

const usePotion = (
  potion: string,
): { potion: string; resource: string; amount: number } => {
  const resources = storeValue('resources');
  const resource = resources[potion];
  const skill = storeValue('skills', 'drink') as Skill;
  let targetResource = '';
  let amount = 0;
  if (resource && resource.amount > 0) {
    const newAmount = resource.amount - 1;
    store.dispatch(
      updateResource({
        resource: potion,
        property: 'amount',
        value: newAmount,
      }),
    );

    switch (potion) {
      case 'healthPotion':
        targetResource = 'healthPoints';
        break;
      case 'manaPotion':
        targetResource = 'mana';
        break;
      case 'energyDrink':
        targetResource = 'focus';
        break;
      case 'staminaPotion':
        targetResource = 'physicalEnergy';
        break;
      default:
        break;
    }
    if (targetResource) {
      amount = Math.round(
        (resources[targetResource].currentCap * (skill.currentPower || 0)) /
          100,
      );
      addResource(targetResource, amount);
    }
  }
  return {
    potion,
    resource: targetResource,
    amount,
  };
};

export default modsList;
