import { store } from '../store';
import { updateResource } from '../store/resourceSlice';
import { updateModal, confirmModal } from '../store/navigationSlice';
import {
  setDayStarted,
  setDayAction,
  setSelectedChoice,
  setActionChoice,
} from '../store/gameSlice';
import { unlockAchievement, unlockItem } from '../utils/gameUtil';
import { updateAllCurrent } from '../utils/gameState';
import { insertAddMod } from '../utils/modUtil';
import days, { rentCost } from './dayConf';
import choices from './choicesConf';
import { AddModifier } from '../types';
import clickMods from './clickModConf';
interface DayActions {
  [key: string]: (dayNum: number, actionType: string) => void;
}

export const gameOverAction = () => {
  unlockItem('lostGame');
  store.dispatch(
    updateModal({
      value: {
        type: 'gameOver',
        show: true,
        uncloseable: true,
      },
    }),
  );
};

const actionResult = (action: string) => {
  store.dispatch(setDayAction(action));
  store.dispatch(
    updateModal({
      value: {
        type: 'actionResult',
        show: true,
        uncloseable: false,
      },
    }),
  );
};

const commonActions = (action: string) => {
  store.dispatch(
    updateModal({
      value: { show: false, type: '' },
    }),
  );
  store.dispatch(setDayStarted(true));
  if (action !== 'choice') {
    actionResult(action);
  }

  const currentDay = store.getState().game.day;
  const currentAction = days[currentDay].eventActions?.find(
    (act) => act.type === action,
  );
  const newAchievement = currentAction?.achievement;
  if (newAchievement) unlockItem(newAchievement);
  updateAllCurrent();
};

const fightAction = (dayNum: number, action: string) => {
  unlockItem('healthPoints');
  store.dispatch(setActionChoice(action));
  store.dispatch(
    confirmModal({
      value: { show: true, type: 'fight', unclosable: true },
    }),
  );
};

export default {
  payRent: (dayNum, action) => {
    store.dispatch(
      updateResource({
        resource: 'coins',
        property: 'amount',
        value: store.getState().resources.coins.amount - rentCost,
      }),
    );
    unlockAchievement('rentPaid');
    commonActions(action);
  },

  gameOver: (dayNum, action) => {
    // get action which type is action
    const currentAction = days[dayNum].eventActions?.find(
      (act) => act.type === action,
    );
    const newAchievement = currentAction?.achievement;
    if (newAchievement) unlockAchievement(newAchievement);
    gameOverAction();
  },
  choose: (dayNum, choice) => {
    const currentChoice = choices[choice];
    const currentChoices = store.getState().game.choices[dayNum];
    const currentChoiceData = currentChoices.find((c) => c.name === choice);
    currentChoice.addMods.forEach((mod: AddModifier) => {
      mod.data = { ...mod.data, value: currentChoiceData?.value || 0 };
      insertAddMod(mod);
    });
    const choiceClickMods = currentChoice.clickMods;
    choiceClickMods?.forEach((modName: string) => {
      const mod = clickMods[modName];
      const data = {
        value: currentChoiceData?.value || 0,
        data: choices[choice].data,
      };
      mod(data);
    });

    store.dispatch(setSelectedChoice(choice));
    commonActions('choice');
    setTimeout(() => {
      updateAllCurrent();
    }, 500);
  },
  understandRobbers: (dayNum, action) => {
    commonActions(action);
  },
  talkRobbers: (dayNum, action) => {
    commonActions(action);
  },
  fightRobbers: (dayNum, action) => {
    fightAction(dayNum, action);
  },
  leadHunt: (dayNum, action) => {
    commonActions(action);
  },
  explodeHunt: (dayNum, action) => {
    commonActions(action);
  },
  fightHunt: (dayNum, action) => {
    commonActions(action);
  },
  avoidAssassin: (dayNum, action) => {
    commonActions(action);
  },
  escapeAssassin: (dayNum, action) => {
    commonActions(action);
  },
  fightAssassin: (dayNum, action) => {
    fightAction(dayNum, action);
  },
  spellDuel: (dayNum, action) => {
    commonActions(action);
  },
  swordDuel: (dayNum, action) => {
    commonActions(action);
  },
  focusDuel: (dayNum, action) => {
    commonActions(action);
  },
  fightArmy: (dayNum, action) => {
    fightAction(dayNum, action);
  },
  magicArmy: (dayNum, action) => {
    commonActions(action);
  },
  displaceArmy: (dayNum, action) => {
    commonActions(action);
  },
  fight: (dayNum, action) => {
    commonActions(action);
  },
  tankPlague: (dayNum, action) => {
    commonActions(action);
  },
  purifyPlague: (dayNum, action) => {
    commonActions(action);
  },
  healPlague: (dayNum, action) => {
    commonActions(action);
  },
  charmGeneral: (dayNum, action) => {
    commonActions(action);
  },
  fightGeneral: (dayNum, action) => {
    fightAction(dayNum, action);
  },
  understandGeneral: (dayNum, action) => {
    commonActions(action);
  },
  findCastle: (dayNum, action) => {
    commonActions(action);
  },
  mapCastle: (dayNum, action) => {
    commonActions(action);
  },
  breakCastle: (dayNum, action) => {
    commonActions(action);
  },
  outlastDemonLord: (dayNum, action) => {
    commonActions(action);
  },
  sealDemonLord: (dayNum, action) => {
    commonActions(action);
  },
  ascendDemonLord: (dayNum, action) => {
    commonActions(action);
  },
  fightDemonLord: (dayNum, action) => {
    fightAction(dayNum, action);
  },
} as DayActions;

export { commonActions };
