import { store } from '../../store';
import { updateFeatureValue } from '../../store/locationSlice';
import monsters from '../../conf/monsterConf';
import { updateResource } from '../../store/resourceSlice';
import { playSfx } from '../sound';
import balance from '../../conf/balanceConf';
import { numberDisplay, textDisplay } from '../index';
import {
  addAttribute,
  addResource,
  getRewardAmount,
  unlockItem,
} from '../gameUtil';
import { LootChance } from '../../types';
import { updateAttributes } from '../gameState';
import { getBalanceModded } from '../modUtil';
import CostHandler from '../costHandler';
import { startAnimation } from '../../store/animationSlice';

const encounters = {
  1: ['rat', 'mandrake'],
  2: ['werewolf', 'wasp'],
  3: ['imp', 'slug'],
  4: ['redOgre', 'shade'],
  5: ['yeti', 'golem'],
};

const getTotalCost = (level: number) => {
  const costHandler = new CostHandler();
  costHandler.addExpCost('physicalEnergy', 'fighting', level);
  costHandler.addCost('socialEnergy', balance.fighting.socialEnergyCost);
  return costHandler;
};

const getDepth = (level: number) => {
  return Math.ceil(level / 10);
};

const getButtonCost = (level: number) => {
  const totalCost = getTotalCost(level).getCostList();
  const energyCost = totalCost.physicalEnergy.currentCost;
  const { resources } = store.getState();
  const haveEnoughEnergy = resources.physicalEnergy.amount >= energyCost;
  const haveEnoughSocialEnergy =
    resources.socialEnergy.amount >= totalCost.socialEnergy.currentCost;
  return {
    haveEnough: haveEnoughEnergy && haveEnoughSocialEnergy,
    text: textDisplay(
      `-<span class="num${!haveEnoughSocialEnergy ? ' red' : ''}">20</span>socialEnergy
     -<span class="num${!haveEnoughEnergy ? ' red' : ''}">${numberDisplay(
       energyCost,
     )}</span>physicalEnergy`,
    ),
  };
};

const pickEncounter = (level?: number) => {
  const useLevel =
    level || store.getState().location.list.forest.values.currentLevel;
  const depth = getDepth(useLevel);
  const possibleEncounters = encounters[depth as keyof typeof encounters];
  return possibleEncounters[
    Math.floor(Math.random() * possibleEncounters.length)
  ];
};

const setValue = (property: string, value: any) => {
  store.dispatch(
    updateFeatureValue({
      location: 'forest',
      property,
      value,
    }),
  );
};

const dropLoot = (
  monsterType: string,
  setAcquiredResources: any = null,
  key: string = null,
) => {
  const { resources } = store.getState();
  const { currentLevel } = store.getState().location.list.forest.values;
  const monsterData = monsters[monsterType];

  const lootTable = [...monsterData.loot];
  lootTable.push({ item: 'coins', chance: 1, amount: 1 } as LootChance);
  lootTable.push({ item: 'diamond', chance: 0.01, amount: 1 } as LootChance);
  lootTable.push({ item: 'gold', chance: 0.01, amount: 1 } as LootChance);
  lootTable.push({ item: 'core', chance: 0.01, amount: 1 } as LootChance);

  const droppedLoot: { [key: string]: string } = {};
  const acquiredResources = [];
  lootTable.forEach((item) => {
    const roll = Math.random();
    if (roll <= item.chance) {
      const droppedAmount = getRewardAmount(resources[item.item], currentLevel);
      addResource(item.item, droppedAmount);
      droppedLoot[item.item] = numberDisplay(droppedAmount);
      acquiredResources.push({
        resource: item.item,
        amount: droppedAmount,
      });
    }
  });

  if (setAcquiredResources) {
    setAcquiredResources({ [key]: acquiredResources });
    store.dispatch(
      startAnimation({
        element: key,
        type: 'upgrade-acquired',
        value: 0,
        duration: 3000,
      }),
    );
  }
  return droppedLoot;
};

const resetMonster = (monsterType: string, level?: number) => {
  const monsterData = monsters[monsterType];
  if (!monsterData) {
    return false;
  }
  const currentLevel =
    level || store.getState().location.list.forest.values.currentLevel;
  const b = balance.fighting;
  let monsterHealth =
    b.monsterBaseHealth * b.monsterHealthMultiplier ** currentLevel;
  const healthVariance = b.monsterHealthVariance * monsterHealth;
  const healthChange = Math.floor(
    Math.random() * (healthVariance - -healthVariance) + -healthVariance,
  );
  monsterHealth += healthChange * monsterData.health;
  setValue('monsterHealth', Math.round(monsterHealth));
  setValue('monsterMaxHealth', Math.round(monsterHealth));

  let monsterAttack =
    b.monsterBaseAttack * b.monsterAttackMultiplier ** currentLevel;
  const attackVariance = b.monsterAttackVariance * monsterAttack;
  const attackChange = Math.floor(
    Math.random() * (attackVariance - -attackVariance) + -attackVariance,
  );
  monsterAttack += attackChange * monsterData.attack;
  setValue('monsterAttack', Math.round(monsterAttack));

  setValue('monsterType', monsterType);
  setValue('monsterState', 'idle');
  return true;
};

const getHitDamage = (damageMax: number) => {
  const damageMin = damageMax / 2;
  return Math.floor(Math.random() * (damageMax - damageMin) + damageMin);
};

const getPlayerAttack = () => {
  return getBalanceModded('fighting.playerAttack');
};

const setPlayerHealth = (newHealth: number) => {
  store.dispatch(
    updateResource({
      resource: 'healthPoints',
      property: 'amount',
      value: newHealth,
    }),
  );
};

const unlockNextLevel = (addToLog: any) => {
  const { values } = store.getState().location.list.forest;
  const levelToUnlock = values.currentLevel + 1;
  if (
    levelToUnlock > values.unlockedLevel &&
    levelToUnlock < balance.fighting.maxLevel + 1
  ) {
    setValue('unlockedLevel', levelToUnlock);
    const strToGet = getDepth(levelToUnlock - 1);
    addToLog(
      `You unlocked Forest Depth ${getDepth(levelToUnlock)} (${levelToUnlock}) and gained +${strToGet} STR`,
      true,
    );
    addAttribute('attrStr', strToGet, 'forest');
    updateAttributes();
  }
};

const goToLevel = (level: number, addToLog: any) => {
  setValue('currentLevel', level);
  addToLog(
    `You arrive to Forest Depth ${getDepth(level)} (Level ${level})`,
    true,
  );
  return level;
};

const gotoNextLevel = (addToLog: any) => {
  const { values } = store.getState().location.list.forest;
  const newLevel = values.currentLevel + 1;
  return goToLevel(newLevel, addToLog);
};

const isBattleActive = (addToLog: any, setBattleStarted: any) => {
  if (!store.getState().location.list.forest.values.battleIsActive) {
    setBattleStarted(0);
    addToLog(`You escaped.`, false);
    return false;
  }
  return true;
};

const monsterAttack = (
  addToLog: any,
  setBattleStarted: any,
  ignorePause: boolean = false,
) => {
  const { isPaused } = store.getState().game;
  if (isPaused && !ignorePause) {
    // try again later
    setTimeout(() => {
      monsterAttack(addToLog, setBattleStarted);
    }, 1000);
    return;
  }
  if (!isBattleActive(addToLog, setBattleStarted)) {
    return;
  }
  const playerHealth = store.getState().resources.healthPoints.amount;
  const { values } = store.getState().location.list.forest;
  const damageMax = values.monsterAttack;
  const damage = getHitDamage(damageMax);
  let newPlayerHealth = playerHealth - damage;
  store.dispatch(
    startAnimation({
      element: `damageByMonster`,
      type: 'damage',
      value: damage,
      duration: 2000,
    }),
  );
  addToLog(`You get hit for ${damage} damage.`, false);
  setValue('monsterState', 'attack');
  setTimeout(() => {
    playSfx('fightHit');
  }, 100);

  if (newPlayerHealth <= 0) {
    if (store.getState().location.list.forest.values.canDie) {
      newPlayerHealth = 0;
      unlockItem('lostGame');
    } else {
      newPlayerHealth = 1;
    }
    setPlayerHealth(newPlayerHealth);
    setBattleStarted(3);
    addToLog(`You have been defeated.`, false);
    setTimeout(() => {
      playSfx('death');
      setValue('monsterState', 'idle');
    }, 1200);
    setValue('battleIsActive', false);
  } else {
    setPlayerHealth(newPlayerHealth);
    setTimeout(() => {
      playerAttack(addToLog, setBattleStarted, ignorePause);
    }, 1500);
  }
};

const playerAttack = (
  addToLog: any,
  setBattleStarted: any,
  ignorePause?: boolean,
) => {
  const { isPaused } = store.getState().game;
  if (isPaused && !ignorePause) {
    // try again later
    setTimeout(() => {
      monsterAttack(addToLog, setBattleStarted);
    }, 1000);
    return;
  }
  if (!isBattleActive(addToLog, setBattleStarted)) {
    return;
  }
  const { values } = store.getState().location.list.forest;
  const monsterData = monsters[values.monsterType];
  const damageMax = getPlayerAttack();
  const damage = getHitDamage(damageMax);
  let newMonsterHealth = values.monsterHealth - damage;
  addToLog(`You hit for ${damage} damage.`, true);
  playSfx('fightHit2');
  store.dispatch(
    startAnimation({
      element: `damageByPlayer`,
      type: 'damage',
      value: damage,
      duration: 2000,
    }),
  );
  if (newMonsterHealth <= 0) {
    newMonsterHealth = 0;
    setValue('monsterHealth', newMonsterHealth);
    setValue('monsterState', 'hurt');
    addToLog(`The ${monsterData.displayName} has died.`, false);
    const loot = dropLoot(values.monsterType);
    const lootText: string = Object.keys(loot)
      .map((key) => `${loot[key]} ${key}`)
      .join(',  ');
    addToLog(`You gain loot: ${lootText}`, true);
    unlockNextLevel(addToLog);
    setTimeout(() => {
      playSfx('kill');
      setValue('monsterState', 'dead');
    }, 500);
    setValue('battleIsActive', false);
    setBattleStarted(2);
  } else {
    setValue('monsterHealth', newMonsterHealth);
    setValue('monsterState', 'hurt');
    setTimeout(() => {
      monsterAttack(addToLog, setBattleStarted, ignorePause);
    }, 1500);
  }
};

const getDepthWidth = (depth: number) => {
  const { values } = store.getState().location.list.forest;
  const unlockedDepth = getDepth(values.unlockedLevel);
  if (unlockedDepth < depth) {
    return '0%';
  }
  if (unlockedDepth > depth) {
    return 'calc(100% - 4px)';
  }
  return `${(((values.unlockedLevel - 1) % 10) / 10) * 100}%`;
};

export {
  encounters,
  pickEncounter,
  resetMonster,
  playerAttack,
  monsterAttack,
  getHitDamage,
  setPlayerHealth,
  gotoNextLevel,
  getDepthWidth,
  getDepth,
  goToLevel,
  getButtonCost,
  getPlayerAttack,
  setValue,
  getTotalCost,
  dropLoot,
};
