import React from 'react';
import { getIcon } from '../../utils';
import { Model } from '../../types';

interface ResourceIconProps {
  model: Model | string;
}

const ModelIcon: React.FC<ResourceIconProps> = ({ model }) => {
  const isModelObj =
    typeof model === 'object' && model !== null && 'icon' in model;
  const iconUrl = isModelObj
    ? getIcon((model as Model).icon)
    : getIcon(model as string);
  const color = isModelObj ? (model as Model).color : 'white';

  const iconStyle = {
    '--var-icon-display': 'inline-block',
    '--var-icon': `url('${iconUrl}')`,
    '--var-color': color,
  } as React.CSSProperties;
  return <span className={`highlighted resource ${color}`} style={iconStyle} />;
};

export default ModelIcon;
