import React from 'react';
import { numberDisplay } from '../../../../utils';

interface MonsterHealthProps {
  values: {
    monsterHealth: number;
    monsterMaxHealth: number;
  };
  battleStarted: number;
}
const MonsterHealth: React.FC<MonsterHealthProps> = ({
  values,
  battleStarted,
}) => {
  return (
    <div className={`monster-health${battleStarted ? '' : ' d-none'}`}>
      <div className="health-bar">
        <div
          className="health-bar-fill"
          style={{
            width: `${(values.monsterHealth / values.monsterMaxHealth) * 100}%`,
          }}
        />
        <div className="health-text num">
          {numberDisplay(values.monsterHealth)} /{' '}
          {numberDisplay(values.monsterMaxHealth)}
        </div>
      </div>
    </div>
  );
};

export default MonsterHealth;
