import { store } from '../../store';
import { startAnimation } from '../../store/animationSlice';
import { recipes, Recipe, RecipeList, RecipeType } from '../../conf/recipeConf';
import { itemList } from '../../conf/itemConf';
import { Item, ItemList } from '../../types';
import {
  addAttribute,
  addResource,
  createItem,
  npcInteraction,
} from '../gameUtil';
import CostHandler from '../costHandler';
import { getBalanceModded } from '../modUtil';
import { makeNumCircular } from '..';
import balance from '../../conf/balanceConf';

const findRecipe = (selectedResources: string[], type: RecipeType) => {
  const recipeList: RecipeList = recipes;
  const currentType: Record<string, Recipe> = recipeList[type];

  // Find a recipe where components match in exact order and count
  const recipe = Object.entries(currentType).find(([key, value]) => {
    const { components } = value;
    for (let i = 0; i < components.length; i += 1) {
      if (components[i].resource !== selectedResources[i]) {
        return false;
      }
    }
    return true;
  });
  if (!recipe) {
    return null;
  }
  return recipe[1];
};

type resourceSlot = {
  type: string;
  description: string;
};

const resourceSlots: Record<string, resourceSlot[]> = {
  material: [
    {
      type: 'material',
      description: 'Core resource',
    },
    {
      type: 'material',
      description: 'Connector resource',
    },
  ],
  spiritual: [
    {
      type: 'spiritual',
      description: 'Spiritual fragment',
    },
    {
      type: 'material',
      description: 'Material component',
    },
  ],
  mental: [
    {
      type: 'material',
      description: 'Vessel',
    },
    {
      type: 'mental',
      description: 'Core concept',
    },
    {
      type: 'mental',
      description: 'Supporting concept',
    },
  ],
};

const additionalCostResource = {
  spiritual: 'focus',
  mental: 'mentalEnergy',
  material: 'socialEnergy',
};

const additionalCostBalance = {
  spiritual: {
    item: 'crafting.itemFocusCost',
    resource: 'crafting.resourceFocusCost',
  },
  mental: {
    item: 'crafting.itemMentalEnergyCost',
    resource: 'crafting.resourceMentalEnergyCost',
  },
  material: {
    item: 'crafting.itemSocialEnergyCost',
    resource: 'crafting.resourceSocialEnergyCost',
  },
};

const getRequiredAmount = (
  recipe: Recipe,
  resource: string,
  timesCrafted: number,
) => {
  const component = recipe.components.find((c) => c.resource === resource);
  if (!component) {
    return 0;
  }
  const resourceData = store.getState().resources[resource];
  let multi = Math.max(timesCrafted + 1 - resourceData.tier, 0) * 10;
  if (!multi && timesCrafted > 0) {
    multi = timesCrafted * 5;
  }
  return makeNumCircular(component.baseAmount * 2 ** multi, 2);
};

const getTimesCrafted = (recipe: Recipe) => {
  if (recipe.type !== 'item') {
    return 0;
  }
  const itemData = itemList[recipe.name];
  const items = store.getState().items.list[itemData.name] as ItemList;
  if (!items) {
    return 0;
  }
  const timesCrafted = Object.values(items).reduce((acc, item: Item) => {
    if (item.name === recipe.name) {
      return acc + 1;
    }
    return acc;
  }, 0);
  return timesCrafted;
};

const getRecipeModel = (recipe: Recipe) => {
  if (recipe.type === 'item') {
    return itemList[recipe.name];
  }
  const { resources } = store.getState();
  return resources[recipe.name];
};

const canCraft = (recipe: Recipe, costHandler: CostHandler) => {
  if (!costHandler.canPayCosts()) {
    return false;
  }
  if (recipe.type === 'item') {
    const timesCrafted = getTimesCrafted(recipe);
    const itemData = itemList[recipe.name];
    const limit = getBalanceModded('craftingLimit');
    if (itemData.limit && timesCrafted >= itemData.limit) {
      return false;
    }
    if (limit && timesCrafted >= limit) {
      return false;
    }
    if (!itemData.limit && timesCrafted >= 5) {
      return false;
    }
  }
  return true;
};

const craftItem = (
  recipe: Recipe,
  costHandler: CostHandler,
  addRelationship: boolean,
) => {
  if (!costHandler.canPayCosts()) {
    return;
  }
  costHandler.payAllCosts();
  if (recipe.type === 'item') {
    const itemData = itemList[recipe.name];
    addAttribute(itemData.attribute, getTimesCrafted(recipe) + 1, 'crafting');

    createItem(recipe.name);
  } else {
    addResource(recipe.name, costHandler.getAmount());
  }
  if (addRelationship) {
    npcInteraction(null, balance.craftingRelationship);
  }
  store.dispatch(
    startAnimation({
      element: `justCrafted`,
      type: `crafting`,
      value: 0,
      duration: 2000,
    }),
  );
};

const createCostHandler = (recipe: Recipe, type: RecipeType) => {
  const timesCrafted = getTimesCrafted(recipe);
  const costHandler = new CostHandler();
  recipe.components.forEach((component) => {
    costHandler.addCost(
      component.resource,
      getRequiredAmount(recipe, component.resource, timesCrafted),
    );
  });
  if (recipe.type === 'item') {
    costHandler.addCost(
      additionalCostResource[type],
      getBalanceModded(additionalCostBalance[type][recipe.type]),
    );
  } else if (type === 'mental') {
    costHandler.addCost(
      additionalCostResource[type],
      getBalanceModded(additionalCostBalance[type].resource),
    );
  }
  return costHandler;
};

const getMaxAttribute = (recipeModel: Item, timesCrafted: number) => {
  let { maxAttribute } = recipeModel;
  maxAttribute +=
    maxAttribute * balance.crafting.attributeIcreasePerCraft * timesCrafted;
  return maxAttribute;
};

export {
  findRecipe,
  resourceSlot,
  getRequiredAmount,
  resourceSlots,
  getTimesCrafted,
  getRecipeModel,
  craftItem,
  createCostHandler,
  canCraft,
  additionalCostBalance,
  additionalCostResource,
  getMaxAttribute,
};
