import React, { FC } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { RootState } from '../../store';
import days from '../../conf/dayConf';
import { challengeRequirements } from '../../utils/gameUtil';
import { textDisplay } from '../../utils';
import ChallengeRequirements from '../util/challengeRequirements';

interface ChallengeProps {
  // Add your props here
}

const Challenge: FC<ChallengeProps> = (props) => {
  const day = useSelector((state: RootState) => state.game.day);
  const daysToChallenge = 5 - (day % 5);
  const nextChallenge = days[day + daysToChallenge];

  return (
    <div className="panel panel-challenge">
      <div className="panel-body container">
        <div className="challenge-title">
          <div className="text">
            In <span className="text-shadow">{daysToChallenge}</span> day
            {daysToChallenge === 1 ? '' : 's'}:{' '}
          </div>
          <span className="text-shadow">{nextChallenge?.eventDescription}</span>
        </div>
        <div className="goal">
          <div className="title">
            Required:
            <br />
            <span>(day start)</span>
          </div>
          {nextChallenge && <ChallengeRequirements dayInfo={nextChallenge} />}
        </div>
      </div>
    </div>
  );
};

export default Challenge;
