import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import type { PayloadAction } from '@reduxjs/toolkit';
import { RootState, store } from './';
import { itemList } from '../conf/itemConf';
import { updateSliceVersion } from './common';
import { ItemSlot, ItemList, Item } from '../types';
import { setSeen as setUnlockSeen, setUnseen } from './unlockSlice';
import { updateAttributes } from '../utils/gameState';
import { getMaxAttribute } from '../utils/location/crafting';

export interface ItemState {
  // object with keys from enum ItemSLot and value of object {name: string, id: number}
  equipped: {
    [key in ItemSlot]?: {
      name: string;
      id: number;
      uuid: string;
    };
  };
  // object with keys of string and value of ItemList
  list: {
    [key: string]: ItemList;
  };
}

const initialState: ItemState = {
  equipped: {},
  list: {},
};

const generateItemValues = (item: Item, timesCrafted: number) => {
  const newItem: Item = structuredClone(item);
  // add uuid of 8 random characters
  newItem.uuid = Math.random().toString(36).substring(2, 10);

  const maxAttribute = getMaxAttribute(item, timesCrafted);
  // add attributeAmount between min and max
  newItem.attributeAmount =
    Math.floor(Math.random() * (maxAttribute - item.minAttribute + 1)) +
    item.minAttribute;
  return newItem;
};

export const addItem = createAsyncThunk(
  'item/addItem',
  async ({ item }: { item: string }, { getState }) => {
    const state = getState() as RootState;
    const name = item;
    const itemConfig = itemList[name as keyof typeof itemList];
    const key = Object.keys(state.items.list[name] || {}).length + 1;
    if (key > 5) {
      throw new Error('Cannot add more than 5 items');
    }
    const newItem = generateItemValues(itemConfig, key - 1);
    store.dispatch(setUnseen('items'));
    setTimeout(() => {
      updateAttributes();
    }, 100);
    return { name, key, newItem };
  },
);

export const setSeen = createAsyncThunk(
  'item/setSeen',
  async ({ name, uuid }: { name: string; uuid: string }, { getState }) => {
    const state = getState() as RootState;
    const item = Object.values(state.items.list[name]).find(
      (i: Item) => i.uuid === uuid,
    );

    // Loop over state.items.list and check if there is any item other than the current one that is unseen
    const unseen = Object.values(state.items.list).some(
      (itemListTmp: ItemList) => {
        return Object.values(itemListTmp).some((i: Item) => {
          return i.uuid !== uuid && !i.isSeen;
        });
      },
    );

    if (!unseen) store.dispatch(setUnlockSeen('items'));

    if (item) {
      return { name, uuid };
    }
    throw new Error('Item not found');
  },
);

export const itemSlice = createSlice({
  name: 'item',
  initialState,
  reducers: {
    resetItems: () => {
      return initialState;
    },
    updateVersion: (state) => {
      return updateSliceVersion(state, initialState);
    },
    equipItem(state, action: PayloadAction<{ item: Item; uuid: string }>) {
      // get the item from the list
      const { item, uuid } = action.payload;
      const { name } = item;
      // find item with the same uuid
      const itemToEquip = Object.values(state.list[name]).find(
        (i: Item) => i.uuid === uuid,
      );
      const idKey = Object.keys(state.list[name]).find(
        (key: string) => state.list[name][parseInt(key, 10)] === itemToEquip,
      );
      const idNumber = parseInt(idKey || '', 10);
      if (!itemToEquip) {
        return;
      }
      const itemSlot = itemToEquip.slot;
      // if the item is already equipped,do nothing. otherwise unequip the current item and equip the new item
      if (state.equipped[itemSlot]) {
        if (state.equipped[itemSlot]?.uuid === itemToEquip.uuid) {
          return;
        }
        const oldItem = state.equipped[itemSlot];
        // TODO: remove mods
      }
      state.equipped[itemSlot] = {
        name,
        id: idNumber,
        uuid: itemToEquip.uuid || '',
      };
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(addItem.fulfilled, (state, action) => {
        const { name, key, newItem } = action.payload;
        if (!state.list[name]) {
          state.list[name] = {};
        }
        state.list[name][key] = newItem;
      })
      .addCase(setSeen.fulfilled, (state, action) => {
        const { name, uuid } = action.payload;
        const item = Object.values(state.list[name]).find(
          (i: Item) => i.uuid === uuid,
        );
        if (item) {
          item.isSeen = true;
        }
      });
  },
});

// Action creators are generated for each case reducer function
export const { resetItems, updateVersion, equipItem } = itemSlice.actions;

export default itemSlice.reducer;
